            if(!handleAIResponseCheck(data)) { getEl('familai-advisor-modal').classList.add('hidden'); return; }
            if(data.success && data.advice) { showAIModal('היועץ העסקי של הארגון', data.advice); triggerConfetti(); fetchData(); } 
