window.renderTasks = function(tasks) {
    const list = getEl('tasks-list'); if(!list) return; let htmlStr = ''; let count = 0;
    tasks.forEach(t => {
        if(t.title && t.title.startsWith('SHIFT|')) return;
        const isMyTask = String(t.assigned_to) === String(currentUser.id); const isAdmin = currentUser.role === 'ADMIN'; if (!isMyTask && !isAdmin) return; count++;
        
        let isSop = false;
        let displayTitle = safeStr(t.title);
        let sopDataStr = '';
        let sopData = null;
        let managerProgressHtml = '';

        if (t.title && t.title.startsWith('SOP|')) {
            isSop = true;
            try {
                sopDataStr = t.title.substring(4);
                sopData = JSON.parse(sopDataStr);
                displayTitle = safeStr(sopData.title || 'נוהל עבודה');
                
                if (isAdmin && t.status === 'pending') {
                    const match = (t.notes || '').match(/PROGRESS:(\d+)\/(\d+)/);
                    if (match) {
                        const checked = parseInt(match[1]);
                        const total = parseInt(match[2]);
                        const pct = total > 0 ? (checked/total)*100 : 0;
                        managerProgressHtml = `
                        <div class="mt-2 w-full max-w-[200px]">
                            <div class="flex justify-between text-[9px] text-slate-400 mb-0.5"><span>התקדמות העובד:</span><span>${checked}/${total}</span></div>
                            <div class="w-full bg-slate-100 rounded-full h-1.5"><div class="bg-indigo-400 h-1.5 rounded-full transition-all" style="width: ${pct}%"></div></div>
                        </div>`;
                    }
                }
            } catch(e) { displayTitle = 'נוהל שגוי'; }
        }

        let statusColor = 'bg-white border-slate-100'; let statusBadge = ''; let actionBtn = '';

        const deleteBtn = isAdmin ? `<button onclick="deleteTask(${t.id})" class="text-slate-300 hover:text-red-500 bg-slate-50 w-7 h-7 rounded-lg flex items-center justify-center transition border border-slate-100" title="בטל משימה"><i class="fa-solid fa-trash-can text-xs"></i></button>` : '';
        const editBtn = (isAdmin && t.status === 'pending' && !isSop) ? `<button onclick="openEditTaskModal(${t.id}, '${displayTitle.replace(/'/g,"\\'")}', ${t.reward||0}, '${t.priority||'medium'}')" class="text-slate-300 hover:text-blue-500 bg-slate-50 w-7 h-7 rounded-lg flex items-center justify-center transition border border-slate-100" title="ערוך משימה"><i class="fa-solid fa-pen text-xs"></i></button>` : '';
        const commentsBtn = `<button onclick="openTaskComments(${t.id}, '${displayTitle.replace(/'/g,"\\'")}' )" class="text-slate-300 hover:text-purple-500 bg-slate-50 w-7 h-7 rounded-lg flex items-center justify-center transition border border-slate-100" title="תגובות"><i class="fa-solid fa-comment text-xs"></i></button>`;

        if (t.status === 'pending') {
            if (isMyTask) {
                if (isSop) {
                    const safeSopData = encodeURIComponent(sopDataStr);
                    actionBtn = `<button onclick="if(typeof window.openSOPExecutionModal === 'function') window.openSOPExecutionModal(${t.id}, '${displayTitle}', '${safeSopData}')" class="bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-xs font-bold shadow-md hover:bg-indigo-700 transition flex items-center gap-1.5"><i class="fa-solid fa-list-check"></i> ביצוע נוהל</button>`;
                } else {
                    actionBtn = `<div class="flex gap-1"><button onclick="clickTaskProof(${t.id}, '${displayTitle}')" class="bg-slate-800 text-white px-2.5 py-1.5 rounded-xl text-xs font-bold shadow-md hover:bg-slate-700 transition flex items-center gap-1" title="הגשה עם בקרת AI"><i class="fa-solid fa-robot"></i> AI</button><button onclick="clickTaskPhotoProof(${t.id}, '${displayTitle}')" class="bg-blue-600 text-white px-2.5 py-1.5 rounded-xl text-xs font-bold shadow-md hover:bg-blue-700 transition flex items-center gap-1" title="הגשה עם תמונה"><i class="fa-solid fa-camera"></i> תמונה</button></div>`;
                }
            } else {
                statusBadge = `<span class="text-[10px] bg-slate-100 text-slate-500 px-2 py-1 rounded-lg font-bold border border-slate-200">ממתין לעובד</span>`;
            }
        }
        else if (t.status === 'done') {
            statusColor = 'bg-amber-50 border-amber-100';
            if (isAdmin) {
                const proofLink = t.proof_image_url ? `<a href="${t.proof_image_url}" target="_blank" class="text-xs text-blue-600 underline font-bold flex items-center gap-1 mb-1"><i class="fa-solid fa-image"></i> צפה בתמונה</a>` : '';
                actionBtn = `<div class="flex flex-col items-end gap-1">${proofLink}<button onclick="openApproveTaskModal(${t.id}, '${displayTitle}', ${t.reward})" class="bg-green-600 text-white px-4 py-1.5 rounded-xl text-xs font-bold shadow-md hover:bg-green-700 transition flex items-center gap-1"><i class="fa-solid fa-check-double"></i> אישור סופי</button></div>`;
            } else {
                statusBadge = `<span class="text-xs text-amber-600 font-bold bg-amber-100 px-2 py-1 rounded-lg shadow-sm">בבקרת מנהל</span>`;
            }
        }
        else if (t.status === 'approved') { statusColor = 'bg-green-50 border-green-100 opacity-70'; statusBadge = `<span class="text-xs text-green-600 font-bold"><i class="fa-solid fa-check-double"></i> סגור</span>`; }

        const sopBadge = isSop ? `<span class="text-[9px] bg-indigo-50 text-indigo-700 border border-indigo-100 px-1.5 py-0.5 rounded font-bold ml-1 shadow-sm"><i class="fa-solid fa-layer-group"></i> נוהל</span>` : '';
        const prioMap = { high: '🔴', medium: '🟡', low: '🟢' };
        const prioBadge = `<span class="text-[9px] px-1 py-0.5 rounded font-bold">${prioMap[t.priority] || '🟡'}</span>`;
        const rewardDisplay = t.reward > 0 ? `<span class="text-[10px] font-black text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded border border-emerald-100 shadow-sm">בונוס ₪${t.reward}</span>` : `<span class="text-[10px] font-bold text-slate-500 bg-slate-100 px-2 py-0.5 rounded border border-slate-200 shadow-sm">שגרה</span>`;
        let deadlineBadge = ''; if (t.deadline && t.status === 'pending') { const diff = Math.ceil((new Date(t.deadline) - new Date()) / (1000 * 60 * 60 * 24)); if (diff > 0) deadlineBadge = `<span class="text-orange-600 bg-orange-50 px-1.5 py-0.5 rounded text-[9px] ml-1 font-bold border border-orange-100"><i class="fa-regular fa-clock"></i> יעד: ${diff} ימ'</span>`; else deadlineBadge = `<span class="text-red-600 bg-red-50 px-1.5 py-0.5 rounded text-[9px] ml-1 font-bold border border-red-100 animate-pulse"><i class="fa-regular fa-clock"></i> חריגה!</span>`; }
        const dateStr = t.created_at ? new Date(t.created_at).toLocaleDateString('he-IL') : ''; const dateBadge = dateStr ? `<span class="text-[9px] text-slate-400 mr-2"><i class="fa-regular fa-calendar"></i> נפתח: ${dateStr}</span>` : '';

        htmlStr += `<div class="card-modern p-4 flex justify-between items-center mb-2 rounded-2xl border shadow-sm hover:shadow-md transition ${statusColor} group"><div class="min-w-0 flex-1"><p class="font-bold text-slate-800 text-sm leading-tight flex items-center flex-wrap gap-1">${prioBadge} ${displayTitle} ${sopBadge} ${deadlineBadge}</p><div class="flex items-center flex-wrap gap-2 mt-2"><span class="text-xs text-slate-500 font-medium"><i class="fa-regular fa-user"></i> ${safeStr(t.assignee_name)}</span>${rewardDisplay}${dateBadge}</div>${managerProgressHtml}</div><div class="flex flex-col items-end gap-2 shrink-0 pl-1"><div class="flex items-center gap-1.5">${actionBtn}${commentsBtn}${editBtn}${deleteBtn}</div>${statusBadge}</div></div>`;
    });
    if (count === 0) list.innerHTML = '<div class="text-center py-8 text-slate-400 text-sm bg-slate-50 rounded-2xl border border-dashed border-slate-200">אין פרויקטים ומשימות פעילים כרגע</div>'; else list.innerHTML = htmlStr;
};

// ── Shift Templates (stored per group in localStorage) ───────────────────────
function getShiftTemplates() {
    const key = `biz_shift_tpl_${currentGroup?.id}`;
    try { const s = localStorage.getItem(key); if(s) return JSON.parse(s); } catch(e) {}
    return [
        { id: 1, name: 'בוקר', start: '08:00', end: '16:00' },
        { id: 2, name: 'ערב', start: '16:00', end: '23:00' }
    ];
}
function saveShiftTemplates(tpls) {
    localStorage.setItem(`biz_shift_tpl_${currentGroup?.id}`, JSON.stringify(tpls));
}

// ── View state ────────────────────────────────────────────────────────────────
let shiftView = 'list';
let shiftNavDate = new Date();

function setShiftView(v) {
    shiftView = v;
    ['list','day','week'].forEach(k => {
        const b = getEl(`sv-${k}`);
        if(b) b.className = `shift-sv-btn px-3 py-1 rounded-full text-xs font-bold transition ${k===v ? 'bg-white text-indigo-700 shadow' : 'text-slate-500 hover:text-slate-700'}`;
    });
    const nav = getEl('shift-nav');
    if(nav) nav.className = (v === 'list') ? 'hidden flex items-center gap-1 shrink-0' : 'flex items-center gap-1 shrink-0';
    updateShiftDateLabel();
    renderShifts();
}

function navShiftDate(delta) {
    if(shiftView === 'day') { shiftNavDate.setDate(shiftNavDate.getDate() + delta); }
    else { shiftNavDate.setDate(shiftNavDate.getDate() + delta * 7); }
    updateShiftDateLabel();
    renderShifts();
}

function updateShiftDateLabel() {
    const el = getEl('shift-date-label'); if(!el) return;
    if(shiftView === 'day') {
        el.textContent = shiftNavDate.toLocaleDateString('he-IL', { weekday:'short', day:'numeric', month:'short' });
    } else {
        const sun = new Date(shiftNavDate); sun.setDate(shiftNavDate.getDate() - shiftNavDate.getDay());
        const sat = new Date(sun); sat.setDate(sun.getDate() + 6);
        el.textContent = `${sun.getDate()}/${sun.getMonth()+1} – ${sat.getDate()}/${sat.getMonth()+1}`;
    }
}

// ── Template manager (admin) ──────────────────────────────────────────────────
function renderShiftTemplatesMgr() {
    const el = getEl('shift-templates-mgr'); if(!el) return;
    const isAdmin = currentUser.role === 'ADMIN';
    if(!isAdmin) { el.className = 'hidden'; return; }
    el.className = 'px-2 mb-3';
    const tpls = getShiftTemplates();
    el.innerHTML = `<div class="bg-indigo-50 rounded-2xl p-3 border border-indigo-100">
      <div class="flex justify-between items-center mb-2">
        <span class="text-xs font-bold text-indigo-700"><i class="fa-solid fa-sliders mr-1"></i> תבניות משמרת</span>
        <button onclick="openAddTemplateModal()" class="text-xs text-indigo-600 font-bold hover:underline">+ הוסף תבנית</button>
      </div>
      <div class="flex flex-wrap gap-2">
        ${tpls.map(t => `<div class="flex items-center gap-1 bg-white border border-indigo-200 rounded-full px-3 py-1 text-xs font-bold text-slate-700">
          <span>${safeStr(t.name)}</span><span class="text-slate-400">${t.start}–${t.end}</span>
          <button onclick="deleteShiftTemplate(${t.id})" class="text-slate-300 hover:text-red-500 ml-1"><i class="fa-solid fa-xmark text-[10px]"></i></button>
        </div>`).join('')}
        ${tpls.length === 0 ? '<span class="text-xs text-slate-400">אין תבניות מוגדרות</span>' : ''}
      </div>
    </div>`;
}

async function openAddTemplateModal() {
    const name  = await window._uiPrompt('שם המשמרת (למשל: בוקר, ערב, לילה):'); if(!name) return;
    const start = await window._uiPrompt('שעת התחלה (HH:MM):'); if(!start) return;
    const end   = await window._uiPrompt('שעת סיום (HH:MM):');   if(!end) return;
    const tpls  = getShiftTemplates();
    tpls.push({ id: Date.now(), name: name.trim(), start, end });
    saveShiftTemplates(tpls);
    renderShiftTemplatesMgr();
    // refresh template buttons in modal if open
    const wrap = getEl('shift-tpl-buttons'); if(wrap) renderTemplateBtns(wrap);
}

async function deleteShiftTemplate(id) {
    if(!await window._uiConfirm('למחוק תבנית זו?', {danger:true, okLabel:'מחק'})) return;
    const tpls = getShiftTemplates().filter(t => t.id !== id);
    saveShiftTemplates(tpls);
    renderShiftTemplatesMgr();
}

function renderTemplateBtns(container) {
    const tpls = getShiftTemplates();
    container.innerHTML = tpls.map(t => `<button type="button" onclick="selectShiftTemplate(${t.id})"
      class="shift-tpl-pick flex-1 border rounded-xl py-2 px-3 text-xs font-bold transition border-slate-200 text-slate-600 hover:border-indigo-400 hover:bg-indigo-50" data-id="${t.id}">
      <div>${safeStr(t.name)}</div><div class="text-[10px] text-slate-400 font-normal mt-0.5">${t.start}–${t.end}</div>
    </button>`).join('') + `<button type="button" onclick="selectShiftTemplate('custom')"
      class="shift-tpl-pick flex-1 border rounded-xl py-2 px-3 text-xs font-bold transition border-slate-200 text-slate-600 hover:border-indigo-400 hover:bg-indigo-50" data-id="custom">
      <div>שעות חופשיות</div><div class="text-[10px] text-slate-400 font-normal mt-0.5">בחר שעות</div>
    </button>`;
}

function selectShiftTemplate(id) {
    document.querySelectorAll('.shift-tpl-pick').forEach(b => {
        b.classList.toggle('border-indigo-500', String(b.dataset.id) === String(id));
        b.classList.toggle('bg-indigo-50',      String(b.dataset.id) === String(id));
        b.classList.toggle('text-indigo-700',   String(b.dataset.id) === String(id));
    });
    const customRow = getEl('shift-hours-row');
    if(id === 'custom') {
        if(customRow) customRow.classList.remove('hidden');
    } else {
        if(customRow) customRow.classList.add('hidden');
        const tpl = getShiftTemplates().find(t => String(t.id) === String(id));
        if(tpl) { const si = getEl('shift-start'); const ei = getEl('shift-end'); if(si) si.value = tpl.start; if(ei) ei.value = tpl.end; }
    }
    window._selectedShiftTplId = id;
}

// ── Main render ───────────────────────────────────────────────────────────────
function renderShifts() {
    renderShiftTemplatesMgr();
    const isAdmin = currentUser.role === 'ADMIN';
    const shiftTasks = allTasks.filter(t => t.title && t.title.startsWith('SHIFT|'));
    const visible = shiftTasks.filter(t => isAdmin || String(t.assigned_to) === String(currentUser.id));
    const list = getEl('shifts-list'); if(!list) return;

    if(shiftView === 'week') { renderShiftWeekly(visible); return; }
    if(shiftView === 'day')  { renderShiftDaily(visible);  return; }

    // List view
    let html = '';
    visible.sort((a,b) => (a.title > b.title ? 1 : -1));
    visible.forEach(t => {
        const parts = t.title.split('|'); const date = parts[1]; const start = parts[2]; const end = parts[3];
        const name  = parts[4] || ''; // optional template name
        const isPending = t.status === 'pending';
        const statusBadge = isPending
            ? '<span class="text-xs bg-orange-100 text-orange-600 px-2 py-1 rounded-full font-bold">ממתין לאישור</span>'
            : '<span class="text-xs bg-green-100 text-green-600 px-2 py-1 rounded-full font-bold">משובץ ✓</span>';
        let actions = '';
        if(isAdmin && isPending) {
            actions += `<button onclick="updateTask(${t.id},'approved')" class="bg-indigo-600 text-white px-3 py-1 rounded-lg text-xs font-bold shadow-sm hover:bg-indigo-700">✓ אשר</button>
                        <button onclick="deleteTask(${t.id})" class="bg-red-50 text-red-500 px-3 py-1 rounded-lg text-xs font-bold hover:bg-red-100">✗ סרב</button>`;
        }
        if(isAdmin || String(t.assigned_to) === String(currentUser.id)) {
            actions += ` <button onclick="deleteTask(${t.id})" class="text-slate-300 hover:text-red-500"><i class="fa-solid fa-trash text-xs"></i></button>`;
        }
        html += `<div class="bg-white p-4 rounded-2xl border ${isPending ? 'border-orange-200' : 'border-slate-100'} shadow-sm flex justify-between items-center mb-2">
          <div>
            <p class="font-bold text-slate-800 text-base">${date}${name ? ` · <span class="text-indigo-600 font-normal text-sm">${safeStr(name)}</span>` : ''}</p>
            <p class="text-sm text-indigo-600 font-bold mt-0.5">${start} – ${end}
              ${isAdmin ? `<span class="text-slate-400 font-normal"> | ${safeStr(t.assignee_name)}</span>` : ''}
            </p>
          </div>
          <div class="flex flex-col items-end gap-2">${statusBadge}<div class="flex gap-1 items-center">${actions}</div></div>
        </div>`;
    });
    list.innerHTML = html || '<p class="text-center text-slate-400 py-8 bg-slate-50 rounded-2xl border border-dashed border-slate-200">אין משמרות</p>';
}

function renderShiftDaily(shifts) {
    const list = getEl('shifts-list'); if(!list) return;
    const dayStr = shiftNavDate.toISOString().slice(0,10);
    const isAdmin = currentUser.role === 'ADMIN';
    const dayShifts = shifts.filter(t => t.title.split('|')[1] === dayStr);
    dayShifts.sort((a,b) => (a.title.split('|')[2] > b.title.split('|')[2] ? 1 : -1));
    let html = `<div class="text-xs font-bold text-slate-500 px-2 mb-2">${shiftNavDate.toLocaleDateString('he-IL', {weekday:'long', day:'numeric', month:'long'})}</div>`;
    if(!dayShifts.length) {
        list.innerHTML = html + '<p class="text-center text-slate-400 py-8 bg-slate-50 rounded-2xl border border-dashed border-slate-200">אין משמרות ביום זה</p>';
        return;
    }
    dayShifts.forEach(t => {
        const parts = t.title.split('|'); const start = parts[2]; const end = parts[3]; const name = parts[4]||'';
        const isPending = t.status === 'pending';
        let actions = '';
        if(isAdmin && isPending) actions = `<button onclick="updateTask(${t.id},'approved')" class="bg-indigo-600 text-white px-3 py-1 rounded-lg text-xs font-bold">✓ אשר</button> <button onclick="deleteTask(${t.id})" class="bg-red-50 text-red-500 px-3 py-1 rounded-lg text-xs font-bold">✗ סרב</button>`;
        if(isAdmin) actions += ` <button onclick="deleteTask(${t.id})" class="text-slate-300 hover:text-red-500 mr-1"><i class="fa-solid fa-trash text-xs"></i></button>`;
        html += `<div class="bg-white p-3 rounded-2xl border ${isPending ? 'border-orange-200' : 'border-slate-100'} shadow-sm flex justify-between items-center mb-2">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 rounded-full bg-indigo-100 text-indigo-700 flex items-center justify-center text-xs font-black">${start.slice(0,5)}</div>
            <div>
              <p class="font-bold text-sm text-slate-800">${safeStr(t.assignee_name)}${name ? ` · <span class="text-indigo-600 font-normal">${safeStr(name)}</span>` : ''}</p>
              <p class="text-xs text-slate-500">${start}–${end}</p>
            </div>
          </div>
          <div class="flex flex-col items-end gap-1">
            ${isPending ? '<span class="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-bold">ממתין</span>' : '<span class="text-[10px] bg-green-100 text-green-600 px-2 py-0.5 rounded-full font-bold">אושר</span>'}
            <div class="flex gap-1">${actions}</div>
          </div>
        </div>`;
    });
    list.innerHTML = html;
}

function renderShiftWeekly(shifts) {
    const list = getEl('shifts-list'); if(!list) return;
    const isAdmin = currentUser.role === 'ADMIN';
    // find Sunday of current week
    const sun = new Date(shiftNavDate); sun.setDate(shiftNavDate.getDate() - shiftNavDate.getDay());
    const days = Array.from({length:7}, (_,i) => { const d = new Date(sun); d.setDate(sun.getDate()+i); return d; });
    const heDay = ['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];

    let html = '<div class="overflow-x-auto pb-2">';
    days.forEach((d, i) => {
        const dayStr = d.toISOString().slice(0,10);
        const dayShifts = shifts.filter(t => t.title.split('|')[1] === dayStr);
        const isToday = dayStr === new Date().toISOString().slice(0,10);
        html += `<div class="bg-white rounded-2xl border ${isToday ? 'border-indigo-300 shadow-md' : 'border-slate-100 shadow-sm'} p-3 mb-2">
          <div class="flex justify-between items-center mb-2">
            <span class="text-xs font-black ${isToday ? 'text-indigo-700' : 'text-slate-600'}">${heDay[i]} ${d.getDate()}/${d.getMonth()+1}${isToday ? ' 📍' : ''}</span>
            ${dayShifts.some(t => t.status === 'pending') && isAdmin
                ? `<span class="text-[10px] bg-orange-100 text-orange-500 px-2 py-0.5 rounded-full font-bold">${dayShifts.filter(t=>t.status==='pending').length} ממתינים</span>` : ''}
          </div>
          ${dayShifts.length === 0
            ? '<p class="text-xs text-slate-300 text-center py-1">ללא משמרות</p>'
            : dayShifts.map(t => {
                const parts = t.title.split('|'); const start=parts[2]; const end=parts[3]; const name=parts[4]||'';
                const isPending = t.status==='pending';
                return `<div class="flex justify-between items-center py-1.5 border-t border-slate-50 first:border-0">
                  <div>
                    <span class="text-xs font-bold text-slate-700">${safeStr(t.assignee_name)}</span>
                    <span class="text-[10px] text-slate-400 mr-1">${start}–${end}${name?' · '+safeStr(name):''}</span>
                  </div>
                  <div class="flex items-center gap-1">
                    ${isPending && isAdmin ? `<button onclick="updateTask(${t.id},'approved')" class="text-[10px] bg-indigo-600 text-white px-2 py-0.5 rounded-full font-bold">אשר</button><button onclick="deleteTask(${t.id})" class="text-[10px] text-red-400 hover:text-red-600">✗</button>` : ''}
                    ${!isPending ? '<span class="text-[10px] text-green-500">✓</span>' : ''}
                  </div>
                </div>`;
              }).join('')
          }
        </div>`;
    });
    html += '</div>';
    list.innerHTML = html;
}

// ── Modal ─────────────────────────────────────────────────────────────────────
function openShiftModal() {
    if(!getEl('shift-modal')) return;
    getEl('shift-modal').classList.remove('hidden');
    window._selectedShiftTplId = null;
    // populate employee selector
    const userSel = getEl('shift-user');
    if(userSel) {
        userSel.innerHTML = '';
        if(currentUser.role === 'ADMIN') { membersCache.forEach(m => { if(m.role !== 'ADMIN') userSel.innerHTML += `<option value="${m.id}">${safeStr(m.nickname)}</option>`; }); }
        else { userSel.innerHTML = `<option value="${currentUser.id}">${safeStr(fmtUserName(currentUser) || currentUser.nickname)}</option>`; }
    }
    // render template buttons
    const wrap = getEl('shift-tpl-buttons');
    if(wrap) renderTemplateBtns(wrap);
    // reset
    const hr = getEl('shift-hours-row'); if(hr) hr.classList.remove('hidden');
    document.querySelectorAll('.shift-tpl-pick').forEach(b => {
        b.classList.remove('border-indigo-500','bg-indigo-50','text-indigo-700');
    });
}

async function submitShift() {
    const date   = val('shift-date');
    const userId = val('shift-user');
    let start = val('shift-start');
    let end   = val('shift-end');
    let tplName = '';

    // if a template is selected (not custom), use its hours
    const tplId = window._selectedShiftTplId;
    if(tplId && tplId !== 'custom') {
        const tpl = getShiftTemplates().find(t => String(t.id) === String(tplId));
        if(tpl) { start = tpl.start; end = tpl.end; tplName = tpl.name; }
    }

    if(!date || !start || !end || !userId) return showToast('error', 'נא למלא תאריך ושעות');
    const title  = `SHIFT|${date}|${start}|${end}${tplName ? '|'+tplName : ''}`;
    const status = currentUser.role === 'ADMIN' ? 'approved' : 'pending';
    const btn = getEl('btn-submit-shift'); btn.disabled = true; btn.innerText = 'שומר...';
    try {
        await fetch(`${API}/tasks`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ title, reward:0, assignedTo:userId, days:null, status, groupId:currentGroup.id }) });
        getEl('shift-modal').classList.add('hidden');
        showToast('success', status === 'approved' ? 'המשמרת שובצה!' : 'הבקשה נשלחה למנהל!');
        fetchData();
    } catch(e) { showToast('error', 'שגיאה בשמירת המשמרת'); }
    finally { btn.disabled = false; btn.innerText = 'שמור'; }
}

async function updateTask(id, s) {
    if(s==='done' || s==='completed_self') triggerConfetti();
    const res = await fetch(`${API}/tasks/update`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({taskId:id, status:s})});
    fetchData();
    try { const d = await res.json(); if (d.triggeredPopup) setTimeout(() => showEmpTriggeredPopup(d.triggeredPopup), 800); } catch(e) {}
}
async function deleteTask(id) { if(!await window._uiConfirm('האם למחוק/לסרב לבקשה?', {danger:true, okLabel:'מחק'})) return; await fetch(`${API}/tasks/update`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({taskId:id, status:'deleted'})}); fetchData(); } 

window.currentFeedPage = 1;

window.changeFeedPage = function(direction) {
    window.currentFeedPage += direction;
    if (window.currentFeedPage < 1) window.currentFeedPage = 1;
    renderUnifiedFeed();
};

// ============================================================
// --- GROUP NAV — 5 קבוצות ניווט ---
// ============================================================
const GNAV_GROUPS = {
    team:      ['timeclock','shifts','calendar','tasks','academy','members','beauty_calendar','beauty_practitioners'],
    sales:     ['pos','sales','customers','cases','leads','deliveries','reviews','menu_templates','beauty_services','beauty_subscriptions','beauty_clients','beauty_rfq'],
    inventory: ['shop','pantry','equipment','foodcost','beauty_inventory'],
    finance:   ['bank','cashflow','budget','timelog','forecast','beauty_commissions','reports'],
    more:      ['community','surveys','content','documents','biz-ads','whatsapp-alerts','settings']
};

// שמירת האב המקורי של כל dropdown לצורך החזרה
const _gnavOriginalParents = {};

window.toggleNavDropdown = function(group) {
    const dd = document.getElementById(`gnav-dropdown-${group}`);
    if (!dd) return;
    const isOpen = !dd.classList.contains('hidden');
    window.closeNavDropdowns();
    if (isOpen) return;

    const btn = document.getElementById(`gnav-group-${group}`);
    if (!btn) return;
    const rect = btn.getBoundingClientRect();

    // Portal: העברה ל-body כדי לעקוף overflow/transform של כל אב
    if (!_gnavOriginalParents[group]) _gnavOriginalParents[group] = dd.parentElement;
    document.body.appendChild(dd);

    const ddWidth = 170;
    let leftPos = rect.left;
    if (leftPos + ddWidth > window.innerWidth - 8) leftPos = window.innerWidth - ddWidth - 8;
    if (leftPos < 8) leftPos = 8;

    dd.style.cssText = `position:fixed; top:${rect.bottom + 4}px; left:${leftPos}px; right:auto; z-index:99999;`;
    dd.classList.remove('hidden');
};

window.closeNavDropdowns = function() {
    Object.keys(GNAV_GROUPS).forEach(g => {
        const dd = document.getElementById(`gnav-dropdown-${g}`);
        if (!dd) return;
        dd.classList.add('hidden');
        dd.removeAttribute('style');
        // החזרה לאב המקורי
        const orig = _gnavOriginalParents[g];
        if (orig && dd.parentElement !== orig) orig.appendChild(dd);
    });
};

function updateGroupNavActiveState(tabId) {
    const feedBtn = document.getElementById('gnav-btn-feed');
    if (feedBtn) {
        feedBtn.className = tabId === 'feed'
            ? 'gnav-btn flex-shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-bold text-white bg-indigo-600 transition-all duration-150'
            : 'gnav-btn flex-shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-medium text-slate-400 hover:text-white hover:bg-slate-800 transition-all duration-150';
    }
    let activeGroup = null;
    for (const [g, tabs] of Object.entries(GNAV_GROUPS)) {
        if (tabs.includes(tabId)) { activeGroup = g; break; }
    }
    Object.keys(GNAV_GROUPS).forEach(g => {
        const btn = document.getElementById(`gnav-btn-${g}`);
        if (!btn) return;
        const isActive = g === activeGroup;
        btn.classList.toggle('bg-indigo-600', isActive);
        btn.classList.toggle('text-white', isActive);
        btn.classList.toggle('text-slate-400', !isActive);
    });
}

function updateGroupNavVisibility() {
    const isEmployee = currentUser?.role === 'MEMBER' || currentUser?.role === 'SENIOR';
    let userTabs = [];
    if (isEmployee) {
        try {
            const perms = typeof currentUser?.permissions === 'string' ? JSON.parse(currentUser.permissions) : (currentUser?.permissions || {});
            userTabs = perms.tabs || ROLE_DEFAULTS[currentUser?.role] || ROLE_DEFAULTS['MEMBER'];
        } catch(e) { userTabs = ROLE_DEFAULTS[currentUser?.role] || ROLE_DEFAULTS['MEMBER']; }
        if (currentUser.employee_role_type && ROLE_TYPE_TABS[currentUser.employee_role_type]) {
            ROLE_TYPE_TABS[currentUser.employee_role_type].forEach(t => { if (!userTabs.includes(t)) userTabs.push(t); });
        }
    }
    Object.entries(GNAV_GROUPS).forEach(([g, tabs]) => {
        const groupEl = document.getElementById(`gnav-group-${g}`);
        if (!groupEl) return;
        // עובדים לא רואים כספים ומלאי אלא אם יש להם הרשאה מפורשת לאחד הטאבים
        if (isEmployee && (g === 'finance' || g === 'inventory')) {
            const hasPermittedTab = tabs.some(id => userTabs.includes(id));
            if (!hasPermittedTab) { groupEl.style.display = 'none'; return; }
        }
        const hasVisible = tabs.some(id => {
            const dropBtn = document.getElementById(`gdrop-${id}`);
            if (dropBtn) return !dropBtn.classList.contains('tab-perm-locked');
            const btn = document.getElementById(`tab-${id}`);
            return btn && btn.style.display !== 'none';
        });
        groupEl.style.display = hasVisible ? '' : 'none';
    });
}

function syncGnavAlertBadge() {
    const src  = document.getElementById('alert-badge');
    const dest = document.getElementById('gnav-alert-badge');
    if (!src || !dest) return;
    const hidden = src.classList.contains('hidden');
    dest.classList.toggle('hidden', hidden);
    if (!hidden) dest.textContent = src.textContent;
}

function updateGroupNavBadges() {
    // צוות: משימות pending
    const teamCount = (allTasks || []).filter(t => t.status === 'pending').length;
    const teamBadge = document.getElementById('gnav-badge-team');
    if (teamBadge) { teamBadge.textContent = teamCount > 9 ? '9+' : teamCount; teamBadge.classList.toggle('hidden', teamCount === 0); }

    // badge ספציפי על שורת "משימות" בדרופ-דאון
    const taskDropBadge = document.getElementById('gdrop-badge-tasks');
    if (taskDropBadge) { taskDropBadge.textContent = teamCount > 9 ? '9+' : teamCount; taskDropBadge.classList.toggle('hidden', teamCount === 0); }

    // מכירות: הזמנות חדשות
    const salesCount = (storeOrdersCache || []).filter(o => o.status === 'new').length;
    const salesBadge = document.getElementById('gnav-badge-sales');
    if (salesBadge) { salesBadge.textContent = salesCount > 9 ? '9+' : salesCount; salesBadge.classList.toggle('hidden', salesCount === 0); }

    // badge ספציפי על שורת "מכירות וחנות" בדרופ-דאון
    const ordersDropBadge = document.getElementById('gdrop-badge-orders');
    if (ordersDropBadge) { ordersDropBadge.textContent = salesCount > 9 ? '9+' : salesCount; ordersDropBadge.classList.toggle('hidden', salesCount === 0); }
}

// רישום Service Worker
if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => { navigator.serviceWorker.register('/sw.js').catch(() => {}); });
}

// סגירת dropdown בלחיצה מחוץ לנאב או מחוץ ל-dropdown הפתוח
document.addEventListener('click', function(e) {
    if (e.target.closest('#group-nav')) return;
    const inOpenDropdown = Object.keys(GNAV_GROUPS).some(g => {
        const dd = document.getElementById(`gnav-dropdown-${g}`);
        return dd && !dd.classList.contains('hidden') && dd.contains(e.target);
    });
    if (!inOpenDropdown) window.closeNavDropdowns();
});

// ============================================================
// --- Dashboard (Home Tab) ---
// ============================================================
// ── EMPLOYEE HOME — MEMBER / SENIOR ────────────────────────────
async function renderEmployeeDashboard() {
    if (!document.getElementById('emp-home-header')) return;

    // הצג חלקי מסך עובד, הסתר כרטיסי מנהל
    ['emp-home-header','emp-home-footer'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.remove('hidden');
    });
    ['tour-balance-card','quick-tiles','admin-kpi-cards','dashboard-alerts'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.add('hidden');
    });

    // ─ ברכה ותאריך ─
    const now = new Date();
    const greet = document.getElementById('emp-greeting');
    const dateL  = document.getElementById('emp-date-label');
    if (greet && currentUser) greet.textContent = `שלום, ${fmtUserName(currentUser) || currentUser.nickname || currentUser.name} 👋`;
    if (dateL) dateL.textContent = now.toLocaleDateString('he-IL', { weekday:'long', day:'numeric', month:'long' });

    // ─ סטטוס החתמה ─
    try {
        const stRes  = await fetch(`${API}/timeclock/status?userId=${currentUser.id}`);
        const stData = await stRes.json();
        const punchEl  = document.getElementById('emp-punch-status');
        const shiftEl  = document.getElementById('emp-shift-label');
        if (punchEl) {
            if (stData.punch_in && !stData.punch_out) {
                const since = new Date(stData.punch_in);
                const hrs   = ((now - since) / 3600000).toFixed(1);
                punchEl.textContent = `✅ בעבודה כבר ${hrs} שעות`;
                punchEl.className   = 'text-[10px] text-emerald-600 font-bold';
            } else if (stData.punch_out) {
                punchEl.textContent = 'יציאה מוקלטת ✓';
                punchEl.className   = 'text-[10px] text-slate-500';
            } else {
                punchEl.textContent = '⚠️ לא החתמת כניסה';
                punchEl.className   = 'text-[10px] text-red-500 font-bold';
            }
        }
        if (shiftEl) shiftEl.textContent = stData.punch_in ? `כניסה: ${new Date(stData.punch_in).toLocaleTimeString('he-IL', {hour:'2-digit', minute:'2-digit'})}` : 'לא בשמרת פעילה';
    } catch(e) {
        const punchEl = document.getElementById('emp-punch-status');
        if (punchEl) punchEl.textContent = 'לא זמין';
    }

    // ─ משימות אישיות להיום ─
    const tasksList = document.getElementById('emp-tasks-list');
    if (tasksList) {
        const todayStr = now.toDateString();
        const myTasks  = (allTasks || []).filter(t => {
            if (t.status === 'approved' || t.status === 'cancelled') return false;
            if (t.assigned_to && t.assigned_to !== currentUser?.id) return false;
            const due = t.deadline ? new Date(t.deadline) : null;
            return due && (due.toDateString() === todayStr || due < now);
        });
        if (myTasks.length === 0) {
            tasksList.innerHTML = `<div class="px-4 py-4 text-xs text-slate-400 text-center">אין משימות לסגירה היום 🎉</div>`;
        } else {
            tasksList.innerHTML = myTasks.slice(0, 6).map(t => {
                const overdue = t.deadline && new Date(t.deadline) < now && new Date(t.deadline).toDateString() !== todayStr;
                const icon    = t.status === 'completed' ? '✅' : overdue ? '🔴' : '⬜';
                return `<div class="flex items-center gap-3 px-4 py-3 cursor-pointer hover:bg-slate-50 active:opacity-70 transition"
                             onclick="switchTab('tasks')">
                  <span class="text-base flex-shrink-0">${icon}</span>
                  <div class="flex-1 min-w-0">
                    <div class="text-xs font-bold text-slate-700 truncate">${t.title}</div>
                    ${overdue ? `<div class="text-[10px] text-red-500">עבר דד-ליין</div>` : ''}
                  </div>
                </div>`;
            }).join('');
        }
    }

    // ─ פאנל "מה מחכה לך" — כמו מנהל, עם אפשרות סגירה ─
    renderUrgentItems();
}

window.renderDashboard = async function(forceRefresh = false) {
    const isEmployee = currentUser?.role === 'MEMBER' || currentUser?.role === 'SENIOR';
    if (isEmployee) { await renderEmployeeDashboard(); return; }

    // For admin/owner in sport business, render sport dashboard into content-feed
    if (currentUser?.role === 'ADMIN' && currentGroup?.business_type === 'sport') {
        if (window._sportScreenActive || window._sportDashRendering) return;
        window._sportDashRendering = true;
        // Show content-feed directly — avoid calling switchTab which re-triggers renderDashboard
        ['timeclock','shifts','calendar','shop','pantry','equipment','sales','pos','foodcost',
         'customers','bank','cashflow','budget','forecast','tasks','deliveries','academy',
         'community','members','surveys','role-dashboard'].forEach(x => {
            const el = document.getElementById(`content-${x}`); if (el) el.classList.add('hidden');
        });
        const feedEl = document.getElementById('content-feed');
        if (feedEl) feedEl.classList.remove('hidden');
        const feedBtn = document.getElementById('tab-feed');
        if (feedBtn) { document.querySelectorAll('[id^="tab-"]').forEach(b => b.classList.remove('tab-active')); feedBtn.classList.add('tab-active'); }
        ['tour-balance-card','quick-tiles','admin-kpi-cards'].forEach(id => {
            const el = document.getElementById(id); if (el) el.classList.add('hidden');
        });
        if (feedEl) {
            await renderSportDashboard(feedEl);
            try { await renderBizFlowWidget(); } catch(e) {}
            if (window._roleDashInterval) clearInterval(window._roleDashInterval);
            window._roleDashInterval = setInterval(() => {
                if (window._sportScreenActive) return;
                const feed = document.getElementById('content-feed');
                if (feed && !feed.classList.contains('hidden') && currentGroup?.business_type === 'sport') {
                    renderSportDashboard(feed);
                } else { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            }, 30000);
        }
        window._sportDashRendering = false;
        return;
    }

    // For admin/owner in beauty business, render beauty dashboard
    if (currentUser?.role === 'ADMIN' && currentGroup?.business_type === 'beauty') {
        if (window._beautyDashRendering) return;
        window._beautyDashRendering = true;
        let dashEl = document.getElementById('content-role-dashboard');
        if (!dashEl) {
            const container = document.getElementById('biz-main-content-wrap');
            if (container) { dashEl = document.createElement('div'); dashEl.id = 'content-role-dashboard'; dashEl.className = 'px-2'; container.appendChild(dashEl); }
        }
        if (dashEl) {
            dashEl.classList.remove('hidden');
            dashEl.style.position = 'relative'; dashEl.style.zIndex = '1';
            const feedEl = document.getElementById('content-feed');
            if (feedEl) feedEl.classList.add('hidden');
            ['tour-balance-card','quick-tiles','admin-kpi-cards'].forEach(id => { const el = document.getElementById(id); if (el) el.classList.add('hidden'); });
            await renderBeautyAdminDashboard(dashEl);
            try { await renderBizFlowWidget(); } catch(e) {}
            if (window._roleDashInterval) { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            window._roleDashInterval = setInterval(async () => {
                const el = document.getElementById('content-role-dashboard');
                if (el && !el.classList.contains('hidden') && currentGroup?.business_type === 'beauty') {
                    await renderBeautyAdminDashboard(el);
                    try { await renderBizFlowWidget(); } catch(e) {}
                } else { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            }, 30000);
        }
        window._beautyDashRendering = false;
        return;
    }

    // For admin/owner in logistics business
    if (currentUser?.role === 'ADMIN' && currentGroup?.business_type === 'logistics') {
        if (window._logisticsDashRendering) return;
        window._logisticsDashRendering = true;
        let dashEl = document.getElementById('content-role-dashboard');
        if (!dashEl) {
            const container = document.getElementById('biz-main-content-wrap');
            if (container) { dashEl = document.createElement('div'); dashEl.id = 'content-role-dashboard'; dashEl.className = 'px-2'; container.appendChild(dashEl); }
        }
        if (dashEl) {
            dashEl.classList.remove('hidden');
            dashEl.style.position = 'relative'; dashEl.style.zIndex = '1';
            const feedEl = document.getElementById('content-feed');
            if (feedEl) feedEl.classList.add('hidden');
            ['tour-balance-card','quick-tiles','admin-kpi-cards'].forEach(id => { const el = document.getElementById(id); if (el) el.classList.add('hidden'); });
            await renderLogisticsAdminDashboard(dashEl);
            try { await renderBizFlowWidget(); } catch(e) {}
            if (window._roleDashInterval) { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            window._roleDashInterval = setInterval(async () => {
                const el = document.getElementById('content-role-dashboard');
                if (el && !el.classList.contains('hidden') && currentGroup?.business_type === 'logistics') {
                    await renderLogisticsAdminDashboard(el);
                    try { await renderBizFlowWidget(); } catch(e) {}
                } else { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            }, 30000);
        }
        window._logisticsDashRendering = false;
        return;
    }

    // For non-admin in logistics business — Driver Companion view
    if (currentGroup?.business_type === 'logistics' && ['MEMBER','EMPLOYEE','MANAGER','SENIOR'].includes(currentUser?.role)) {
        if (window._logisticsDriverDashRendering) return;
        window._logisticsDriverDashRendering = true;
        let dashEl = document.getElementById('content-role-dashboard');
        if (!dashEl) {
            const container = document.getElementById('biz-main-content-wrap');
            if (container) { dashEl = document.createElement('div'); dashEl.id = 'content-role-dashboard'; dashEl.className = 'px-2'; container.appendChild(dashEl); }
        }
        if (dashEl) {
            dashEl.classList.remove('hidden');
            const feedEl = document.getElementById('content-feed');
            if (feedEl) feedEl.classList.add('hidden');
            ['tour-balance-card','quick-tiles','admin-kpi-cards'].forEach(id => { const el = document.getElementById(id); if (el) el.classList.add('hidden'); });
            await renderLogisticsDriverDashboard(dashEl);
            try { await renderBizFlowWidget(); } catch(e) {}
            if (window._roleDashInterval) { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            window._roleDashInterval = setInterval(async () => {
                const el = document.getElementById('content-role-dashboard');
                if (el && !el.classList.contains('hidden') && currentGroup?.business_type === 'logistics') {
                    await renderLogisticsDriverDashboard(el);
                    try { await renderBizFlowWidget(); } catch(e) {}
                } else { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            }, 60000);
        }
        window._logisticsDriverDashRendering = false;
        return;
    }

    // For admin/owner in maintenance_repair business, show service calls dashboard
    if (currentUser?.role === 'ADMIN' && currentGroup?.business_type === 'maintenance_repair' && !window._inProcurementMode) {
        let dashEl = document.getElementById('content-role-dashboard');
        if (!dashEl) {
            const container = document.getElementById('biz-main-content-wrap');
            if (container) {
                dashEl = document.createElement('div');
                dashEl.id = 'content-role-dashboard';
                dashEl.className = 'px-2';
                container.appendChild(dashEl);
            }
        }
        if (dashEl) {
            dashEl.classList.remove('hidden');
            dashEl.style.position = 'relative';
            dashEl.style.zIndex = '1';
            const feedEl = document.getElementById('content-feed');
            if (feedEl) feedEl.classList.add('hidden');
            await renderBranchManagerMaintenanceDashboard(dashEl);
            try { await renderBizFlowWidget(); } catch(e) {}
            if (window._roleDashInterval) { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            window._roleDashInterval = setInterval(async () => {
                const el = document.getElementById('content-role-dashboard');
                if (el && !el.classList.contains('hidden')) {
                    await renderBranchManagerMaintenanceDashboard(el);
                    try { await renderBizFlowWidget(); } catch(e) {}
                } else { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            }, 20000);
        }
        return;
    }

    // Professional business type custom dashboard
    if (currentGroup?.business_type === 'professional' && !window._profDashRendering) {
        window._profDashRendering = true;
        let dashEl = document.getElementById('content-role-dashboard');
        if (!dashEl) {
            const container = document.getElementById('biz-main-content-wrap');
            if (container) { dashEl = document.createElement('div'); dashEl.id = 'content-role-dashboard'; dashEl.className = 'px-2'; container.appendChild(dashEl); }
        }
        if (dashEl) {
            dashEl.classList.remove('hidden');
            dashEl.style.position = 'relative'; dashEl.style.zIndex = '1';
            const feedEl = document.getElementById('content-feed');
            if (feedEl) feedEl.classList.add('hidden');
            ['tour-balance-card','quick-tiles','admin-kpi-cards'].forEach(id => { const el = document.getElementById(id); if (el) el.classList.add('hidden'); });
            await renderProfessionalDashboard(dashEl);
            try { await renderBizFlowWidget(); } catch(e) {}
            if (window._roleDashInterval) { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            window._roleDashInterval = setInterval(async () => {
                const el = document.getElementById('content-role-dashboard');
                if (el && !el.classList.contains('hidden') && currentGroup?.business_type === 'professional') {
                    await renderProfessionalDashboard(el);
                    try { await renderBizFlowWidget(); } catch(e) {}
                } else { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
            }, 60000);
        }
        window._profDashRendering = false;
        return;
    }

    // עטיפת גריד FLOW תחילה (sync) — לפני הצגת tour-balance-card, מונע פלאש גודל
    renderBizFlowWidget().catch(()=>{});
    // הצג מחדש כרטיסי מנהל — כבר בתוך גריד, אין מתיחה
    ['tour-balance-card','quick-tiles','admin-kpi-cards'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.remove('hidden');
    });
    ['emp-home-header','emp-home-footer'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.add('hidden');
    });

    try {
        // Header
        const greetEl = document.getElementById('dash-greeting');
        const dateEl  = document.getElementById('dash-date');
        if (greetEl && currentUser) greetEl.textContent = `שלום, ${fmtUserName(currentUser) || currentUser.nickname || currentUser.name} 👋`;
        if (dateEl) {
            const now = new Date();
            dateEl.textContent = now.toLocaleDateString('he-IL', { weekday:'long', day:'numeric', month:'long' });
        }

        // Load store orders if not yet loaded
        if (forceRefresh || !storeOrdersCache || storeOrdersCache.length === 0) {
            try { await window.fetchStoreOrders(); } catch(e) {}
        }

        // KPI calculations
        const now = new Date();
        let salesToday = 0, ordersToday = 0, openOrders = 0, revenueMonth = 0;
        const thisMonth = now.getMonth(), thisYear = now.getFullYear();
        (storeOrdersCache || []).forEach(o => {
            if (o.status === 'cancelled') return;
            const d = new Date(o.created_at);
            const amt = parseFloat(o.total_amount) || parseFloat(o.total) || 0;
            const done = o.status === 'completed' || o.status === 'shipped';
            const isToday = d.getDate()===now.getDate() && d.getMonth()===thisMonth && d.getFullYear()===thisYear;
            const isThisMonth = d.getMonth()===thisMonth && d.getFullYear()===thisYear;
            if (isToday) { ordersToday++; if (done) salesToday += amt; }
            if (isThisMonth && done) revenueMonth += amt;
            if (!done) openOrders++;
        });
        const openTasks   = (allTasks || []).filter(t => t.status === 'pending').length;

        // Count only employees scheduled for today who checked in
        let activeStaff = 0;
        let missingStaff = [];
        try {
            const tcRes = await fetch(`${API}/timeclock/report?groupId=${currentGroup.id}&userId=all`);
            if (tcRes.ok) {
                const tcData = await tcRes.json();
                const todayStr2 = now.toDateString();
                const todayPunches = tcData.filter(p => p.punch_in && new Date(p.punch_in).toDateString() === todayStr2);
                const punchedIds = new Set(todayPunches.map(p => p.user_id));

                // Get today's scheduled shifts from tasks with "SHIFT|" prefix
                const todayDateStr = now.toISOString().split('T')[0];
                const todayShifts = (allTasks || []).filter(t =>
                    t.title && t.title.startsWith('SHIFT|') &&
                    t.title.includes(todayDateStr) &&
                    (t.status === 'approved' || t.status === 'completed' || t.status === 'pending')
                );
                const scheduledEmployeeIds = new Set(todayShifts.map(s => s.assigned_to));

                // Count active staff only among scheduled employees
                activeStaff = Array.from(scheduledEmployeeIds).filter(id => punchedIds.has(id)).length;
                // Missing staff: scheduled but didn't punch in
                missingStaff = Array.from(scheduledEmployeeIds).filter(id => !punchedIds.has(id));
                // Convert IDs to member names for display
                missingStaff = missingStaff.map(id =>
                    (membersCache || []).find(m => m.id === id) || { id, nickname: '?' }
                );
            }
        } catch(e) {
            // Fallback: if fetching shifts fails, don't show warning
            activeStaff = 0;
            missingStaff = [];
        }

        // Balance: sum all cashflow transactions
        let totalIncome = 0, totalExpense = 0;
        (allTransactions || []).forEach(t => {
            const amt = parseFloat(t.amount) || 0;
            if (t.type === 'income') totalIncome += amt; else totalExpense += amt;
        });
        const netBalance = totalIncome - totalExpense;

        const s = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
        s('kpi-sales-today',   `₪${salesToday.toLocaleString('he-IL', {maximumFractionDigits:0})}`);
        s('kpi-orders-today',  `${ordersToday} הזמנות היום`);
        s('kpi-active-staff',  activeStaff);

        const staffStatusEl = document.getElementById('kpi-staff-status');
        if (staffStatusEl) {
            if (missingStaff.length > 0) {
                staffStatusEl.textContent = `${activeStaff} בצוות, ${missingStaff.length} לא החתימו`;
            } else {
                staffStatusEl.textContent = `${activeStaff} בצוות`;
            }
        }

        s('kpi-open-orders',   openOrders);
        s('kpi-open-tasks',    openTasks);
        s('kpi-revenue-month', `₪${revenueMonth.toLocaleString('he-IL', {maximumFractionDigits:0})}`);

        // Alerts: low stock (qty ≤ 2)
        const lowStock = (pantryCache || []).filter(p => parseFloat(p.quantity) <= 2);

        // === KPIs ייחודיים למסעדה/בית קפה ===
        const restKpiDiv = document.getElementById('restaurant-kpi-cards');
        if (restKpiDiv) {
            const isRest = ['restaurant','cafe'].includes(currentGroup?.business_type);
            restKpiDiv.classList.toggle('hidden', !isRest);
            if (isRest) {
                // משלוחים בדרך
                const inTransit = (storeOrdersCache || []).filter(o => o.status === 'shipped').length;
                s('kpi-deliveries-transit', inTransit);
                // ממוצע להזמנה (החודש)
                const monthOrders = (storeOrdersCache || []).filter(o => {
                    const d = new Date(o.created_at);
                    return d.getMonth() === thisMonth && d.getFullYear() === thisYear && !['cancelled','quote'].includes(o.status);
                });
                const avgPerOrder = monthOrders.length > 0 ? Math.round(revenueMonth / monthOrders.length) : 0;
                // ממוצע דירוג לקוחות
                const ratedOrders = (storeOrdersCache || []).filter(o => o.customer_rating > 0);
                const avgRating = ratedOrders.length > 0
                    ? (ratedOrders.reduce((sum, o) => sum + parseFloat(o.customer_rating), 0) / ratedOrders.length).toFixed(1)
                    : '—';
                s('kpi-avg-rating', avgRating !== '—' ? avgRating + ' ⭐' : '—');
                // הזמנות שולחן ממתינות
                const pendingRes = (calEventsCache || []).filter(e => e.call_type === 'table_reservation' && e.status === 'pending').length;
                s('kpi-pending-reservations', pendingRes);
                window._pendingCalCount = pendingRes;
                s('kpi-avg-per-order', `₪${avgPerOrder.toLocaleString('he-IL')}`);
                // מלאי נמוך (כמות)
                s('kpi-low-stock-count', lowStock.length);
                // Food Cost % מתוך foodCostData אם טעון
                const fcEl = document.getElementById('kpi-food-cost-pct');
                if (fcEl) {
                    if (typeof foodCostData !== 'undefined' && foodCostData?.length > 0) {
                        const withCost = foodCostData.filter(i => i.costs?.foodCostPct > 0);
                        if (withCost.length > 0) {
                            const avgFC = withCost.reduce((a, i) => a + i.costs.foodCostPct, 0) / withCost.length;
                            fcEl.textContent = `${avgFC.toFixed(1)}%`;
                            fcEl.className = `text-2xl font-black ${avgFC < 30 ? 'text-white' : avgFC < 40 ? 'text-yellow-200' : 'text-red-200'}`;
                        } else { fcEl.textContent = 'לא מחושב'; }
                    } else { fcEl.textContent = '—'; }
                }
            }
        }

        // Balance banner — keep white text on blue card; add subtle indicator via prefix
        const balEl = document.getElementById('user-balance');
        if (balEl) {
            const prefix = netBalance > 0 ? '+' : netBalance < 0 ? '-' : '';
            balEl.textContent = `${prefix}₪${Math.abs(netBalance).toLocaleString('he-IL', {maximumFractionDigits:0})}`;
            // Keep font-size large; add subtle color hint for negative
            balEl.className = `text-5xl font-bold tracking-tight${netBalance < 0 ? ' text-red-200' : ''}`;
        }

        // Alerts: low stock (qty ≤ 2)
        const alertsBox  = document.getElementById('dashboard-alerts');
        const alertsList = document.getElementById('dashboard-alerts-list');
        if (alertsBox && alertsList) {
            if (lowStock.length > 0) {
                alertsList.innerHTML = lowStock.slice(0,5).map(p =>
                    `<div class="flex items-center gap-2 text-xs text-amber-900">
                       <i class="fa-solid fa-box-open text-amber-400 w-4 text-center"></i>
                       <span><strong>${p.item_name}</strong> — נותרו ${parseFloat(p.quantity)} ${p.unit||'יח׳'}</span>
                     </div>`
                ).join('');
                alertsBox.classList.remove('hidden');
            } else {
                alertsBox.classList.add('hidden');
            }
        }

        // ★ Urgent items panel
        renderUrgentItems();

        // ★ pending store orders for restaurant/cafe admin (same view as waiter, auto-polled)
        if (['restaurant','cafe'].includes(currentGroup?.business_type)) {
            try { await renderRestaurantPendingOrders(); } catch(e) {}
            try { window.renderPendingTableReservations(); } catch(e) {}
            startAdminPendingOrdersPolling();
        }

        // ★ קריאות שירות ממשפחות (maintenance_repair + שירותים)
        try { renderFamilyServiceCallsSection(); } catch(e) {}

        // ★ Sparklines
        try { renderSparklines(); } catch(e) {}

        // ★ FLOW balance widget (מנהלים בלבד)
        try { await renderBizFlowWidget(); } catch(e) {}

    } catch(err) { console.error('renderDashboard:', err); }
};

async function renderFamilyServiceCallsSection() {
    const bizType = currentGroup?.business_type;
    if (!['maintenance_repair','construction','services','healthcare','beauty'].includes(bizType)) return;
    const containerId = 'family-service-calls-section';
    let section = document.getElementById(containerId);
    if (!section) {
        const urgentSection = document.getElementById('urgent-items-section');
        if (!urgentSection) return;
        section = document.createElement('div');
        section.id = containerId;
        section.className = 'mb-4';
        urgentSection.parentNode.insertBefore(section, urgentSection.nextSibling);
    }
    try {
        const r = await fetch(`/api/service-calls/family/${currentGroup.id}`);
        const d = await r.json();
        const calls = d.calls || [];
        if (!calls.length) { section.innerHTML = ''; return; }
        const sevColors = { low:'bg-slate-100 text-slate-600', medium:'bg-amber-100 text-amber-700', high:'bg-orange-100 text-orange-700', critical:'bg-red-100 text-red-700' };
        const sevLabels = { low:'נמוכה', medium:'בינונית', high:'גבוהה', critical:'קריטית' };
        section.innerHTML = `<div class="bg-white rounded-2xl shadow-sm border border-orange-100 overflow-hidden">
            <div class="flex items-center justify-between px-4 py-3 bg-orange-50 border-b border-orange-100">
                <h3 class="font-black text-orange-800 text-sm flex items-center gap-2">🔧 קריאות שירות ממשפחות <span class="bg-orange-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full">${calls.length}</span></h3>
            </div>
            <div class="divide-y divide-slate-50">${calls.slice(0,5).map(c => `
                <div class="flex items-start gap-3 px-4 py-3">
                    <div class="flex-1 min-w-0">
                        <div class="flex items-center gap-1.5 flex-wrap">
                            <span class="font-bold text-slate-800 text-sm truncate">${safeStr(c.title)}</span>
                            <span class="text-[10px] px-1.5 py-0.5 rounded-full font-bold ${sevColors[c.severity]||'bg-slate-100 text-slate-600'}">${sevLabels[c.severity]||c.severity}</span>
                        </div>
                        <p class="text-[11px] text-slate-400">${safeStr(c.family_name||'')} · ${new Date(c.created_at).toLocaleDateString('he-IL')}</p>
                        ${c.scheduled_date ? `<p class="text-[10px] text-indigo-500 font-bold"><i class="fa-solid fa-calendar-check ml-1"></i>${new Date(c.scheduled_date).toLocaleString('he-IL',{dateStyle:'short',timeStyle:'short'})}</p>` : ''}
                        ${c.description ? `<p class="text-[11px] text-slate-500 truncate">${safeStr(c.description)}</p>` : ''}
                    </div>
                </div>`).join('')}
            </div>
        </div>`;
    } catch(e) { section.innerHTML = ''; }
}

// ── pending orders for restaurant/cafe admin main dashboard ────────────────
window.renderRestaurantPendingOrders = async function() {
    const bizType = currentGroup?.business_type;
    if (!['restaurant','cafe'].includes(bizType)) return;

    const containerId = 'admin-pending-orders-section';
    let section = document.getElementById(containerId);
    if (!section) {
        const urgentSection = document.getElementById('urgent-items-section');
        if (!urgentSection) return;
        section = document.createElement('div');
        section.id = containerId;
        section.className = 'mb-4 px-2';
        urgentSection.parentNode.insertBefore(section, urgentSection);
    }

    let pendingOrders = [];
    try {
        const or = await fetch(`${API}/store/orders/${currentGroup.id}`);
        const od = await or.json();
        if (Array.isArray(od)) {
            od.filter(o => o.status === 'pending_approval').forEach(o => {
                let items = [];
                try { items = (Array.isArray(o.items) ? o.items : JSON.parse(o.items||'[]')).filter(i => !i.is_quote_metadata && !(i.name && i.name.startsWith('DELIVERY_META|'))); } catch(e) {}
                const isDeliv = o.is_delivery == 1 || o.is_delivery === true || o.is_delivery === 'true';
                pendingOrders.push({ orderId: o.id, items, customerName: o.customer_name, customerPhone: o.customer_phone, deliveryDetails: o.delivery_details, isDelivery: isDeliv, totalAmount: o.total_amount });
            });
        }
    } catch(e) {}

    if (!pendingOrders.length) { section.innerHTML = ''; return; }

    section.innerHTML = `<div class="bg-white rounded-2xl shadow-sm border border-orange-300 overflow-hidden">
        <div class="px-4 py-3 border-b border-orange-200 bg-orange-50/80 flex items-center gap-2">
            <h3 class="font-black text-orange-700 text-sm flex-1">📋 ממתין לאישורך — הזמנות חדשות</h3>
            <span class="bg-orange-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full">${pendingOrders.length}</span>
        </div>
        <div class="divide-y divide-slate-50">${pendingOrders.map(r => {
            let dd = {};
            try { dd = typeof r.deliveryDetails === 'string' ? JSON.parse(r.deliveryDetails) : (r.deliveryDetails || {}); } catch(e) {}
            const addr = [dd.street, dd.house, dd.city].filter(Boolean).join(' ');
            const dishList = (r.items||[]).map(i => {
                const nm = i.name || '';
                const qty = (i.quantity||i.qty||1);
                return nm ? (qty > 1 ? `${nm} ×${qty}` : nm) : null;
            }).filter(Boolean).join(', ');
            const typeBadge = r.isDelivery
                ? '<span class="text-[9px] font-black text-orange-600 bg-orange-100 px-1.5 py-0.5 rounded-full ml-1">🛵 משלוח</span>'
                : '<span class="text-[9px] font-black text-blue-600 bg-blue-100 px-1.5 py-0.5 rounded-full ml-1">🚗 איסוף</span>';
            const totalStr = r.totalAmount ? `<span class="text-[10px] font-black text-green-700 ml-1">₪${parseFloat(r.totalAmount).toFixed(0)}</span>` : '';
            return `<div class="flex items-start gap-2 px-4 py-3">
                <div class="flex-1 min-w-0">
                    <div class="flex items-center gap-1 mb-0.5"><span class="text-xs font-black text-orange-700 bg-orange-100 px-1.5 py-0.5 rounded-full">#${r.orderId}</span>${typeBadge}<span class="text-xs font-black text-slate-800">${safeStr(r.customerName || '')} ${totalStr}</span></div>
                    ${r.customerPhone ? `<div class="text-[10px] text-slate-500 mb-0.5">📞 ${safeStr(r.customerPhone)}</div>` : ''}
                    <div class="text-[10px] text-slate-500">${safeStr(dishList) || '—'}</div>
                    ${addr ? `<div class="text-[10px] text-indigo-600">📍 ${safeStr(addr)}</div>` : ''}
                </div>
                <div class="flex flex-col gap-1 shrink-0">
                    <button ontouchend="event.preventDefault();approveDeliveryToKitchen(${r.orderId});" onclick="approveDeliveryToKitchen(${r.orderId})" class="bg-green-600 text-white text-[10px] font-black px-2 py-1.5 rounded-lg whitespace-nowrap" style="touch-action:manipulation;">✅ אשר לטבח</button>
                    <button ontouchend="event.preventDefault();rejectStoreOrder(${r.orderId});" onclick="rejectStoreOrder(${r.orderId})" class="bg-red-100 text-red-700 text-[10px] font-black px-2 py-1.5 rounded-lg whitespace-nowrap" style="touch-action:manipulation;">❌ דחה</button>
                </div>
            </div>`;
        }).join('')}</div>
    </div>`;
};

// ── הזמנות שולחן ממתינות לאישור — מוצג בדשבורד הראשי ────────────────
window.renderPendingTableReservations = function() {
    const bizType = currentGroup?.business_type;
    if (!['restaurant','cafe'].includes(bizType)) return;

    const containerId = 'dashboard-pending-table-res';
    let section = document.getElementById(containerId);
    if (!section) {
        const urgentSection = document.getElementById('urgent-items-section');
        if (!urgentSection) return;
        section = document.createElement('div');
        section.id = containerId;
        section.className = 'mb-4 px-2';
        urgentSection.parentNode.insertBefore(section, urgentSection);
    }

    const pending = (calEventsCache || []).filter(e => e.call_type === 'table_reservation' && e.status === 'pending');
    if (!pending.length) { section.innerHTML = ''; return; }

    const fmtDate = d => {
        if (!d) return '';
        const dt = new Date(String(d).split('T')[0] + 'T12:00:00');
        return dt.toLocaleDateString('he-IL', { weekday: 'short', day: 'numeric', month: 'numeric' });
    };

    section.innerHTML = `<div class="bg-white rounded-2xl shadow-sm border border-blue-300 overflow-hidden">
        <div class="px-4 py-3 border-b border-blue-200 bg-blue-50/80 flex items-center gap-2">
            <h3 class="font-black text-blue-700 text-sm flex-1">📅 הזמנות שולחן ממתינות לאישור</h3>
            <span class="bg-blue-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full">${pending.length}</span>
        </div>
        <div class="divide-y divide-slate-50">${pending.map(e => {
            const dateStr = `${fmtDate(e.event_date)} · ${String(e.start_time||'').slice(0,5)}`;
            return `<div class="flex items-center gap-3 px-4 py-3">
                <div class="flex-1 min-w-0">
                    <div class="text-xs font-black text-slate-800 truncate">${safeStr(e.title||'הזמנת שולחן')}</div>
                    <div class="text-[10px] text-slate-500">${dateStr}${e.num_guests ? ` · ${e.num_guests} סועדים` : ''}</div>
                    ${e.customer_phone ? `<div class="text-[10px] text-slate-400">📞 ${safeStr(e.customer_phone)}</div>` : ''}
                    ${e.notes ? `<div class="text-[10px] text-indigo-600 truncate">💬 ${safeStr(e.notes)}</div>` : ''}
                </div>
                <div class="flex flex-col gap-1 shrink-0">
                    <button ontouchend="event.preventDefault();approveCalendarEvent(${e.id});" onclick="approveCalendarEvent(${e.id})" class="bg-green-600 text-white text-[10px] font-black px-2 py-1.5 rounded-lg whitespace-nowrap" style="touch-action:manipulation;">✅ אשר</button>
                    <button ontouchend="event.preventDefault();switchTab('calendar');setTimeout(()=>typeof switchCalendarTab==='function'&&switchCalendarTab('requests'),200);" onclick="switchTab('calendar');setTimeout(()=>typeof switchCalendarTab==='function'&&switchCalendarTab('requests'),200)" class="bg-slate-100 text-slate-600 text-[10px] font-black px-2 py-1.5 rounded-lg whitespace-nowrap" style="touch-action:manipulation;">פרטים</button>
                </div>
            </div>`;
        }).join('')}</div>
    </div>`;
};

// ── URGENT ITEMS — "מה מחכה לך עכשיו" ─────────────────────────
async function renderUrgentItems() {
    const section = document.getElementById('urgent-items-section');
    const list    = document.getElementById('urgent-items-list');
    const badge   = document.getElementById('urgent-count-badge');
    if (!section || !list || !currentGroup) return;

    const isAdmin   = currentUser?.role === 'ADMIN';
    const isManager = currentUser?.role === 'MANAGER';
    const isSenior  = currentUser?.role === 'SENIOR';
    const isMember  = currentUser?.role === 'MEMBER';
    const now       = new Date();
    const todayStr  = now.toDateString();
    const items     = [];

    if (isAdmin || isManager) {
        // ─ התראות גביה — תחנות שמועד פירעונן הגיע ─
        try {
            const colRes = await fetch(`${API}/work-orders/collection-alerts/${currentGroup.id}`);
            const colData = await colRes.json();
            if (colData.success && colData.alerts?.length > 0) {
                const al = colData.alerts;
                const totalDue = al.reduce((s, a) => s + parseFloat(a.amount || 0), 0);
                items.push({ icon:'💳', urgency:'high',
                    title:`${al.length} תחנות גביה ממתינות לטיפול`,
                    sub:`סה"כ לגביה: ₪${totalDue.toLocaleString('he-IL', {maximumFractionDigits:0})}`,
                    tab:'cashflow', actionLabel:'לגביה' });
            }
        } catch(e) {}

        // ─ הזמנות ממתינות מעל שעתיים ─
        const oldOrders = (storeOrdersCache || []).filter(o => {
            if (o.status !== 'new') return false;
            return (now - new Date(o.created_at)) / 3600000 >= 2;
        });
        if (oldOrders.length > 0) {
            const hrs = Math.floor((now - new Date(oldOrders[0].created_at)) / 3600000);
            items.push({ icon:'🚨', urgency:'high',
                title:`${oldOrders.length} הזמנות ממתינות לטיפול`,
                sub:`הישנה: ${hrs} שעות ללא מענה`,
                tab:'sales', actionLabel:'טפל' });
        }

        // ─ עובדים מתוזמנים ללא החתמת כניסה — fetch lightweight ─
        try {
            const tcRes = await fetch(`${API}/timeclock/report?groupId=${currentGroup.id}&userId=all`);
            const tcData = await tcRes.json();
            const todayPunches = tcData.filter(p => new Date(p.punch_in).toDateString() === todayStr);
            const punchedIds = new Set(todayPunches.map(p => p.user_id));

            // Get today's scheduled shifts from tasks with "SHIFT|" prefix
            const todayDateStr = now.toISOString().split('T')[0];
            const todayShifts = (allTasks || []).filter(t =>
                t.title && t.title.startsWith('SHIFT|') &&
                t.title.includes(todayDateStr) &&
                (t.status === 'approved' || t.status === 'completed' || t.status === 'pending')
            );
            const scheduledEmployeeIds = new Set(todayShifts.map(s => s.assigned_to));

            // Only count missing staff among scheduled employees
            const missing = Array.from(scheduledEmployeeIds)
                .filter(id => !punchedIds.has(id))
                .map(id => (membersCache || []).find(m => m.id === id) || { id, nickname: '?' });

            if (missing.length > 0) {
                items.push({ icon:'👤', urgency:'medium',
                    title:`${missing.length} עובדים מתוזמנים לא החתימו כניסה היום`,
                    sub: missing.slice(0,3).map(m => m.nickname || m.name).join(', '),
                    tab:'timeclock', actionLabel:'צפה' });
            }
        } catch(e) {}

        // ─ הצעות מחיר פתוחות מעל 3 ימים ─
        const oldQuotes = (storeOrdersCache || []).filter(o => {
            if (o.status !== 'quote') return false;
            if (o.quote_status === 'approved' || o.quote_status === 'rejected') return false;
            return (now - new Date(o.created_at)) / 86400000 >= 3;
        });
        if (oldQuotes.length > 0) {
            items.push({ icon:'📄', urgency:'medium',
                title:`${oldQuotes.length} הצעות מחיר ממתינות מעל 3 ימים`,
                sub:`האחרונה: ${oldQuotes[0].customer_name || `#${oldQuotes[0].id}`}`,
                tab:'sales', actionLabel:'צפה' });
        }

        // ─ מלאי נמוך ─
        const lowStock = (pantryCache || []).filter(p => parseFloat(p.quantity) <= 2);
        if (lowStock.length > 0) {
            items.push({ icon:'📦', urgency:'low',
                title:`${lowStock.length} מוצרים מתחת למינימום`,
                sub: lowStock.slice(0,3).map(p => p.item_name).join(', '),
                tab:'pantry', actionLabel:'עדכן' });
        }

        // ─ משימות שעברו דד-ליין ─
        const overdue = (allTasks || []).filter(t =>
            t.status !== 'approved' && t.status !== 'cancelled' &&
            t.deadline && new Date(t.deadline) < now
        );
        if (overdue.length > 0) {
            items.push({ icon:'✅', urgency:'medium',
                title:`${overdue.length} משימות שעברו דד-ליין`,
                sub: overdue[0].title || '',
                tab:'tasks', actionLabel:'טפל' });
        }

        // ─ תחזוקת ציוד + תקלות ─
        try {
            const [eqMRes, eqFRes] = await Promise.all([
                fetch(`${API}/equipment/maintenance/${currentGroup.id}`),
                fetch(`${API}/equipment/faults/${currentGroup.id}`)
            ]);
            const eqMData = await eqMRes.json();
            const eqFData = await eqFRes.json();
            if (eqMData.success) {
                const today2 = new Date(); today2.setHours(0,0,0,0);
                const in7 = new Date(today2); in7.setDate(today2.getDate() + 7);
                const urgMaint = eqMData.records.filter(m => {
                    if (m.status === 'completed') return false;
                    if (!m.scheduled_date) return false;
                    const sd = new Date(m.scheduled_date); sd.setHours(0,0,0,0);
                    return sd <= in7;
                });
                if (urgMaint.length > 0) {
                    const lateMaint = urgMaint.filter(m => new Date(m.scheduled_date) < today2);
                    const firstLabel = urgMaint[0].description || MTYPE_LABELS[urgMaint[0].maintenance_type] || '';
                    items.push({ icon:'🔧', urgency: lateMaint.length > 0 ? 'high' : 'medium',
                        title:`${urgMaint.length} תחזוקות ממתינות${lateMaint.length > 0 ? ` (${lateMaint.length} באיחור)` : ''}`,
                        sub: firstLabel, tab:'equipment', actionLabel:'טפל' });
                }
            }
            if (eqFData.success) {
                const openFaults = eqFData.faults.filter(f => f.status !== 'resolved');
                if (openFaults.length > 0) {
                    const critFaults = openFaults.filter(f => f.severity === 'critical' || f.severity === 'high');
                    items.push({ icon:'⚠️', urgency: critFaults.length > 0 ? 'high' : 'medium',
                        title:`${openFaults.length} תקלות ציוד פתוחות`,
                        sub: openFaults[0].title || '', tab:'equipment', actionLabel:'טפל' });
                }
            }
        } catch(e) {}

    } else if (isSenior || isMember) {
        // ─ האם החתמתי כניסה היום ─
        try {
            const stRes = await fetch(`${API}/timeclock/status?userId=${currentUser.id}`);
            const stData = await stRes.json();
            if (!stData.punch_in) {
                items.push({ icon:'⏱', urgency:'high',
                    title:'לא החתמת כניסה היום',
                    sub:'לחץ להחתמה מהירה',
                    tab:'timeclock', actionLabel:'החתם עכשיו' });
            }
        } catch(e) {}

        // ─ משימות אישיות ליום זה ─
        const myTasks = (allTasks || []).filter(t => {
            if (t.status === 'approved' || t.status === 'cancelled') return false;
            if (t.assigned_to && t.assigned_to !== currentUser?.id) return false;
            const due = t.deadline ? new Date(t.deadline) : null;
            return due && (due.toDateString() === todayStr || due < now);
        });
        if (myTasks.length > 0) {
            items.push({ icon:'✅', urgency:'medium',
                title:`${myTasks.length} משימות שלך להיום`,
                sub: myTasks.slice(0,2).map(t => t.title).join(', '),
                tab:'tasks', actionLabel:'פתח' });
        }
    }

    if (items.length === 0) { section.classList.add('hidden'); return; }

    const C = {
        high:   { bg:'bg-red-50',   border:'border-red-100',   ibg:'bg-red-100',   txt:'text-red-600' },
        medium: { bg:'bg-amber-50', border:'border-amber-100', ibg:'bg-amber-100', txt:'text-amber-700' },
        low:    { bg:'bg-slate-50', border:'border-slate-100', ibg:'bg-slate-100', txt:'text-slate-500' }
    };

    list.innerHTML = items.map((item, i) => {
        const c = C[item.urgency] || C.low;
        const sep = i < items.length - 1 ? `border-b ${c.border}` : '';
        return `<div class="flex items-center gap-3 px-4 py-3 ${c.bg} ${sep} cursor-pointer active:opacity-70 transition-opacity"
                     onclick="switchTab('${item.tab}')">
          <div class="w-9 h-9 rounded-xl ${c.ibg} flex items-center justify-center flex-shrink-0 text-base">${item.icon}</div>
          <div class="flex-1 min-w-0">
            <div class="text-xs font-bold text-slate-800 leading-tight">${item.title}</div>
            <div class="text-[10px] text-slate-400 mt-0.5 truncate">${item.sub}</div>
          </div>
          <span class="text-[10px] font-bold ${c.txt} bg-white border ${c.border} rounded-full px-2.5 py-1 flex-shrink-0 whitespace-nowrap">${item.actionLabel} →</span>
        </div>`;
    }).join('');

    if (badge) badge.textContent = items.length;
    section.classList.remove('hidden');
}

// ── SPARKLINES ─────────────────────────────────────────────────
function buildSparklineSVG(data, stroke, w = 120, h = 28) {
    if (!data || data.length < 2) return '';
    const min = Math.min(...data), max = Math.max(...data);
    const range = max - min || 1;
    const pts = data.map((v, i) => {
        const x = (i / (data.length - 1)) * w;
        const y = h - 2 - ((v - min) / range) * (h - 6);
        return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(' ');
    return `<svg width="100%" height="${h}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">
        <polyline points="${pts}" fill="none" stroke="${stroke}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>`;
}

function renderSparklines() {
    const now = new Date();
    const days7 = Array.from({length: 7}, (_, i) => {
        const d = new Date(now); d.setDate(d.getDate() - (6 - i)); return d.toDateString();
    });

    // מכירות יומיות
    const salesByDay = days7.map(ds => (storeOrdersCache || []).filter(o =>
        (o.status === 'completed' || o.status === 'shipped') &&
        new Date(o.created_at).toDateString() === ds
    ).reduce((s, o) => s + (parseFloat(o.total_amount) || parseFloat(o.total) || 0), 0));

    // הזמנות פתוחות לפי יום (צבירה)
    const ordersByDay = days7.map(ds => (storeOrdersCache || []).filter(o =>
        o.status === 'new' && new Date(o.created_at).toDateString() <= ds
    ).length);

    // משימות פתוחות (פשוט — אותו מספר לכל יום, ניתן לשפר)
    const openTasksNow = (allTasks || []).filter(t => t.status === 'pending').length;
    const tasksByDay = days7.map((_, i) => Math.max(0, openTasksNow - (6 - i) * 0.3 | 0));

    // עובדים — קבוע (אין היסטוריה)
    const staffCount = (membersCache || []).filter(m => m.role !== 'ADMIN').length;
    const staffByDay = days7.map(() => staffCount);

    const sp = document.getElementById('spark-sales');
    if (sp) sp.innerHTML = buildSparklineSVG(salesByDay, 'rgba(255,255,255,0.8)');
    const so = document.getElementById('spark-orders');
    if (so) so.innerHTML = buildSparklineSVG(ordersByDay, '#f59e0b');
    const st = document.getElementById('spark-tasks');
    if (st) st.innerHTML = buildSparklineSVG(tasksByDay, '#f43f5e');
    const ss = document.getElementById('spark-staff');
    if (ss) ss.innerHTML = buildSparklineSVG(staffByDay, 'rgba(255,255,255,0.8)');
}

// ── GLOBAL SEARCH ───────────────────────────────────────────────
window.openGlobalSearch = function() {
    const modal = document.getElementById('global-search-modal');
    if (!modal) return;
    modal.classList.remove('hidden');
    setTimeout(() => document.getElementById('global-search-input')?.focus(), 100);
};

window.closeGlobalSearch = function() {
    const modal = document.getElementById('global-search-modal');
    if (modal) modal.classList.add('hidden');
    const inp = document.getElementById('global-search-input');
    if (inp) inp.value = '';
    const res = document.getElementById('global-search-results');
    if (res) res.innerHTML = '<div class="text-center text-slate-400 text-xs py-8">התחל להקליד לחיפוש...</div>';
};

window.runGlobalSearch = function(q) {
    const res = document.getElementById('global-search-results');
    if (!res) return;
    q = (q || '').trim().toLowerCase();
    if (q.length < 2) {
        res.innerHTML = '<div class="text-center text-slate-400 text-xs py-8">התחל להקליד לחיפוש...</div>';
        return;
    }

    const sections = [];

    // הזמנות
    const orders = (storeOrdersCache || []).filter(o =>
        (o.customer_name || '').toLowerCase().includes(q) ||
        String(o.id).includes(q) || (o.status || '').includes(q)
    ).slice(0, 5);
    if (orders.length) sections.push({
        title: '🛍️ הזמנות', tab: 'sales',
        items: orders.map(o => ({
            label: `הזמנה #${o.id} — ${o.customer_name || 'לא ידוע'}`,
            sub: `₪${parseFloat(o.total_amount || o.total || 0).toFixed(0)} · ${o.status}`,
            tab: 'sales'
        }))
    });

    // לקוחות
    const customers = (window.customersCache || []).filter(c =>
        (c.name || '').toLowerCase().includes(q) ||
        (c.phone || '').includes(q) || (c.email || '').toLowerCase().includes(q)
    ).slice(0, 5);
    if (customers.length) sections.push({
        title: '🤝 לקוחות',
        items: customers.map(c => ({ label: c.name, sub: c.phone || c.email || '', tab: 'customers' }))
    });

    // מוצרים / מלאי
    const products = (pantryCache || []).filter(p =>
        (p.item_name || '').toLowerCase().includes(q) ||
        (p.category || '').toLowerCase().includes(q)
    ).slice(0, 5);
    if (products.length) sections.push({
        title: '📦 מוצרים',
        items: products.map(p => ({ label: p.item_name, sub: `כמות: ${p.quantity} ${p.unit || ''}`, tab: 'pantry' }))
    });

    // עובדים
    const staff = (membersCache || []).filter(m =>
        (m.name || '').toLowerCase().includes(q) ||
        (m.nickname || '').toLowerCase().includes(q) ||
        (m.email || '').toLowerCase().includes(q)
    ).slice(0, 5);
    if (staff.length) sections.push({
        title: '👥 צוות',
        items: staff.map(m => ({ label: m.nickname || m.name, sub: m.role, tab: 'members' }))
    });

    // משימות
    const tasks = (allTasks || []).filter(t =>
        (t.title || '').toLowerCase().includes(q) ||
        (t.description || '').toLowerCase().includes(q)
    ).slice(0, 5);
    if (tasks.length) sections.push({
        title: '✅ משימות',
        items: tasks.map(t => ({ label: t.title, sub: t.status, tab: 'tasks' }))
    });

    if (sections.length === 0) {
        res.innerHTML = '<div class="text-center text-slate-400 text-xs py-8">לא נמצאו תוצאות</div>';
        return;
    }

    res.innerHTML = sections.map(sec => `
        <div class="mb-3">
          <div class="text-[10px] font-black text-slate-400 px-3 py-1.5 uppercase tracking-wide">${sec.title}</div>
          ${sec.items.map(item => `
            <div class="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-slate-50 cursor-pointer active:bg-slate-100 transition"
                 onclick="switchTab('${item.tab}'); closeGlobalSearch()">
              <div class="flex-1 min-w-0">
                <div class="text-xs font-bold text-slate-800 truncate">${item.label}</div>
                <div class="text-[10px] text-slate-400 truncate">${item.sub}</div>
              </div>
              <i class="fa-solid fa-arrow-left text-slate-300 text-xs flex-shrink-0"></i>
            </div>
          `).join('')}
        </div>
    `).join('');
};

// close search on Escape
document.addEventListener('keydown', e => {
    if (e.key === 'Escape') window.closeGlobalSearch?.();
});

function buildAndRenderFeed() {
    window.currentFeedPage = 1;
    feedCache = [];
    if (currentGroup && currentGroup.created_at) { feedCache.push({ type: 'system', id: 'sys_creation', user_id: 0, user_name: 'מערכת', date: new Date(currentGroup.created_at), title: 'סביבת עבודה עסקית נפתחה בהצלחה! 🎉', amount: 0, status: 'welcome' }); }

    if(Array.isArray(allTransactions)) {
        allTransactions.forEach(t => { feedCache.push({ type: 'transaction', id: t.id, user_id: t.user_id, user_name: t.user_name || currentUser.nickname, date: t.date ? new Date(t.date) : new Date(), title: t.description, amount: t.amount, isIncome: t.type === 'income', category: t.category }); });
    }

    if(Array.isArray(allTasks)) {
        allTasks.forEach(t => {
            if(t.title && !t.title.startsWith('SHIFT|')) {
                const statusLabel = t.status === 'pending' ? 'פתוח' : (t.status === 'done' ? 'ממתין לאישור' : 'הושלם');
                
                let displayTitle = t.title || 'ללא שם';
                let isSop = false;
                if (displayTitle.startsWith('SOP|')) {
                    isSop = true;
                    try {
                        const sopData = JSON.parse(displayTitle.substring(4));
                        displayTitle = sopData.title || 'נוהל עבודה';
                    } catch(e) {
                        displayTitle = displayTitle.split('|')[1] || 'נוהל עבודה';
                    }
                }
                const prefix = isSop ? 'נוהל' : 'משימה';

                feedCache.push({ type: 'task', id: `task_${t.id}`, user_id: t.assigned_to, user_name: t.assignee_name || currentUser.nickname, date: t.created_at ? new Date(t.created_at) : new Date(), title: `${prefix}: ${displayTitle} (${statusLabel})`, amount: t.reward || 0, status: t.status });
            }
        });
    }

    if(Array.isArray(bundlesCache)) {
        bundlesCache.forEach(b => { feedCache.push({ type: 'quiz', id: `quiz_${b.bundle_id}_${b.user_id || b.assigned_to_user || currentUser.id}`, user_id: b.user_id || b.assigned_to_user || currentUser.id, user_name: b.assignee_name || currentUser.nickname, date: b.assigned_at ? new Date(b.assigned_at) : (b.created_at ? new Date(b.created_at) : new Date()), title: `הכשרה: ${b.title}`, amount: b.custom_reward !== null ? b.custom_reward : b.default_reward, status: b.status }); });
    }

    if(Array.isArray(b2bOrdersHistory)) {
        b2bOrdersHistory.forEach(o => {
            const statusMap = { sent: 'נשלחה לספק', processing: 'בטיפול', shipped: 'במשלוח', delivered: 'סופקה', cancelled: 'בוטלה' };
            feedCache.push({ type: 'order', id: `order_${o.id}`, user_id: o.created_by || 0, user_name: o.creator_name || 'צוות', date: o.created_at ? new Date(o.created_at) : new Date(), title: `הזמנת רכש #${o.id} מ-${o.supplier_name || 'ספק'} — ${statusMap[o.status] || o.status}`, amount: parseFloat(o.total_amount) || 0, isIncome: false });
        });
    }

    feedCache.sort((a, b) => {
        const timeA = (a.date && !isNaN(a.date.getTime())) ? a.date.getTime() : 0;
        const timeB = (b.date && !isNaN(b.date.getTime())) ? b.date.getTime() : 0;
        return timeB - timeA;
    });
    
    const filterEl = getEl('feed-user-filter');
    if (filterEl) { if(currentUser.role === 'ADMIN') filterEl.classList.remove('hidden'); else filterEl.classList.add('hidden'); }
    renderUnifiedFeed();
}

window.currentFeedPage = 1;

window.changeFeedPage = function(direction) {
    window.currentFeedPage += direction;
    if (window.currentFeedPage < 1) window.currentFeedPage = 1;
    renderUnifiedFeed();
};

function renderUnifiedFeed() {
    const userFilter = val('feed-user-filter') || 'all'; const dateFilter = val('feed-date-filter') || 'all'; const list = getEl('unified-feed-list'); if (!list) return;
    let filtered = feedCache;
    if (currentUser.role !== 'ADMIN') { filtered = feedCache.filter(item => String(item.user_id) === String(currentUser.id) || item.type === 'system'); } 
    else if (userFilter !== 'all' && userFilter !== '') { filtered = feedCache.filter(item => String(item.user_id) === String(userFilter) || item.type === 'system'); }
    if (dateFilter !== 'all') { const monthsBack = parseInt(dateFilter); const cutoffDate = new Date(); cutoffDate.setMonth(cutoffDate.getMonth() - monthsBack); filtered = filtered.filter(item => item.date && item.date >= cutoffDate); }
    
    // פגינציה חכמה (15 פריטים בעמוד)
    const itemsPerPage = 15;
    const totalPages = Math.ceil(filtered.length / itemsPerPage) || 1;
    if (window.currentFeedPage > totalPages) window.currentFeedPage = totalPages;
    if (window.currentFeedPage < 1) window.currentFeedPage = 1;

    const startIndex = (window.currentFeedPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const paginatedItems = filtered.slice(startIndex, endIndex);

    const controls = document.getElementById('feed-pagination-controls');
    if (controls) {
        if (filtered.length > itemsPerPage) {
            controls.classList.remove('hidden'); controls.classList.add('flex');
            const pageInfo = document.getElementById('feed-page-info');
            if (pageInfo) pageInfo.innerText = `עמוד ${window.currentFeedPage} מתוך ${totalPages}`;
        } else {
            controls.classList.add('hidden'); controls.classList.remove('flex');
        }
    }

    if(paginatedItems.length === 0) { list.innerHTML = '<div class="text-center py-10 bg-white rounded-3xl border border-dashed border-slate-200 mt-2"><i class="fa-solid fa-ghost text-4xl text-slate-200 mb-3"></i><p class="text-slate-400 text-sm font-medium">אין פעילות להצגה כרגע</p></div>'; return; }
    
    let html = '';
    paginatedItems.forEach(item => {
        if(!item.date || isNaN(item.date.getTime())) return;
        const colorClass = item.type === 'system' ? 'bg-blue-50 border-blue-100' : (userColors[item.user_id % userColors.length] || 'bg-white border-slate-50'); 
        const userNameDisplay = item.type !== 'system' && item.user_name ? `<span class="text-xs font-bold text-slate-500 block mb-0.5">${safeStr(item.user_name)}</span>` : '';
        const d = item.date; const today = new Date(); const isToday = d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
        const timeStr = d.toLocaleTimeString('he-IL', {hour: '2-digit', minute:'2-digit'}); const dateStr = isToday ? `היום, ${timeStr}` : `${d.toLocaleDateString('he-IL')} ${timeStr}`;
        let contentHtml = '';
        if (item.type === 'transaction') {
            const icon = item.isIncome ? '<i class="fa-solid fa-arrow-trend-up text-green-500 bg-green-100 p-1.5 rounded-full text-[10px]"></i>' : '<i class="fa-solid fa-arrow-trend-down text-red-500 bg-red-100 p-1.5 rounded-full text-[10px]"></i>';
            const amountClass = item.isIncome ? 'text-green-600' : 'text-red-600'; const prefix = item.isIncome ? '+' : '-';
            contentHtml = `<div class="flex justify-between items-center w-full"><div>${userNameDisplay}<p class="font-bold text-slate-800 leading-tight flex items-center gap-2 mt-0.5">${icon} <span>${safeStr(item.title)}</span></p><p class="text-[10px] text-slate-400 mt-1">${dateStr}</p></div><span class="font-bold text-lg ${amountClass}" dir="ltr">${prefix}₪${item.amount}</span></div>`;
        } else if (item.type === 'task') {
            const icon = '<i class="fa-solid fa-list-check text-slate-600 bg-slate-200 p-1.5 rounded-full text-[10px]"></i>'; let statusLabel = item.status === 'pending' ? 'פתוח' : (item.status === 'done' ? 'ממתין לאישור' : 'סגור'); let badgeClass = item.status === 'pending' ? 'bg-slate-100 text-slate-500' : (item.status === 'done' ? 'bg-amber-100 text-amber-600' : 'bg-green-100 text-green-600');
            contentHtml = `<div class="flex justify-between items-center w-full opacity-90"><div>${userNameDisplay}<p class="font-bold text-slate-700 leading-tight flex items-center gap-2 mt-0.5">${icon} <span>${safeStr(item.title)}</span></p><p class="text-[10px] text-slate-400 mt-1">${dateStr} • <span class="px-1.5 rounded ${badgeClass}">${statusLabel}</span></p></div><span class="text-xs font-bold text-slate-700 bg-slate-100 px-2 py-1 rounded-lg">₪${item.amount}</span></div>`;
        } else if (item.type === 'quiz') {
            const icon = '<i class="fa-solid fa-book-open text-blue-500 bg-blue-100 p-1.5 rounded-full text-[10px]"></i>'; let statusLabel = item.status === 'assigned' ? 'נשלח לעובד' : (item.status === 'completed' ? 'הושלם בהצטיינות' : 'לא עבר'); let badgeClass = item.status === 'assigned' ? 'bg-slate-100 text-slate-500' : (item.status === 'completed' ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600');
            contentHtml = `<div class="flex justify-between items-center w-full opacity-90"><div>${userNameDisplay}<p class="font-bold text-slate-700 leading-tight flex items-center gap-2 mt-0.5">${icon} <span>${safeStr(item.title)}</span></p><p class="text-[10px] text-slate-400 mt-1">${dateStr} • <span class="px-1.5 rounded ${badgeClass}">${statusLabel}</span></p></div><span class="text-xs font-bold text-blue-700 bg-blue-50 px-2 py-1 rounded-lg">₪${item.amount}</span></div>`;
        } else if (item.type === 'system') {
            const icon = '<i class="fa-solid fa-building text-blue-500 bg-blue-100 p-1.5 rounded-full text-[10px]"></i>';
            contentHtml = `<div class="flex justify-between items-center w-full"><div><p class="font-bold text-slate-800 leading-tight flex items-center gap-2 mt-0.5">${icon} <span>${safeStr(item.title)}</span></p><p class="text-[10px] text-slate-400 mt-1">${dateStr}</p></div></div>`;
        } else if (item.type === 'order') {
            const icon = '<i class="fa-solid fa-file-invoice text-indigo-500 bg-indigo-100 p-1.5 rounded-full text-[10px]"></i>';
            contentHtml = `<div class="flex justify-between items-center w-full"><div>${userNameDisplay}<p class="font-bold text-slate-800 leading-tight flex items-center gap-2 mt-0.5">${icon} <span>${safeStr(item.title)}</span></p><p class="text-[10px] text-slate-400 mt-1">${dateStr}</p></div><span class="font-bold text-lg text-slate-800" dir="ltr">₪${item.amount.toFixed(2)}</span></div>`;
        }
        html += `<div class="${colorClass} p-3.5 rounded-2xl shadow-sm border transform transition hover:scale-[1.01] mb-2 flex items-center">${contentHtml}</div>`;
    });
    list.innerHTML = html;
}

async function fetchCommissionSummary() {
    if (!currentGroup || !currentGroup.id) return;
    const container = document.getElementById('biz-commission-cubes');
    if (!container) return;
    try {
        const res = await fetch(`${API}/store/commission-summary/${currentGroup.id}`);
        const data = await res.json();
        if (!data.success) { container.innerHTML = '<div class="col-span-2 text-center text-xs text-red-400 py-2">שגיאה בטעינת נתונים</div>'; return; }
        const s = data.summary;
        const fmt = v => '₪' + parseFloat(v || 0).toLocaleString('he-IL', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        const pct = (collected, total) => total > 0 ? Math.min(100, Math.round(collected / total * 100)) : 0;
        const totalPct = pct(s.total_collected, s.total_commission);
        const monthPct = pct(s.month_collected, s.month_commission);
        const cube = (icon, color, label, main, sub, subLabel, barPct, barColor, tag) => `
            <div class="bg-${color}-50 border border-${color}-100 rounded-2xl p-4 text-center relative">
                ${tag ? `<span class="absolute top-2 right-2 text-[9px] font-bold bg-${color}-200 text-${color}-700 px-1.5 py-0.5 rounded-full">${tag}</span>` : ''}
                <i class="fa-solid ${icon} text-lg text-${color}-400 mb-1 ${tag ? 'mt-2' : ''} block"></i>
                <div class="text-base font-black text-${color}-700">${main}</div>
                <div class="text-[10px] text-${color}-600 font-bold mb-2">${label}</div>
                <div class="text-[10px] font-bold text-${color}-500 mb-0.5">${sub} · ${subLabel}</div>
                <div class="w-full bg-${color}-100 rounded-full h-1.5">
                    <div class="bg-${barColor} h-1.5 rounded-full transition-all duration-700" style="width:${barPct}%"></div>
                </div>
                <div class="text-[9px] text-${color}-400 mt-0.5">${barPct}% שולם</div>
            </div>`;
        container.innerHTML =
            cube('fa-file-invoice-dollar', 'blue', 'סה"כ עמלה', fmt(s.total_commission), fmt(s.total_collected), 'שולם', totalPct, 'rgb(99,102,241)', '') +
            cube('fa-file-invoice-dollar', 'indigo', 'עמלה החודש', fmt(s.month_commission), fmt(s.month_collected), 'שולם', monthPct, 'rgb(99,102,241)', 'חודש שוטף');
    } catch(e) { if(container) container.innerHTML = '<div class="col-span-2 text-center text-xs text-slate-400 py-2">אין נתוני עמלות עדיין</div>'; }
}

window.switchCfSubTab = function(tab) {
    ['cashflow','collection'].forEach(t => {
        const v = document.getElementById(`cf-sub-view-${t}`);
        const b = document.getElementById(`cf-sub-tab-${t}`);
        if (v) v.classList.toggle('hidden', t !== tab);
        if (b) {
            if (t === tab) {
                b.className = 'px-4 py-2 text-xs font-bold border-b-2 border-indigo-500 text-indigo-600 bg-indigo-50 rounded-t-lg transition';
            } else {
                b.className = 'px-4 py-2 text-xs font-bold border-b-2 border-transparent text-slate-500 hover:text-slate-700 rounded-t-lg transition';
            }
        }
    });
    if (tab === 'collection') window.renderCollectionTab();
};

window.renderCollectionTab = async function() {
    const list = document.getElementById('collection-list');
    const summaryBar = document.getElementById('collection-summary-bar');
    if (!list || !currentGroup) return;
    list.innerHTML = '<p class="text-xs text-slate-400 text-center py-4"><i class="fa-solid fa-spinner fa-spin ml-1"></i> טוען...</p>';
    try {
        const r = await fetch(`${API}/work-orders/collection/${currentGroup.id}`);
        const d = await r.json();
        const items = d.items || [];
        if (!items.length) {
            list.innerHTML = '<p class="text-xs text-slate-400 text-center py-6">אין תחנות גביה עדיין</p>';
            if (summaryBar) summaryBar.classList.add('hidden');
            return;
        }
        const METHODS = { cash:'מזומן', card:'כרטיס', transfer:'העברה', check:'שיק', bit:'ביט' };
        let sumPending = 0, sumReceived = 0, sumTotal = 0;
        const today = new Date(); today.setHours(0,0,0,0);

        list.innerHTML = items.map(p => {
            const isPaid = p.status === 'received';
            const amt = parseFloat(p.amount);
            const recAmt = parseFloat(p.received_amount || 0);
            sumTotal += amt;
            if (isPaid) sumReceived += recAmt;
            else sumPending += amt;
            const dueDateStr = p.due_date ? new Date(p.due_date).toLocaleDateString('he-IL') : '—';
            const isOverdue = !isPaid && p.due_date && new Date(p.due_date) < today;
            const woLabel = p.wo_number || `#${p.work_order_id}`;
            const milestoneLabel = p.total_milestones > 1
                ? `תשלום ${p.received_milestones}/${p.total_milestones}`
                : '';
            return `<div class="p-3 rounded-xl border ${isPaid ? 'border-green-200 bg-green-50' : isOverdue ? 'border-red-200 bg-red-50' : 'border-slate-200 bg-white'} flex items-start gap-3">
                <div class="flex-1 min-w-0">
                    <div class="flex items-center gap-2 flex-wrap mb-0.5">
                        <span class="text-xs font-black text-slate-800">${safeStr(p.customer_name || 'לקוח')}</span>
                        <span class="text-[9px] text-slate-400 border border-slate-200 rounded-full px-1.5 py-0.5">${woLabel}</span>
                        ${milestoneLabel ? `<span class="text-[9px] text-indigo-600 bg-indigo-50 border border-indigo-100 rounded-full px-1.5 py-0.5">${milestoneLabel}</span>` : ''}
                        ${isPaid ? '<span class="text-[9px] bg-green-100 text-green-700 px-1.5 py-0.5 rounded-full font-bold">התקבל ✅</span>' : isOverdue ? '<span class="text-[9px] bg-red-100 text-red-700 px-1.5 py-0.5 rounded-full font-bold">באיחור ⚠️</span>' : '<span class="text-[9px] bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded-full font-bold">ממתין</span>'}
                    </div>
                    <div class="text-[10px] text-slate-500 mt-0.5">
                        ${safeStr(p.milestone_name || 'תשלום')} ·
                        <b class="text-slate-700 dir-ltr">₪${amt.toFixed(0)}</b> מתוך <b class="dir-ltr">₪${parseFloat(p.total_amount||p.wo_total||amt).toFixed(0)}</b>
                        ${p.payment_method ? ' · ' + (METHODS[p.payment_method] || p.payment_method) : ''}
                        · יעד: <b>${dueDateStr}</b>
                        ${isPaid ? ` · התקבל: <b class="text-green-600">₪${recAmt.toFixed(0)}</b>` : ''}
                    </div>
                </div>
                ${!isPaid ? `<button onclick="window._colMarkReceived(${p.id})" class="shrink-0 text-[9px] bg-green-600 text-white px-2.5 py-1.5 rounded-lg font-bold hover:bg-green-700 transition">גבה ✓</button>` : ''}
            </div>`;
        }).join('');

        if (summaryBar) {
            summaryBar.classList.remove('hidden');
            const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = '₪' + v.toLocaleString('he-IL', {maximumFractionDigits:0}); };
            setText('col-sum-pending', sumPending);
            setText('col-sum-received', sumReceived);
            setText('col-sum-total', sumTotal);
        }
    } catch(e) { list.innerHTML = '<p class="text-xs text-red-400 text-center py-2">שגיאת טעינה</p>'; }
};

window._colMarkReceived = async function(paymentId) {
    const recAmt = await window._uiPrompt('סכום שהתקבל (ריק = סכום מלא):', {type:'number', placeholder:'השאר ריק לסכום מלא'});
    if (recAmt === null) return;
    try {
        const r = await fetch(`/api/work-orders/payments/${paymentId}/receive`, {
            method: 'PATCH', headers: {'Content-Type':'application/json'},
            body: JSON.stringify({ receivedAmount: recAmt || null, userName: currentUser?.nickname || 'מנהל' })
        });
        const d = await r.json();
        if (!d.success) { showToast('error', d.error || 'שגיאה'); return; }
        showToast('success', 'תשלום נרשם כהתקבל ✅');
        window.renderCollectionTab();
        renderUrgentItems();
    } catch(e) { showToast('error', 'שגיאת תקשורת'); }
};

function renderCashflow() {
    const list = getEl('cashflow-list'); if (!list) return;
    const userFilter = val('cashflow-user-filter') || 'all'; const dateFilter = val('cashflow-date-filter') || 'all';
    let filtered = allTransactions; 
    if (currentUser.role !== 'ADMIN') { filtered = allTransactions.filter(t => String(t.user_id) === String(currentUser.id)); const cfFilter = getEl('cashflow-user-filter'); if(cfFilter) cfFilter.classList.add('hidden'); } 
    else { const cfFilter = getEl('cashflow-user-filter'); if(cfFilter) cfFilter.classList.remove('hidden'); if (userFilter !== 'all' && userFilter !== '') { filtered = allTransactions.filter(t => String(t.user_id) === String(userFilter)); } }
    if (dateFilter !== 'all') { const monthsBack = parseInt(dateFilter); const cutoffDate = new Date(); cutoffDate.setMonth(cutoffDate.getMonth() - monthsBack); filtered = filtered.filter(t => new Date(t.date) >= cutoffDate); }
    if (filtered.length === 0) { list.innerHTML = '<p class="text-center text-slate-400 text-sm py-4 bg-slate-50 rounded-2xl border border-dashed border-slate-200 mt-2">אין תנועות תזרים להצגה בתקופה זו.</p>'; return; }
    let html = '';
    filtered.forEach(t => {
        const isIncome = t.type === 'income'; const icon = isIncome ? '<i class="fa-solid fa-arrow-trend-up text-green-500 bg-green-100 p-1.5 rounded-full text-[10px]"></i>' : '<i class="fa-solid fa-arrow-trend-down text-red-500 bg-red-100 p-1.5 rounded-full text-[10px]"></i>';
        const amountClass = isIncome ? 'text-green-600' : 'text-red-600'; const prefix = isIncome ? '+' : '-';
        const d = new Date(t.date); const dateStr = `${d.toLocaleDateString('he-IL')} ${d.toLocaleTimeString('he-IL', {hour: '2-digit', minute:'2-digit'})}`;
        const userName = t.user_name ? `<span class="text-[9px] bg-slate-100 px-1.5 rounded text-slate-500 ml-1 font-normal">${safeStr(t.user_name)}</span>` : '';
        const catLabel = BUDGET_LABELS[t.category] || t.category || ''; const catBadge = catLabel ? `<span class="text-[9px] text-slate-400 border border-slate-200 px-1.5 rounded-full mr-2">${catLabel}</span>` : '';
        const editBtn = currentUser.role === 'ADMIN' ? `<button onclick="openEditTransactionModal(${t.id}, ${t.amount}, '${safeStr(t.description)}', '${t.category}', '${t.type}')" class="text-slate-500 bg-slate-100 w-8 h-8 rounded-full flex items-center justify-center hover:bg-slate-200 transition"><i class="fa-solid fa-pen text-xs"></i></button>` : '';
        html += `<div class="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 mb-2 flex items-center justify-between hover:border-slate-200 transition"><div class="flex-1 overflow-hidden pr-2"><p class="font-bold text-slate-800 leading-tight flex items-center mt-0.5">${icon} <span class="mr-2 truncate">${safeStr(t.description)}</span> ${userName}</p><p class="text-[10px] text-slate-400 mt-1">${dateStr} ${catBadge}</p></div><div class="flex items-center gap-3 pl-1"><span class="font-bold text-base ${amountClass} whitespace-nowrap" dir="ltr">${prefix}₪${t.amount}</span>${editBtn}</div></div>`;
    });
    list.innerHTML = html;
}

function openEditTransactionModal(id, amount, desc, cat, type) {
    getEl('edit-trans-id').value = id; getEl('edit-trans-old-amount').value = amount; getEl('edit-trans-type').value = type; getEl('edit-trans-amount').value = amount; getEl('edit-trans-desc').value = desc;
    const catSelect = getEl('edit-trans-cat'); catSelect.innerHTML = '';
    if(CATEGORIES[type]) { CATEGORIES[type].forEach(c => { const selected = c.value === cat ? 'selected' : ''; catSelect.innerHTML += `<option value="${c.value}" ${selected}>${c.label}</option>`; }); } else { catSelect.innerHTML += `<option value="${cat}" selected>${cat}</option>`; }
    getEl('edit-transaction-modal').classList.remove('hidden');
}

async function submitEditTransaction() {
    const id = val('edit-trans-id'); const amount = val('edit-trans-amount'); const desc = val('edit-trans-desc'); const cat = val('edit-trans-cat');
    if(!amount) return showToast('error', 'נא להזין סכום');
    const btn = getEl('btn-submit-edit-transaction'); if(btn) { btn.disabled = true; btn.innerText = 'שומר...'; }
    try {
        const res = await fetch(`${API}/transaction/${id}`, { method: 'PUT', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({ amount, description: desc, category: cat, requesterId: currentUser.id, groupId: currentGroup.id }) }); const data = await res.json();
        if(data.success) { showToast('success', 'הפעולה עודכנה!'); getEl('edit-transaction-modal').classList.add('hidden'); fetchData(); } else { showToast('error', data.error || 'שגיאה בעדכון'); }
    } catch(e) { showToast('error', 'שגיאת תקשורת'); } finally { if(btn) { btn.disabled = false; btn.innerText = 'שמור שינויים'; } }
}

async function deleteTransaction() {
    const id = val('edit-trans-id'); if(!await window._uiConfirm('האם אתה בטוח שברצונך למחוק פעולה זו לחלוטין? היתרה תתעדכן בהתאם.', {danger:true, okLabel:'מחק'})) return;
    try {
        const res = await fetch(`${API}/transaction/${id}?requesterId=${currentUser.id}`, { method: 'DELETE' }); const data = await res.json();
        if(data.success) { showToast('success', 'הפעולה נמחקה!'); getEl('edit-transaction-modal').classList.add('hidden'); fetchData(); } else { showToast('error', data.error || 'שגיאה במחיקה'); }
    } catch(e) { showToast('error', 'שגיאת תקשורת'); }
}

window.updateAssignDetails = function() { const select = getEl('assign-bundle-select'); const bundleId = select.value; const bundle = allBundles.find(b => String(b.id) === String(bundleId)); if(bundle) { getEl('assign-reward').value = bundle.reward || 0; } };

