window.sendQuoteToCustomer = async function(id) {
    const q = window.storeQuotesCache.find(x => String(x.id) === String(id));
    if (!q) return;

    if (!q.customer_phone) {
        return showToast('error', 'לא מוגדר מספר טלפון ללקוח בהצעת מחיר זו.');
    }

    const storeAlias = document.getElementById('store-alias-input') ? document.getElementById('store-alias-input').value : '';
    const displayId = storeAlias || currentGroup.group_code;
    const publicUrl = `${window.location.origin}/${displayId}`;

    const cleanPhone = q.customer_phone.replace(/\D/g, '');
    let waPhone = cleanPhone;
    if (cleanPhone.startsWith('0')) {
        waPhone = '972' + cleanPhone.substring(1);
    }

    const amount = q.total_amount ? parseFloat(q.total_amount).toFixed(2) : "0.00";

    let confirmUrl = '';
    try {
        const resp = await fetch(`${API}/store/quotes/${id}/prepare-send`, { method: 'POST' });
        const data = await resp.json();
        if (data.confirmUrl) confirmUrl = data.confirmUrl;
    } catch(e) {}

    let text = `שלום ${safeStr(q.customer_name)}, בהמשך לפנייתך,\n`;
    text += `הכנו עבורך הצעת מחיר (מס' ${q.id}) על סך ₪${amount}.\n\n`;
    text += `ההצעה המלאה תצורף לכאן כמסמך PDF.\n`;
    text += `לצפייה במוצרים נוספים בחנות שלנו:\n${publicUrl}\n\n`;
    if (confirmUrl) {
        text += `✅ לאישור קבלת ההצעה — לחץ כאן:\n${confirmUrl}\n`;
        text += `(לחיצה תסמן שההצעה התקבלה אצלך)\n\n`;
    }
    text += `אנא השב/י להודעה זו במילה "מאשר" או "לא מאשר" כדי שנוכל להתקדם.\n\n`;
    text += `בברכה,\n${currentGroup.name}\n\n`;
    text += `Oneflowlife.co.il תכירו, המערכת המושלמת לניהול משפחות ועסקים.`;

    window.updateQuoteStatus(q.id, 'sent');
    window.open(`https://wa.me/${waPhone}?text=${encodeURIComponent(text)}`, '_blank');
};

window.currentActionTargetId = null;
window.currentActionType = null; 

window.approveQuoteToOrder = function(id) {
    window.currentActionTargetId = id;
    window.currentActionType = 'quote';
    getEl('target-datetime-input').value = '';
    getEl('target-date-modal-title').innerText = 'המרה להזמנה';
    getEl('target-date-modal-desc').innerText = 'ההצעה תעבור לתור ההזמנות (וישובץ אירוע ביומן במידת הצורך). בחר תאריך ושעת יעד לאספקה/הגעה:';
    getEl('target-datetime-modal').classList.remove('hidden');
};

window.editOrderTargetDate = async function(orderId, currentDate) {
    window.currentActionTargetId = orderId;
    window.currentActionType = 'order';
    let formattedDate = '';
    if (currentDate && currentDate !== 'null' && currentDate !== '') {
        try {
            const d = new Date(currentDate);
            formattedDate = new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0,16);
        } catch(e) {}
    }
    getEl('target-datetime-input').value = formattedDate;
    getEl('target-date-modal-title').innerText = 'עדכון יעד אספקה';
    getEl('target-date-modal-desc').innerText = 'בחר תאריך ושעה מעודכנים ליעד מסירת ההזמנה ללקוח:';
    getEl('target-datetime-modal').classList.remove('hidden');
};

window.submitTargetDatetime = async function() {
    const targetDate = document.getElementById('target-datetime-input').value;
    if (!targetDate && window.currentActionType === 'quote') {
        if (!await window._uiConfirm('לא הוזן תאריך יעד לאירוע/לאספקה. האם להמשיך ללא שיבוץ ביומן?')) return;
    }

    const btn = document.getElementById('btn-submit-target-date');
    btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> מאשר וממיר...';
    
    try {
        if (window.currentActionType === 'quote') {
            const q = window.storeQuotesCache.find(x => String(x.id) === String(window.currentActionTargetId));

            let approvalSuccess = false;

            // המרת ההצעה לפקודת עבודה - זה יוצר את אירוע converted_to_work_order בהיסטוריה
            try {
                const res = await fetch(`${API}/store/quotes/${window.currentActionTargetId}/to-work-order`, {
                    method: 'POST', headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({})
                });
                const data = await res.json();
                if (data.success) approvalSuccess = true;
            } catch(e) {
                console.error('שגיאה בהמרה ל-work order:', e);
            }

            if (!approvalSuccess) {
                throw new Error('שגיאה באישור ההצעה מול השרת.');
            }

            if (targetDate) {
                const d = new Date(targetDate);
                
                // שיבוץ אירוע ביומן
                const payload = {
                    groupId: currentGroup.id,
                    title: `ביצוע פרויקט/אירוע: ${q ? safeStr(q.customer_name) : ''}`,
                    eventDate: d.toISOString().split('T')[0],
                    startTime: d.toTimeString().substring(0,5),
                    serviceId: null,
                    notes: `ORDER_REF:${window.currentActionTargetId}`,
                    status: 'approved',
                    customerPhone: q ? q.customer_phone : ''
                };
                fetch(`${API}/calendar/events`, {
                    method: 'POST', headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(payload)
                }).catch(e => {});

                // עדכון התאריך בהזמנה
                fetch(`${API}/store/orders/${window.currentActionTargetId}/target-date`, {
                    method: 'PATCH', headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ targetDatetime: targetDate })
                }).catch(e=>{});
            }

            // עדכון המטמון המקומי כדי שההעברה תשוקף מיד למשתמש
            if (q) {
                q.status = 'processing';
                q.quote_status = 'approved';

                // הוסף את אירוע converted_to_work_order להיסטוריה
                const history = typeof q.quote_history === 'string' ? JSON.parse(q.quote_history || '[]') : (q.quote_history || []);
                history.push({ type: 'converted_to_work_order', actor: 'business', ts: new Date().toISOString() });
                q.quote_history = JSON.stringify(history);

                // נוודא שהיא נכנסת למטמון ההזמנות
                if (window.storeOrdersCache) {
                    const existingOrder = window.storeOrdersCache.find(o => String(o.id) === String(q.id));
                    if (!existingOrder) {
                        window.storeOrdersCache.push(q);
                    } else {
                        existingOrder.status = 'processing';
                        existingOrder.quote_status = 'approved';
                        existingOrder.quote_history = q.quote_history;
                    }
                }
            }
            
            showToast('success', 'הצעת המחיר אושרה והועברה לתור ההזמנות בהצלחה!');
            document.getElementById('target-datetime-modal').classList.add('hidden');
            
            // רינדור מחדש של המסכים ללא צורך בהמתנה לקריאת שרת
            if(typeof window.renderStoreQuotes === 'function') window.renderStoreQuotes();
            if(typeof window.renderStoreOrders === 'function') window.renderStoreOrders();
            
            // משיכה שקטה ברקע לאימות
            setTimeout(() => {
                if(typeof window.fetchStoreOrders === 'function') window.fetchStoreOrders();
                if(typeof window.fetchCalendarData === 'function') window.fetchCalendarData();
            }, 1000);
            
        } else if (window.currentActionType === 'order') {
            const res = await fetch(`${API}/store/orders/${window.currentActionTargetId}/target-date`, {
                method: 'PATCH', headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ targetDatetime: targetDate })
            });
            const data = await res.json();
            if(data.success) {
                showToast('success', 'יעד האספקה / האירוע עודכן בהזמנה!');
                document.getElementById('target-datetime-modal').classList.add('hidden');
                if(typeof window.fetchStoreOrders === 'function') window.fetchStoreOrders();
            } else {
                showToast('error', data.error || 'שגיאה בעדכון יעד');
            }
        }
    } catch(e) {
        showToast('error', e.message || 'שגיאת תקשורת מול השרת בביצוע ההמרה');
    } finally {
        btn.disabled = false; btn.innerHTML = 'אישור ועדכון';
    }
};

let selectedQuoteItems = {};
let editingQuoteId = null;

window.openEditQuoteModal = async function(quoteId) {
    const q = window.storeQuotesCache.find(x => String(x.id) === String(quoteId));
    if (!q) return;

    const rawItems = Array.isArray(q.items) ? q.items : (typeof q.items === 'string' ? JSON.parse(q.items||'[]') : []);

    // Load catalog if needed (for catalog items)
    if (!window.storeCatalogCache || !window.storeCatalogCache.length) {
        try { const res = await fetch(`${API}/store/catalog/${currentGroup.id}`); window.storeCatalogCache = await res.json(); } catch(e) {}
    }

    // Open unified modal in edit mode
    window.showCustomerQuoteModal(null, { editingQuoteId: quoteId });

    // Populate fields
    const nameEl = document.getElementById('cq-customer-name');
    const phoneEl = document.getElementById('cq-customer-phone');
    if (nameEl) nameEl.value = q.customer_name || '';
    if (phoneEl) phoneEl.value = q.customer_phone || '';

    // Parse metadata
    const metaItem = rawItems.find(i => i.is_quote_metadata);
    let meta = {};
    if (metaItem) { try { meta = JSON.parse(metaItem.data||'{}'); } catch(e) {} }

    // Backwards compatibility: try parsing from notes JSON
    if (!metaItem && q.notes) {
        try {
            const parsedNotes = JSON.parse(q.notes);
            if (parsedNotes && typeof parsedNotes === 'object') {
                meta = parsedNotes;
                meta.notes = parsedNotes.notes || '';
            }
        } catch(e) {}
    }

    const set = (id, val) => { const el = document.getElementById(id); if (el && val !== undefined && val !== null) el.value = val; };
    set('cq-title', q.quote_title || meta.title || '');
    set('cq-validity', meta.validity || '30');
    set('cq-company-id', meta.companyId || '');
    set('cq-my-company-id', meta.myCompanyId || localStorage.getItem('ofl_my_company_id') || '');
    set('cq-intro-text', meta.introText || '');
    set('cq-notes', (meta.notes || q.notes || '').replace('[הצעת מחיר] - הוגשה בקשה לאירוע/פרויקט.', '').trim());
    set('cq-internal-note', meta.internalNote || '');
    set('cq-discount', meta.discount !== undefined ? meta.discount : 0);
    set('cq-customer-email', meta.customerEmail || '');
    set('cq-recipient-name', meta.recipientName || q.customer_name || '');
    if (meta.vatRate !== undefined) set('cq-vat-rate', meta.vatRate);
    if (meta.noVat) { const el = document.getElementById('cq-no-vat'); if (el) el.checked = true; }

    // Load items as DOM lines
    rawItems.forEach(i => {
        if (i.is_quote_metadata || i.is_delivery_metadata || i.catalogId === 999999 || (i.name && i.name.startsWith('DELIVERY_META|'))) return;
        window.cqAddLine({
            desc: i.item_name || i.name || '',
            qty: parseFloat(i.quantity) || 1,
            price: parseFloat(i.price_at_order || i.price) || 0,
            unit: i.unit || "יח'",
            boxSize: i.boxSize || '',
            catalogId: (i.catalogId && i.catalogId !== 0) ? i.catalogId : null,
            note: i.note || ''
        });
    });

    window.cqCalcTotal();
};
window.getQuotePresets = function(type) {
    try { return JSON.parse(localStorage.getItem(`ofl_quote_presets_${type}`)) || []; } catch(e) { return []; }
};

window.saveQuotePreset = function(type) {
    const valToSave = getEl(type === 'intro' ? 'quote-intro-text' : 'quote-notes').value.trim();
    if(!valToSave) return showToast('error', 'הטקסט ריק, אין מה לשמור');
    const presets = window.getQuotePresets(type);
    if(!presets.includes(valToSave)) { 
        presets.push(valToSave); 
        localStorage.setItem(`ofl_quote_presets_${type}`, JSON.stringify(presets)); 
        showToast('success', 'נשמר כתבנית לשימוש עתידי!'); 
        window.ensureQuoteHeaders(true); 
    } else {
        showToast('info', 'התבנית הזו כבר שמורה');
    }
};

window.applyQuotePreset = function(type, idx) {
    if(idx === '') return;
    const presets = window.getQuotePresets(type);
    if(presets[idx]) getEl(type === 'intro' ? 'quote-intro-text' : 'quote-notes').value = presets[idx];
};

window.generateQuoteAI = async function(type, btnElement) {
    const custName = val('quote-cust-name') || 'לקוח יקר';
    const query = type === 'intro' 
        ? `כתוב 2 משפטי פתיחה רשמיים, מכובדים ומקצועיים להצעת מחיר עבור הלקוח: ${custName}. העסק השולח: ${currentGroup.name}. חובה: ללא אימוג'ים או אייקונים כלל. החזר אך ורק את המשפטים ללא שום מילת הקדמה מצידך.` 
        : `כתוב 3 סעיפים מפורטים, רשמיים ומקצועיים של תנאי תשלום והערות משפטיות להצעת מחיר (למשל: תוקף ההצעה 14 יום, המחיר אינו כולל מע"מ) עבור העסק: ${currentGroup.name}. חובה: ללא אימוג'ים או אייקונים כלל. החזר אך ורק את הסעיפים, ללא מילות פתיחה וללא סיכום.`;
    
    const targetId = type === 'intro' ? 'quote-intro-text' : 'quote-notes';
    
    const originalHtml = btnElement ? btnElement.innerHTML : '';
    if (btnElement) {
        btnElement.disabled = true;
        btnElement.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> מנסח...';
    }
    
    showToast('info', 'ה-AI מעבד בקשה, המתן מספר שניות...');
    
    try {
        const res = await fetch(`${API}/biz/chat-assistant`, { 
            method: 'POST', headers: {'Content-Type': 'application/json'}, 
            body: JSON.stringify({ 
                query: query, 
                context: JSON.stringify({ role: "מומחה לכתיבת מסמכים עסקיים ומשפטיים. אתה מנסח טקסטים בצורה רשמית, מפורטת ומקצועית בלבד, ללא אימוג'ים וללא שום טקסט מקדים או מסכם." }), 
                groupId: currentGroup.id 
            }) 
        });
        const data = await res.json();
        
        if (data.error === 'BATTERY_EMPTY') {
            handleAIResponseCheck(data);
            return;
        }
        
        if (data.success && data.answer) { 
            let finalOutput = data.answer.replace(/["*]/g, '').trim();
            finalOutput = finalOutput.replace(/^(להלן|הנה|אלו|מצאתי|מצורפים|לבקשתך|הסעיפים).*?:?\n/i, '').trim(); 
            getEl(targetId).value = finalOutput;
            showToast('success', 'הטקסט הושלם בהצלחה!'); 
        } else { 
            showToast('error', data.error || 'אירעה שגיאת AI, נסה שנית'); 
        }
    } catch(e) { 
        showToast('error', 'תקלת רשת מול שרת ה-AI'); 
    } finally {
        if (btnElement) {
            btnElement.disabled = false;
            btnElement.innerHTML = originalHtml;
        }
    }
};

