function openGlobalAIAssistant() { getEl('global-ai-input').value = ''; getEl('global-ai-modal').classList.remove('hidden'); }

async function submitGlobalAI() {
    const inputEl = getEl('global-ai-input'); const query = inputEl.value.trim(); if (!query) return;
    const chatBox = getEl('global-ai-chat'); chatBox.innerHTML += `<div class="bg-indigo-600 text-white p-3 rounded-xl rounded-tl-none shadow-sm text-sm self-end max-w-[85%] fade-in">${safeStr(query)}</div>`; inputEl.value = '';
    const btn = getEl('btn-global-ai-submit'); btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i>';

    // ודא שפקודות עבודה נטענו לפני בניית הקשר
    if (workOrdersCache.length === 0 && typeof window.fetchWorkOrders === 'function') {
        try { await window.fetchWorkOrders(); } catch(e) {}
    }

    // קונטקסט עשיר ומקיף לעוזרת העסקית
    const now_ai = new Date();
    const thisM = now_ai.getMonth(), thisY = now_ai.getFullYear();
    const allOrd = storeOrdersCache || [];
    const ordMonth = allOrd.filter(o => { const d=new Date(o.created_at); return d.getMonth()===thisM && d.getFullYear()===thisY && o.status!=='cancelled'; });
    const ordToday = allOrd.filter(o => { const d=new Date(o.created_at); return d.toDateString()===now_ai.toDateString() && o.status!=='cancelled'; });
    const revenueM = ordMonth.filter(o=>['completed','shipped'].includes(o.status)).reduce((s,o)=>s+(parseFloat(o.total_amount)||parseFloat(o.total)||0),0);
    const revenueToday = ordToday.filter(o=>['completed','shipped'].includes(o.status)).reduce((s,o)=>s+(parseFloat(o.total_amount)||parseFloat(o.total)||0),0);
    const statusCounts = {};
    allOrd.forEach(o => { statusCounts[o.status] = (statusCounts[o.status]||0)+1; });
    const lowStockItems = (pantryCache||[]).filter(p=>parseFloat(p.quantity)<=2);
    const totalInc = (allTransactions||[]).filter(t=>t.type==='income').reduce((s,t)=>s+(parseFloat(t.amount)||0),0);
    const totalExp = (allTransactions||[]).filter(t=>t.type==='expense').reduce((s,t)=>s+(parseFloat(t.amount)||0),0);
    // Food cost summary
    let fcSummary = null;
    if (typeof foodCostData !== 'undefined' && foodCostData?.length > 0) {
        const withCost = foodCostData.filter(i=>i.costs?.foodCostPct>0);
        fcSummary = {
            total_items: foodCostData.length,
            items_with_recipe: withCost.length,
            avg_food_cost_pct: withCost.length>0 ? (withCost.reduce((a,i)=>a+i.costs.foodCostPct,0)/withCost.length).toFixed(1) : null,
            top_profitable: foodCostData.filter(i=>i.costs?.profit>0).sort((a,b)=>b.costs.profit-a.costs.profit).slice(0,3).map(i=>({name:i.name,profit:i.costs.profit?.toFixed(2),fc_pct:i.costs.foodCostPct?.toFixed(1)})),
            problematic: foodCostData.filter(i=>i.costs?.foodCostPct>40).map(i=>({name:i.name,fc_pct:i.costs.foodCostPct?.toFixed(1)}))
        };
    }
    const systemContext = {
        business_type: currentGroup?.business_type,
        business_name: currentGroup?.name,
        date_today: now_ai.toLocaleDateString('he-IL', {weekday:'long',day:'numeric',month:'long',year:'numeric'}),
        orders_summary: {
            total: allOrd.length,
            by_status: statusCounts,
            today_count: ordToday.length,
            today_revenue: revenueToday,
            month_count: ordMonth.length,
            month_revenue: revenueM,
            avg_per_order_month: ordMonth.length>0 ? Math.round(revenueM/ordMonth.length) : 0,
            deliveries_in_transit: allOrd.filter(o=>o.status==='shipped').length,
            recent_10: allOrd.slice(0,10).map(o=>({id:o.id,status:o.status,customer:o.customer_name,amount:o.total_amount||o.total,date:o.created_at,is_delivery:o.is_delivery}))
        },
        work_orders: workOrdersCache.slice(0,20).map(wo=>({id:wo.id,customer:wo.customer_name,status:wo.status,amount:wo.total_amount,date:wo.created_at})),
        employees: membersCache.map(m=>({name:m.nickname||m.name,role:m.role,balance:m.balance})),
        pantry: {
            total_items: (pantryCache||[]).length,
            low_stock: lowStockItems.map(p=>({item:p.item_name,qty:p.quantity,unit:p.unit})),
            all: (pantryCache||[]).slice(0,30).map(p=>({item:p.item_name,qty:p.quantity,unit:p.unit,category:p.category}))
        },
        cashflow: {
            total_income: totalInc,
            total_expense: totalExp,
            net_balance: totalInc-totalExp,
            recent_income: (allTransactions||[]).filter(t=>t.type==='income').slice(0,5).map(t=>({desc:t.description,amount:t.amount,date:t.date})),
            recent_expense: (allTransactions||[]).filter(t=>t.type==='expense').slice(0,5).map(t=>({desc:t.description,amount:t.amount,date:t.date}))
        },
        food_cost: fcSummary,
        open_tasks: (allTasks||[]).filter(t=>t.status==='pending').slice(0,10).map(t=>({title:t.title,assignee:t.assignee_name})),
        catalog: (currentGroup?.business_type==='restaurant'||currentGroup?.business_type==='cafe')
            ? (window.storeCatalogCache||[]).slice(0,60).map(p=>({id:p.id,name:p.name,price:p.price,available:p.is_available,category:p.category}))
            : undefined,
        table_reservations_today: (currentGroup?.business_type==='restaurant'||currentGroup?.business_type==='cafe')
            ? (window._tableReservationsCache||[]).filter(r=>{try{const d=new Date(r.event_date||r.created_at);return d.toDateString()===now_ai.toDateString();}catch(e){return false;}}).slice(0,20).map(r=>({id:r.id,name:r.title||r.customer_name,phone:r.customer_phone,time:r.start_time,guests:r.num_guests,status:r.status,table:r.reserved_table_number}))
            : undefined,
        beauty_appointments_today: currentGroup?.business_type==='beauty'
            ? (window._beautyState?.appointments||[]).filter(a=>{try{const seg=a.segments?.[0];const ts=seg?.start_time||a.start_time;return ts&&new Date(ts).toDateString()===now_ai.toDateString();}catch(e){return false;}}).slice(0,30).map(a=>{const seg=a.segments?.[0]||{};return{id:a.id,client:a.client_name,phone:a.client_phone,service:seg.service_name||a.service_name,practitioner:seg.practitioner_name||a.practitioner_name,time:seg.start_time||a.start_time,status:a.status,price:a.total_price};})
            : undefined,
        professional_leads_recent: currentGroup?.business_type==='professional'
            ? (window._professionalLeadsCache||[]).slice(0,20).map(l=>({id:l.id,name:l.name,phone:l.phone,email:l.email,subject:l.subject,status:l.status,date:l.created_at}))
            : undefined,
        service_calls_open: currentGroup?.business_type==='maintenance_repair'
            ? (window._serviceCallsCache||[]).filter(c=>!['done','cancelled'].includes(c.status)).slice(0,20).map(c=>({id:c.id,title:c.title,customer:c.customer_name||c.family_name,status:c.status,priority:c.priority,scheduled:c.scheduled_at,parts_status:c.parts_status}))
            : undefined,
        my_communities: (window.myCommunityBusinessesCache||[]).filter(c=>c.status==='approved').map(c=>({id:c.id,name:c.name,type:c.type,cashback_percent:c.cashback_percent,members_count:c.members_count}))
    };

    try {
        const res = await fetch(`${API}/biz/chat-assistant`, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({ query: query, context: JSON.stringify(systemContext), groupId: currentGroup.id }) }); const data = await res.json();
        if (!handleAIResponseCheck(data)) { getEl('global-ai-modal').classList.add('hidden'); btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-arrow-up"></i>'; return; }
        
        if (data.success && data.answer) { 
            let answerText = data.answer;
            let actionHtml = '';
            
            // AI Action Parser — משימה
            const taskMatch = answerText.match(/\[ACTION:ADD_TASK\|(.*?)\]/);
            if (taskMatch) {
                const taskTitle = taskMatch[1].trim();
                answerText = answerText.replace(taskMatch[0], '');
                actionHtml += `<button onclick="document.getElementById('global-ai-modal').classList.add('hidden'); openTaskModal(); setTimeout(() => document.getElementById('task-title').value='${safeStr(taskTitle)}', 300);" class="mt-3 w-full bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-list-check"></i> פתיחת משימה: ${safeStr(taskTitle)}</button>`;
            }
            // AI Action Parser — רכש
            const shopMatch = answerText.match(/\[ACTION:ADD_SHOP\|(.*?)\]/);
            if (shopMatch) {
                const shopItem = shopMatch[1].trim();
                answerText = answerText.replace(shopMatch[0], '');
                actionHtml += `<button onclick="document.getElementById('global-ai-modal').classList.add('hidden'); openShopModal(); setTimeout(() => document.getElementById('shop-item').value='${safeStr(shopItem)}', 300);" class="mt-3 w-full bg-blue-50 text-blue-700 hover:bg-blue-100 border border-blue-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-cart-shopping"></i> הוסף לרכש: ${safeStr(shopItem)}</button>`;
            }
            // AI Action Parser — ייצוא Excel/CSV
            const excelMatch = answerText.match(/\[ACTION:EXPORT_EXCEL\|(.*?)\]/);
            if (excelMatch) {
                const exportType = excelMatch[1].trim();
                answerText = answerText.replace(excelMatch[0], '');
                const exportLabels = { orders: 'הזמנות', customers: 'לקוחות', cashflow: 'תזרים', pantry: 'מלאי', staff: 'צוות', 'food-cost': 'Food Cost' };
                const label = exportLabels[exportType] || exportType;
                actionHtml += `<button onclick="window.downloadBizReport('${exportType}')" class="mt-3 w-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-file-excel"></i> הורד דוח ${label} (Excel)</button>`;
            }
            // AI Action Parser — מעבר לטאב
            const tabMatch = answerText.match(/\[ACTION:OPEN_TAB\|(.*?)\]/);
            if (tabMatch) {
                const tabId = tabMatch[1].trim();
                answerText = answerText.replace(tabMatch[0], '');
                actionHtml += `<button onclick="document.getElementById('global-ai-modal').classList.add('hidden'); switchTab('${tabId}')" class="mt-3 w-full bg-slate-50 text-slate-700 hover:bg-slate-100 border border-slate-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-arrow-left"></i> עבור ל${tabId}</button>`;
            }
            // AI Action Parser — יצירת הזמנת שולחן (מסעדה)
            const tableResMatch = answerText.match(/\[ACTION:CREATE_TABLE_RES\|([^|\]]*)\|([^|\]]*)\|([^|\]]*)\|([^|\]]*)(?:\|([^|\]]*))?(?:\|([^\]]*))?\]/);
            if (tableResMatch) {
                const [, trName, trPhone, trDate, trTime, trGuests, trNotes] = tableResMatch;
                answerText = answerText.replace(tableResMatch[0], '');
                actionHtml += `<button onclick="window._aiCreateTableRes('${safeStr(trName)}','${safeStr(trPhone)}','${safeStr(trDate)}','${safeStr(trTime)}','${safeStr(trGuests||'2')}','${safeStr(trNotes||'')}',this)" class="mt-3 w-full bg-orange-50 text-orange-700 hover:bg-orange-100 border border-orange-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-utensils"></i> שמור הזמנת שולחן: ${safeStr(trName)} | ${safeStr(trDate)} ${safeStr(trTime)} | ${safeStr(trGuests||'2')} סועדים</button>`;
            }
            // AI Action Parser — עדכון סטטוס הזמנה
            const updateOrderMatch = answerText.match(/\[ACTION:UPDATE_ORDER_STATUS\|(\d+)\|([\w]+)\]/);
            if (updateOrderMatch) {
                const aoId = updateOrderMatch[1], aoStatus = updateOrderMatch[2];
                answerText = answerText.replace(updateOrderMatch[0], '');
                const aoLabels = {processing:'בעבודה',completed:'הושלם',cancelled:'בוטל',ready:'מוכן',shipped:'בדרך'};
                actionHtml += `<button onclick="window._aiUpdateOrderStatus(${aoId},'${aoStatus}',this)" class="mt-3 w-full bg-blue-50 text-blue-700 hover:bg-blue-100 border border-blue-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-rotate"></i> עדכן הזמנה #${aoId} → ${aoLabels[aoStatus]||aoStatus}</button>`;
            }
            // AI Action Parser — הפעלה/השבתה מנה
            const toggleCatalogMatch = answerText.match(/\[ACTION:TOGGLE_CATALOG_ITEM\|(\d+)\|(true|false)\]/);
            if (toggleCatalogMatch) {
                const tcId = toggleCatalogMatch[1], tcAvail = toggleCatalogMatch[2] === 'true';
                answerText = answerText.replace(toggleCatalogMatch[0], '');
                actionHtml += `<button onclick="window._aiToggleCatalogItem(${tcId},${tcAvail},this)" class="mt-3 w-full bg-purple-50 text-purple-700 hover:bg-purple-100 border border-purple-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-toggle-${tcAvail?'on':'off'}"></i> ${tcAvail?'הפעל':'הסתר'} מנה מהתפריט</button>`;
            }
            // AI Action Parser — עדכון מחיר מנה
            const updatePriceMatch = answerText.match(/\[ACTION:UPDATE_CATALOG_PRICE\|(\d+)\|([\d.]+)\]/);
            if (updatePriceMatch) {
                const upId = updatePriceMatch[1], upPrice = updatePriceMatch[2];
                answerText = answerText.replace(updatePriceMatch[0], '');
                actionHtml += `<button onclick="window._aiUpdateCatalogPrice(${upId},${upPrice},this)" class="mt-3 w-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-tag"></i> עדכן מחיר → ₪${upPrice}</button>`;
            }
            // AI Action Parser — עדכון סטטוס תור (יופי)
            const beautyApptMatch = answerText.match(/\[ACTION:UPDATE_APPT_STATUS\|(\d+)\|([\w_]+)\|([^\]]*)\]/);
            if (beautyApptMatch) {
                const baId = beautyApptMatch[1], baStatus = beautyApptMatch[2], baName = beautyApptMatch[3];
                answerText = answerText.replace(beautyApptMatch[0], '');
                const baLabels = {confirmed:'אושר',cancelled:'בוטל',completed:'הושלם',no_show:'לא הגיע',scheduled:'מתוזמן'};
                actionHtml += `<button onclick="window._aiUpdateApptStatus(${baId},'${baStatus}','${safeStr(baName)}',this)" class="mt-3 w-full bg-pink-50 text-pink-700 hover:bg-pink-100 border border-pink-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-calendar-check"></i> עדכן תור ${safeStr(baName)} → ${baLabels[baStatus]||baStatus}</button>`;
            }
            // AI Action Parser — השלמת תור (יופי)
            const beautyCompleteMatch = answerText.match(/\[ACTION:COMPLETE_APPT\|(\d+)\|([^\]]*)\]/);
            if (beautyCompleteMatch) {
                const bcId = beautyCompleteMatch[1], bcName = beautyCompleteMatch[2];
                answerText = answerText.replace(beautyCompleteMatch[0], '');
                actionHtml += `<button onclick="window._aiCompleteAppt(${bcId},'${safeStr(bcName)}',this)" class="mt-3 w-full bg-green-50 text-green-700 hover:bg-green-100 border border-green-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-circle-check"></i> סיים טיפול: ${safeStr(bcName)}</button>`;
            }
            // AI Action Parser — אי-הגעה (יופי)
            const beautyNoShowMatch = answerText.match(/\[ACTION:NO_SHOW_APPT\|(\d+)\|([^\]]*)\]/);
            if (beautyNoShowMatch) {
                const bnId = beautyNoShowMatch[1], bnName = beautyNoShowMatch[2];
                answerText = answerText.replace(beautyNoShowMatch[0], '');
                actionHtml += `<button onclick="window._aiNoShowAppt(${bnId},'${safeStr(bnName)}',this)" class="mt-3 w-full bg-orange-50 text-orange-700 hover:bg-orange-100 border border-orange-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-user-xmark"></i> סמן "לא הגיע": ${safeStr(bnName)}</button>`;
            }
            // AI Action Parser — הוספת לקוחה (יופי)
            const beautyAddClientMatch = answerText.match(/\[ACTION:ADD_BEAUTY_CLIENT\|([^|^\]]*)\|([^|^\]]*)\|([^\]]*)\]/);
            if (beautyAddClientMatch) {
                const bacName = beautyAddClientMatch[1], bacPhone = beautyAddClientMatch[2], bacNotes = beautyAddClientMatch[3];
                answerText = answerText.replace(beautyAddClientMatch[0], '');
                actionHtml += `<button onclick="window._aiAddBeautyClient('${safeStr(bacName)}','${safeStr(bacPhone)}','${safeStr(bacNotes)}',this)" class="mt-3 w-full bg-purple-50 text-purple-700 hover:bg-purple-100 border border-purple-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-user-plus"></i> הוסף לקוחה: ${safeStr(bacName)}</button>`;
            }
            // AI Action Parser — עדכון סטטוס פנייה (מומחים)
            const leadStatusMatch = answerText.match(/\[ACTION:UPDATE_LEAD_STATUS\|(\d+)\|([\w]+)\|([^\]]*)\]/);
            if (leadStatusMatch) {
                const lsId = leadStatusMatch[1], lsStatus = leadStatusMatch[2], lsName = leadStatusMatch[3];
                answerText = answerText.replace(leadStatusMatch[0], '');
                const lsLabels = {new:'חדש',contacted:'נוצר קשר',converted:'הפך לקוח',closed:'נסגר'};
                actionHtml += `<button onclick="window._aiUpdateLeadStatus(${lsId},'${lsStatus}','${safeStr(lsName)}',this)" class="mt-3 w-full bg-blue-50 text-blue-700 hover:bg-blue-100 border border-blue-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-user-tag"></i> עדכן פנייה ${safeStr(lsName)} → ${lsLabels[lsStatus]||lsStatus}</button>`;
            }
            // AI Action Parser — עדכון סטטוס תיק (מומחים)
            const caseStatusMatch = answerText.match(/\[ACTION:UPDATE_CASE_STATUS\|(\d+)\|([\w]+)\|([^\]]*)\]/);
            if (caseStatusMatch) {
                const csId = caseStatusMatch[1], csStatus = caseStatusMatch[2], csDesc = caseStatusMatch[3];
                answerText = answerText.replace(caseStatusMatch[0], '');
                const csLabels = {processing:'בתהליך',scheduled:'מתוזמן',completed:'הושלם',cancelled:'בוטל',new:'חדש'};
                actionHtml += `<button onclick="window._aiUpdateCaseStatus(${csId},'${csStatus}','${safeStr(csDesc)}',this)" class="mt-3 w-full bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-folder-open"></i> עדכן תיק ${safeStr(csDesc)} → ${csLabels[csStatus]||csStatus}</button>`;
            }
            // AI Action Parser — עדכון סטטוס קריאת שירות (תיקונים)
            const scStatusMatch = answerText.match(/\[ACTION:UPDATE_SC_STATUS\|(\d+)\|([\w_]+)\|([^\]]*)\]/);
            if (scStatusMatch) {
                const scId = scStatusMatch[1], scStatus = scStatusMatch[2], scTitle = scStatusMatch[3];
                answerText = answerText.replace(scStatusMatch[0], '');
                const scLabels = {new:'חדש',scheduled:'נקבע תור',processing:'בטיפול',done:'הושלם',cancelled:'בוטל',waiting_parts:'ממתין לחלקים'};
                actionHtml += `<button onclick="window._aiUpdateSCStatus(${scId},'${scStatus}','${safeStr(scTitle)}',this)" class="mt-3 w-full bg-slate-50 text-slate-700 hover:bg-slate-100 border border-slate-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-wrench"></i> עדכן קריאה: ${safeStr(scTitle)} → ${scLabels[scStatus]||scStatus}</button>`;
            }
            // AI Action Parser — יצירת משימה ישירה (גנרי לכל סוגי עסקים)
            const createTaskMatch = answerText.match(/\[ACTION:CREATE_TASK\|([^|^\]]+)\|([^|^\]]*)\|?(\d*)\]/);
            if (createTaskMatch) {
                const ctTitle = createTaskMatch[1].trim(), ctAssignee = (createTaskMatch[2]||'self').trim(), ctDays = parseInt(createTaskMatch[3])||1;
                answerText = answerText.replace(createTaskMatch[0], '');
                const ctLabel = ctAssignee === 'self' ? 'לי' : ctAssignee;
                actionHtml += `<button onclick="window._aiCreateTask('${safeStr(ctTitle)}','${safeStr(ctAssignee)}',${ctDays},this)" class="mt-3 w-full bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-list-check"></i> צור משימה ל${ctLabel}: ${safeStr(ctTitle)}</button>`;
            }
            // AI Action Parser — יצירת כלל התראה (גנרי לכל סוגי עסקים)
            const createAlertMatch = answerText.match(/\[ACTION:CREATE_ALERT_RULE\|([^|^\]]+)\|([^|^\]]+)\|(\d*)\|?([^\]]*)\]/);
            if (createAlertMatch) {
                const arName = createAlertMatch[1].trim(), arTrigger = createAlertMatch[2].trim(), arCooldown = parseInt(createAlertMatch[3])||60, arDesc = (createAlertMatch[4]||'').trim();
                answerText = answerText.replace(createAlertMatch[0], '');
                const arTriggerLabels = {new_order:'הזמנה חדשה',order_timeout_15:'הזמנה לא מטופלת 15 דקות',order_timeout_30:'הזמנה לא מטופלת 30 דקות',new_lead:'פנייה חדשה',new_booking:'הזמנה/תור חדש',new_service_call:'קריאת שירות חדשה',payment_received:'תשלום התקבל',low_stock:'מלאי נמוך'};
                actionHtml += `<button onclick="window._aiCreateAlertRule('${safeStr(arName)}','${arTrigger}',${arCooldown},'${safeStr(arDesc)}',this)" class="mt-3 w-full bg-yellow-50 text-yellow-700 hover:bg-yellow-100 border border-yellow-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-bell"></i> צור התראה: ${safeStr(arName)} — ${arTriggerLabels[arTrigger]||arTrigger}</button>`;
            }
            // Markdown bold → <strong>
            answerText = answerText.trim().replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br>');
            chatBox.innerHTML += `<div class="bg-white p-3.5 rounded-xl rounded-tr-none shadow-sm border border-slate-100 text-sm text-slate-700 self-start max-w-[85%] fade-in leading-relaxed">${answerText}${actionHtml}</div>`;
            chatBox.scrollTop = chatBox.scrollHeight;
        } else {
            showToast('error', 'שגיאה בתשובת ה-AI');
        }
    } catch(e) { showToast('error', 'תקלת רשת מול מנוע ה-AI'); } finally { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-arrow-up"></i>'; }
}

// ייצוא דוח CSV מהעוזרת העסקית
window.downloadBizReport = async function(type) {
    if (!currentGroup?.id) return;
    showToast('info', 'מכין קובץ ייצוא...');
    try {
        const url = `${API}/biz/export-report?groupId=${currentGroup.id}&type=${type}`;
        const res = await fetch(url);
        if (!res.ok) { showToast('error', 'שגיאה בהפקת דוח'); return; }
        const blob = await res.blob();
        const blobUrl = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = blobUrl;
        const labels = { orders:'הזמנות', customers:'לקוחות', cashflow:'תזרים', pantry:'מלאי', staff:'צוות', 'food-cost':'food_cost', 'sport-members':'חברים_ספורט', 'sport-checkins':'כניסות_ספורט', 'sport-revenue':'הכנסות_ספורט', 'sport-classes':'שיעורים_ספורט', 'logistics-orders':'הזמנות_לוגיסטיקה', 'logistics-drivers':'נהגים_לוגיסטיקה', 'logistics-revenue':'הכנסות_לוגיסטיקה', 'logistics-vehicles':'צי_לוגיסטיקה' };
        a.download = `${labels[type]||type}_${new Date().toISOString().split('T')[0]}.csv`;
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        URL.revokeObjectURL(blobUrl);
        showToast('success', 'הקובץ הורד בהצלחה!');
    } catch(e) { showToast('error', 'שגיאת הורדה'); }
};

// ============================================================
// --- BIZ COMMUNITY & SA MANAGEMENT ---
// ============================================================

let saCommunitiesCache = [];
let saBusinessesCache = [];

async function loadSACommunityData() {
    try {
        const [commRes, bizRes] = await Promise.all([
            fetch(`${API}/sa/communities`),
            fetch(`${API}/sa/businesses`)
        ]);
        const commData = await commRes.json();
        const bizData = await bizRes.json();
        
        if(commData.success) {
            saCommunitiesCache = commData.communities;
            if (typeof filterSACommSelect === 'function') filterSACommSelect();
            if (typeof renderSACommunitiesTable === 'function') renderSACommunitiesTable();
        }
        if(bizData.success) {
            saBusinessesCache = bizData.businesses;
            if (typeof filterSABizSelect === 'function') filterSABizSelect();
        }
        
        // קריאה קריטית להבאת הבקשות הממתינות!
        if (typeof loadSAPendingRequests === 'function') {
            loadSAPendingRequests();
        }
    } catch(e) { console.error("Error loading SA Communities", e); }
}

async function loadSAPendingRequests() {
    const container = getEl('sa-pending-biz-container');
    const list = getEl('sa-pending-biz-list');
    if(!container || !list) return;

    try {
        const res = await fetch(`${API}/sa/communities/pending-businesses`);
        const data = await res.json();
        
        if (data.success && data.pending && data.pending.length > 0) {
            container.classList.remove('hidden');
            list.innerHTML = data.pending.map(p => `
                <div class="bg-white p-4 rounded-2xl shadow-sm border border-orange-100 flex justify-between items-center hover:shadow-md transition mb-2">
                    <div>
                        <h4 class="font-bold text-slate-800 text-sm">העסק: ${safeStr(p.biz_name)}</h4>
                        <p class="text-xs text-slate-500 mt-0.5">מבקש להצטרף לקהילת: <strong>${safeStr(p.comm_name)}</strong></p>
                        <p class="text-[11px] text-green-700 font-bold mt-1 bg-green-50 px-2 py-0.5 rounded-full inline-block border border-green-200">מוכן לתת ${p.discount_pct}% הנחה לחברי הקהילה</p>
                    </div>
                    <div class="flex flex-col gap-2">
                        <button onclick="approveSABizRequest(${p.community_id}, ${p.business_id})" class="bg-slate-800 text-white px-5 py-2 rounded-xl text-xs font-bold hover:bg-slate-700 transition shadow-sm border border-slate-700"><i class="fa-solid fa-check mr-1"></i> אשר וצרף</button>
                        <button onclick="rejectSABizRequest(${p.community_id}, ${p.business_id})" class="bg-red-50 text-red-600 px-5 py-2 rounded-xl text-xs font-bold hover:bg-red-100 transition shadow-sm border border-red-100"><i class="fa-solid fa-xmark mr-1"></i> דחה בקשה</button>
                    </div>
                </div>
            `).join('');
        } else {
            container.classList.add('hidden');
        }
    } catch(e) { console.error('Error loading pending requests', e); }
}

async function approveSABizRequest(communityId, businessId) {
    if(!await window._uiConfirm('האם לאשר את הצטרפות העסק לקהילה? הלקוחות יראו אותו מיד.')) return;
    try {
        const res = await fetch(`${API}/sa/community-business/approve`, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({ communityId, businessId }) });
        if((await res.json()).success) { showToast('success', 'העסק אושר וצורף לקהילה!'); loadSACommunityData(); }
    } catch(e) { showToast('error', 'שגיאת רשת'); }
}

async function rejectSABizRequest(communityId, businessId) {
    if(!await window._uiConfirm('האם לדחות ולהסיר את הבקשה של העסק?')) return;
    try {
        const res = await fetch(`${API}/sa/community-business/reject`, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({ communityId, businessId }) });
        if((await res.json()).success) { showToast('info', 'הבקשה נדחתה והוסרה מהרשימה.'); loadSACommunityData(); }
    } catch(e) { showToast('error', 'שגיאת רשת'); }
}

function filterSACommSelect() {
    const queryInput = getEl('sa-search-comm-select');
    const query = queryInput ? queryInput.value.toLowerCase() : '';
    const select = getEl('sa-link-comm');
    if (!select) return;
    select.innerHTML = '<option value="">בחר קהילה...</option>' + 
        saCommunitiesCache
            .filter(c => c.name.toLowerCase().includes(query) || (c.code && c.code.toLowerCase().includes(query)))
            .map(c => `<option value="${c.id}">${safeStr(c.name)} (${c.code})</option>`)
            .join('');
}

function filterSABizSelect() {
    const queryInput = getEl('sa-search-biz-select');
    const query = queryInput ? queryInput.value.toLowerCase() : '';
    const select = getEl('sa-link-biz');
    if (!select) return;
    select.innerHTML = '<option value="">בחר עסק לחיבור...</option>' + 
        saBusinessesCache
            .filter(b => b.name.toLowerCase().includes(query))
            .map(b => `<option value="${b.id}">${safeStr(b.name)}</option>`)
            .join('');
}

function renderSACommunitiesTable() {
    const tbody = getEl('sa-communities-table-body');
    if (!tbody) return;
    
    const query = getEl('sa-search-comm') ? getEl('sa-search-comm').value.toLowerCase() : '';
    const countFilter = getEl('sa-filter-comm-count') ? getEl('sa-filter-comm-count').value : 'all';
    
    let filtered = [...saCommunitiesCache];
    
    if (query) {
        filtered = filtered.filter(c => 
            (c.name && c.name.toLowerCase().includes(query)) || 
            (c.code && c.code.toLowerCase().includes(query)) ||
            (c.city && c.city.toLowerCase().includes(query))
        );
    }
    
    if (countFilter === 'with_families') {
        filtered = filtered.filter(c => parseInt(c.family_count || 0) > 0);
    } else if (countFilter === 'empty') {
        filtered = filtered.filter(c => parseInt(c.family_count || 0) === 0);
    } else if (countFilter === 'sort_desc') {
        filtered.sort((a, b) => parseInt(b.family_count || 0) - parseInt(a.family_count || 0));
    }
    
    if (filtered.length === 0) {
        tbody.innerHTML = `<tr><td colspan="6" class="px-4 py-8 text-center text-slate-400">לא נמצאו קהילות שמתאימות לסינון.</td></tr>`;
        return;
    }
    
    tbody.innerHTML = filtered.map(c => `
        <tr class="hover:bg-slate-50 transition border-b border-slate-50 last:border-0">
            <td class="px-4 py-4 font-bold text-slate-800">
                ${safeStr(c.name || 'ללא שם (תקלה קודמת)')}
                <div class="text-[10px] text-slate-500 mt-1"><i class="fa-solid fa-location-dot text-red-400"></i> ${safeStr(c.city || 'לא הוגדר')}</div>
            </td>
            <td class="px-4 py-4 font-mono text-orange-600 font-bold tracking-widest">${safeStr(c.code || '---')}</td>
            <td class="px-4 py-4">
                <div class="text-xs text-slate-600 mb-1"><span class="text-slate-400 font-bold ml-1">מייל:</span> ${safeStr(c.manager_email || '---')}</div>
                <div class="text-xs text-slate-600"><span class="text-slate-400 font-bold ml-1">סיסמה:</span> ${safeStr(c.manager_password || '---')}</div>
            </td>
            <td class="px-4 py-4 text-center">
                <span class="bg-indigo-50 text-indigo-600 px-3 py-1.5 rounded-full font-bold text-xs" title="משפחות"><i class="fa-solid fa-house text-[10px]"></i> ${c.family_count || 0}</span>
                <span class="bg-emerald-50 text-emerald-600 px-3 py-1.5 rounded-full font-bold text-xs ml-1" title="עסקים"><i class="fa-solid fa-briefcase text-[10px]"></i> ${c.business_count || 0}</span>
            </td>
            <td class="px-4 py-4 text-center">
                <button onclick="openSACommunityModal(${c.id})" class="bg-blue-100 text-blue-600 hover:bg-blue-200 px-3 py-1.5 rounded-lg text-xs font-bold transition"><i class="fa-solid fa-gear"></i> ניהול / מחיקה</button>
            </td>
        </tr>
    `).join('');
}

function filterSACommunities() { renderSACommunitiesTable(); }

async function createSACommunity() {
    const name = val('sa-comm-name'); const city = val('sa-comm-city'); const code = val('sa-comm-code'); const email = val('sa-comm-email'); const pass = val('sa-comm-pass');
    if(!name || !code || !city) return showToast('error', 'שם, עיר וקוד קהילה הם חובה');
    
    const btn = document.querySelector('button[onclick="createSACommunity()"]');
    if(btn) { btn.disabled = true; btn.innerText = 'מקים...'; }
    try {
        const res = await fetch(`${API}/sa/communities`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({name, city, code, managerEmail: email, managerPassword: pass})});
        const data = await res.json();
        if(data.success) { 
            showToast('success', 'קהילה הוקמה!'); 
            getEl('sa-comm-name').value=''; getEl('sa-comm-city').value=''; getEl('sa-comm-code').value=''; getEl('sa-comm-email').value=''; getEl('sa-comm-pass').value=''; 
            loadSACommunityData(); 
        } else {
            showToast('error', data.error || 'שגיאה בהקמת קהילה');
        }
    } catch(e) { showToast('error', 'שגיאת רשת מול השרת'); }
    finally { if(btn) { btn.disabled = false; btn.innerText = 'הקמת קהילה'; } }
}

async function linkBizToCommunity() {
    const communityId = val('sa-link-comm'); const businessId = val('sa-link-biz'); const discountPct = val('sa-link-discount');
    if(!communityId || !businessId) return showToast('error', 'חובה לבחור קהילה ועסק');
    try {
        const res = await fetch(`${API}/sa/community-business`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({communityId, businessId, discountPct})});
        if((await res.json()).success) { showToast('success', 'העסק חובר בהצלחה!'); loadCommunityBusinesses(); loadSACommunityData(); }
    } catch(e) { showToast('error', 'שגיאת רשת'); }
}

async function loadCommunityBusinesses() {
    const communityId = val('sa-link-comm');
    const list = getEl('sa-comm-biz-list');
    if(!communityId) { if(list) list.innerHTML = 'יש לבחור קהילה מהרשימה'; return; }
    try {
        const res = await fetch(`${API}/sa/community-business/${communityId}`);
        const data = await res.json();
        if(data.success && list) {
            if(data.connections.length === 0) { list.innerHTML = 'אין עסקים מקושרים'; return; }
            list.innerHTML = data.connections.map(c => `<div class="flex justify-between items-center bg-white p-2 rounded border text-xs shadow-sm"><span>${safeStr(c.business_name)} (${c.discount_pct}%)</span><button onclick="removeBizFromCommunity(${c.community_id}, ${c.business_id})" class="text-red-400"><i class="fa-solid fa-times"></i></button></div>`).join('');
        }
    } catch(e) {}
}

async function removeBizFromCommunity(commId, bizId) {
    if(!await window._uiConfirm('להסיר את העסק?', {danger:true, okLabel:'הסר'})) return;
    await fetch(`${API}/sa/community-business/${commId}/${bizId}`, {method:'DELETE'});
    loadCommunityBusinesses(); loadSACommunityData();
}

async function deleteSACommunity(id) {
    if(!await window._uiConfirm('למחוק את הקהילה לצמיתות?', {danger:true, okLabel:'מחק'})) return;
    await fetch(`${API}/sa/communities/${id}`, { method: 'DELETE' });
    loadSACommunityData();
}

async function saveWelcomeMsg(type = 'FAMILY') { 
    const body = type === 'BUSINESS' ? { businessWelcomeMsg: val('sa-biz-welcome-msg') } : { welcomeMsg: val('sa-welcome-msg') };
    const btn = document.querySelector(`button[onclick="saveWelcomeMsg('${type}')"]`);
    if (btn) { btn.disabled = true; btn.innerText = 'שומר...'; }
    try { 
        const res = await fetch(`${API}/superadmin/settings`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': saToken }, body: JSON.stringify(body) }); 
        if ((await res.json()).success) {
            showToast('success', 'הודעת הפתיחה נשמרה בהצלחה!'); 
        } else {
            showToast('error', 'שגיאה בשמירת ההודעה');
        }
    } catch(e) { 
        showToast('error', 'תקלת תקשורת בשמירת ההודעה'); 
    } finally {
        if (btn) { btn.disabled = false; btn.innerText = 'שמור הודעה'; }
    }
}

// ─── ניהול סיור קבלת פנים מהסופר אדמין ───────────────────────────────────────
async function saveTourEnabled(enabled) {
    try {
        await fetch(`${API}/settings/tour`, { method: 'PUT', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${saToken}` }, body: JSON.stringify({ enabled }) });
        showToast('success', enabled ? 'הסיור הופעל בהצלחה' : 'הסיור הושבת בהצלחה');
    } catch(e) { showToast('error', 'שגיאה בשמירה'); }
}

async function loadTourSettings() {
    try {
        const r = await fetch(`${API}/settings/tour`).then(r=>r.json());
        const toggle = document.getElementById('sa-tour-enabled');
        if (toggle) toggle.checked = r.enabled !== false;
    } catch(e) {}
}

window.switchBizCommunityTab = function(tab) {
    ['mine', 'discover', 'pool', 'pool-archive'].forEach(t => {
        const view = document.getElementById(`comm-view-${t}`);
        const btn = document.getElementById(`btn-comm-${t}`);
        if (view) view.classList.add('hidden');
        if (btn) btn.className = 'w-full flex flex-col items-center justify-center gap-1 py-3 px-1 rounded-xl text-[10px] font-bold bg-slate-100 text-slate-600 hover:bg-slate-200 transition';
    });
    const activeView = document.getElementById(`comm-view-${tab}`);
    const activeBtn = document.getElementById(`btn-comm-${tab}`);
    if (activeView) activeView.classList.remove('hidden');
    if (activeBtn) activeBtn.className = 'w-full flex flex-col items-center justify-center gap-1 py-3 px-1 rounded-xl text-[10px] font-bold bg-orange-500 text-white shadow-md shadow-orange-200 transition';
    if (tab === 'discover') filterBizAvailableCommunities();
    if (tab === 'pool') loadBizPools();
    if (tab === 'pool-archive') loadBizPoolArchivePage();
};

async function loadBizCommunities() {
    try {
        if (!currentGroup || !currentGroup.id) return;
        const res = await fetch(`${API}/biz/communities/my/${currentGroup.id}`);
        
        let data;
        try { data = await res.json(); } catch(err) { return; }
        
        if (!res.ok) { return; }
        
        if (data.success && data.communities) {
            myCommunityBusinessesCache = data.communities;
            const list = document.getElementById('biz-my-communities-list');
            if (list) {
                if (data.communities.length === 0) {
                    list.innerHTML = `<div class="text-center py-8 text-slate-400">
  <i class="fa-solid fa-users text-4xl mb-3"></i>
  <p class="font-bold text-sm">אין קהילות פעילות</p>
  <p class="text-xs mt-1">חפש קהילות בטאב "גלה קהילות"</p>
</div>`;
                } else {
                    list.innerHTML = data.communities.map(c => {
                        let statusHtml = c.status === 'approved' ? '<span class="text-green-600 bg-green-50 px-2 py-0.5 rounded text-[10px] border border-green-100">מאושר</span>' : '<span class="text-orange-500 bg-orange-50 px-2 py-0.5 rounded text-[10px] border border-orange-100">ממתין לאישור</span>';
                        const imgHtml = c.image_url ? `<img src="${c.image_url}" class="w-10 h-10 rounded-lg object-cover shadow-sm shrink-0">` : `<div class="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-lg flex items-center justify-center shrink-0"><i class="fa-solid fa-users-rays"></i></div>`;
                        
                        const updateBtn = c.status === 'approved' ? `<button onclick="openUpdateDiscountModal(${c.id},'${safeStr(c.name).replace(/'/g,"\\'")}',${c.discount_pct})" class="text-[10px] font-bold text-teal-600 hover:bg-teal-50 px-2 py-1 rounded border border-transparent hover:border-teal-200 transition"><i class="fa-solid fa-percent mr-1"></i>עדכן הנחה</button>` : '';
                        return `<div class="bg-white p-3 rounded-xl shadow-sm border border-slate-100 flex justify-between items-center mb-2"><div class="flex items-center gap-3">${imgHtml}<div><h4 class="font-bold text-slate-800 text-sm">${safeStr(c.name)}</h4><p class="text-[10px] text-slate-500 mt-0.5"><i class="fa-solid fa-location-dot text-red-400"></i> ${safeStr(c.city || 'כללי')} • <i class="fa-solid fa-house ml-1"></i> ${c.families_count || 0} משפחות (${c.users_count || 0} משתמשים)</p><p class="text-[10px] text-slate-500 mt-0.5">הצעת הנחה: <span class="font-bold text-slate-700">${c.discount_pct}%</span></p></div></div><div class="flex flex-col items-end gap-2">${statusHtml}${updateBtn}<button onclick="leaveBizCommunity(${c.id})" class="text-[10px] font-bold text-red-500 hover:underline">התנתק</button></div></div>`;
                    }).join('');
                }
            }
        }

        await loadBizAvailableCommunities();
        
    } catch(e) { console.error("Error loading biz communities", e); }
}

async function loadBizAvailableCommunities() {
    try {
        if (!currentGroup || !currentGroup.id) return;
        const res = await fetch(`${API}/biz/communities/available/${currentGroup.id}`);
        const data = await res.json();
        if (data.success && data.communities) {
            bizAvailableCommCache = data.communities;
            filterBizAvailableCommunities();
        }
    } catch(e) { console.error("Error loading available communities", e); }
}

// ─── FlowPool — BIZ ──────────────────────────────────────────────────
let _bizMyBids = [];

async function loadBizMyBids() {
    if (!currentGroup || !currentGroup.id) return;
    try {
        const res = await fetch(`${API}/biz/my-pool-bids/${currentGroup.id}`, { headers: { Authorization: `Bearer ${window._bizToken}` } });
        const data = await res.json();
        _bizMyBids = data.success ? (data.bids || []) : [];
        renderBizMyBids();
    } catch(e) { _bizMyBids = []; }
}

function renderBizMyBids() {
    let el = document.getElementById('biz-my-bids-section');
    if (!el) {
        const poolList = document.getElementById('biz-pool-list');
        if (!poolList) return;
        el = document.createElement('div');
        el.id = 'biz-my-bids-section';
        poolList.parentElement.insertBefore(el, poolList);
    }
    if (!_bizMyBids.length) { el.innerHTML = ''; return; }
    const statusIcon = { pending: '⏳', accepted: '✅', rejected: '❌' };
    const statusText = { pending: 'ממתין לאישור', accepted: 'הצעה נבחרה!', rejected: 'לא נבחרה' };
    const statusColor = { pending: 'bg-amber-50 border-amber-200 text-amber-800', accepted: 'bg-green-50 border-green-200 text-green-800', rejected: 'bg-slate-50 border-slate-200 text-slate-500' };
    el.innerHTML = `
    <div class="mb-4">
        <h3 class="text-xs font-black text-slate-600 uppercase tracking-wider mb-2 flex items-center gap-1">
            <i class="fa-solid fa-paper-plane text-blue-400"></i> הצעות שהגשתי
        </h3>
        <div class="space-y-2">
        ${_bizMyBids.map(b => {
            const st = b.bid_status || 'pending';
            const colorClass = statusColor[st] || statusColor.pending;
            const poolClosed = b.pool_status === 'closed' || b.pool_status === 'expired';
            return `<div class="border rounded-2xl p-3 ${colorClass}">
                <div class="flex justify-between items-start mb-1">
                    <span class="text-[11px] font-bold">${statusIcon[st]} ${statusText[st] || st}</span>
                    <div class="text-right">
                        <p class="text-xs font-bold text-slate-800">${safeStr(b.title)}</p>
                        <p class="text-[10px] text-slate-500">יוזם: ${safeStr(b.initiator_name)}</p>
                    </div>
                </div>
                <p class="text-[11px] text-slate-600 mb-2">הצעתי: <span class="font-black">₪${Number(b.price).toLocaleString()}</span> — ${safeStr(b.description)}</p>
                ${!poolClosed ? `<button onclick="openBizPoolChat(${b.pool_id},'${safeStr(b.title).replace(/'/g,"\\'")}','${safeStr(b.initiator_name).replace(/'/g,"\\'")}',${b.initiator_id})" class="text-[11px] font-bold bg-white/70 hover:bg-white border border-current px-3 py-1 rounded-xl transition">
                    💬 שלח הודעה ליוזם
                </button>` : ''}
                ${st === 'accepted' ? `<p class="text-[11px] font-bold mt-2">🎉 מזל טוב! ההצעה שלך נבחרה. צור קשר עם ${safeStr(b.initiator_name)} להמשך.</p>` : ''}
            </div>`;
        }).join('')}
        </div>
    </div>`;
}

window.openBizPoolChat = async function(poolId, poolTitle, initiatorName, initiatorId) {
    const existing = document.getElementById('biz-pool-chat-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'biz-pool-chat-modal';
    modal.className = 'fixed inset-0 bg-white z-[9999] flex flex-col overflow-hidden';
    modal.onclick = null;
    modal.innerHTML = `<div class="w-full max-w-lg mx-auto flex flex-col flex-1 overflow-hidden">
        <div class="flex justify-between items-center px-5 py-4 border-b shrink-0 bg-white sticky top-0 z-10">
            <button onclick="document.getElementById('biz-pool-chat-modal').remove()" class="text-slate-400 hover:text-slate-600 text-xl"><i class="fa-solid fa-xmark"></i></button>
            <div class="text-right">
                <h3 class="font-black text-slate-800 text-sm">${safeStr(poolTitle)}</h3>
                <p class="text-[11px] text-slate-400">שיחה עם ${safeStr(initiatorName)}</p>
            </div>
        </div>
        <div id="biz-pool-chat-msgs" class="flex-1 overflow-y-auto p-4 space-y-2">
            <p class="text-xs text-slate-300 text-center py-4">טוען...</p>
        </div>
        <div class="flex gap-2 p-4 border-t shrink-0">
            <input id="biz-pool-chat-input" type="text" class="modern-input py-2 text-xs flex-1" placeholder="הודעה ליוזם הפול..." onkeydown="if(event.key==='Enter')sendBizPoolMsg(${poolId})">
            <button onclick="sendBizPoolMsg(${poolId})" class="bg-blue-500 text-white px-3 py-2 rounded-xl text-xs font-bold hover:bg-blue-600"><i class="fa-solid fa-paper-plane"></i></button>
        </div>
    </div>`;
    document.body.appendChild(modal);
    await loadBizPoolChatMsgs(poolId);
};

async function loadBizPoolChatMsgs(poolId) {
    const el = document.getElementById('biz-pool-chat-msgs');
    if (!el) return;
    try {
        const res = await fetch(`${API}/community/pool/${poolId}/messages`, { headers: { Authorization: `Bearer ${window._bizToken}` } });
        const data = await res.json();
        const msgs = data.messages || [];
        if (!msgs.length) { el.innerHTML = '<p class="text-xs text-slate-300 text-center py-4">אין הודעות עדיין</p>'; return; }
        el.innerHTML = msgs.map(m => {
            if (m.sender_type === 'system') return `<div class="bg-slate-100 text-slate-500 text-center mx-auto rounded-full px-3 py-1 text-[11px] max-w-xs">${safeStr(m.content)}</div>`;
            const isMine = m.sender_id == currentGroup.id;
            return `<div class="flex ${isMine ? 'flex-row-reverse' : 'flex-row'}">
                <div class="max-w-[80%] px-3 py-2 rounded-2xl text-xs ${isMine ? 'bg-blue-100 text-blue-800 rounded-br-none' : 'bg-slate-100 text-slate-700 rounded-bl-none'}">
                    ${!isMine ? `<p class="text-[10px] font-bold mb-0.5 text-slate-500">${safeStr(m.sender_name || '')}</p>` : ''}
                    ${safeStr(m.content)}
                </div>
            </div>`;
        }).join('');
        el.scrollTop = el.scrollHeight;
    } catch(e) { el.innerHTML = '<p class="text-xs text-red-400 text-center py-4">שגיאה</p>'; }
}

window.sendBizPoolMsg = async function(poolId) {
    const input = document.getElementById('biz-pool-chat-input');
    const content = input ? input.value.trim() : '';
    if (!content) return;
    try {
        await fetch(`${API}/community/pool/${poolId}/message`, {
            method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${window._bizToken}` },
            body: JSON.stringify({ senderId: currentGroup.id, senderType: 'business', content })
        });
        if (input) input.value = '';
        await loadBizPoolChatMsgs(poolId);
    } catch(e) {}
};

async function loadBizPools() {
    const el = document.getElementById('biz-pool-list');
    if (!el || !currentGroup || !currentGroup.id) return;
    el.innerHTML = '<p class="text-xs text-slate-400 text-center py-8">טוען פולים...</p>';
    await loadBizMyBids();
    try {
        const res = await fetch(`${API}/biz/pools/${currentGroup.id}`, { headers: { Authorization: `Bearer ${window._bizToken}` } });
        const data = await res.json();
        if (!data.success) throw new Error(data.error || 'שגיאה');
        const pools = data.pools || [];
        const expiredPools = data.expiredPools || [];
        const myBidPoolIds = new Set(_bizMyBids.map(b => String(b.pool_id)));

        const renderPoolCard = (p, isExpired = false) => {
            const statusLabel = isExpired ? '⏰ פג תוקף' : ({ open_r1: 'סיבוב 1', open_r2: 'סיבוב 2 — עסקים חיצוניים' }[p.status] || p.status);
            const statusColor = isExpired ? 'bg-orange-100 text-orange-700' : (p.status === 'open_r2' ? 'bg-purple-100 text-purple-700' : 'bg-blue-100 text-blue-700');
            const maxP = p.max_price > 0 ? `עד ₪${Number(p.max_price).toLocaleString()}` : 'מחיר פתוח';
            const myBid = _bizMyBids.find(b => String(b.pool_id) === String(p.id));
            let actionBtn = '';
            if (isExpired) {
                actionBtn = `<button onclick="archiveBizPool(${p.id},this)" class="w-full py-2 rounded-xl bg-slate-100 text-slate-600 text-xs font-bold hover:bg-slate-200 transition">📦 העבר לארכיב</button>`;
            } else {
                actionBtn = myBid
                    ? `<div class="w-full py-2 rounded-xl bg-amber-50 border border-amber-200 text-amber-700 text-xs font-bold text-center">⏳ הצעה הוגשה — ₪${Number(myBid.price).toLocaleString()}</div>`
                    : `<button onclick="openBizBidModal(${p.id},'${safeStr(p.title).replace(/'/g,"\\'")}',${p.max_price||0})" class="w-full py-2 rounded-xl bg-blue-500 text-white text-xs font-bold hover:bg-blue-600 transition shadow-sm"><i class="fa-solid fa-gavel ml-1"></i>הגש הצעת מחיר</button>`;
            }
            return `<div class="bg-white rounded-2xl border ${isExpired ? 'border-orange-100' : 'border-slate-100'} shadow-sm p-4">
                <div class="flex justify-between items-start mb-2">
                    <div class="flex-1 min-w-0">
                        <h4 class="font-bold text-slate-800 text-sm">${safeStr(p.title)}</h4>
                        ${p.service_category ? `<p class="text-[11px] text-slate-400">${safeStr(p.service_category)}</p>` : ''}
                    </div>
                    <span class="text-[10px] font-bold px-2 py-0.5 rounded-full ${statusColor} mr-2 shrink-0">${statusLabel}</span>
                </div>
                ${p.description ? `<p class="text-xs text-slate-500 mb-2 line-clamp-2">${safeStr(p.description)}</p>` : ''}
                <div class="flex gap-3 text-xs text-slate-400 mb-3">
                    <span><i class="fa-solid fa-users ml-1"></i>${p.member_count || p.members_count || 0} משפחות</span>
                    <span><i class="fa-solid fa-shekel-sign ml-1"></i>${maxP}</span>
                    <span><i class="fa-solid fa-user ml-1"></i>יוזם: ${safeStr(p.initiator_name)}</span>
                </div>
                ${actionBtn}
            </div>`;
        };

        const activePart = pools.length
            ? pools.map(p => renderPoolCard(p, false)).join('')
            : '<div class="text-center py-8"><i class="fa-solid fa-water text-4xl text-slate-200 mb-3"></i><p class="text-sm font-bold text-slate-500">אין פולים פתוחים כעת</p><p class="text-xs text-slate-400">כשמשפחות בקהילה יפתחו פולים הם יופיעו כאן</p></div>';

        const expiredPart = expiredPools.length
            ? `<div class="mt-4">
                <h3 class="text-xs font-black text-orange-600 uppercase tracking-wider mb-2 flex items-center gap-1">
                    <i class="fa-solid fa-clock text-orange-400"></i> פולים שפג תוקפם (השתתפתי)
                </h3>
                <div class="space-y-2">${expiredPools.map(p => renderPoolCard(p, true)).join('')}</div>
               </div>`
            : '';

        el.innerHTML = activePart + expiredPart;
    } catch (e) {
        el.innerHTML = `<p class="text-xs text-red-400 text-center py-8">${e.message}</p>`;
    }
}

window.archiveBizPool = async function(poolId, btn) {
    if (btn) { btn.disabled = true; btn.textContent = 'מעביר...'; }
    try {
        const res = await fetch(`${API}/community/pool/${poolId}/archive`, {
            method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${window._bizToken}` },
            body: JSON.stringify({ viewerId: currentGroup.id, bizArchive: true })
        });
        const data = await res.json();
        if (!data.success) throw new Error(data.error || 'שגיאה');
        showToast('success', '📦 הפול הועבר לארכיב');
        loadBizPools();
    } catch(e) {
        if (btn) { btn.disabled = false; btn.textContent = '📦 העבר לארכיב'; }
        showToast('error', 'שגיאה: ' + e.message);
    }
};

async function loadBizPoolArchivePage() {
    const el = document.getElementById('biz-pool-archive-list');
    if (!el || !currentGroup) return;
    el.innerHTML = '<p class="text-xs text-slate-400 text-center py-8">טוען ארכיב...</p>';
    try {
        const res = await fetch(`${API}/biz/pool-archive/${currentGroup.id}`, { headers: { Authorization: `Bearer ${window._bizToken}` } });
        const data = await res.json();
        const archived = data.pools || [];
        if (!archived.length) {
            el.innerHTML = '<div class="text-center py-12"><i class="fa-solid fa-box-archive text-4xl text-slate-200 mb-3"></i><p class="text-sm font-bold text-slate-400">הארכיב ריק</p><p class="text-xs text-slate-300 mt-1">פולים שתעבירו לארכיב יופיעו כאן</p></div>';
            return;
        }
        const statusLabel = { open_r1: 'פעיל', open_r2: 'פעיל — סיבוב 2', expired: 'פג תוקף', archived: 'מוארכב', closed: 'סגור' };
        const statusColor = { open_r1: 'bg-blue-100 text-blue-700', open_r2: 'bg-purple-100 text-purple-700', expired: 'bg-orange-100 text-orange-700', archived: 'bg-slate-100 text-slate-600', closed: 'bg-green-100 text-green-700' };
        el.innerHTML = archived.map(p => {
            const myBid = (p.my_price != null) ? `₪${Number(p.my_price).toLocaleString()}` : null;
            const acceptedBadge = p.my_bid_status === 'accepted' ? '<span class="text-[10px] font-bold bg-green-100 text-green-700 px-1.5 py-0.5 rounded-full ml-1">✅ נבחרה</span>' : '';
            const stLabel = statusLabel[p.status] || p.status;
            const stColor = statusColor[p.status] || 'bg-slate-100 text-slate-600';
            return `<div class="bg-white rounded-2xl border border-slate-100 shadow-sm p-4">
                <div class="flex justify-between items-start mb-1">
                    <span class="text-[10px] font-bold px-2 py-0.5 rounded-full ${stColor}">${stLabel}</span>
                    ${acceptedBadge}
                </div>
                <h4 class="font-bold text-slate-800 text-sm mt-1">${safeStr(p.title)}</h4>
                ${p.description ? `<p class="text-xs text-slate-500 mt-0.5 line-clamp-2">${safeStr(p.description)}</p>` : ''}
                <div class="flex gap-3 text-[11px] text-slate-400 mt-2">
                    <span><i class="fa-solid fa-user ml-0.5"></i>יוזם: ${safeStr(p.initiator_name)}</span>
                    ${myBid ? `<span>· הצעתי: <b class="text-slate-600">${myBid}</b></span>` : ''}
                </div>
            </div>`;
        }).join('');
    } catch(e) {
        el.innerHTML = `<p class="text-xs text-red-400 text-center py-8">שגיאה: ${e.message}</p>`;
    }
}

let _bizBidTargetPoolId = null;
function openBizBidModal(poolId, title, maxPrice) {
    _bizBidTargetPoolId = poolId;
    const modal = document.getElementById('modal-biz-bid');
    if (!modal) {
        const m = document.createElement('div');
        m.id = 'modal-biz-bid';
        m.className = 'fixed inset-0 bg-black/60 z-50 flex items-end justify-center';
        m.onclick = function(e) { if (e.target === m) closeBizBidModal(); };
        m.innerHTML = `<div class="bg-white rounded-t-3xl w-full max-w-lg p-6 pb-10 max-h-[90vh] overflow-y-auto">
            <div class="flex justify-between items-center mb-4">
                <h3 class="font-black text-slate-800 text-lg">💼 הגש הצעת מחיר</h3>
                <button onclick="closeBizBidModal()" class="text-slate-400 hover:text-slate-600 text-xl"><i class="fa-solid fa-xmark"></i></button>
            </div>
            <p class="text-sm font-bold text-slate-700 mb-4" id="biz-bid-pool-title"></p>
            <div class="space-y-3">
                <div>
                    <label class="text-xs font-bold text-slate-600 mb-1 block">מחיר מוצע (₪) *</label>
                    <input id="biz-bid-price-input" type="number" min="1" class="modern-input py-2 text-sm w-full" placeholder="הכנס מחיר">
                    <p id="biz-bid-maxprice-note" class="text-[11px] text-slate-400 mt-1"></p>
                </div>
                <div class="border border-slate-200 rounded-xl p-3 bg-slate-50">
                    <p class="text-xs font-black text-slate-700 mb-2">📋 הצעה מסודרת</p>
                    <div class="space-y-2">
                        <div>
                            <label class="text-[11px] font-bold text-slate-500 mb-1 block">מה כולל השירות *</label>
                            <textarea id="biz-bid-includes-input" rows="2" class="modern-input py-2 text-sm w-full resize-none" placeholder="פרט מה בדיוק כולל השירות..."></textarea>
                        </div>
                        <div>
                            <label class="text-[11px] font-bold text-slate-500 mb-1 block">לוח זמנים</label>
                            <input id="biz-bid-timeline-input" type="text" class="modern-input py-2 text-sm w-full" placeholder="לדוגמה: תוך 3 ימי עסקים, שבוע...">
                        </div>
                        <div>
                            <label class="text-[11px] font-bold text-slate-500 mb-1 block">תנאים והערות</label>
                            <textarea id="biz-bid-terms-input" rows="2" class="modern-input py-2 text-sm w-full resize-none" placeholder="תנאי תשלום, הגבלות, הערות נוספות..."></textarea>
                        </div>
                    </div>
                </div>
            </div>
            <div class="mt-5 flex gap-3">
                <button onclick="closeBizBidModal()" class="flex-1 py-3 rounded-xl border border-slate-200 text-slate-600 text-sm font-bold hover:bg-slate-50 transition">ביטול</button>
                <button onclick="submitBizPoolBid()" class="flex-1 py-3 rounded-xl bg-blue-500 text-white text-sm font-bold hover:bg-blue-600 transition shadow-md">שלח הצעה</button>
            </div>
        </div>`;
        document.body.appendChild(m);
    }
    const modal2 = document.getElementById('modal-biz-bid');
    modal2.classList.remove('hidden');
    const titleEl = document.getElementById('biz-bid-pool-title');
    if (titleEl) titleEl.textContent = title;
    const note = document.getElementById('biz-bid-maxprice-note');
    if (note) note.textContent = maxPrice > 0 ? `* המחיר המקסימלי בפול: ₪${Number(maxPrice).toLocaleString()}` : '';
    const priceInput = document.getElementById('biz-bid-price-input');
    if (priceInput) priceInput.value = '';
    ['biz-bid-includes-input','biz-bid-timeline-input','biz-bid-terms-input'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
}
function closeBizBidModal() {
    const m = document.getElementById('modal-biz-bid');
    if (m) m.classList.add('hidden');
}

async function submitBizPoolBid() {
    const price = parseFloat(document.getElementById('biz-bid-price-input').value);
    const includes = (document.getElementById('biz-bid-includes-input')?.value || '').trim();
    const timeline = (document.getElementById('biz-bid-timeline-input')?.value || '').trim();
    const terms = (document.getElementById('biz-bid-terms-input')?.value || '').trim();
    if (!price || price <= 0) { showToast('הכנס מחיר תקף', 'error'); return; }
    if (!includes) { showToast('נדרש לפרט מה כולל השירות', 'error'); return; }
    if (!_bizBidTargetPoolId) return;
    const parts = [`📦 מה כולל: ${includes}`];
    if (timeline) parts.push(`⏱ לוח זמנים: ${timeline}`);
    if (terms) parts.push(`📌 תנאים: ${terms}`);
    const description = parts.join('\n');
    try {
        const res = await fetch(`${API}/community/pool/${_bizBidTargetPoolId}/bid`, { method: 'POST', headers: { ...{ Authorization: `Bearer ${window._bizToken}` }, 'Content-Type': 'application/json' }, body: JSON.stringify({ price, description, businessGroupId: currentGroup.id }) });
        const data = await res.json();
        if (!data.success) throw new Error(data.error || 'שגיאה');
        showToast('✅ הצעה הוגשה בהצלחה! היא תופיע בסקציית "הצעות שהגשתי"', 'success');
        closeBizBidModal();
        loadBizPools();
    } catch (e) { showToast(e.message, 'error'); }
}

window.setDiscoverMode = function(mode) {
    const cityPanel = document.getElementById('disc-panel-city');
    const bizPanel = document.getElementById('disc-panel-biz');
    const cityBtn = document.getElementById('disc-mode-city');
    const bizBtn = document.getElementById('disc-mode-biz');
    const active = 'flex-1 py-2 px-3 rounded-xl text-xs font-bold bg-orange-500 text-white transition';
    const inactive = 'flex-1 py-2 px-3 rounded-xl text-xs font-bold bg-slate-100 text-slate-600 hover:bg-slate-200 transition';
    if (mode === 'city') {
        if (cityPanel) cityPanel.classList.remove('hidden');
        if (bizPanel) bizPanel.classList.add('hidden');
        if (cityBtn) cityBtn.className = active;
        if (bizBtn) bizBtn.className = inactive;
    } else {
        if (cityPanel) cityPanel.classList.add('hidden');
        if (bizPanel) bizPanel.classList.remove('hidden');
        if (cityBtn) cityBtn.className = inactive;
        if (bizBtn) bizBtn.className = active;
    }
};

window.detectBizCity = function() {
    const cityInp = document.getElementById('biz-filter-city');
    if (!cityInp) return;
    // Try from business profile first
    const profileCity = currentGroup?.city || currentGroup?.address_city;
    if (profileCity) {
        cityInp.value = profileCity;
        filterBizAvailableCommunities();
        return;
    }
    // Fallback: browser geolocation → reverse geocode
    if (!navigator.geolocation) { showToast('info', 'הדפדפן לא תומך בזיהוי מיקום'); return; }
    showToast('info', '📍 מזהה מיקום...');
    navigator.geolocation.getCurrentPosition(async pos => {
        try {
            const r = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${pos.coords.latitude}&lon=${pos.coords.longitude}&format=json&accept-language=he`);
            const d = await r.json();
            const city = d.address?.city || d.address?.town || d.address?.village || '';
            if (city && cityInp) {
                cityInp.value = city;
                filterBizAvailableCommunities();
            }
        } catch(e) { showToast('error', 'לא הצלחנו לזהות את העיר'); }
    }, () => showToast('error', 'לא ניתן לגשת למיקום'));
};

window.discoverViaBusinessCode = async function() {
    const code = (document.getElementById('biz-via-code')?.value || '').trim().toUpperCase();
    const el = document.getElementById('biz-via-result');
    const list = document.getElementById('biz-available-communities-list');
    if (!code || !currentGroup?.id) return;
    if (el) el.innerHTML = '<p class="text-xs text-slate-400 text-center py-3">מחפש...</p>';
    try {
        const res = await fetch(`${API}/biz/communities/via-biz/${code}/${currentGroup.id}`);
        const data = await res.json();
        if (!data.success) { if (el) el.innerHTML = `<p class="text-xs text-red-500 text-center py-2">${data.error || 'שגיאה'}</p>`; return; }
        if (el) el.innerHTML = `<p class="text-xs text-green-700 font-bold bg-green-50 rounded-lg px-3 py-1.5">✅ קהילות של ${safeStr(data.via_biz)}:</p>`;
        const comms = data.communities || [];
        if (!comms.length) { if (list) list.innerHTML = '<p class="text-xs text-slate-400 text-center py-6 col-span-2">העסק אינו חבר בקהילות שאינך כבר חבר בהן</p>'; return; }
        if (list) list.innerHTML = comms.map(c => {
            const imgHtml = c.image_url ? `<img src="${c.image_url}" class="w-10 h-10 rounded-xl object-cover shadow-sm border border-slate-100 shrink-0">` : `<div class="w-10 h-10 rounded-xl bg-indigo-50 flex items-center justify-center text-indigo-400 shrink-0"><i class="fa-solid fa-users-rays"></i></div>`;
            return `<div class="bg-white p-4 rounded-2xl shadow-sm border border-indigo-100 flex flex-col justify-between hover:shadow-md transition">
                <div class="flex items-center gap-3 mb-3">
                    ${imgHtml}
                    <div>
                        <h4 class="font-bold text-slate-800 text-sm">${safeStr(c.name)}</h4>
                        <p class="text-[10px] text-slate-500"><i class="fa-solid fa-location-dot text-red-400"></i> ${safeStr(c.city || 'כללי')} · ${c.families_count || 0} משפחות</p>
                    </div>
                </div>
                <button onclick="openBizJoinModal(${c.id}, '${safeStr(c.name).replace(/'/g,"\\'")}') " class="w-full bg-slate-800 text-white py-2 rounded-xl text-xs font-bold hover:bg-slate-700 transition">הצטרף לקהילה</button>
            </div>`;
        }).join('');
    } catch(e) { if (el) el.innerHTML = '<p class="text-xs text-red-500 text-center py-2">שגיאת רשת</p>'; }
};

function filterBizAvailableCommunities() {
    const list = document.getElementById('biz-available-communities-list');
    if (!list) return;

    const cityFilter = (val('biz-filter-city') || '').toLowerCase();
    const sizeFilter = val('biz-filter-size') || 'all';
    const multiFilter = getEl('biz-filter-multi') ? getEl('biz-filter-multi').checked : false;

    let filtered = [...bizAvailableCommCache];

    if (cityFilter) {
        filtered = filtered.filter(c =>
            (c.name && c.name.toLowerCase().includes(cityFilter)) ||
            (c.city && c.city.toLowerCase().includes(cityFilter))
        );
    }
    
    if (sizeFilter !== 'all') {
        const minSize = parseInt(sizeFilter);
        filtered = filtered.filter(c => parseInt(c.families_count || 0) >= minSize);
    }

    if (multiFilter) {
        filtered = filtered.filter(c => c.city && c.city.split(',').filter(x => x.trim()).length >= 2);
    }

    if (filtered.length === 0) {
        list.innerHTML = '<p class="text-xs text-slate-400 text-center py-6 bg-slate-50 rounded-xl w-full sm:col-span-2 border border-dashed border-slate-200">לא נמצאו קהילות פתוחות התואמות לחיפוש.</p>';
        return;
    }

    list.innerHTML = filtered.map(c => {
        const imgHtml = c.image_url ? `<img src="${c.image_url}" class="w-10 h-10 rounded-full object-cover shadow-sm mb-2 border border-slate-100">` : '';
        return `
        <div class="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex flex-col justify-between hover:shadow-md transition">
            <div class="flex justify-between items-start mb-3">
                <div>
                    ${imgHtml}
                    <h4 class="font-bold text-slate-800">${safeStr(c.name)}</h4>
                    <p class="text-[10px] text-slate-500 mt-1 max-w-[150px] truncate"><i class="fa-solid fa-location-dot text-red-400"></i> ${safeStr(c.city || 'כללי')}</p>
                </div>
                <div class="flex flex-col gap-1 items-end">
                    <span class="bg-emerald-50 text-emerald-600 px-2 py-1 rounded font-bold text-[10px]"><i class="fa-solid fa-house"></i> ${c.families_count || 0} משפחות</span>
                    <span class="bg-blue-50 text-blue-600 px-2 py-1 rounded font-bold text-[10px]"><i class="fa-solid fa-user"></i> ${c.users_count || 0} משתמשים</span>
                </div>
            </div>
            <button onclick="openBizJoinModal(${c.id}, '${safeStr(c.name)}')" class="w-full bg-slate-800 text-white py-2 rounded-xl text-xs font-bold hover:bg-slate-700 transition mt-2">בקשת הצטרפות</button>
        </div>
        `;
    }).join('');
}

function openBizJoinModal(id, name) {
    const idEl = getEl('biz-join-comm-id');
    const nameEl = getEl('biz-join-comm-name');
    const modal = getEl('biz-join-community-modal');
    if (idEl && nameEl && modal) {
        idEl.value = id;
        nameEl.innerText = `בקשת הצטרפות ל: ${name}`;
        getEl('biz-join-discount').value = '';
        modal.classList.remove('hidden');
    }
}

async function submitBizCommunityJoin() {
    const commId = getEl('biz-join-comm-id').value;
    const discount = parseFloat(getEl('biz-join-discount').value);
    
    if (isNaN(discount) || discount < 0) return showToast('error', 'יש להזין אחוז הנחה תקין (אפשרי 0)');
    
    try {
        const res = await fetch(`${API}/biz/communities/join`, {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ communityId: commId, businessId: currentGroup.id, discountPct: discount })
        });
        const data = await res.json();
        
        if(data.success) {
            showToast('success', 'בקשת ההצטרפות נשלחה לניהול הקהילה!');
            getEl('biz-join-community-modal').classList.add('hidden');
            loadBizCommunities();
        } else {
            showToast('error', data.error || 'שגיאה בשליחת הבקשה');
        }
    } catch(e) { showToast('error', 'תקלת רשת'); }
}

window.openUpdateDiscountModal = function(commId, commName, currentDiscount) {
    const existing = document.getElementById('update-discount-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'update-discount-modal';
    modal.className = 'fixed inset-0 z-[9999] bg-black/50 flex items-center justify-center p-4';
    modal.innerHTML = `
    <div class="bg-white rounded-3xl p-6 w-full max-w-sm shadow-2xl" dir="rtl">
        <h3 class="font-bold text-slate-800 mb-1"><i class="fa-solid fa-percent text-teal-500 mr-1"></i> עדכון אחוז הנחה</h3>
        <p class="text-sm text-slate-500 mb-4">קהילת ${safeStr(commName)}</p>
        <label class="text-xs font-bold text-slate-600 block mb-1">אחוז הנחה חדש לחברי הקהילה:</label>
        <input id="update-discount-input" type="number" min="0" max="100" value="${currentDiscount}" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm mb-4 focus:ring-2 focus:ring-teal-300 outline-none">
        <div class="flex gap-2">
            <button onclick="submitUpdateDiscount(${commId})" class="flex-1 bg-teal-500 text-white py-2.5 rounded-xl font-bold text-sm hover:bg-teal-600">שמור</button>
            <button onclick="document.getElementById('update-discount-modal').remove()" class="flex-1 bg-slate-100 text-slate-600 py-2.5 rounded-xl font-bold text-sm hover:bg-slate-200">ביטול</button>
        </div>
    </div>`;
    document.body.appendChild(modal);
    document.getElementById('update-discount-input')?.focus();
};

window.submitUpdateDiscount = async function(commId) {
    const val = document.getElementById('update-discount-input')?.value;
    if (val === '' || val === undefined) return showToast('error', 'יש להזין אחוז הנחה');
    try {
        const res = await fetch(`${API}/biz/community-discount`, {
            method: 'PUT', headers: {'Content-Type':'application/json'},
            body: JSON.stringify({ businessId: currentGroup.id, communityId: commId, discountPct: parseFloat(val)||0 })
        });
        const data = await res.json();
        if (data.success) { showToast('success', 'ההנחה עודכנה בהצלחה'); document.getElementById('update-discount-modal')?.remove(); loadBizCommunities(); }
        else showToast('error', data.error || 'שגיאה');
    } catch(e) { showToast('error', 'שגיאת רשת'); }
};

async function leaveBizCommunity(commId) {
    if(!await window._uiConfirm('האם אתה בטוח שברצונך להתנתק מקהילה זו? לקוחות הקהילה לא יוכלו ליהנות יותר מההטבות בחנות שלך.')) return;
    
    try {
        const res = await fetch(`${API}/biz/communities/leave/${commId}/${currentGroup.id}`, { method: 'DELETE' });
        const data = await res.json();
        if(data.success) {
            showToast('success', 'התנתקת מהקהילה בהצלחה.');
            loadBizCommunities();
        } else {
            showToast('error', 'שגיאה בהתנתקות מהקהילה');
        }
    } catch(e) { showToast('error', 'תקלת רשת'); }
}

