let currentWizardStep = 1;
wizardProducts = []; // כבר מוגדר בראש הקובץ, רק מאפסים פה

// ══════════════════════════════════════════════════════
//  BUSINESS TYPE WIZARD — בחירת מהות עסק (עסק חדש)
// ══════════════════════════════════════════════════════
function showBusinessTypeWizard(afterSave) {
    if (document.getElementById('biz-type-wizard')) return;
    let selected = currentGroup?.business_type || null;

    const WIZARD_TYPES = [
        { id: 'restaurant',   icon: '🍕', name: 'מסעדה' },
        { id: 'services',     icon: '🔧', name: 'שירות / מתקינים' },
        { id: 'sport',        icon: '🏋️', name: 'ספורט וחוגים' },
        { id: 'professional', icon: '👔', name: 'מומחים' },
        { id: 'beauty',       icon: '💅', name: 'יופי ואסטטיקה' },
    ];

    const cards = WIZARD_TYPES.map(b => `
        <button type="button" onclick="btWizSelect('${b.id}',this)"
            class="bt-wiz-card flex flex-col items-center gap-2 p-4 rounded-2xl border-2 transition active:scale-95 ${selected===b.id?'border-indigo-500 bg-indigo-50':'border-slate-200 bg-white hover:border-indigo-200'}"
            data-btype="${b.id}" style="touch-action:manipulation;cursor:pointer;">
            <span class="text-3xl">${b.icon}</span>
            <span class="text-xs font-bold text-slate-700 text-center leading-tight">${b.name}</span>
        </button>`).join('');

    const html = `<div id="biz-type-wizard" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[99999] flex items-center justify-center p-4">
        <div class="bg-white w-full max-w-lg rounded-[2rem] shadow-2xl flex flex-col max-h-[90vh]">
            <div class="bg-gradient-to-r from-indigo-600 to-purple-700 rounded-t-[2rem] px-6 py-5 text-white text-center">
                <div class="text-3xl mb-2">🏢</div>
                <h2 class="text-xl font-black mb-1">מה סוג העסק שלך?</h2>
                <p class="text-white/70 text-xs">הבחירה תתאים את המערכת לצרכי העסק שלך</p>
            </div>
            <div class="flex-1 overflow-y-auto modal-scroll p-5">
                <div class="grid grid-cols-3 gap-3 mb-4">${cards}</div>
                <button type="button" onclick="btWizSelect('other',null)" class="w-full text-center text-xs text-slate-400 py-2 hover:text-slate-600 transition" style="touch-action:manipulation;cursor:pointer;">
                    לא מוצא את הסוג שלי — בחר "כללי"
                </button>
            </div>
            <div class="px-5 py-4 border-t border-slate-100 shrink-0">
                <button type="button" id="bt-wiz-confirm" onclick="btWizConfirm()"
                    class="w-full py-3.5 rounded-xl font-bold shadow transition ${selected ? 'bg-indigo-600 text-white hover:bg-indigo-700' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}"
                    ${selected ? '' : 'disabled'}>
                    ${selected ? 'המשך →' : 'בחר סוג עסק להמשך'}
                </button>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);

    window._btWizSelected = selected;
    window._btWizAfterSave = afterSave || null;
}

window.btWizSelect = function(typeId, btn) {
    window._btWizSelected = typeId;
    document.querySelectorAll('.bt-wiz-card').forEach(b => {
        b.className = b.className.replace(/border-indigo-500 bg-indigo-50|border-slate-200 bg-white hover:border-indigo-200/g, '');
        b.className += b.dataset.btype === typeId ? ' border-indigo-500 bg-indigo-50' : ' border-slate-200 bg-white hover:border-indigo-200';
    });
    const confirmBtn = document.getElementById('bt-wiz-confirm');
    if (confirmBtn) {
        confirmBtn.disabled = false;
        confirmBtn.className = confirmBtn.className.replace('bg-slate-200 text-slate-400 cursor-not-allowed','bg-indigo-600 text-white hover:bg-indigo-700');
        confirmBtn.textContent = 'המשך →';
    }
};

window.btWizConfirm = async function() {
    const typeId = window._btWizSelected;
    if (!typeId) return;
    try {
        await fetch(`/api/groups/${currentGroup.id}/business-settings`, {
            method:'PATCH', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({ business_type: typeId, licensed_features: currentGroup.licensed_features || {} })
        });
        currentGroup.business_type = typeId;
        applyBusinessTypeFilter();
        document.getElementById('biz-type-wizard')?.remove();
        if (window._btWizAfterSave) { window._btWizAfterSave(); return; }
        // For new businesses — continue to main onboarding wizard
        if (currentGroup.is_onboarded === false) {
            const _wizFn = typeId === 'other' ? showOnboardingWizard : showOnboardingWizardV2;
            setTimeout(_wizFn, 300);
        } else {
            showToast('success', `מהות העסק עודכנה ל-${BUSINESS_TYPES.find(b=>b.id===typeId)?.name||typeId}`);
        }
    } catch(e) { showToast('error', 'שגיאה בשמירה'); }
};

function showBusinessTypeWizardV2(afterSave) {
    if (document.getElementById('biz-type-wizard-v2')) return;
    let selected = currentGroup?.business_type || null;

    const TYPES_V2 = [
        { id: 'restaurant',   icon: '🍕', name: 'מסעדה / אוכל',         sub: 'קופה, תפריט, שולחנות, משלוחים' },
        { id: 'beauty',       icon: '💅', name: 'יופי ואסטטיקה',         sub: 'תורים, מטפלות, שירותים, מנויים' },
        { id: 'sport',        icon: '🏋️', name: 'ספורט וחוגים',          sub: 'מנויים, מאמנים, לוח אימונים, צ׳ק-אין' },
        { id: 'services',     icon: '🔧', name: 'תיקונים ושירותים',      sub: 'קריאות שירות, הצעות מחיר, לקוחות, גבייה' },
        { id: 'professional', icon: '👔', name: 'מומחים וייעוץ',         sub: 'תיקים, פגישות, מסמכים, אתר תדמית' },
        { id: 'other',        icon: '🏢', name: 'כללי / אחר',             sub: 'כל המודולים פתוחים, גמישות מלאה' },
    ];

    const cards = TYPES_V2.map(t => `
        <button type="button" onclick="btWizV2Select('${t.id}',this)"
            class="bt-wiz-v2-card flex flex-col items-start gap-1.5 p-4 rounded-2xl border-2 transition active:scale-95 w-full text-right
                ${selected === t.id ? 'border-indigo-500 bg-indigo-50' : 'border-slate-200 bg-white hover:border-indigo-200'}"
            data-btype="${t.id}" style="touch-action:manipulation;cursor:pointer;">
            <span class="text-3xl">${t.icon}</span>
            <span class="text-sm font-black text-slate-800 leading-tight">${t.name}</span>
            <span class="text-[11px] text-slate-400 leading-snug">${t.sub}</span>
        </button>`).join('');

    const confirmClass = selected
        ? 'bg-indigo-600 text-white hover:bg-indigo-700'
        : 'bg-slate-200 text-slate-400 cursor-not-allowed';

    const html = `<div id="biz-type-wizard-v2" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[99999] flex items-center justify-center p-4">
        <div class="bg-white w-full max-w-lg rounded-[2rem] shadow-2xl flex flex-col max-h-[90vh]">
            <div class="bg-gradient-to-r from-indigo-600 to-purple-700 rounded-t-[2rem] px-6 py-5 text-white text-center">
                <div class="text-3xl mb-2">🏢</div>
                <h2 class="text-xl font-black mb-1">מה סוג העסק שלך?</h2>
                <p class="text-white/70 text-xs">הבחירה תתאים את המערכת לצרכי העסק שלך</p>
            </div>
            <div class="flex-1 overflow-y-auto modal-scroll p-5">
                <div class="grid grid-cols-2 gap-3">${cards}</div>
            </div>
            <div class="px-5 py-4 border-t border-slate-100 shrink-0">
                <button type="button" id="bt-wiz-v2-confirm" onclick="btWizV2Confirm()"
                    class="w-full py-3.5 rounded-xl font-bold shadow transition ${confirmClass}"
                    ${selected ? '' : 'disabled'}>
                    ${selected ? 'המשך ←' : 'בחר סוג עסק להמשך'}
                </button>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);

    window._btWizV2Selected = selected;
    window._btWizV2AfterSave = afterSave || null;
}

window.btWizV2Select = function(typeId, btn) {
    window._btWizV2Selected = typeId;
    document.querySelectorAll('.bt-wiz-v2-card').forEach(b => {
        b.className = b.className.replace(/border-indigo-500 bg-indigo-50|border-slate-200 bg-white hover:border-indigo-200/g, '');
        b.className += b.dataset.btype === typeId ? ' border-indigo-500 bg-indigo-50' : ' border-slate-200 bg-white hover:border-indigo-200';
    });
    const confirmBtn = document.getElementById('bt-wiz-v2-confirm');
    if (confirmBtn) {
        confirmBtn.disabled = false;
        confirmBtn.className = confirmBtn.className.replace('bg-slate-200 text-slate-400 cursor-not-allowed', 'bg-indigo-600 text-white hover:bg-indigo-700');
        confirmBtn.textContent = 'המשך ←';
    }
};

window.btWizV2SelectOther = function() {
    window._btWizV2Selected = 'other';
    btWizV2Confirm();
};

window.btWizV2Confirm = async function() {
    const typeId = window._btWizV2Selected;
    if (!typeId) return;
    const confirmBtn = document.getElementById('bt-wiz-v2-confirm');
    if (confirmBtn) { confirmBtn.disabled = true; confirmBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>'; }
    try {
        await fetch(`/api/groups/${currentGroup.id}/business-settings`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ business_type: typeId, licensed_features: currentGroup.licensed_features || {} })
        });
        currentGroup.business_type = typeId;
        applyBusinessTypeFilter();
        document.getElementById('biz-type-wizard-v2')?.remove();
        if (window._btWizV2AfterSave) { window._btWizV2AfterSave(); return; }
        if (currentGroup.is_onboarded === false) {
            // מסך ביניים — הקמה מלאה או חנות בלבד
            setTimeout(function() { _showWizardPathChoice(typeId); }, 300);
        } else {
            showToast('success', `מהות העסק עודכנה ל-${BUSINESS_TYPES.find(b => b.id === typeId)?.name || typeId}`);
        }
    } catch(e) { showToast('error', 'שגיאה בשמירה'); }
};

function _showWizardPathChoice(typeId) {
    const bizName = BUSINESS_TYPES.find(b => b.id === typeId)?.name || typeId;
    const bizIcon = BUSINESS_TYPES.find(b => b.id === typeId)?.icon || '🏢';
    document.getElementById('wizard-path-choice')?.remove();
    const html = `<div id="wizard-path-choice" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[99999] flex items-center justify-center p-4">
        <div class="bg-white w-full max-w-sm rounded-[2rem] shadow-2xl overflow-hidden">
            <div class="bg-gradient-to-r from-indigo-600 to-purple-700 px-6 py-5 text-white text-center">
                <div class="text-3xl mb-1">${bizIcon}</div>
                <div class="text-base font-black mb-0.5">${bizName}</div>
                <p class="text-white/75 text-xs">כיצד תרצה להמשיך?</p>
            </div>
            <div class="p-5 space-y-3">
                <button type="button" onclick="_wizPathFullSetup('${typeId}')"
                    class="w-full flex items-center gap-4 p-4 rounded-2xl border-2 border-indigo-400 bg-indigo-50 hover:bg-indigo-100 transition text-right active:scale-95">
                    <span class="text-2xl shrink-0">🚀</span>
                    <div>
                        <div class="text-sm font-black text-indigo-800">הקמה מלאה</div>
                        <div class="text-[11px] text-indigo-600 mt-0.5">אשף שלב-אחר-שלב — פרטים, צוות, שירותים ועוד</div>
                    </div>
                </button>
                <button type="button" onclick="_wizPathStoreOnly('${typeId}')"
                    class="w-full flex items-center gap-4 p-4 rounded-2xl border-2 border-emerald-400 bg-emerald-50 hover:bg-emerald-100 transition text-right active:scale-95">
                    <span class="text-2xl shrink-0">🛍️</span>
                    <div>
                        <div class="text-sm font-black text-emerald-800">חנות בלבד בשלב זה</div>
                        <div class="text-[11px] text-emerald-600 mt-0.5">הקם חנות מהירה — ניתן להרחיב שירותים בהמשך לפי הסוג</div>
                    </div>
                </button>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
}

window._wizPathFullSetup = function(typeId) {
    document.getElementById('wizard-path-choice')?.remove();
    const _wizFn = typeId === 'other' ? showOnboardingWizard : showOnboardingWizardV2;
    setTimeout(_wizFn, 200);
};

window._wizPathStoreOnly = function(typeId) {
    document.getElementById('wizard-path-choice')?.remove();
    const html = `<div id="store-only-wizard-choice" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[99999] flex items-center justify-center p-4">
        <div class="bg-white w-full max-w-sm rounded-[2rem] shadow-2xl overflow-hidden">
            <div class="bg-gradient-to-r from-emerald-500 to-teal-600 px-6 py-5 text-white text-center">
                <div class="text-3xl mb-2">🛍️</div>
                <h2 class="text-lg font-black mb-1">חנות בלבד</h2>
                <p class="text-white/80 text-xs">בחר כיצד תרצה להמשיך</p>
            </div>
            <div class="p-5 space-y-3">
                <button type="button" onclick="btWizV2StoreOnlyNow()"
                    class="w-full flex items-center gap-4 p-4 rounded-2xl border-2 border-emerald-400 bg-emerald-50 hover:bg-emerald-100 transition text-right active:scale-95">
                    <span class="text-2xl shrink-0">⚡</span>
                    <div>
                        <div class="text-sm font-black text-emerald-800">בנה את החנות עכשיו</div>
                        <div class="text-[11px] text-emerald-600 mt-0.5">אשף מהיר — שם, לוגו ומוצרים ראשונים</div>
                    </div>
                </button>
                <button type="button" onclick="btWizV2StoreOnlyLater()"
                    class="w-full flex items-center gap-4 p-4 rounded-2xl border-2 border-slate-200 bg-slate-50 hover:bg-slate-100 transition text-right active:scale-95">
                    <span class="text-2xl shrink-0">⏩</span>
                    <div>
                        <div class="text-sm font-black text-slate-700">דלג להגדרות חנות מאוחר יותר</div>
                        <div class="text-[11px] text-slate-400 mt-0.5">כניסה ישירה לממשק — תגדיר את החנות בקצב שלך</div>
                    </div>
                </button>
                <button type="button" onclick="document.getElementById('store-only-wizard-choice').remove(); _showWizardPathChoice('${typeId}');"
                    class="w-full text-xs text-slate-400 py-2 hover:text-slate-600 transition underline">חזור</button>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
};

// ── חנות בלבד — מסלול מהיר ──────────────────────────────────────────────────

window.btWizV2StoreOnlyNow = async function() {
    document.getElementById('store-only-wizard-choice')?.remove();
    // שמור business_type = 'other' (הכי גנרי — מפעיל מודול חנות)
    try {
        await fetch(`/api/groups/${currentGroup.id}/business-settings`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ business_type: 'other', licensed_features: currentGroup.licensed_features || {} })
        });
        currentGroup.business_type = 'other';
        applyBusinessTypeFilter();
    } catch(e) {}
    // הפעל ויזארד מסלול store_only (skipInit=true — כבר הגדרנו wizardStepsV2)
    wizardStepsV2 = ['identity', 'catalog'];
    currentWizardStepV2 = 0;
    wizardV2Data = {};
    setTimeout(function() { showOnboardingWizardV2(true); }, 300);
};

window.btWizV2StoreOnlyLater = async function() {
    document.getElementById('store-only-wizard-choice')?.remove();
    // שמור business_type = 'other', סמן כ-onboarded (דילוג מלא על ויזארד)
    try {
        await fetch(`/api/groups/${currentGroup.id}/business-settings`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ business_type: 'other', licensed_features: currentGroup.licensed_features || {} })
        });
        currentGroup.business_type = 'other';
        applyBusinessTypeFilter();
        // סמן כ-onboarded ← מסיר את הוויזארד מהמסך
        await fetch(`/api/biz/wizard/complete`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' } });
        currentGroup.is_onboarded = true;
        showToast('success', 'ברוכים הבאים! תוכל להגדיר את החנות בטאב מכירות ← הגדרות');
        // ניווט ישיר להגדרות חנות
        setTimeout(function() {
            if (typeof switchTab === 'function') switchTab('sales');
            setTimeout(function() {
                if (typeof window.switchSalesTab === 'function') window.switchSalesTab('settings');
            }, 300);
        }, 800);
    } catch(e) { showToast('error', 'שגיאה בשמירה'); }
};

// SA: Change business type for a group
async function saChangeBizType(groupId, groupName, currentType) {
    const cards = BUSINESS_TYPES.map(b => `
        <button type="button" onclick="saBtSelect('${b.id}',this)" data-btype="${b.id}"
            class="sa-bt-card flex items-center gap-3 px-4 py-3 rounded-2xl border-2 transition text-right w-full ${currentType===b.id?'border-indigo-500 bg-indigo-50':'border-slate-100 bg-white hover:border-indigo-200'}"
            style="touch-action:manipulation;cursor:pointer;">
            <span class="text-2xl shrink-0">${b.icon}</span>
            <span class="text-sm font-bold text-slate-700">${b.name}</span>
            ${currentType===b.id?'<i class="fa-solid fa-check text-indigo-500 mr-auto"></i>':''}
        </button>`).join('');

    const html = `<div id="sa-biz-type-modal" class="fixed inset-0 bg-black/60 z-[99999] flex items-center justify-center p-4">
        <div class="bg-white w-full max-w-md rounded-[2rem] shadow-2xl flex flex-col max-h-[85vh]">
            <div class="px-5 py-4 border-b border-slate-100 flex justify-between items-center shrink-0">
                <h2 class="font-black text-slate-800 text-base">🏢 מהות עסק — ${safeStr(groupName)}</h2>
                <button onclick="document.getElementById('sa-biz-type-modal').remove()" class="text-slate-400 text-xl"><i class="fa-solid fa-xmark"></i></button>
            </div>
            <div class="flex-1 overflow-y-auto modal-scroll p-4 space-y-2">${cards}</div>
            <div class="px-4 py-3 border-t border-slate-100 shrink-0">
                <button type="button" onclick="saBtConfirm(${groupId})" class="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold shadow">שמור שינוי מהות</button>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
    window._saBtGroupId = groupId;
    window._saBtSelected = currentType;
}

window.saBtSelect = function(typeId, btn) {
    window._saBtSelected = typeId;
    document.querySelectorAll('.sa-bt-card').forEach(b => {
        const isThis = b.dataset.btype === typeId;
        b.className = b.className.replace(/border-indigo-500 bg-indigo-50|border-slate-100 bg-white hover:border-indigo-200/g,'') + (isThis?' border-indigo-500 bg-indigo-50':' border-slate-100 bg-white hover:border-indigo-200');
        const icon = b.querySelector('.fa-check'); if(icon) icon.remove();
        if(isThis) b.insertAdjacentHTML('beforeend','<i class="fa-solid fa-check text-indigo-500 mr-auto"></i>');
    });
};

window.saBtConfirm = async function(groupId) {
    const typeId = window._saBtSelected;
    if (!typeId) return;
    try {
        await fetch(`/api/groups/${groupId}/business-settings`, {
            method:'PATCH', headers:{'Content-Type':'application/json', 'Authorization': saToken||''},
            body: JSON.stringify({ business_type: typeId })
        });
        document.getElementById('sa-biz-type-modal')?.remove();
        showToast('success', `מהות עודכנה ל-${BUSINESS_TYPES.find(b=>b.id===typeId)?.name||typeId}`);
    } catch(e) { showToast('error', 'שגיאה בשמירה'); }
};

