window._generateBeautyServices = async function() {
    if (!wizardV2Data.serviceCategories || wizardV2Data.serviceCategories.length === 0) return;
    let resultEl = document.getElementById('wiz-v2-svc-result');
    if (!resultEl) {
        updateWizardUIV2();
        resultEl = document.getElementById('wiz-v2-svc-result');
        if (!resultEl) return;
    }
    resultEl.innerHTML = `<div id="wiz-v2-svc-spinner" class="text-center py-6 text-slate-400"><i class="fa-solid fa-spinner fa-spin text-2xl"></i><p class="text-xs mt-2 font-bold">בונה רשימת טיפולים...</p></div>`;
    console.log('generating beauty services for:', wizardV2Data.serviceCategories);
    try {
        const res = await fetch(`${API}/ai/generate-catalog`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                promptText: `צור רשימת טיפולי יופי עבור: ${wizardV2Data.serviceCategories.join(', ')}. צור בדיוק 6 טיפולים. החזר JSON בלבד: {"items": [{"name": "string", "duration_minutes": number, "price": number, "category": "string"}]} משך ריאלי בדקות (30-120), מחירים ריאליים בשקלים. ללא טקסט נוסף.`,
                type: 'BUSINESS',
                groupId: currentGroup.id
            })
        });
        const responseText = await res.text();
        console.log('raw response:', responseText);
        let outer;
        try { outer = JSON.parse(responseText); } catch(e) {
            console.error('JSON parse error:', e, responseText);
            resultEl.innerHTML = '<p style="color:red">שגיאה בבניית הרשימה. נסה שנית.</p>';
            return;
        }
        const _beautyManualRows = () => _wizBatteryEmptyHTML(i => `
            <div class="flex items-center gap-2 bg-white border border-slate-200 p-2 rounded-xl mb-2">
                <input type="text" placeholder="שם טיפול" class="modern-input py-1.5 text-sm flex-1"
                    oninput="if(!wizardV2Data.services)wizardV2Data.services=[];if(!wizardV2Data.services[${i}])wizardV2Data.services[${i}]={name:'',duration_minutes:60,price:0,category:''};wizardV2Data.services[${i}].name=this.value">
                <input type="number" placeholder="דק'" min="0" step="15" class="modern-input py-1.5 text-xs w-16 text-center"
                    oninput="if(wizardV2Data.services&&wizardV2Data.services[${i}])wizardV2Data.services[${i}].duration_minutes=parseInt(this.value)||60">
                <input type="number" placeholder="₪" min="0" class="modern-input py-1.5 text-xs w-20 text-center"
                    oninput="if(wizardV2Data.services&&wizardV2Data.services[${i}])wizardV2Data.services[${i}].price=parseFloat(this.value)||0">
                <button type="button" onclick="_wiz2RemoveSvc(${i})" class="text-red-400 hover:text-red-600 px-1">✕</button>
            </div>`);
        if (!outer.success || outer.error) {
            resultEl.innerHTML = _beautyManualRows();
            return;
        }
        let items = (outer.success && outer.items) ? outer.items : null;
        if (!items && outer.result) {
            try { const p = JSON.parse(outer.result); items = p.items || p; } catch(e) {}
        }
        wizardV2Data.services = (items || []).map(it => ({
            name: it.name || '',
            duration_minutes: it.duration_minutes || 60,
            price: it.price || 0,
            category: it.category || wizardV2Data.serviceCategories[0] || ''
        }));
    } catch(e) {
        console.error('fetch error:', e);
        resultEl.innerHTML = '<p style="color:red">שגיאה בבניית הרשימה. נסה שנית.</p>';
        return;
    }
    updateWizardUIV2();
};

window._wiz2RemoveSvc = function(idx) {
    if (wizardV2Data.services) wizardV2Data.services.splice(idx, 1);
    const el = document.getElementById('wiz-v2-svc-result');
    if (el) {
        const DURATION_OPTS = [30,45,60,90,120];
        el.innerHTML = (wizardV2Data.services || []).map((s, i) => `
            <div class="flex items-center gap-2 bg-white border border-slate-200 p-2 rounded-xl">
                <span class="flex-1 text-sm font-bold text-slate-700 truncate">${safeStr(s.name)}</span>
                <select class="modern-input py-1.5 text-xs w-20 bg-white text-center"
                    onchange="wizardV2Data.services[${i}].duration_minutes=parseInt(this.value)">
                    ${DURATION_OPTS.map(d=>`<option value="${d}" ${s.duration_minutes==d?'selected':''}>${d}′</option>`).join('')}
                </select>
                <input type="number" value="${s.price||0}" min="0"
                    class="modern-input py-1.5 text-center text-sm font-bold text-indigo-600 dir-ltr w-20 bg-indigo-50"
                    onchange="wizardV2Data.services[${i}].price=parseFloat(this.value)||0">
                <button onclick="_wiz2RemoveSvc(${i})"
                    class="text-red-400 hover:text-red-600 w-7 h-7 flex items-center justify-center shrink-0">
                    <i class="fa-solid fa-xmark text-xs"></i>
                </button>
            </div>`).join('') || '<p class="text-xs text-slate-400 text-center py-2">אין טיפולים</p>';
    }
};

window._wiz2AddSvc = function() {
    if (!wizardV2Data.services) wizardV2Data.services = [];
    wizardV2Data.services.push({ name: '', duration_minutes: 60, price: 0, category: (wizardV2Data.serviceCategories || [])[0] || '' });
    const idx = wizardV2Data.services.length - 1;
    const el = document.getElementById('wiz-v2-svc-result');
    if (el) {
        const row = document.createElement('div');
        row.className = 'flex items-center gap-2 bg-white border border-slate-200 p-2 rounded-xl';
        row.innerHTML = `
            <input type="text" placeholder="שם טיפול" class="modern-input py-1.5 text-sm flex-1"
                oninput="wizardV2Data.services[${idx}].name=this.value">
            <select class="modern-input py-1.5 text-xs w-20 bg-white text-center"
                onchange="wizardV2Data.services[${idx}].duration_minutes=parseInt(this.value)">
                ${[30,45,60,90,120].map(d=>`<option value="${d}" ${d===60?'selected':''}>${d}′</option>`).join('')}
            </select>
            <input type="number" value="0" min="0"
                class="modern-input py-1.5 text-center text-sm font-bold text-indigo-600 dir-ltr w-20 bg-indigo-50"
                onchange="wizardV2Data.services[${idx}].price=parseFloat(this.value)||0">
            <button onclick="_wiz2RemoveSvc(${idx})"
                class="text-red-400 hover:text-red-600 w-7 h-7 flex items-center justify-center shrink-0">
                <i class="fa-solid fa-xmark text-xs"></i>
            </button>`;
        el.appendChild(row);
    }
};

const _PRACT_COLORS_V2 = ['#8b5cf6','#ec4899','#3b82f6','#22c55e','#f97316','#ef4444'];

window._wiz2PractColor = function(idx, color) {
    if (!wizardV2Data.practitioners) wizardV2Data.practitioners = [];
    if (!wizardV2Data.practitioners[idx]) wizardV2Data.practitioners[idx] = {};
    wizardV2Data.practitioners[idx].color = color;
    const wrap = document.getElementById(`wiz-v2-pract-color-${idx}`);
    if (!wrap) return;
    wrap.querySelectorAll('button').forEach(btn => {
        const isSelected = btn.style.background === color || btn.style.backgroundColor === color;
        btn.className = btn.className
            .replace(/border-slate-700 scale-110|border-transparent hover:border-slate-400/g, '')
            + (isSelected ? ' border-slate-700 scale-110' : ' border-transparent hover:border-slate-400');
    });
};

window._wiz2AddPract = function() {
    if (!wizardV2Data.practitioners) wizardV2Data.practitioners = [];
    if (wizardV2Data.practitioners.length >= 5) return;
    const idx = wizardV2Data.practitioners.length;
    wizardV2Data.practitioners.push({ name: '', specialty: 'הכל', color: _PRACT_COLORS_V2[idx % _PRACT_COLORS_V2.length] });
    updateWizardUIV2();
};

window._wiz2RemovePract = function(idx) {
    if (!wizardV2Data.practitioners) return;
    wizardV2Data.practitioners.splice(idx, 1);
    updateWizardUIV2();
};

window._toggleWizardV2Cuisine = function(value) {
    if (!wizardV2Data.cuisineTypes) wizardV2Data.cuisineTypes = [];
    const idx = wizardV2Data.cuisineTypes.indexOf(value);
    if (idx === -1) wizardV2Data.cuisineTypes.push(value);
    else wizardV2Data.cuisineTypes.splice(idx, 1);
    const isNowSelected = wizardV2Data.cuisineTypes.includes(value);
    const btn = document.getElementById(`wiz-v2-cuisine-${value}`);
    if (btn) {
        btn.className = btn.className
            .replace(/border-indigo-500 bg-indigo-50|border-slate-200 bg-white hover:border-indigo-200/g, '')
            + (isNowSelected ? ' border-indigo-500 bg-indigo-50' : ' border-slate-200 bg-white hover:border-indigo-200');
    }
    wizardV2Data.menuItems = [];
    wizardV2Data.useAI = null;
    updateWizardUIV2();
};

window._generateWizardMenu = async function() {
    if (!wizardV2Data.cuisineTypes || wizardV2Data.cuisineTypes.length === 0) return;
    let resultEl = document.getElementById('wiz-v2-menu-result');
    if (!resultEl) {
        updateWizardUIV2();
        resultEl = document.getElementById('wiz-v2-menu-result');
        if (!resultEl) return;
    }
    resultEl.innerHTML = `<div id="wiz-v2-menu-spinner" class="text-center py-6 text-slate-400"><i class="fa-solid fa-spinner fa-spin text-2xl"></i><p class="text-xs mt-2 font-bold">בונה תפריט...</p></div>`;
    console.log('generating menu for:', wizardV2Data.cuisineTypes);
    try {
        const res = await fetch(`${API}/ai/generate-catalog`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                promptText: `אתה יוצר תפריט לעסק המשלב: ${wizardV2Data.cuisineTypes.join(', ')}. צור בדיוק 8 פריטים מגוונים מכל הסוגים שנבחרו. החזר JSON בלבד במבנה: {"items": [{"name": "string", "price": number, "category": "string"}]} הקטגוריה תהיה אחת מ: מנות עיקריות / סלטים / תוספות / שתייה / קינוחים מחירים ריאליים בשקלים. ללא טקסט נוסף.`,
                type: 'BUSINESS',
                groupId: currentGroup.id
            })
        });
        const responseText = await res.text();
        console.log('raw response:', responseText);
        let outerData;
        try {
            outerData = JSON.parse(responseText);
        } catch(e) {
            console.error('JSON parse error:', e, responseText);
            resultEl.innerHTML = '<p style="color:red">שגיאה בבניית התפריט. נסה שנית.</p>';
            return;
        }
        const _menuManualRows = () => _wizBatteryEmptyHTML(i => `
            <div class="flex items-center gap-2 bg-white border border-slate-200 p-2 rounded-xl mb-2">
                <input type="text" placeholder="שם מנה" class="modern-input py-1.5 text-sm flex-1"
                    oninput="if(!wizardV2Data.menuItems)wizardV2Data.menuItems=[];if(!wizardV2Data.menuItems[${i}])wizardV2Data.menuItems[${i}]={name:'',price:0,category:'מנות עיקריות'};wizardV2Data.menuItems[${i}].name=this.value">
                <select class="modern-input py-1.5 text-xs w-28 bg-white"
                    onchange="if(wizardV2Data.menuItems&&wizardV2Data.menuItems[${i}])wizardV2Data.menuItems[${i}].category=this.value">
                    ${['מנות עיקריות','סלטים','תוספות','שתייה','קינוחים'].map(c=>`<option>${c}</option>`).join('')}
                </select>
                <input type="number" placeholder="₪" min="0" class="modern-input py-1.5 text-xs w-20 text-center"
                    oninput="if(wizardV2Data.menuItems&&wizardV2Data.menuItems[${i}])wizardV2Data.menuItems[${i}].price=parseFloat(this.value)||0">
                <button type="button" onclick="_removeWizardV2MenuItem(${i})" class="text-red-400 hover:text-red-600 px-1">✕</button>
            </div>`);
        if (!outerData.success || outerData.error) {
            resultEl.innerHTML = _menuManualRows();
            return;
        }
        const items = (outerData.success && outerData.items) ? outerData.items : null;
        if (items) {
            wizardV2Data.menuItems = items;
        } else if (outerData.result) {
            try {
                const parsed = JSON.parse(outerData.result);
                wizardV2Data.menuItems = parsed.items || parsed;
            } catch(e) {
                console.error('JSON parse error (result field):', e, outerData.result);
                resultEl.innerHTML = '<p style="color:red">שגיאה בבניית התפריט. נסה שנית.</p>';
                return;
            }
        } else {
            wizardV2Data.menuItems = [];
        }
    } catch(e) {
        console.error('fetch error:', e);
        resultEl.innerHTML = '<p style="color:red">שגיאה בבניית התפריט. נסה שנית.</p>';
        return;
    }
    updateWizardUIV2();
};

const _MENU_CAT_OPTIONS = ['מנות עיקריות','סלטים','תוספות','שתייה','קינוחים','אחר'];

function _menuCatSelect(item, idx) {
    return `<select class="modern-input py-1.5 text-xs w-28 bg-white"
        onchange="wizardV2Data.menuItems[${idx}].category = this.value">
        ${_MENU_CAT_OPTIONS.map(c => `<option value="${c}" ${item.category===c?'selected':''}>${c}</option>`).join('')}
    </select>`;
}

function _menuItemRow(item, idx) {
    return `<div class="flex items-center gap-2 bg-white border border-slate-200 p-2 rounded-xl">
        <span class="flex-1 text-sm font-bold text-slate-700 truncate">${safeStr(item.name)}</span>
        ${_menuCatSelect(item, idx)}
        <input type="number" value="${item.price}" min="0"
            class="modern-input py-1.5 text-center text-sm font-bold text-indigo-600 dir-ltr w-20 bg-indigo-50"
            onchange="wizardV2Data.menuItems[${idx}].price = parseFloat(this.value)||0">
        <button onclick="_removeWizardV2MenuItem(${idx})"
            class="text-red-400 hover:text-red-600 w-7 h-7 flex items-center justify-center shrink-0">
            <i class="fa-solid fa-xmark text-xs"></i>
        </button>
    </div>`;
}

window._removeWizardV2MenuItem = function(idx) {
    if (wizardV2Data.menuItems) wizardV2Data.menuItems.splice(idx, 1);
    const resultEl = document.getElementById('wiz-v2-menu-result');
    if (resultEl) {
        resultEl.innerHTML = (wizardV2Data.menuItems || []).map((item, i) => _menuItemRow(item, i)).join('')
            || '<p class="text-xs text-slate-400 text-center py-2">אין פריטים</p>';
    }
};

window._addWizardV2MenuItem = function() {
    if (!wizardV2Data.menuItems) wizardV2Data.menuItems = [];
    wizardV2Data.menuItems.push({ name: '', price: 0, category: 'מנות עיקריות' });
    const idx = wizardV2Data.menuItems.length - 1;
    const resultEl = document.getElementById('wiz-v2-menu-result');
    if (resultEl) {
        const row = document.createElement('div');
        row.className = 'flex items-center gap-2 bg-white border border-slate-200 p-2 rounded-xl';
        row.innerHTML = `
            <input type="text" placeholder="שם מנה" class="modern-input py-1.5 text-sm flex-1"
                oninput="wizardV2Data.menuItems[${idx}].name = this.value">
            ${_menuCatSelect({ category: 'מנות עיקריות' }, idx)}
            <input type="number" value="0" min="0"
                class="modern-input py-1.5 text-center text-sm font-bold text-indigo-600 dir-ltr w-20 bg-indigo-50"
                onchange="wizardV2Data.menuItems[${idx}].price = parseFloat(this.value)||0">
            <button onclick="_removeWizardV2MenuItem(${idx})"
                class="text-red-400 hover:text-red-600 w-7 h-7 flex items-center justify-center shrink-0">
                <i class="fa-solid fa-xmark text-xs"></i>
            </button>`;
        resultEl.appendChild(row);
    }
};

window._toggleWizardV2FoodType = function(value) {
    if (!wizardV2Data.serviceTypes) wizardV2Data.serviceTypes = [];
    const idx = wizardV2Data.serviceTypes.indexOf(value);
    if (idx === -1) wizardV2Data.serviceTypes.push(value);
    else wizardV2Data.serviceTypes.splice(idx, 1);

    const isNowSelected = wizardV2Data.serviceTypes.includes(value);
    const btn = document.getElementById(`wiz-v2-ft-${value}`);
    if (btn) {
        btn.className = btn.className
            .replace(/border-indigo-500 bg-indigo-50|border-slate-200 bg-white hover:border-indigo-200/g, '')
            + (isNowSelected ? ' border-indigo-500 bg-indigo-50' : ' border-slate-200 bg-white hover:border-indigo-200');
    }
    const wrap = document.getElementById('wiz-v2-table-count-wrap');
    if (wrap) wrap.classList.toggle('hidden', !wizardV2Data.serviceTypes.includes('tables'));
};

async function _nextWizardV2Step() {
    const stepName = wizardStepsV2[currentWizardStepV2] || '';

    if (stepName === 'menu') {
        if (!wizardV2Data.cuisineTypes || wizardV2Data.cuisineTypes.length === 0) { alert('נא לבחור לפחות סוג מטבח אחד'); return; }
        if (wizardV2Data.useAI === null || wizardV2Data.useAI === undefined) { alert('נא לבחור: בניה אוטומטית עם AI או ידנית'); return; }
        const items = (wizardV2Data.menuItems || []).filter(i => i.name && i.name.trim());
        if (items.length === 0) { alert('נא להוסיף לפחות מנה אחת'); return; }
        try {
            for (const item of items) {
                const r = await fetch(`${API}/store/catalog`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        groupId: currentGroup.id,
                        name: item.name,
                        price: item.price || 0,
                        category: item.category || 'כללי',
                        isAvailable: true,
                        productType: 'retail'
                    })
                });
                if (!r.ok) {
                    const err = await r.json().catch(() => ({}));
                    if (err.error) showToast('info', err.error);
                    break;
                }
            }
        } catch(e) {}
    }

    if (stepName === 'trainer') {
        const raw = wizardV2Data.trainers || [];
        const filled = raw.filter(t => t && t.name && t.name.trim());
        if (filled.length === 0) {
            const firstName = (document.getElementById('wiz-v2-trainer-name-0')?.value || '').trim();
            if (!firstName) { alert('נא להזין שם מאמן אחד לפחות'); return; }
            filled.push({
                name: firstName,
                specialty: document.getElementById('wiz-v2-trainer-specialty-0')?.value || 'כושר כללי'
            });
        }
        wizardV2Data.trainers = filled;
    }

    if (stepName === 'subscriptions') {
        const rows = document.querySelectorAll('#wiz-v2-sub-list > div');
        const collected = [];
        rows.forEach((row, i) => {
            const nameEl = row.querySelector('span, input[type="text"]');
            const priceEl = document.getElementById(`wiz-v2-sub-price-${i}`);
            const unitEl = row.querySelectorAll('input[type="text"]')[1];
            const name = nameEl ? (nameEl.value !== undefined ? nameEl.value : nameEl.textContent).trim() : '';
            if (name) collected.push({
                name,
                price: parseFloat(priceEl?.value) || 0,
                unit: unitEl?.value || ''
            });
        });
        if (collected.length === 0) { alert('נא להגדיר לפחות סוג מנוי אחד'); return; }
        wizardV2Data.subscriptions = collected;
        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
        try {
            for (const s of collected) {
                await fetch(`${API}/store/catalog`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ groupId: currentGroup.id, name: s.name, price: s.price, category: 'מנויים', isAvailable: true, productType: 'retail' })
                });
            }
        } catch(e) {}
    }

    if (stepName === 'schedule') {
        const name = (document.getElementById('wiz-v2-class-name')?.value || '').trim() || 'אימון';
        const days = wizardV2Data.scheduleClass?.days || [];
        const time = document.getElementById('wiz-v2-class-time')?.value || '07:00';
        const duration = parseInt(document.getElementById('wiz-v2-class-duration')?.value) || 60;
        const capacity = parseInt(document.getElementById('wiz-v2-class-capacity')?.value) || 15;
        wizardV2Data.scheduleClass = { name, days, time, duration, capacity };
        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
        try {
            await fetch(`${API}/calendar/classes`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ groupId: currentGroup.id, name, days, time, duration, capacity, trainer: document.getElementById('wiz-v2-class-trainer')?.value || '' })
            });
        } catch(e) {}
    }

    if (stepName === 'service_types') {
        if (!wizardV2Data.serviceTypes || wizardV2Data.serviceTypes.length === 0) { alert('נא לבחור לפחות תחום אחד'); return; }
        if (wizardV2Data.useAI === null || wizardV2Data.useAI === undefined) { alert('נא לבחור: בניה אוטומטית עם AI או ידנית'); return; }
        const svcs = wizardV2Data.repairServices || [];
        const valid = svcs.filter(s => s.name && s.name.trim());
        if (valid.length === 0) { alert('נא להוסיף לפחות שירות אחד'); return; }
        wizardV2Data.repairServices = valid;
        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
        try {
            for (const s of valid) {
                const r = await fetch(`${API}/calendar/services`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        groupId: currentGroup.id, name: s.name.trim(),
                        durationMins: (s.duration_hours || 1) * 60,
                        price: s.price_from || 0
                    })
                });
                if (!r.ok) {
                    const err = await r.json().catch(() => ({}));
                    if (err.error) { showToast('error', err.error); break; }
                }
            }
        } catch(e) {}
    }

    if (stepName === 'billing_flow') {
        if (!wizardV2Data.billingFlows || wizardV2Data.billingFlows.length === 0) { alert('נא לבחור לפחות סוג עבודה אחד'); return; }
    }

    if (stepName === 'first_customer') {
        const name = (document.getElementById('wiz-v2-customer-name')?.value || '').trim();
        if (!name) { alert('נא להזין שם לקוח'); return; }
        const phone = (document.getElementById('wiz-v2-customer-phone')?.value || '').trim();
        const address = (document.getElementById('wiz-v2-customer-address')?.value || '').trim();
        const flows = wizardV2Data.billingFlows || [];
        const createCall  = flows.includes('immediate') ? (document.getElementById('wiz-v2-fc-create-call')?.checked !== false) : false;
        const createQuote = flows.includes('quote')     ? (document.getElementById('wiz-v2-fc-create-quote')?.checked !== false) : false;
        const depositAmount = parseFloat(document.getElementById('wiz-v2-fc-deposit-amount')?.value) || 0;
        const depositPct    = parseFloat(document.getElementById('wiz-v2-fc-deposit-pct')?.value) || 0;
        const hasCatalog = wizardV2Data.firstCustomer?.hasCatalog ?? null;
        wizardV2Data.firstCustomer = { name, phone, address, createCall, createQuote, depositAmount, depositPct, hasCatalog };
        if (depositAmount || depositPct) wizardV2Data.defaultDeposit = { amount: depositAmount, pct: depositPct };

        // הוסף שלב catalog דינמית אם נבחר 'sales' + hasCatalog
        if (flows.includes('sales') && hasCatalog === true) {
            const nextIdx = currentWizardStepV2 + 1;
            if (!wizardStepsV2.includes('catalog')) {
                wizardStepsV2.splice(nextIdx, 0, 'catalog');
            }
        }

        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
        try {
            await fetch(`${API}/store/customers`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ groupId: currentGroup.id, name, phone, address, businessId: currentGroup.id })
            });
            if (createCall) await fetch(`${API}/service-calls`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ groupId: currentGroup.id, customerName: name, title: 'קריאת שירות ראשונה', status: 'new' })
            });
            if (createQuote) await fetch(`${API}/store/quotes`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ groupId: currentGroup.id, customerName: name, title: 'הצעת מחיר לדוגמה', status: 'draft' })
            });
        } catch(e) {}
    }

    if (stepName === 'services') {
        if (!wizardV2Data.serviceCategories || wizardV2Data.serviceCategories.length === 0) { alert('נא לבחור לפחות קטגוריה אחת'); return; }
        if (wizardV2Data.useAI === null || wizardV2Data.useAI === undefined) { alert('נא לבחור: בניה אוטומטית עם AI או ידנית'); return; }
        const svcs = wizardV2Data.services || [];
        if (svcs.length === 0) { alert('נא להוסיף לפחות טיפול אחד'); return; }
        // אסוף ערכים עדכניים מה-DOM
        document.querySelectorAll('#wiz-v2-svc-result > div').forEach((row, i) => {
            const nameEl = row.querySelector('span');
            const priceEl = row.querySelector('input[type="number"]');
            const durEl = row.querySelector('select');
            if (svcs[i]) {
                if (nameEl) svcs[i].name = nameEl.textContent.trim();
                if (priceEl) svcs[i].price = parseFloat(priceEl.value) || 0;
                if (durEl) svcs[i].duration_minutes = parseInt(durEl.value) || 60;
            }
        });
        const valid = svcs.filter(s => s.name && s.name.trim());
        if (valid.length === 0) { alert('נא להוסיף לפחות טיפול אחד'); return; }
        wizardV2Data.services = valid;
        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
        try {
            for (const s of valid) {
                await fetch(`${API}/beauty/services`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ groupId: currentGroup.id, name: s.name.trim(), duration_minutes: s.duration_minutes || 60, price: s.price || 0, category: s.category || '' })
                });
            }
        } catch(e) {}
    }

    if (stepName === 'practitioners') {
        const practsRaw = wizardV2Data.practitioners || [];
        const filled = practsRaw.filter(p => p && p.name && p.name.trim());
        if (filled.length === 0) {
            const firstName = (document.getElementById('wiz-v2-pract-name-0')?.value || '').trim();
            if (!firstName) { alert('נא להזין שם מטפלת אחת לפחות'); return; }
            filled.push({
                name: firstName,
                specialty: document.getElementById('wiz-v2-pract-specialty-0')?.value || 'הכל',
                color: practsRaw[0]?.color || '#8b5cf6'
            });
        }
        wizardV2Data.practitioners = filled;
        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
        try {
            for (const p of filled) {
                await fetch(`${API}/beauty/practitioners`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ groupId: currentGroup.id, name: p.name.trim(), specialty: p.specialty || 'הכל', color: p.color || '#8b5cf6' })
                });
            }
        } catch(e) {}
    }

    if (stepName === 'catalog') {
        if (wizardV2Data.useAI === null || wizardV2Data.useAI === undefined) { alert('נא לבחור: בניה אוטומטית עם AI או ידנית'); return; }
        const prods = (wizardV2Data.catalogProducts || []).filter(p => p.name && p.name.trim());
        if (wizardV2Data.useAI === false && prods.length === 0) { alert('נא להוסיף לפחות מוצר אחד'); return; }
        if (prods.length > 0) {
            const btnNext = document.getElementById('wizard-v2-btn-next');
            if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
            try {
                for (const p of prods) {
                    const r = await fetch(`${API}/store/catalog`, {
                        method: 'POST', headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            groupId: currentGroup.id,
                            name: p.name, price: p.price, category: p.category || '',
                            description: '', productType: 'retail', isAvailable: true
                        })
                    });
                    if (!r.ok) {
                        const err = await r.json().catch(() => ({}));
                        if (err.error) { showToast('error', err.error); break; }
                    }
                }
            } catch(e) {}
        }
    }

    if (stepName === 'case_type') {
        if (!wizardV2Data.profession) { alert('נא לבחור תחום מומחיות'); return; }
    }

    if (stepName === 'first_case') {
        const clientName = (document.getElementById('wiz-v2-case-client')?.value || '').trim() || 'לקוח לדוגמה';
        const title      = (document.getElementById('wiz-v2-case-title')?.value || '').trim() || 'תיק ראשון';
        const meetDate   = document.getElementById('wiz-v2-case-meeting')?.value || '';
        wizardV2Data.firstCase = { clientName, title, meetDate };
        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
        try {
            const caseRes = await fetch(`${API}/cases`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ groupId: currentGroup.id, clientName, title, status: 'active' })
            });
            const caseData = await caseRes.json().catch(() => ({}));
            if (meetDate) {
                await fetch(`${API}/calendar/events`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ groupId: currentGroup.id, title: `פגישה — ${clientName}`, date: meetDate, type: 'meeting' })
                });
            }
            if (!caseData.success) console.warn('case create:', caseData);
        } catch(e) {}
    }

    if (stepName === 'document_template') {
        const docType = wizardV2Data.docTemplateType || '';
        const content = (document.getElementById('wiz-v2-doc-textarea')?.value || wizardV2Data.docTemplateContent || '').trim();
        if (docType && content) {
            const btnNext = document.getElementById('wizard-v2-btn-next');
            if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...';
            try {
                await fetch(`${API}/documents/templates`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ groupId: currentGroup.id, title: docType, content, profession: wizardV2Data.profession || '' })
                });
            } catch(e) {}
        }
    }

    if (stepName === 'food_type') {
        if (!wizardV2Data.serviceTypes || wizardV2Data.serviceTypes.length === 0) { alert('נא לבחור סוג פעילות'); return; }
        if (wizardV2Data.serviceTypes.includes('tables')) {
            wizardV2Data.tableCount = parseInt(document.getElementById('wiz-v2-table-count')?.value) || 8;
        }
    }

    if (stepName === 'identity') {
        const phone = (document.getElementById('wiz-v2-phone')?.value || '').trim();
        if (!phone) { alert('נא להזין מספר טלפון'); return; }
        wizardV2Data.phone = phone;
        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
        try {
            await fetch(`${API}/store/settings`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    groupId: currentGroup.id,
                    isActive: true,
                    phone: wizardV2Data.phone,
                    logoUrl: document.getElementById('wizard-logo-base64')?.value || ''
                })
            });
        } catch(e) {}
    }

    if (stepName === 'my_role') {
        const roleType = wizardV2Data.myRoleType;
        if (roleType && currentUser?.id) {
            try {
                await fetch(`${API}/users/${currentUser.id}/role-type`, {
                    method: 'PATCH', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ employee_role_type: roleType })
                });
            } catch(e) {}
        }
    }

    if (stepName === 'team') {
        const btnNext = document.getElementById('wizard-v2-btn-next');
        if (btnNext) btnNext.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> מסיים...';
        const _closeAndFinish = () => {
            if (currentGroup) currentGroup.is_onboarded = true;
            const modal = document.getElementById('onboarding-wizard-v2');
            if (modal) modal.classList.add('hidden');
            triggerConfetti();
            setTimeout(() => location.reload(), 1200);
        };
        try {
            const ctrl = new AbortController();
            const tid = setTimeout(() => ctrl.abort(), 8000);
            await fetch(`${API}/groups/onboard`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                signal: ctrl.signal,
                body: JSON.stringify({ groupId: currentGroup.id })
            });
            clearTimeout(tid);
        } catch(e) {}
        _closeAndFinish();
        return;
    }

    if (currentWizardStepV2 < wizardStepsV2.length - 1) {
        currentWizardStepV2++;
        updateWizardUIV2();
    }
}

window.updateWizardUIV2 = function updateWizardUIV2() {
    const stepName = wizardStepsV2[currentWizardStepV2] || '';
    const total = wizardStepsV2.length;
    const progressPct = total > 0 ? ((currentWizardStepV2 + 1) / total) * 100 : 0;

    const progressEl = document.getElementById('wizard-v2-progress');
    if (progressEl) progressEl.style.width = `${progressPct}%`;

    const contentEl = document.getElementById('wizard-v2-content');
    if (contentEl) contentEl.innerHTML = _renderWizardV2StepContent(stepName);

    const btnPrev = document.getElementById('wizard-v2-btn-prev');
    if (btnPrev) {
        btnPrev.classList.remove('hidden');
        if (currentWizardStepV2 === 0) {
            btnPrev.onclick = () => {
                document.getElementById('onboarding-wizard-v2')?.classList.add('hidden');
                showBusinessTypeWizardV2();
            };
        } else {
            btnPrev.onclick = () => { currentWizardStepV2--; updateWizardUIV2(); };
        }
    }

    const btnSkip = document.getElementById('wizard-v2-btn-skip');
    if (btnSkip) {
        const skippable = ['first_case', 'document_template'];
        btnSkip.classList.toggle('hidden', !skippable.includes(stepName));
        btnSkip.onclick = () => { currentWizardStepV2++; updateWizardUIV2(); };
    }

    const btnNext = document.getElementById('wizard-v2-btn-next');
    if (btnNext) {
        btnNext.innerText = currentWizardStepV2 === total - 1 ? 'סיום 🚀' : 'המשך';
        btnNext.onclick = _nextWizardV2Step;
    }
}

function _initWizardV2State() {
    const bizType = currentGroup?.business_type || 'other';
    wizardStepsV2 = WIZARD_STEPS_BY_TYPE_V2[bizType] || WIZARD_STEPS_BY_TYPE_V2['other'];
    currentWizardStepV2 = 0;
    wizardV2Data = {};
}

window.showOnboardingWizardV2 = function showOnboardingWizardV2(skipInit) {
    if (document.getElementById('onboarding-wizard-v2-modal')) {
        if (!skipInit) _initWizardV2State();
        document.getElementById('onboarding-wizard-v2-modal').classList.remove('hidden');
        updateWizardUIV2();
        return;
    }

    if (!skipInit) _initWizardV2State();

    const modalHtml = `
    <div id="onboarding-wizard-v2-modal" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[99999] flex items-center justify-center p-2 sm:p-4">
        <div class="bg-white w-full max-w-2xl rounded-[2rem] shadow-2xl overflow-hidden flex flex-col h-[90vh] sm:h-auto sm:max-h-[90vh]">

            <div class="w-full bg-slate-100 h-1.5 shrink-0">
                <div id="wizard-v2-progress" class="bg-indigo-600 h-1.5 transition-all duration-500" style="width: 0%;"></div>
            </div>

            <div class="bg-indigo-50 p-4 sm:p-6 text-center border-b border-indigo-100 shrink-0">
                <h2 class="text-xl sm:text-2xl font-black text-indigo-900 mb-1">ברוכים הבאים ל-Oneflow BIZ! 🎉</h2>
                <p class="text-indigo-600 text-xs sm:text-sm font-bold">בואו נקים את העסק שלכם ב-${wizardStepsV2.length} צעדים מהירים</p>
            </div>

            <div class="flex-1 overflow-y-auto modal-scroll p-4 sm:p-6 bg-slate-50/50">
                <div id="wizard-v2-content" class="fade-in max-w-md mx-auto"></div>
            </div>

            <div class="p-4 bg-white border-t border-slate-100 flex justify-between items-center shrink-0">
                <button id="wizard-v2-btn-skip" class="text-xs text-slate-400 font-bold hover:text-slate-600 transition underline px-2">דלג על שלב זה</button>
                <div class="flex gap-2">
                    <button id="wizard-v2-btn-prev" class="px-4 sm:px-5 py-2.5 text-slate-500 font-bold hover:bg-slate-100 rounded-xl transition hidden">חזור</button>
                    <button id="wizard-v2-btn-next" class="px-6 sm:px-8 py-2.5 bg-slate-800 text-white font-bold rounded-xl shadow-md hover:bg-slate-700 transition">המשך</button>
                </div>
            </div>
        </div>
    </div>`;

    document.body.insertAdjacentHTML('beforeend', modalHtml);
    updateWizardUIV2();
}

// --- מנגנון מחשבון תמחיר מנה (Food Cost) ---
let fcIngredients = [];

function openFoodCostModal() {
    fcIngredients = [];
    renderFCIngredients();
    populateFCPantrySelect();
    calculateFC();
    getEl('food-cost-modal').classList.remove('hidden');
}

function populateFCPantrySelect() {
    const select = getEl('fc-ingredient-select');
    if (!select) return;
    
    let html = '<option value="">בחר מוצר מהמלאי...</option>';
    if (typeof pantryCache !== 'undefined' && pantryCache.length > 0) {
        pantryCache.forEach(item => {
            const cost = parseFloat(item.price) || 0; // בהנחה שהשדה הוא price
            html += `<option value="${item.id}" data-name="${safeStr(item.item_name)}" data-cost="${cost}">${safeStr(item.item_name)} (₪${cost}/${item.unit || "יח'"})</option>`;
        });
    }
    html += '<option value="custom">-- הזנה ידנית של חומר גלם --</option>';
    select.innerHTML = html;
}

async function addFCIngredient() {
    const select = getEl('fc-ingredient-select');
    const qtyInput = getEl('fc-ingredient-qty');
    const qty = parseFloat(qtyInput.value);

    if (select.value === '') return showToast('error', 'יש לבחור מוצר מהמלאי');
    if (!qty || qty <= 0) return showToast('error', 'יש להזין כמות תקינה (למשל: 1, 0.5)');

    const option = select.options[select.selectedIndex];
    let name = option.getAttribute('data-name');
    let costPerUnit = parseFloat(option.getAttribute('data-cost')) || 0;

    if (select.value === 'custom') {
        name = await window._uiPrompt('שם חומר הגלם:');
        if (!name) return;
        const costInput = await window._uiPrompt(`מהי העלות ליחידה אחת של ${name}? (₪)`, {type:'number'});
        costPerUnit = parseFloat(costInput) || 0;
    }

    fcIngredients.push({ name: name, qty: qty, costPerUnit: costPerUnit });
    qtyInput.value = '';
    select.value = '';
    renderFCIngredients();
    calculateFC();
}

function removeFCIngredient(index) {
    fcIngredients.splice(index, 1);
    renderFCIngredients();
    calculateFC();
}

function renderFCIngredients() {
    const list = getEl('fc-ingredients-list');
    if (!list) return;
    if (fcIngredients.length === 0) {
        list.innerHTML = '<p class="text-[10px] text-emerald-600/70 text-center py-2 font-medium">טרם הוספו מרכיבים.</p>';
        return;
    }
    let html = '';
    fcIngredients.forEach((ing, idx) => {
        const total = ing.qty * ing.costPerUnit;
        html += `
        <div class="flex justify-between items-center bg-white p-2 rounded border border-emerald-100 text-xs shadow-sm">
            <span>${safeStr(ing.name)} <span class="text-slate-400 mx-1">x${ing.qty}</span></span>
            <div class="flex items-center gap-2">
                <span class="font-bold text-slate-700">₪${total.toFixed(2)}</span>
                <button onclick="removeFCIngredient(${idx})" class="text-red-400 hover:text-red-600 w-5 h-5 flex items-center justify-center bg-slate-50 rounded"><i class="fa-solid fa-times"></i></button>
            </div>
        </div>`;
    });
    list.innerHTML = html;
}

function calculateFC() {
    let totalMatCost = 0;
    fcIngredients.forEach(ing => totalMatCost += (ing.qty * ing.costPerUnit));
    
    const overhead = parseFloat(val('fc-overhead')) || 0;
    const targetPct = parseFloat(val('fc-target-pct')) || 30;
    
    const totalCost = totalMatCost + overhead;
    let recPrice = 0;
    
    if (targetPct > 0) {
        recPrice = totalCost / (targetPct / 100);
    }
    
    getEl('fc-total-cost').innerText = `₪${totalCost.toFixed(2)}`;
    getEl('fc-recommended-price').innerText = `₪${recPrice.toFixed(0)}`; // מעגלים לשקל שלם
    getEl('fc-recommended-price').dataset.raw = recPrice.toFixed(2);
}

function applyFCPrice() {
    const recPriceEl = getEl('fc-recommended-price');
    const priceStr = recPriceEl.dataset.raw || recPriceEl.innerText.replace('₪', '');
    const price = parseFloat(priceStr);
    
    if (price > 0) {
        const priceInput = getEl('sp-price');
        if (priceInput) {
            priceInput.value = Math.ceil(price); // מעגל כלפי מעלה בחנות
            showToast('success', 'המחיר עודכן בטופס!');
        }
    }
    getEl('food-cost-modal').classList.add('hidden');
}

async function analyzeFoodCostAI() {
    executeWithAIWarning(async () => {
        showAIModal('אנליסט התמחור AI', null); getEl('familai-loading-text').innerText = 'מנתח אפשרויות להוזלת המנה...';
        try {
            const ingredientsData = fcIngredients.map(i => `${i.name}: ${i.qty} יח' (₪${i.costPerUnit}/יח')`).join(', ');
            const promptText = `נתח את עלות המנה הבאה והצע חלופות לחומרי גלם כדי להוריד את ה-Food Cost:\n${ingredientsData}\nהוצאות עקיפות: ₪${val('fc-overhead')}\nיעד רצוי: ${val('fc-target-pct')}%`;
            
            const res = await fetch(`${API}/biz/chat-assistant`, { 
                method: 'POST', 
                headers: {'Content-Type': 'application/json'}, 
                body: JSON.stringify({ query: promptText, context: JSON.stringify({ role: "יועץ קולינרי וכלכלי למסעדות" }), groupId: currentGroup.id }) 
            });
            const data = await res.json();
            if(!handleAIResponseCheck(data)) { getEl('familai-advisor-modal').classList.add('hidden'); return; }
            if(data.success && data.answer) { showAIModal('אנליסט התמחור AI', data.answer); }
            else { getEl('familai-advisor-modal').classList.add('hidden'); showToast('error', 'שגיאה בניתוח'); }
        } catch(e) { getEl('familai-advisor-modal').classList.add('hidden'); showToast('error', 'שגיאה בתקשורת'); }
    });
}
// --- מסופון שליחים משופר (Dropdown UI) ---
let _courierPollingInterval = null;
function startCourierPolling() {
    if (_courierPollingInterval) clearInterval(_courierPollingInterval);
    _courierPollingInterval = setInterval(() => { try { loadCourierData(); } catch(e) {} }, 8000);
}
function stopCourierPolling() {
    if (_courierPollingInterval) { clearInterval(_courierPollingInterval); _courierPollingInterval = null; }
}

window.switchDeliveryTab = function(tab) {
    window._currentBizSubTab = 'deliveries.' + tab;
    const views = ['active', 'transit', 'history'];
    views.forEach(v => {
        const viewEl = getEl(`del-view-${v}`);
        const btnEl = getEl(`btn-del-${v}`);
        if(viewEl) viewEl.classList.add('hidden');
        if(btnEl) btnEl.className = 'flex-1 py-2 px-3 text-sm font-bold text-slate-500 hover:text-slate-700 rounded-lg transition';
    });

    const targetView = getEl(`del-view-${tab}`);
    const targetBtn = getEl(`btn-del-${tab}`);
    if(targetView) targetView.classList.remove('hidden');
    if(targetBtn) targetBtn.className = 'flex-1 py-2 px-3 text-sm font-bold bg-white text-slate-800 rounded-lg shadow-sm transition border border-slate-200';

    loadCourierData();
    startCourierPolling();
};

window.loadCourierData = async function() {
    const hasAccess = (currentUser.permissions?.tabs?.includes('deliveries') || currentUser.role === 'ADMIN');
    if (!hasAccess) return;
    
    try {
        const res = await fetch(`${API}/store/orders/${currentGroup.id}`);
        const data = await res.json();
        const searchId = val('courier-search-id');
        
        let ordersArray = [];
        if (Array.isArray(data)) ordersArray = data;
        else if (data.orders) ordersArray = data.orders;
        else if (data.data) ordersArray = data.data;
        
        if (ordersArray.length > 0) {
            const checkIsDelivery = (o) => (o.is_delivery == 1 || o.is_delivery === true || o.is_delivery === 'true' || getDeliveryMeta(o) !== null || hasDeliveryItems(o));

            let filtered = ordersArray.filter(checkIsDelivery);
            if (searchId) {
                const s = searchId.toLowerCase();
                filtered = filtered.filter(o =>
                    String(o.id).includes(s) ||
                    (o.customer_phone && String(o.customer_phone).includes(s)) ||
                    (o.customer_name && String(o.customer_name).toLowerCase().includes(s))
                );
            }

            // Tab 1 "ממתין": shipped orders (waiter marked ready for courier pickup)
            const active = filtered.filter(o => o.status === 'shipped');
            // Tab 2 "במשלוח": delivering orders (courier picked up, en route)
            const transit = filtered.filter(o => o.status === 'delivering');
            // Tab 3 "היסטוריה": completed + cancelled
            const history = filtered.filter(o => o.status === 'completed' || o.status === 'cancelled');
            history.sort((a,b) => new Date(b.created_at) - new Date(a.created_at));

            renderCourierList('active', active, 'shipped');
            renderCourierList('transit', transit, 'delivering');
            renderCourierList('history', history, 'history');
        } else {
            renderCourierList('active', [], 'shipped');
            renderCourierList('transit', [], 'delivering');
            renderCourierList('history', [], 'history');
        }
    } catch(e) { console.error('Courier Load Error', e); }
};

window.renderCourierList = function(type, orders, statusType) {
    const container = getEl(`courier-${type}-list`);
    if (!container) return;
    if (orders.length === 0) {
        container.innerHTML = `<div class="py-12 text-center bg-slate-50 rounded-3xl border border-dashed border-slate-200"><i class="fa-solid fa-box-open text-3xl text-slate-200 mb-2"></i><p class="text-[11px] text-slate-400 font-bold">אין הזמנות</p></div>`;
        return;
    }

    container.innerHTML = orders.map(o => {
        let deliveryData = {};
        const meta = getDeliveryMeta(o);
        if (meta && meta.delivery_details) deliveryData = meta.delivery_details;
        else { try { deliveryData = typeof o.delivery_details === 'string' ? JSON.parse(o.delivery_details) : (o.delivery_details || {}); } catch(e){} }

        const addr = `${safeStr(deliveryData.street || '')} ${safeStr(deliveryData.house || '')}, ${safeStr(deliveryData.city || '')}`;
        const waze = `https://waze.com/ul?q=${encodeURIComponent(addr)}&navigate=yes`;
        const cleanPhone = (o.customer_phone || '').replace(/\D/g, '');
        const waPhone = cleanPhone.startsWith('0') ? '972' + cleanPhone.substring(1) : cleanPhone;
        const waMsg = encodeURIComponent(`היי ${safeStr(o.customer_name)}, השליח בדרך אליך! 🛵`);
        const waLink = `https://wa.me/${waPhone}?text=${waMsg}`;

        const statusBadge = o.status === 'cancelled'
            ? '<span class="text-[10px] font-black text-red-600 bg-red-50 border border-red-200 px-2 py-0.5 rounded-full">❌ בוטלה</span>'
            : '<span class="text-[10px] font-black text-emerald-600 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-full">✅ נמסר</span>';
        let actionBtn = '';
        if (statusType === 'shipped') {
            actionBtn = `<button onclick="updateStoreOrderStatusCourier(${o.id}, 'delivering')" class="w-full mt-4 py-3 bg-blue-600 text-white font-black rounded-2xl shadow-lg hover:bg-blue-700 transition flex items-center justify-center gap-2"><i class="fa-solid fa-box-open"></i> נאסף — יצאתי לדרך 🛵</button>`;
        } else if (statusType === 'delivering') {
            actionBtn = `<button onclick="updateStoreOrderStatusCourier(${o.id}, 'completed')" class="w-full mt-4 py-3 bg-emerald-600 text-white font-black rounded-2xl shadow-lg hover:bg-emerald-700 transition flex items-center justify-center gap-2"><i class="fa-solid fa-check-double"></i> אישור מסירה ללקוח ✅</button>`;
        }

        return `
        <div class="bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm mb-4 relative overflow-hidden fade-in">
            ${(statusType === 'shipped' || statusType === 'delivering') ? '<div class="absolute top-0 right-0 left-0 h-1 bg-blue-500 animate-pulse"></div>' : ''}
            <div class="flex justify-between items-center cursor-pointer select-none" onclick="toggleCardCollapse('cour-${o.id}')">
                <div class="flex-1 pr-1">
                    <div class="flex items-center gap-2 mb-1">
                        <span class="bg-slate-900 text-white text-[10px] px-2 py-0.5 rounded-full font-bold">#${o.id}</span>
                        <span class="text-[10px] text-slate-400 font-mono">${new Date(o.created_at).toLocaleTimeString('he-IL', {hour:'2-digit',minute:'2-digit'})}</span>
                        ${statusType === 'history' ? statusBadge : ''}
                    </div>
                    <h4 class="font-black text-slate-800 text-sm mb-0.5 truncate pr-1">${safeStr(deliveryData.street || 'כתובת')} ${safeStr(deliveryData.house || '')}</h4>
                </div>
                <div class="flex items-center gap-3">
                    <span class="font-black text-slate-900 text-base dir-ltr">₪${o.total_amount}</span>
                    <i id="card-icon-cour-${o.id}" class="fa-solid fa-chevron-down text-slate-300 transition-transform"></i>
                </div>
            </div>
            
            <div id="order-details-cour-${o.id}" class="hidden">
                <div class="mt-3 bg-indigo-50 p-2.5 rounded-xl text-xs font-bold text-indigo-800 border border-indigo-100 flex items-start gap-2">
                    <i class="fa-solid fa-location-dot mt-0.5"></i> 
                    <div>
                        <div class="leading-tight">${addr}</div>
                        ${deliveryData.notes ? `<div class="text-[10px] text-amber-700 font-medium mt-1.5 pt-1.5 border-t border-indigo-200/50">${safeStr(deliveryData.notes)}</div>` : ''}
                    </div>
                </div>

                <p class="text-xs font-bold text-slate-600 mt-3 text-center">${safeStr(o.customer_name)} | <span dir="ltr">${safeStr(o.customer_phone)}</span></p>

                <div class="grid grid-cols-3 gap-2 mt-3">
                    <a href="${waze}" target="_blank" class="flex flex-col items-center justify-center gap-1 py-2.5 bg-blue-50 text-blue-700 rounded-xl font-bold text-[10px] border border-blue-100 hover:bg-blue-100 transition"><i class="fa-brands fa-waze text-lg"></i> Waze</a>
                    <a href="tel:${o.customer_phone}" class="flex flex-col items-center justify-center gap-1 py-2.5 bg-slate-50 text-slate-700 rounded-xl font-bold text-[10px] border border-slate-100 hover:bg-slate-100 transition"><i class="fa-solid fa-phone text-lg"></i> חייג</a>
                    <a href="${waLink}" target="_blank" class="flex flex-col items-center justify-center gap-1 py-2.5 bg-[#25D366]/10 text-[#25D366] rounded-xl font-bold text-[10px] border border-[#25D366]/20 hover:bg-[#25D366]/20 transition"><i class="fa-brands fa-whatsapp text-lg"></i> הודעה</a>
                </div>

                ${(() => {
                    let items = [];
                    try { items = (Array.isArray(o.items) ? o.items : JSON.parse(o.items||'[]')).filter(i => !i.is_quote_metadata); } catch(e) {}
                    if (items.length === 0) return '';
                    const itemsHtml = items.map(i => {
                        const qty = parseInt(i.quantity||i.qty||1);
                        const name = i.name || '?';
                        return `<div class="flex items-center justify-between text-[11px] py-1 px-2 bg-slate-50 rounded"><span>${safeStr(name)}</span><span class="font-bold text-slate-600">×${qty}</span></div>`;
                    }).join('');
                    return `<div class="mt-3 bg-amber-50 rounded-xl border border-amber-200 p-2 text-xs font-bold text-amber-800">
                        <div class="mb-1.5">📦 תכולת ההזמנה:</div>
                        ${itemsHtml}
                    </div>`;
                })()}

                ${buildOrderLogHtml(o.status, o.created_at, !!(o.is_delivery == 1 || o.is_delivery === true || o.is_delivery === 'true' || getDeliveryMeta(o) !== null || hasDeliveryItems(o)))}
                ${actionBtn}
            </div>
        </div>`;
    }).join('');
};

window.updateStoreOrderStatusCourier = async function(orderId, status) {
    try {
        const res = await fetch(`${API}/store/orders/status`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ orderId, status }) });
        const data = await res.json();
        if(data.success) {
            try { if(status === 'completed') triggerConfetti(); } catch(e){}
            showToast('success', status === 'completed' ? '🎉 המשלוח נמסר!' : status === 'delivering' ? '🛵 יצאת לדרך!' : 'עודכן');
            if (typeof window.loadCourierData === 'function') window.loadCourierData();
            if(typeof window.fetchStoreOrders === 'function') window.fetchStoreOrders();
        } else { showToast('error', data.error || 'שגיאה בעדכון'); }
    } catch(e) {
        console.error('Update status error:', e);
        showToast('error', 'שגיאת רשת בעדכון הסטטוס');
    }
};
window.approveDeliveryToKitchen = async function(orderId) {
    try {
        const payload = { orderId, status: 'processing' };
        console.log('[approveDeliveryToKitchen] Sending:', payload);
        const res = await fetch(`${API}/store/orders/status`, {
            method: 'POST',
            headers: {'Content-Type':'application/json'},
            body: JSON.stringify(payload)
        });
        const data = await res.json();
        console.log('[approveDeliveryToKitchen] Response:', data);
        if (data.success) {
            showToast('success', '✅ ההזמנה אושרה ונשלחה למטבח');
            if (typeof refreshWaiterReadySection === 'function') try { refreshWaiterReadySection(); } catch(e) {}
            if (typeof window.refreshAdminTablesData === 'function') try { window.refreshAdminTablesData(); } catch(e) {}
            if (typeof window.renderRestaurantPendingOrders === 'function') try { window.renderRestaurantPendingOrders(); } catch(e) {}
            if (typeof window.fetchStoreOrders === 'function') window.fetchStoreOrders();
            // רענן KDS מיידית אם הפאנל פתוח
            if (document.getElementById('admin-kds-panel') && typeof window.kdsRefreshPanel === 'function') {
                try { window.kdsRefreshPanel(); } catch(e) {}
            }
        } else {
            showToast('error', data.error || 'שגיאה');
        }
    } catch(e) { showToast('error', 'שגיאת רשת'); console.error('[approveDeliveryToKitchen] Error:', e); }
};
window.rejectStoreOrder = async function(orderId) {
    if (!await window._uiConfirm('לדחות את ההזמנה?')) return;
    try {
        const res = await fetch(`${API}/store/orders/status`, {
            method: 'POST',
            headers: {'Content-Type':'application/json'},
            body: JSON.stringify({ orderId, status: 'cancelled' })
        });
        const data = await res.json();
        if (data.success) {
            showToast('info', '❌ ההזמנה נדחתה');
            if (typeof refreshWaiterReadySection === 'function') try { refreshWaiterReadySection(); } catch(e) {}
            if (typeof window.refreshAdminTablesData === 'function') try { window.refreshAdminTablesData(); } catch(e) {}
            if (typeof window.renderRestaurantPendingOrders === 'function') try { window.renderRestaurantPendingOrders(); } catch(e) {}
            if (typeof window.fetchStoreOrders === 'function') window.fetchStoreOrders();
        } else {
            showToast('error', data.error || 'שגיאה');
        }
    } catch(e) { showToast('error', 'שגיאת רשת'); }
};
window.updateCustomTabsByRoles = function() {
    // אוסף את התפקידים שנבחרו
    const checkboxes = document.querySelectorAll('.role-cb:checked');
    const selectedRoles = Array.from(checkboxes).map(cb => cb.value);
    
    // בונה רשימת טאבים מאוחדת
    let combinedTabs = new Set();
    
    selectedRoles.forEach(role => {
        if (role === 'COURIER') {
            combinedTabs.add('deliveries');
        } else if (ROLE_DEFAULTS[role]) {
            ROLE_DEFAULTS[role].forEach(t => combinedTabs.add(t));
        }
    });
    
    // מעדכן את הצ'קבוקסים של הטאבים למטה לפי האיחוד
    document.querySelectorAll('.perm-tab-cb').forEach(cb => {
        if (cb.value !== 'feed') { // feed תמיד נשאר
            cb.checked = combinedTabs.has(cb.value);
        }
    });
};
// ============================================================
// --- FOOD COST MODULE ---
// ============================================================
async function fetchFoodCost() {
    const list = getEl('fc-list');
    if(!list) return;
    list.innerHTML = '<p class="text-xs text-slate-400 text-center py-10"><i class="fa-solid fa-spinner fa-spin mr-1"></i> שואב נתוני עלות מחירונים...</p>';
    
    try {
        const res = await fetch(`${API}/food-cost/${currentGroup.id}`);
        const data = await res.json();
        
        if(data.success) {
            foodCostData = data.catalog;
            foodCostPrices = data.priceMap;
            renderFoodCostList();
        } else {
            list.innerHTML = '<p class="text-xs text-red-500 text-center py-10">שגיאה בטעינת נתונים</p>';
        }
    } catch(e) {
        list.innerHTML = '<p class="text-xs text-red-500 text-center py-10">שגיאת תקשורת</p>';
    }
}

function renderFoodCostList() {
    const list = getEl('fc-list');
    const query = val('fc-search').toLowerCase().trim();
    
    let filtered = foodCostData;
    if (query) {
        filtered = filtered.filter(item => item.name.toLowerCase().includes(query) || item.category.toLowerCase().includes(query));
    }
    
    if (filtered.length === 0) {
        list.innerHTML = '<p class="text-xs text-slate-400 text-center py-10 bg-white rounded-xl border border-dashed">לא נמצאו מנות תואמות.</p>';
        return;
    }
    
    let html = '';
    filtered.forEach(item => {
        const fc = item.costs.foodCostPct;
        let fcColor = 'text-green-600 bg-green-50 border-green-200';
        let statusIcon = '<i class="fa-solid fa-check-circle"></i>';
        
        if (fc === 0 && item.costs.total === 0) {
            fcColor = 'text-slate-500 bg-slate-100 border-slate-200';
            statusIcon = '<i class="fa-solid fa-triangle-exclamation"></i>';
        } else if (fc > 40) {
            fcColor = 'text-red-600 bg-red-50 border-red-200';
            statusIcon = '<i class="fa-solid fa-arrow-trend-down"></i> הפסדי';
        } else if (fc > 35) {
            fcColor = 'text-orange-600 bg-orange-50 border-orange-200';
            statusIcon = '<i class="fa-solid fa-scale-balanced"></i> גבולי';
        } else {
            statusIcon = '<i class="fa-solid fa-arrow-trend-up"></i> רווחי';
        }

        html += `
        <div class="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 mb-3 flex flex-col hover:border-emerald-200 transition">
            <div class="flex justify-between items-start mb-2 border-b border-slate-50 pb-2">
                <div>
                    <h4 class="font-bold text-slate-800 text-sm">${safeStr(item.name)}</h4>
                    <p class="text-[10px] text-slate-400">${safeStr(item.category)} | מכירה: ₪${parseFloat(item.price).toFixed(2)}</p>
                </div>
                <div class="text-left flex flex-col items-end">
                    <span class="text-xs font-black ${fcColor.split(' ')[0]} bg-slate-50 px-2 py-1 rounded-lg border shadow-sm" dir="ltr">${fc > 0 ? fc.toFixed(1) + '%' : 'לא חושב'}</span>
                </div>
            </div>
            
            <div class="flex justify-between items-end mt-1">
                <div class="flex gap-4 text-[10px] font-bold">
                    <div class="flex flex-col"><span class="text-slate-400">עלות יצור</span><span class="text-slate-700 text-xs">₪${item.costs.total.toFixed(2)}</span></div>
                    <div class="flex flex-col"><span class="text-slate-400">רווח גולמי</span><span class="text-green-600 text-xs">₪${item.costs.profit.toFixed(2)}</span></div>
                </div>
                <button onclick="openRecipeBuilder(${item.id})" class="text-[10px] font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 px-3 py-1.5 rounded-lg transition border border-indigo-100"><i class="fa-solid fa-pen mr-1"></i> עץ מוצר</button>
            </div>
        </div>`;
    });
    
    list.innerHTML = html;
}

