window.toggleSopScheduleUI = function() {
    const type = document.getElementById('ts-builder-schedule-type').value;
    const spec = document.getElementById('ts-schedule-specific');
    const rout = document.getElementById('ts-schedule-routine');
    if(spec) spec.classList.add('hidden');
    if(rout) rout.classList.add('hidden');
    if (type === 'specific' && spec) spec.classList.remove('hidden');
    if (type === 'routine' && rout) rout.classList.remove('hidden');
};

window.openTaskSetBuilderModal = function() {
    window.injectSOPAdvancedFields();
    window.editingTaskSetId = null;
    window.currentTaskSetSubTasks = [];
    
    document.getElementById('ts-builder-title').innerHTML = '<i class="fa-solid fa-list-check text-indigo-500 mr-2"></i> בונה הנהלים (סט חדש)';
    document.getElementById('ts-builder-name').value = '';
    
    const reqPhoto = document.getElementById('ts-builder-requires-photo');
    if(reqPhoto) reqPhoto.checked = false;
    
    const schedType = document.getElementById('ts-builder-schedule-type');
    if(schedType) { schedType.value = 'manual'; window.toggleSopScheduleUI(); }
    
    document.querySelectorAll('.ts-routine-day').forEach(cb => cb.checked = false);
    const tsTime = document.getElementById('ts-builder-time');
    if(tsTime) tsTime.value = '08:00';
    const tsDate = document.getElementById('ts-builder-date');
    if(tsDate) tsDate.value = '';

    window.renderTaskSetSubTasks();
    const modal = document.getElementById('task-set-builder-modal');
    if(modal) modal.classList.remove('hidden');
};

window.editTaskSet = function(id) {
    window.injectSOPAdvancedFields();
    const ts = window.taskSetTemplates.find(t => t.id === id);
    if (!ts) return;
    
    window.editingTaskSetId = id;
    document.getElementById('ts-builder-title').innerHTML = '<i class="fa-solid fa-pen text-indigo-500 mr-2"></i> עריכת נוהל קיים';
    document.getElementById('ts-builder-name').value = ts.title;
    window.currentTaskSetSubTasks = [...ts.tasks];
    
    const reqPhoto = document.getElementById('ts-builder-requires-photo');
    if(reqPhoto) reqPhoto.checked = ts.requiresPhoto === true;
    
    const schedType = document.getElementById('ts-builder-schedule-type');
    if(schedType) { 
        schedType.value = ts.scheduleType || 'manual'; 
        window.toggleSopScheduleUI(); 
    }
    
    if (ts.routineDays && Array.isArray(ts.routineDays)) {
        document.querySelectorAll('.ts-routine-day').forEach(cb => {
            cb.checked = ts.routineDays.includes(parseInt(cb.value));
        });
    }
    
    const tsTime = document.getElementById('ts-builder-time');
    if(tsTime && ts.routineTime) tsTime.value = ts.routineTime;
    
    const tsDate = document.getElementById('ts-builder-date');
    if(tsDate && ts.specificDate) tsDate.value = ts.specificDate;

    window.renderTaskSetSubTasks();
    const modal = document.getElementById('task-set-builder-modal');
    if(modal) modal.classList.remove('hidden');
};

window.addTaskSetSubTask = function() { window.currentTaskSetSubTasks.push(''); window.renderTaskSetSubTasks(); };
window.removeTaskSetSubTask = function(idx) { window.currentTaskSetSubTasks.splice(idx, 1); window.renderTaskSetSubTasks(); };
window.updateTaskSetSubTask = function(idx, val) { window.currentTaskSetSubTasks[idx] = val; };

window.renderTaskSetSubTasks = function() {
    const list = document.getElementById('ts-builder-tasks');
    if (!list) return;
    if (window.currentTaskSetSubTasks.length === 0) {
        list.innerHTML = '<p class="text-[11px] text-slate-400 text-center py-6 bg-white rounded-xl border border-dashed border-indigo-200 font-medium">הסט ריק. הוסיפו את שורות הנוהל שיוצגו כרשימת תיוג (Checklist) לעובד.</p>';
        return;
    }
    list.innerHTML = window.currentTaskSetSubTasks.map((t, idx) => `
        <div class="flex gap-2 items-center bg-white p-2 rounded-xl border border-slate-200 shadow-sm fade-in hover:border-indigo-300 transition">
            <span class="text-xs font-black text-indigo-300 w-5 text-center shrink-0">${idx+1}.</span>
            <input type="text" class="flex-1 bg-slate-50 border border-slate-100 rounded-lg text-sm px-3 py-2.5 outline-none focus:border-indigo-400 focus:bg-white text-slate-700 font-bold transition shadow-inner" value="${safeStr(t)}" onchange="window.updateTaskSetSubTask(${idx}, this.value)" placeholder="תיאור המשימה (למשל: ספירת קופה)">
            <button type="button" onclick="window.removeTaskSetSubTask(${idx})" class="text-slate-300 hover:text-red-500 w-8 h-8 flex items-center justify-center transition bg-slate-50 rounded-lg shrink-0 border border-slate-100"><i class="fa-solid fa-times"></i></button>
        </div>
    `).join('');
};

window.saveTaskSet = function() {
    const title = document.getElementById('ts-builder-name').value.trim();
    const validTasks = window.currentTaskSetSubTasks.filter(t => t.trim() !== '');
    
    if (!title) return showToast('error', 'יש להזין שם לסט המשימות');
    if (validTasks.length === 0) return showToast('error', 'יש להוסיף לפחות משימה אחת תקינה לסט');
    
    const reqPhotoEl = document.getElementById('ts-builder-requires-photo');
    const schedTypeEl = document.getElementById('ts-builder-schedule-type');
    
    const requiresPhoto = reqPhotoEl ? reqPhotoEl.checked : false;
    const scheduleType = schedTypeEl ? schedTypeEl.value : 'manual';
    
    let routineDays = [];
    if (scheduleType === 'routine') {
        document.querySelectorAll('.ts-routine-day:checked').forEach(cb => routineDays.push(parseInt(cb.value)));
        if (routineDays.length === 0) return showToast('error', 'ברוטינה, חובה לבחור לפחות יום אחד בשבוע.');
    }
    
    const routineTime = document.getElementById('ts-builder-time') ? document.getElementById('ts-builder-time').value : '08:00';
    const specificDate = document.getElementById('ts-builder-date') ? document.getElementById('ts-builder-date').value : '';
    
    if (scheduleType === 'specific' && !specificDate) return showToast('error', 'יש לבחור תאריך ספציפי לסט');

    const setData = {
        id: window.editingTaskSetId ? window.editingTaskSetId : ('ts_' + Date.now()),
        title: title,
        tasks: validTasks,
        requiresPhoto: requiresPhoto,
        scheduleType: scheduleType,
        routineDays: routineDays,
        routineTime: routineTime,
        specificDate: specificDate
    };
    
    if (window.editingTaskSetId) {
        const index = window.taskSetTemplates.findIndex(t => t.id === window.editingTaskSetId);
        if (index > -1) window.taskSetTemplates[index] = setData;
    } else {
        window.taskSetTemplates.push(setData);
    }
    
    window.saveTaskSetTemplates();
    
    showToast('success', window.editingTaskSetId ? 'הנוהל עודכן בהצלחה!' : 'הנוהל נשמר בהצלחה במאגר הארגון!');
    const modal = document.getElementById('task-set-builder-modal');
    if(modal) modal.classList.add('hidden');
    window.renderTaskSetsList();
};

window.openAssignTaskSetModal = function(id) {
    const ts = window.taskSetTemplates.find(t => t.id === id);
    if (!ts) return;
    
    document.getElementById('assign-ts-id').value = id;
    document.getElementById('assign-ts-title').innerText = ts.title;
    document.getElementById('assign-ts-reward').value = '';
    
    // חישוב ימים אוטומטי בהתבסס על ההגדרה (אם ספציפי נחשב את ההפרש להיום)
    let autoDays = '';
    if (ts.scheduleType === 'specific' && ts.specificDate) {
        const diff = Math.ceil((new Date(ts.specificDate) - new Date()) / (1000 * 60 * 60 * 24));
        autoDays = diff > 0 ? diff : 1;
    }
    document.getElementById('assign-ts-days').value = autoDays;
    
    const userSelect = document.getElementById('assign-ts-user');
    userSelect.innerHTML = '<option value="" disabled selected>בחרו עובד מהרשימה...</option>';
    if (membersCache) {
        membersCache.forEach(m => {
            if (m.role !== 'ADMIN') userSelect.innerHTML += `<option value="${m.id}">${safeStr(m.nickname)}</option>`;
        });
    }
    
    const modal = document.getElementById('assign-task-set-modal');
    if(modal) modal.classList.remove('hidden');
};

window.submitAssignTaskSet = async function() {
    const tsId = document.getElementById('assign-ts-id').value;
    const userId = document.getElementById('assign-ts-user').value;
    const reward = parseFloat(document.getElementById('assign-ts-reward').value) || 0;
    const days = parseInt(document.getElementById('assign-ts-days').value) || null;
    
    if (!userId) return showToast('error', 'יש לבחור עובד/ת להקצאה');
    
    const ts = window.taskSetTemplates.find(t => t.id === tsId);
    if (!ts) return;
    
    const btn = document.getElementById('btn-submit-assign-ts');
    if(btn) { btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> משגר...'; }
    
    // אורזים את כל הנתונים (כולל הגדרת צילום חובה) לתוך אובייקט JSON בתוך ה-Title של הטיקט
    const sopPayload = {
        title: ts.title,
        items: ts.tasks,
        requiresPhoto: ts.requiresPhoto === true
    };
    const combinedTitle = `SOP|${JSON.stringify(sopPayload)}`;
    
    try {
        const res = await fetch(`${API}/tasks`, { 
            method:'POST', 
            headers:{'Content-Type':'application/json'}, 
            body:JSON.stringify({ 
                title: combinedTitle, 
                reward: reward, 
                assignedTo: userId, 
                days: days, 
                status: 'pending', 
                groupId: currentGroup.id 
            }) 
        }); 
        
        const data = await res.json();
        if(data.success) {
            showToast('success', 'הנוהל שוגר בהצלחה והופיע למשתמש!');
            const modal = document.getElementById('assign-task-set-modal');
            if(modal) modal.classList.add('hidden');
            if (typeof fetchData === 'function') fetchData();
        } else {
            showToast('error', data.error || 'שגיאה בשיגור');
        }
    } catch(e) {
        showToast('error', 'שגיאת רשת מול השרת');
    } finally {
        if(btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-check"></i> הקצה עכשיו'; }
    }
};

window.openSOPExecutionModal = function(taskId, displayTitle, sopDataStr) {
    let sopData = { items: [], requiresPhoto: false };
    try { sopData = JSON.parse(decodeURIComponent(sopDataStr)); } catch(e) { }
    
    window.currentSOPTaskContext = { id: taskId, title: displayTitle, requiresPhoto: sopData.requiresPhoto };
    
    const list = document.getElementById('sop-execution-list');
    if(list && sopData.items) {
        list.innerHTML = sopData.items.map((item, idx) => `
            <label class="flex items-center gap-3 p-4 bg-white border border-slate-200 rounded-2xl cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/50 transition group shadow-sm mb-3 fade-in">
                <div class="relative flex items-center justify-center shrink-0">
                    <input type="checkbox" onchange="window.checkSOPProgress()" class="sop-checkbox w-6 h-6 appearance-none border-2 border-slate-300 rounded-lg checked:bg-indigo-600 checked:border-indigo-600 outline-none transition peer cursor-pointer">
                    <i class="fa-solid fa-check absolute text-white text-xs opacity-0 peer-checked:opacity-100 pointer-events-none transition"></i>
                </div>
                <span class="text-sm font-bold text-slate-700 group-hover:text-indigo-900 transition leading-tight">${safeStr(item)}</span>
            </label>
        `).join('');
    }
    
    const titleEl = document.getElementById('sop-execution-title');
    if(titleEl) titleEl.innerText = displayTitle;
    
    const btn = document.getElementById('btn-complete-sop');
    if(btn) {
        btn.disabled = true;
        btn.classList.add('opacity-50', 'cursor-not-allowed', 'bg-slate-400');
        btn.classList.remove('animate-pulse', 'bg-indigo-600', 'shadow-indigo-200');
        
        // החלפת טקסט הכפתור בהתאם לדרישת הצילום
        if (sopData.requiresPhoto) {
            btn.innerHTML = '<i class="fa-solid fa-camera"></i> סיום וצילום הוכחה';
        } else {
            btn.innerHTML = '<i class="fa-solid fa-check-double"></i> אישור סיום נוהל';
        }
    }
    
    const modal = document.getElementById('sop-execution-modal');
    if(modal) modal.classList.remove('hidden');
    window.checkSOPProgress();
};

window.sopProgressDebounce = null;

window.checkSOPProgress = function() {
    const checkboxes = document.querySelectorAll('.sop-checkbox');
    const total = checkboxes.length;
    const checked = document.querySelectorAll('.sop-checkbox:checked').length;
    const btn = document.getElementById('btn-complete-sop');
    const progressText = document.getElementById('sop-progress-text');
    const progressBar = document.getElementById('sop-progress-bar');
    
    const pct = total === 0 ? 0 : (checked / total) * 100;
    if(progressBar) progressBar.style.width = `${pct}%`;
    if(progressText) progressText.innerText = `${checked} מתוך ${total} הושלמו`;
    
    checkboxes.forEach(cb => {
        const label = cb.closest('label');
        if (label) {
            if (cb.checked) {
                label.classList.add('bg-indigo-50/50', 'border-indigo-300');
                label.classList.remove('bg-white', 'border-slate-200');
                label.querySelector('span').classList.add('line-through', 'text-indigo-400');
            } else {
                label.classList.remove('bg-indigo-50/50', 'border-indigo-300');
                label.classList.add('bg-white', 'border-slate-200');
                label.querySelector('span').classList.remove('line-through', 'text-indigo-400');
            }
        }
    });
    
    if (checked === total && total > 0) {
        if(btn) {
            btn.disabled = false;
            btn.classList.remove('opacity-50', 'cursor-not-allowed', 'bg-slate-400');
            btn.classList.add('animate-pulse', 'bg-indigo-600', 'shadow-indigo-200');
        }
    } else {
        if(btn) {
            btn.disabled = true;
            btn.classList.add('opacity-50', 'cursor-not-allowed', 'bg-slate-400');
            btn.classList.remove('animate-pulse', 'bg-indigo-600', 'shadow-indigo-200');
        }
    }

    // שיגור שקט לשרת כדי שהמנהל יראה חיווי התקדמות אונליין
    if (window.currentSOPTaskContext && window.currentSOPTaskContext.id) {
        clearTimeout(window.sopProgressDebounce);
        window.sopProgressDebounce = setTimeout(() => {
            fetch(`${API}/tasks/update`, {
                method: 'POST', headers: {'Content-Type': 'application/json'},
                // מנצלים את שדה notes כדי לשתול חיווי התקדמות (למנהל יש גישה אליו)
                body: JSON.stringify({ taskId: window.currentSOPTaskContext.id, status: 'pending', notes: `PROGRESS:${checked}/${total}` })
            }).catch(e=>{});
        }, 1000);
    }
};

window.completeSOP = async function() {
    if (!window.currentSOPTaskContext) return;
    const ctx = window.currentSOPTaskContext;
    const modal = document.getElementById('sop-execution-modal');
    if(modal) modal.classList.add('hidden');
    
    if (ctx.requiresPhoto) {
        // שלח את העובד למנגנון צילום ההוכחה הקיים
        if(typeof window.clickTaskProof === 'function') {
            window.clickTaskProof(ctx.id, ctx.title);
        }
    } else {
        // סגור עצמאית ללא צילום מול השרת
        try {
            await fetch(`${API}/tasks/update`, { 
                method: 'POST', headers: {'Content-Type': 'application/json'}, 
                body: JSON.stringify({ taskId: ctx.id, status: 'done', notes: 'הושלם (לא נדרש צילום הוכחה)' }) 
            });
            showToast('success', 'הנוהל הושלם ונשלח לאישור מנהל!');
            if (typeof triggerConfetti === 'function') triggerConfetti();
            if (typeof fetchData === 'function') fetchData();
        } catch(e) { showToast('error', 'שגיאה בעדכון הסטטוס מול השרת'); }
    }
};

setInterval(() => {
    const btnManageSets = document.getElementById('btn-manage-task-sets');
    if (btnManageSets && typeof currentUser !== 'undefined' && currentUser && currentUser.role === 'ADMIN') {
        btnManageSets.classList.remove('hidden');
    }
}, 1500);

// ============================================================
// --- מודול תיבת הודעות נכנסות (INBOX) ---
// ============================================================

window.inboxMessagesCache = [];

window.fetchInboxMessages = async function() {
    if (!currentGroup || !currentGroup.id) return;
    try {
        const res = await fetch(`${API}/inbox/${currentGroup.id}`);
        const data = await res.json();
        if (data.success) {
            window.inboxMessagesCache = data.messages || [];
            window.updateInboxBadge();
            // אם ה-modal פתוח — רנדר מחדש את הרשימה
            if (!document.getElementById('inbox-modal')?.classList.contains('hidden')) {
                window.renderInboxList();
            }
        }
    } catch(e) { console.error('Error fetching inbox', e); }
};

window.updateInboxBadge = function() {
    const badge = document.getElementById('inbox-unread-badge');
    if (!badge) return;
    
    const unreadCount = window.inboxMessagesCache.filter(m => !m.is_read).length;
    if (unreadCount > 0) {
        badge.innerText = unreadCount;
        badge.classList.remove('hidden');
    } else {
        badge.classList.add('hidden');
    }
};

window.openInboxModal = function() {
    const modal = document.getElementById('inbox-modal');
    if (!modal) return;
    
    window.renderInboxList();
    modal.classList.remove('hidden');
};

window.renderInboxList = function() {
    const list = document.getElementById('inbox-messages-list');
    if (!list) return;
    
    if (window.inboxMessagesCache.length === 0) {
        list.innerHTML = '<p class="text-xs text-slate-400 text-center py-8 bg-slate-50 rounded-xl border border-dashed border-slate-200">אין לך הודעות חדשות כרגע.</p>';
        return;
    }
    
    list.innerHTML = window.inboxMessagesCache.map(m => {
        const isSys = m.sender_type === 'superadmin';
        const isCustomer = m.sender_type === 'customer';
        const dateStr = new Date(m.created_at).toLocaleString('he-IL', { dateStyle: 'short', timeStyle: 'short' });
        
        let iconHtml = '<i class="fa-solid fa-envelope text-slate-400"></i>';
        let bgClass = m.is_read ? 'bg-slate-50 opacity-70 border-slate-100' : 'bg-white border-indigo-200 shadow-sm';
        let typeBadge = '';
        
        const isZM = m.sender_type === 'zone_manager';
        if (isSys) {
            iconHtml = '<i class="fa-solid fa-tower-cell text-indigo-500"></i>';
            typeBadge = '<span class="text-[9px] bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded font-bold ml-2 shadow-sm border border-indigo-200">הודעת מערכת</span>';
        } else if (isCustomer) {
            iconHtml = '<i class="fa-solid fa-user text-emerald-500"></i>';
            typeBadge = '<span class="text-[9px] bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded font-bold ml-2 shadow-sm border border-emerald-200">לקוח (חנות)</span>';
        } else if (isZM) {
            iconHtml = '<i class="fa-solid fa-map-location-dot text-violet-500"></i>';
            typeBadge = '<span class="text-[9px] bg-violet-100 text-violet-700 px-1.5 py-0.5 rounded font-bold ml-2 shadow-sm border border-violet-200">מנהל האזור</span>';
        }

        // זיהוי החתימה הדיגיטלית של הניוזלטר
        const isRichHtml = m.content && (m.content.includes('') || (m.content.includes('<div') && m.content.includes('style=')));
        
        // יצירת תוכן התצוגה - אם זה ניוזלטר אין safeStr ואין whitespace-pre-wrap
        const displayContent = isRichHtml 
            ? `<div class="mt-4">${m.content}</div>`
            : `<div class="text-xs text-slate-600 leading-relaxed whitespace-pre-wrap mt-2 ${!m.is_read ? 'font-medium' : ''}">${safeStr(m.content)}</div>`;

        return `
        <div class="p-4 rounded-xl border ${bgClass} transition flex flex-col mb-3 overflow-hidden">
            <div class="flex justify-between items-center mb-2 border-b border-slate-100 pb-2">
                <div class="flex items-center gap-2">
                    <div class="w-8 h-8 rounded-full bg-white flex items-center justify-center shadow-sm border border-slate-100 shrink-0">
                        ${iconHtml}
                    </div>
                    <div>
                        <h4 class="font-bold text-slate-800 text-sm leading-tight flex items-center gap-1">${safeStr(m.subject)} ${!m.is_read ? '<span class="w-2 h-2 bg-red-500 rounded-full inline-block shadow-sm"></span>' : ''}</h4>
                        <p class="text-[10px] text-slate-500 flex items-center gap-1 mt-0.5">מאת: <strong>${safeStr(m.sender_name)}</strong> ${typeBadge}</p>
                    </div>
                </div>
                <div class="flex flex-col items-end gap-2 shrink-0">
                    <span class="text-[9px] text-slate-400 font-mono">${dateStr}</span>
                    <button onclick="window.deleteInboxMessage(${m.id})" class="text-slate-300 hover:text-red-500 transition" title="מחק הודעה"><i class="fa-solid fa-trash-can text-xs"></i></button>
                </div>
            </div>
            
            ${displayContent}
            
            ${m.sender_contact && isCustomer ? `<div class="mt-3 pt-3 border-t border-slate-100"><a href="tel:${safeStr(m.sender_contact)}" class="text-[10px] font-bold text-emerald-700 bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100 shadow-sm hover:bg-emerald-100 transition inline-flex items-center gap-1.5"><i class="fa-solid fa-phone"></i> צור קשר: <span dir="ltr">${safeStr(m.sender_contact)}</span></a></div>` : ''}
            
            ${isCustomer && m.customer_group_id ? `<div class="mt-3 pt-3 border-t border-slate-100" id="inbox-reply-area-${m.id}">
                <div id="inbox-thread-${m.id}" class="space-y-1 mb-2 hidden"></div>
                <button onclick="window.toggleInboxThread(${m.id},${m.customer_group_id})" class="text-[10px] font-bold text-indigo-600 hover:text-indigo-800 transition mb-2 block">
                    <i class="fa-solid fa-comments ml-1"></i>היסטוריית שיחה
                </button>
                <div class="flex gap-2">
                    <textarea id="inbox-reply-txt-${m.id}" rows="2" placeholder="כתוב תגובה ללקוח..." class="flex-1 border border-slate-200 rounded-xl px-3 py-2 text-xs resize-none focus:outline-none focus:border-indigo-400"></textarea>
                    <button onclick="window.sendInboxReply(${m.id},${m.customer_group_id})" class="bg-indigo-600 text-white rounded-xl px-3 py-2 text-xs font-bold hover:bg-indigo-700 transition shrink-0"><i class="fa-solid fa-paper-plane"></i></button>
                </div>
            </div>` : ''}
            
            ${!m.is_read ? `<div class="mt-4 pt-3 border-t border-slate-100 text-left"><button onclick="window.markInboxAsRead(${m.id})" class="text-xs font-bold text-slate-500 bg-white border border-slate-200 px-4 py-2 rounded-xl shadow-sm hover:bg-slate-50 transition"><i class="fa-solid fa-check"></i> סמן כנקרא והסתר</button></div>` : ''}
        </div>
        `;
    }).join('');
};

window.markInboxAsRead = async function(id) {
    try {
        await fetch(`${API}/inbox/${id}/read`, { method: 'PUT', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({ isRead: true }) });
        const msg = window.inboxMessagesCache.find(m => m.id === id);
        if (msg) msg.is_read = true;
        window.renderInboxList();
        window.updateInboxBadge();
    } catch(e) {}
};

window.toggleInboxThread = async function(msgId, customerGroupId) {
    const el = document.getElementById(`inbox-thread-${msgId}`);
    if (!el) return;
    if (!el.classList.contains('hidden')) { el.classList.add('hidden'); return; }
    el.innerHTML = '<p class="text-[10px] text-slate-400">טוען...</p>';
    el.classList.remove('hidden');
    try {
        const r = await fetch(`${API}/inbox/${currentGroup.id}/thread/${customerGroupId}`).then(r=>r.json());
        const msgs = r.messages || [];
        if (!msgs.length) { el.innerHTML = '<p class="text-[10px] text-slate-400">אין הודעות קודמות</p>'; return; }
        el.innerHTML = msgs.map(m => {
            const isMine = m.direction === 'outbound';
            const dt = new Date(m.created_at).toLocaleString('he-IL', { day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit' });
            return `<div class="flex ${isMine ? 'justify-end' : 'justify-start'} mb-1">
                <div class="max-w-[85%] px-2.5 py-1.5 rounded-xl text-[11px] ${isMine ? 'bg-indigo-600 text-white rounded-bl-none' : 'bg-slate-100 text-slate-700 rounded-br-none'}">
                    <p>${safeStr(m.content)}</p>
                    <p class="text-[9px] mt-0.5 opacity-60">${dt}</p>
                </div>
            </div>`;
        }).join('');
    } catch(e) { el.innerHTML = '<p class="text-[10px] text-red-400">שגיאה בטעינה</p>'; }
};

window.sendInboxReply = async function(msgId, customerGroupId) {
    const ta = document.getElementById(`inbox-reply-txt-${msgId}`);
    const txt = ta?.value?.trim();
    if (!txt) return;
    const btn = ta?.nextElementSibling;
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>'; }
    try {
        const r = await fetch(`${API}/inbox/${currentGroup.id}/reply/${customerGroupId}`, {
            method:'POST', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({ content: txt })
        }).then(r=>r.json());
        if (r.success) {
            if (ta) ta.value = '';
            showToast('success','תגובה נשלחה ✅');
            // Refresh thread
            window.toggleInboxThread(msgId, customerGroupId);
            setTimeout(() => window.toggleInboxThread(msgId, customerGroupId), 100);
        } else { showToast('error', r.error||'שגיאה'); }
    } catch(e) { showToast('error','שגיאת תקשורת'); }
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-paper-plane"></i>'; }
};

window.deleteInboxMessage = async function(id) {
    if(!await window._uiConfirm('האם למחוק את ההודעה?', {danger:true, okLabel:'מחק'})) return;
    try {
        await fetch(`${API}/inbox/${id}`, { method: 'DELETE' });
        window.inboxMessagesCache = window.inboxMessagesCache.filter(m => m.id !== id);
        window.renderInboxList();
        window.updateInboxBadge();
        showToast('info', 'ההודעה נמחקה');
    } catch(e) {}
};

// שילוב קריאת המשיכה אל תוך מחזור החיים הקיים של האפליקציה!
// מוסיפים האזנה ל-setInterval שכבר רץ במערכת ומעדכן את המידע התקופתי:
const origFetchDataInboxHook = window.fetchData;
if (origFetchDataInboxHook) {
    window.fetchData = async function() {
        await origFetchDataInboxHook(); // קורא קודם לפונקציה המקורית
        window.fetchInboxMessages(); // ואז מושך גם את תיבת ההודעות ברקע!
        // משיכה שקטה של הצ'אט ברקע - אם יש הודעות חדשות, זה יקפיץ את הבועה האדומה
        if (typeof window.fetchTeamChat === 'function') {
            window.fetchTeamChat(true);
        }
    };
}

// ============================================================
// --- TEAM CHAT MODULE (MODAL VERSION WITH SEARCH & EXPORT) ---
// ============================================================

window.teamChatCache = [];
let lastReadChatId = parseInt(localStorage.getItem('ofl_last_chat_read') || 0);

window.openTeamChatModal = function() {
    const modal = document.getElementById('team-chat-modal');
    if (modal) {
        modal.classList.remove('hidden');
        window.fetchTeamChat();
        
        // סימון הכל כנקרא
        if (window.teamChatCache.length > 0) {
            lastReadChatId = window.teamChatCache[window.teamChatCache.length - 1].id;
            localStorage.setItem('ofl_last_chat_read', lastReadChatId);
            window.updateTeamChatBadge();
        }
        
        // גלילה למטה ברגע שהמודאל נפתח
        setTimeout(() => {
            const container = document.getElementById('chat-messages-container');
            if(container) container.scrollTop = container.scrollHeight;
        }, 100);
    }
};

window.closeTeamChatModal = function() {
    const modal = document.getElementById('team-chat-modal');
    if (modal) {
        modal.classList.add('hidden');
        // סימון כנקרא שוב בסגירה ליתר ביטחון
        if (window.teamChatCache.length > 0) {
            lastReadChatId = window.teamChatCache[window.teamChatCache.length - 1].id;
            localStorage.setItem('ofl_last_chat_read', lastReadChatId);
            window.updateTeamChatBadge();
        }
    }
};

window.updateTeamChatBadge = function() {
    const badge = document.getElementById('team-chat-unread-badge');
    if (!badge) return;

    const unreadCount = window.teamChatCache.filter(m => m.id > lastReadChatId).length;
    if (unreadCount > 0) {
        badge.innerText = unreadCount > 9 ? '9+' : unreadCount;
        badge.classList.remove('hidden');
    } else {
        badge.classList.add('hidden');
    }
};

window.fetchTeamChat = async function(isSilent = false) {
    if (!currentGroup || !currentGroup.id) return;
    
    const container = document.getElementById('chat-messages-container');
    const isModalOpen = document.getElementById('team-chat-modal') && !document.getElementById('team-chat-modal').classList.contains('hidden');

    if (!isSilent && isModalOpen && container && (!container.innerHTML.includes('bg-white') && !container.innerHTML.includes('bg-indigo-100'))) {
        container.innerHTML = '<p class="text-xs text-slate-400 text-center py-4 mt-auto"><i class="fa-solid fa-spinner fa-spin"></i> טוען שיחה...</p>';
    }

    try {
        const res = await fetch(`${API}/chat/${currentGroup.id}`);
        const data = await res.json();
        
        if (data.success) {
            const isNewMessages = data.messages.length > window.teamChatCache.length;
            window.teamChatCache = data.messages || [];
            
            window.updateTeamChatBadge();
            
            if (isModalOpen) {
                const shouldScroll = !isSilent || isNewMessages;
                window.renderTeamChat(shouldScroll);
                
                if (window.teamChatCache.length > 0) {
                    lastReadChatId = window.teamChatCache[window.teamChatCache.length - 1].id;
                    localStorage.setItem('ofl_last_chat_read', lastReadChatId);
                    window.updateTeamChatBadge();
                }
            }
        }
    } catch(e) { console.error('Error fetching chat', e); }
};

window.renderTeamChat = function(scrollToBottom = false) {
    const container = document.getElementById('chat-messages-container');
    if (!container) return;

    const searchInput = document.getElementById('team-chat-search');
    const searchTerm = searchInput ? searchInput.value.trim().toLowerCase() : '';
    
    let filteredChat = window.teamChatCache;
    if (searchTerm) {
        filteredChat = window.teamChatCache.filter(m => 
            (m.message && m.message.toLowerCase().includes(searchTerm)) || 
            (m.user_name && m.user_name.toLowerCase().includes(searchTerm))
        );
    }

    if (filteredChat.length === 0) {
        container.innerHTML = `
            <div class="flex flex-col items-center justify-center h-full opacity-50 mt-auto mb-auto">
                <i class="fa-regular fa-comments text-5xl text-slate-300 mb-3"></i>
                <p class="text-sm font-bold text-slate-500">${searchTerm ? 'לא נמצאו הודעות תואמות לחיפוש.' : 'אין הודעות עדיין.'}</p>
                <p class="text-[10px] text-slate-400 mt-1">${searchTerm ? 'נסו לחפש מילה אחרת.' : 'שלחו הודעה ראשונה לצוות!'}</p>
            </div>`;
        return;
    }

    let html = '<div class="flex-1 min-h-0"></div>'; 
    let currentDateGroup = '';

    const otherColors = [
        { bg: 'bg-emerald-50', border: 'border-emerald-200', text: 'text-emerald-900', name: 'text-emerald-600' },
        { bg: 'bg-rose-50', border: 'border-rose-200', text: 'text-rose-900', name: 'text-rose-600' },
        { bg: 'bg-amber-50', border: 'border-amber-200', text: 'text-amber-900', name: 'text-amber-600' },
        { bg: 'bg-cyan-50', border: 'border-cyan-200', text: 'text-cyan-900', name: 'text-cyan-600' },
        { bg: 'bg-fuchsia-50', border: 'border-fuchsia-200', text: 'text-fuchsia-900', name: 'text-fuchsia-600' }
    ];

    filteredChat.forEach(msg => {
        const isMe = String(msg.user_id) === String(currentUser.id);
        const msgDate = new Date(msg.created_at);
        const dateStr = msgDate.toLocaleDateString('he-IL');
        const timeStr = msgDate.toLocaleTimeString('he-IL', {hour: '2-digit', minute:'2-digit'});

        if (dateStr !== currentDateGroup) {
            const todayStr = new Date().toLocaleDateString('he-IL');
            const displayDate = dateStr === todayStr ? 'היום' : dateStr;
            html += `<div class="flex justify-center my-3"><span class="bg-slate-200/60 text-slate-500 text-[9px] font-bold px-3 py-1 rounded-full">${displayDate}</span></div>`;
            currentDateGroup = dateStr;
        }

        if (isMe) {
            html += `
            <div class="flex flex-col items-start w-full mb-1">
                <div class="bg-indigo-100 text-indigo-900 px-4 py-2 rounded-2xl rounded-tl-sm max-w-[85%] shadow-sm relative text-sm leading-relaxed border border-indigo-200/50 break-words">
                    ${safeStr(msg.message)}
                </div>
                <span class="text-[9px] text-slate-400 mt-1 ml-1">${timeStr} <i class="fa-solid fa-check text-indigo-300"></i></span>
            </div>`;
        } else {
            const colorIndex = parseInt(msg.user_id || 0) % otherColors.length;
            const colorObj = otherColors[colorIndex];
            
            html += `
            <div class="flex flex-col items-end w-full mb-1">
                <span class="text-[10px] font-bold ${colorObj.name} mb-0.5 mr-1">${safeStr(msg.user_name)}</span>
                <div class="${colorObj.bg} ${colorObj.text} px-4 py-2 rounded-2xl rounded-tr-sm max-w-[85%] shadow-sm relative text-sm leading-relaxed border ${colorObj.border} break-words">
                    ${safeStr(msg.message)}
                </div>
                <span class="text-[9px] text-slate-400 mt-1 mr-1">${timeStr}</span>
            </div>`;
        }
    });

    const isScrolledToBottom = container.scrollHeight - container.clientHeight <= container.scrollTop + 50;
    container.innerHTML = html;

    if (scrollToBottom || isScrolledToBottom) {
        setTimeout(() => {
            container.scrollTop = container.scrollHeight;
        }, 50);
    }
};

window.exportTeamChat = function() {
    if (!window.teamChatCache || window.teamChatCache.length === 0) {
        return showToast('error', "אין הודעות לייצוא בקבוצה זו");
    }
    
    const dateNow = new Date();
    const dateStrFormatted = `${dateNow.toLocaleDateString('he-IL')} ${dateNow.toLocaleTimeString('he-IL')}`;
    
    let content = `היסטוריית צ'אט צוות - ${currentGroup.name}\n`;
    content += `הופק בתאריך: ${dateStrFormatted}\n`;
    content += `(שים לב: ההיסטוריה נשמרת אוטומטית ל-3 חודשים בלבד)\n`;
    content += `====================================================\n\n`;
    
    window.teamChatCache.forEach(msg => {
        const msgDate = new Date(msg.created_at);
        const dateStr = `${msgDate.toLocaleDateString('he-IL')} ${msgDate.toLocaleTimeString('he-IL', {hour: '2-digit', minute:'2-digit'})}`;
        content += `[${dateStr}] ${msg.user_name}: ${msg.message}\n`;
    });
    
    const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Chat_History_${currentGroup.name}_${dateNow.toISOString().split('T')[0]}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    
    showToast('success', "היסטוריית הצ'אט ירדה בהצלחה למכשירך");
};

window.submitChatMessage = async function(e) {
    e.preventDefault();
    const input = document.getElementById('chat-message-input');
    const msg = input.value.trim();
    if (!msg) return;

    const btn = document.getElementById('btn-send-chat');
    btn.disabled = true;
    
    const tempMsg = {
        id: 99999999,
        user_id: currentUser.id,
        user_name: currentUser.nickname,
        message: msg,
        created_at: new Date().toISOString()
    };
    
    window.teamChatCache.push(tempMsg);
    window.renderTeamChat(true); 
    input.value = '';

    try {
        const res = await fetch(`${API}/chat`, {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ groupId: currentGroup.id, userId: currentUser.id, message: msg })
        });
        const data = await res.json();
        
        if (data.success) {
            window.fetchTeamChat(true); 
        } else {
            showToast('error', 'שגיאה בשליחת ההודעה');
            window.teamChatCache.pop(); 
            window.renderTeamChat(true);
        }
    } catch(err) {
        showToast('error', 'שגיאת רשת בשליחה');
        window.teamChatCache.pop();
        window.renderTeamChat(true);
    } finally {
        btn.disabled = false;
        input.focus(); 
    }
};

