window.getVatSettings = function() {
    try {
        const id = (typeof currentGroup !== 'undefined' && currentGroup) ? currentGroup.id : '';
        const savedVat = localStorage.getItem('ofl_vat_' + id);
        const settings = savedVat ? JSON.parse(savedVat) : { enabled: true, rate: 18 };
        // מיגרציה: עדכון מ-17% ל-18% (שיעור מע"מ חדש בישראל)
        if (settings.rate === 17) {
            settings.rate = 18;
            localStorage.setItem('ofl_vat_' + id, JSON.stringify(settings));
        }
        return settings;
    } catch(e) { return { enabled: true, rate: 18 }; }
};

window.forceLoadCatalog = async function(e) {
    if(e) { e.preventDefault(); e.stopPropagation(); }
    const btn = e ? e.currentTarget : null;
    if(btn) btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> מעדכן...';
    try {
        if(typeof window.fetchStoreCatalog === 'function') await window.fetchStoreCatalog();
        await window.fetchStorePromotions();
        window.renderPOSCatalog(window.posCurrentCategory);
        window.renderPOSCart();
        showToast('success', 'הקטלוג והמבצעים סונכרנו בהצלחה!');
    } catch(err) {
        showToast('error', 'שגיאה ברענון הקטלוג');
    } finally {
        if(btn) btn.innerHTML = '<i class="fa-solid fa-rotate"></i> טען מוצרים';
    }
};

window.fetchStorePromotions = async function() {
    try {
        const res = await fetch(`${API}/store/promotions/${currentGroup.id}`);
        const data = await res.json();
        if(data.success) {
            window.storePromotionsCache = data.promotions || data.data || [];
        } else {
            window.storePromotionsCache = [];
        }
    } catch(e) { 
        window.storePromotionsCache = [];
    }
    window._posPromosLoaded = true;
    
    if (typeof window.renderStorePromotions === 'function') window.renderStorePromotions();
    if (typeof window.fetchStoreCoupons === 'function') window.fetchStoreCoupons();
    
    window._internalRenderPOSCatalog(window.posCurrentCategory || 'all');
    window.renderPOSCart();
};

window.isPromoActive = function(p) {
    const active = p.is_active !== undefined ? p.is_active : p.isActive;
    if (active === false || active === 0 || String(active) === 'false') return false;
    
    const now = new Date().getTime();
    const sDate = p.start_date || p.startDate;
    if (sDate && new Date(sDate).getTime() > now) return false;
    
    const eDate = p.end_date || p.endDate;
    if (eDate) {
        let ed = new Date(eDate);
        ed.setHours(23,59,59,999);
        if (ed.getTime() < now) return false;
    }
    return true;
};

window.checkPromoApplies = function(promo, category) {
    const tType = promo.target_type || promo.targetType;
    if (tType === 'all') return true;
    
    if (tType === 'category') {
        let tIds = promo.target_ids || promo.targetIds;
        if (typeof tIds === 'string') { try { tIds = JSON.parse(tIds); } catch(e) { tIds = [tIds]; } }
        if (!Array.isArray(tIds)) tIds = [tIds];
        const catStr = String(category || 'כללי').trim();
        return tIds.some(id => String(id).trim() === catStr);
    }
    return false;
};

window.calcPOSPromotions = function(cartTotal, cartItems) {
    if (!window.storePromotionsCache) return { amount: 0, text: '' };
    const activePromos = window.storePromotionsCache.filter(window.isPromoActive);
    let totalDiscount = 0;
    let appliedPromos = new Set();
    
    // PCT & FIXED
    cartItems.forEach(item => {
        const catItem = storeCatalogCache.find(x => String(x.id) === String(item.real_id));
        if (!catItem) return;
        let bestItemDiscount = 0;
        let bestPromoName = '';
        
        activePromos.forEach(promo => {
            if (window.checkPromoApplies(promo, catItem.category)) {
                const pType = promo.promo_type || promo.promoType;
                const pVal = parseFloat(promo.promo_value || promo.promoValue) || 0;
                let currentDiscount = 0;
                
                if (pType === 'discount_pct') currentDiscount = item.price * (pVal / 100);
                else if (pType === 'discount_fixed') currentDiscount = pVal;
                
                if (currentDiscount > bestItemDiscount && currentDiscount <= item.price) {
                    bestItemDiscount = currentDiscount;
                    bestPromoName = promo.title;
                }
            }
        });
        if (bestItemDiscount > 0) {
            totalDiscount += (bestItemDiscount * item.qty);
            appliedPromos.add(bestPromoName);
        }
    });
    
    // BOGO
    activePromos.filter(p => (p.promo_type || p.promoType) === 'bogo').forEach(promo => {
        let eligibleItemsPrices = [];
        cartItems.forEach(item => {
            const catItem = storeCatalogCache.find(x => String(x.id) === String(item.real_id));
            if (catItem && window.checkPromoApplies(promo, catItem.category)) {
                for(let i=0; i<item.qty; i++) eligibleItemsPrices.push(item.price);
            }
        });
        if (eligibleItemsPrices.length >= 2) {
            eligibleItemsPrices.sort((a,b) => a - b);
            let freeCount = Math.floor(eligibleItemsPrices.length / 2);
            let bogoDiscount = 0;
            let pVal = parseFloat(promo.promo_value || promo.promoValue) || 999999;
            for(let i=0; i<freeCount; i++) bogoDiscount += Math.min(eligibleItemsPrices[i], pVal);
            
            if (bogoDiscount > totalDiscount) {
                totalDiscount = bogoDiscount;
                appliedPromos.clear();
                appliedPromos.add(promo.title);
            } else if (bogoDiscount > 0 && totalDiscount === 0) {
                totalDiscount = bogoDiscount;
                appliedPromos.add(promo.title);
            }
        }
    });
    
    return { amount: totalDiscount, text: Array.from(appliedPromos).join(', ') };
};

window.renderPOSCatalog = async function(cat = 'all') {
    if (!window._posPromosLoaded && typeof window.fetchStorePromotions === 'function') {
        await window.fetchStorePromotions();
    } else {
        window._internalRenderPOSCatalog(cat);
    }
};

window._internalRenderPOSCatalog = function(cat = 'all') {
    window.posCurrentCategory = cat;
    const grid = document.getElementById('pos-catalog-grid');
    const catTabs = document.getElementById('pos-categories-tabs');
    if(!grid || !catTabs) return;

    let categories = ['all', ...new Set(storeCatalogCache.filter(p => p.is_available).map(p => p.category || 'כללי'))];
    
    const activePromos = (window.storePromotionsCache || []).filter(window.isPromoActive);
    if (activePromos.length > 0 && !categories.includes('promotions_tab')) {
        categories.push('promotions_tab');
    }

    catTabs.innerHTML = categories.map(c => {
        let label = c === 'all' ? 'הכל' : safeStr(c);
        let activeClass = c === cat ? 'bg-indigo-600 text-white' : 'bg-white text-slate-600 hover:bg-indigo-50 border border-slate-200';
        if (c === 'promotions_tab') {
            label = '🔥 מבצעים';
            activeClass = c === cat ? 'bg-pink-500 text-white shadow-md border-pink-500' : 'bg-pink-50 text-pink-600 hover:bg-pink-100 border border-pink-200';
        }
        return `<button onclick="window._internalRenderPOSCatalog('${safeStr(c)}')" class="px-5 py-2.5 whitespace-nowrap rounded-2xl font-bold text-sm transition shadow-sm ${activeClass}">${label}</button>`;
    }).join('');

    let products = storeCatalogCache.filter(p => p.is_available);
    if (cat === 'promotions_tab') {
        products = products.filter(p => activePromos.some(promo => window.checkPromoApplies(promo, p.category)));
    } else if(cat !== 'all') {
        products = products.filter(p => (p.category || 'כללי') === cat);
    }
    
    const searchQ = (document.getElementById('pos-search') ? document.getElementById('pos-search').value : '').toLowerCase();
    if(searchQ) products = products.filter(p => p.name.toLowerCase().includes(searchQ));

    // complimentary items — staff only
    const complimentaryItems = storeCatalogCache.filter(p => p.is_complimentary && p.is_available);
    const compZone = document.getElementById('pos-complimentary-zone');
    if (complimentaryItems.length > 0) {
        const compHtml = complimentaryItems.map(p => `
            <button type="button" onclick="window.addPOSComplimentary(${p.id})"
                class="bg-amber-50 border border-amber-200 rounded-xl px-3 py-2 text-xs font-bold text-amber-800 hover:bg-amber-100 transition text-right whitespace-nowrap"
                style="touch-action:manipulation;cursor:pointer;">
                🎁 ${safeStr(p.name)}
            </button>`).join('');
        if (compZone) {
            compZone.innerHTML = `<div class="flex gap-2 flex-wrap">${compHtml}</div>`;
            compZone.classList.remove('hidden');
        } else {
            grid.insertAdjacentHTML('afterend', `<div id="pos-complimentary-zone" class="mt-3 px-1">
                <div class="text-[10px] font-black text-amber-600 mb-1.5">🎁 בקשות שירות (ללא חיוב)</div>
                <div class="flex gap-2 flex-wrap">${compHtml}</div>
            </div>`);
        }
    } else if (compZone) { compZone.classList.add('hidden'); }

    grid.innerHTML = products.map(p => {
        const isComp = !!(p.is_complimentary);
        let isComplex = false;
        if (!isComp && p.options_text && p.options_text.length > 10) {
            try {
                const parsed = JSON.parse(p.options_text);
                if (Array.isArray(parsed) || parsed.isBundle || parsed.isPizza || parsed.isComplex || parsed.complexType) isComplex = true;
            } catch(e){}
        }
        
        let badgesHtml = '<div class="absolute top-3 right-3 flex flex-col gap-1 z-20 items-end">';
        let promoBadge = '';
        let finalPrice = parseFloat(p.price) || 0;
        let originalPrice = finalPrice;
        
        if (activePromos.length > 0) {
            let bestDiscount = 0;
            activePromos.forEach(promo => {
                if (window.checkPromoApplies(promo, p.category)) {
                    const pType = promo.promo_type || promo.promoType;
                    const pVal = parseFloat(promo.promo_value || promo.promoValue) || 0;
                    let currentDiscount = 0;
                    let badgeText = '';

                    if (pType === 'discount_pct') {
                        currentDiscount = originalPrice * (pVal / 100);
                        badgeText = `-${pVal}%`;
                    } else if (pType === 'discount_fixed') {
                        currentDiscount = pVal;
                        badgeText = `₪${pVal} הנחה`;
                    } else if (pType === 'bogo') {
                        badgeText = '1+1 מתנה';
                        if (bestDiscount === 0) promoBadge = `<div class="bg-pink-500 text-white text-[10px] font-black px-2 py-1 rounded-lg shadow-sm border border-pink-400">${badgeText}</div>`;
                    }
                    
                    if (currentDiscount > bestDiscount && currentDiscount <= originalPrice) {
                        bestDiscount = currentDiscount;
                        promoBadge = `<div class="bg-pink-500 text-white text-[10px] font-black px-2 py-1 rounded-lg shadow-sm border border-pink-400">${badgeText}</div>`;
                    }
                }
            });
            finalPrice = originalPrice - bestDiscount;
            if (finalPrice < 0) finalPrice = 0;
        }
        
        if (promoBadge) badgesHtml += promoBadge;
        if (p.badge_text) {
            const colors = { 'red':'bg-red-500', 'green':'bg-green-500', 'blue':'bg-blue-500', 'yellow':'bg-yellow-500 text-yellow-900', 'pink':'bg-pink-500' };
            const bgClass = colors[p.badge_color] || 'bg-red-500';
            badgesHtml += `<div class="${bgClass} text-white text-[10px] font-black px-2 py-1 rounded-lg shadow-sm border border-white/50">${safeStr(p.badge_text)}</div>`;
        }
        badgesHtml += '</div>';
        
        let priceHtml = '';
        if (finalPrice < originalPrice && finalPrice > 0) {
            priceHtml = `<div class="flex items-center justify-end gap-1 mt-1"><span class="text-[10px] text-slate-400 line-through">₪${originalPrice.toFixed(2)}</span> <span class="font-black text-pink-600 text-base dir-ltr">₪${finalPrice.toFixed(2)}</span></div>`;
        } else {
            priceHtml = `<span class="font-black text-indigo-600 text-base dir-ltr block text-right mt-1">₪${originalPrice.toFixed(2)}</span>`;
        }
        
        const clickHandler = isComp ? `window.addPOSComplimentary(${p.id})` : `window.addPOSItem(${p.id})`;
        const compBadge = isComp ? `<span class="absolute top-3 left-3 bg-amber-400 text-white text-[9px] font-black px-2 py-1 rounded-lg shadow-sm z-20">🎁 חינם</span>` : '';
        const cardBorder = isComp ? 'border-amber-200 hover:border-amber-400' : 'border-slate-200 hover:border-indigo-400';
        const isRestCtx = ['restaurant','cafe'].includes(currentGroup?.business_type);
        const outOfStockBtn = (isRestCtx && !isComp) ? `<button type="button" onclick="event.stopPropagation();window.pos86Item(${p.id})" title="סמן כאזל" class="absolute bottom-2 left-2 z-30 bg-slate-100 hover:bg-red-100 text-slate-400 hover:text-red-600 text-[9px] font-black px-1.5 py-1 rounded-lg border border-slate-200 opacity-0 group-hover:opacity-100 transition" style="touch-action:manipulation;">86</button>` : '';
        return `
        <div onclick="${clickHandler}" class="bg-white rounded-3xl border ${cardBorder} shadow-sm cursor-pointer hover:shadow-lg transition-all flex flex-col relative overflow-hidden group h-full" style="touch-action:manipulation;">
            ${badgesHtml}
            ${compBadge}
            ${isComplex ? `<span class="absolute top-3 left-3 bg-purple-500 text-white text-[9px] font-black px-2 py-1 rounded-lg shadow-sm z-20"><i class="fa-solid fa-layer-group ml-1"></i>הרכבה</span>` : ''}
            <div class="h-28 bg-slate-50 flex items-center justify-center border-b border-slate-100 overflow-hidden relative z-0">
                ${p.image_url ? `<img src="${p.image_url}" class="w-full h-full object-cover">` : `<i class="${isComp ? 'fa-solid fa-gift text-amber-300' : 'fa-solid fa-utensils text-slate-300'} text-3xl"></i>`}
            </div>
            <div class="p-4 flex-1 flex flex-col justify-between text-right">
                <h4 class="font-bold text-slate-800 text-sm leading-tight mb-2 line-clamp-2">${safeStr(p.name)}</h4>
                ${isComp ? `<span class="text-xs font-black text-amber-600">ללא חיוב → בחר שולחן</span>` : priceHtml}
            </div>
            ${outOfStockBtn}
        </div>`;
    }).join('');
};

window.posSelectedTable = null;

window.selectPOSTable = function(tableId, btn) {
    window.posSelectedTable = tableId;
    document.querySelectorAll('.pos-table-btn').forEach(b => {
        b.className = b.className.replace(/bg-amber-100 border-amber-400 text-amber-800/g, 'bg-slate-100 text-slate-600 border border-slate-200');
        b.className = b.className.replace(/bg-slate-100 text-slate-600 border border-slate-200/g, 'bg-slate-100 text-slate-600 border border-slate-200');
    });
    if (btn) {
        btn.className = btn.className.replace('bg-slate-100 text-slate-600 border border-slate-200', 'bg-amber-100 border-amber-400 text-amber-800');
        btn.className += ' font-black';
    }
    const label = document.getElementById('pos-table-label');
    if (label) label.textContent = `שולחן ${tableId}`;
};

window.initPOSTableSelector = function() {
    if (document.getElementById('pos-table-zone')) return;
    const isRestaurant = (currentGroup?.business_type === 'restaurant' || currentGroup?.business_type === 'cafe');
    if (!isRestaurant) return;
    const phoneInput = document.getElementById('pos-customer-phone');
    if (!phoneInput) return;
    const count = parseInt(currentGroup.table_count || 8);
    const assigns = getTableAssignments ? getTableAssignments() : {};
    const states = getTableStates ? getTableStates() : {};
    const tableBtns = Array.from({length:count}, (_, i) => {
        const tid = i+1;
        const isFree = (states[tid]||'free') === 'free';
        const waiter = assigns[tid] ? ` (${assigns[tid]})` : '';
        return `<button type="button" onclick="selectPOSTable(${tid},this)"
            class="pos-table-btn bg-slate-100 text-slate-600 border border-slate-200 rounded-lg px-2 py-1 text-xs font-bold transition whitespace-nowrap ${!isFree?'opacity-60':''}"
            style="touch-action:manipulation;cursor:pointer;">${tid}${waiter}</button>`;
    }).join('');
    const zone = document.createElement('div');
    zone.id = 'pos-table-zone';
    zone.className = 'px-4 pt-3 pb-2 border-b border-slate-100 bg-slate-50';
    zone.innerHTML = `<div class="flex items-center gap-2 mb-1.5">
        <span class="text-xs font-bold text-slate-600 shrink-0">🍽️ שולחן:</span>
        <span id="pos-table-label" class="text-xs font-black text-amber-600">לא נבחר</span>
    </div>
    <div class="flex gap-1.5 flex-wrap">${tableBtns}</div>`;
    phoneInput.closest('.p-4.border-b') ? phoneInput.closest('.p-4.border-b').before(zone) : phoneInput.closest('div').before(zone);
};

window.addPOSComplimentary = function(id) {
    const p = storeCatalogCache.find(x => x.id === id); if(!p) return;
    // Show table picker for complimentary items (no POS checkout needed)
    document.getElementById('comp-table-picker')?.remove();
    const count = parseInt(currentGroup.table_count || 8);
    const assigns = getTableAssignments ? getTableAssignments() : {};
    const tableBtns = Array.from({length:count}, (_, i) => {
        const tid = i+1;
        const waiter = assigns[tid] ? ` · ${assigns[tid]}` : '';
        return `<button type="button"
            ontouchend="event.preventDefault();sendComplimentaryToTable(${id},${tid});"
            onclick="sendComplimentaryToTable(${id},${tid})"
            class="bg-amber-50 border border-amber-200 rounded-xl p-3 font-black text-amber-800 text-sm active:bg-amber-200"
            style="touch-action:manipulation;cursor:pointer;">${tid}<span class="block text-[9px] text-amber-600 font-normal">${waiter}</span></button>`;
    }).join('');
    const html = `<div id="comp-table-picker" class="fixed inset-0 bg-black/60 z-[9999] flex items-end justify-center p-4">
        <div class="bg-white rounded-[2rem] w-full max-w-sm p-5 shadow-2xl">
            <h3 class="font-black text-slate-800 mb-3 text-center">🎁 ${safeStr(p.name)}<br><span class="text-sm font-normal text-slate-500">לאיזה שולחן?</span></h3>
            <div class="grid grid-cols-4 gap-2 mb-4">${tableBtns}</div>
            <button onclick="document.getElementById('comp-table-picker').remove()" class="w-full bg-slate-100 py-3 rounded-xl font-bold text-slate-600" style="touch-action:manipulation;">ביטול</button>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
};

window.sendComplimentaryToTable = function(productId, tableNumber) {
    const p = storeCatalogCache.find(x => x.id === productId); if(!p) return;
    const key = `service_req_${currentGroup.id}`;
    let reqs = [];
    try { reqs = JSON.parse(localStorage.getItem(key) || '[]'); } catch(e) {}
    reqs.unshift({ id: Date.now(), productId, name: p.name, tableNumber, time: new Date().toISOString(), done: false });
    reqs = reqs.slice(0, 50); // keep last 50
    localStorage.setItem(key, JSON.stringify(reqs));
    document.getElementById('comp-table-picker')?.remove();
    showToast('success', `${p.name} → שולחן ${tableNumber} 🎁`);
};

window.markServiceReqDone = function(reqId) {
    const key = `service_req_${currentGroup.id}`;
    let reqs = [];
    try { reqs = JSON.parse(localStorage.getItem(key) || '[]'); } catch(e) {}
    const req = reqs.find(r => r.id === reqId);
    if (req) { req.done = true; localStorage.setItem(key, JSON.stringify(reqs)); }
    const dashEl = document.getElementById('content-role-dashboard');
    if (dashEl) {
        const rt = currentUser?.employee_role_type;
        if (rt === 'waiter') renderWaiterDashboard(dashEl);
        else if (rt === 'shift_manager') renderShiftManagerDashboard(dashEl);
    }
};

window.markItemServed = function(orderId, idx) {
    fetch(`/api/store/orders/${orderId}/item-ready`, {
        method: 'PATCH', headers: {'Content-Type':'application/json'},
        body: JSON.stringify({idx, ready: false})
    }).then(() => refreshWaiterReadySection()).catch(() => {});
};

window.waiterOpenOrderDetails = async function(orderId) {
    const numId = parseInt(orderId);
    if (!storeOrdersCache || !storeOrdersCache.find(o => o.id === numId)) {
        try { await window.fetchStoreOrders(); } catch(e) {}
    }
    window.openStoreOrderModal(numId);
};

window.collectAndBill = function(orderId, tableNum) {
    window.markReadyDelivered(orderId, 'completed');
    if (tableNum) {
        window.waiterSelectedTable = parseInt(tableNum);
        setTimeout(() => window.waiterCloseBill(), 150);
    }
};

window.markReadyDelivered = function(orderId, newStatus) {
    const finalStatus = newStatus || 'completed';
    const body = { orderId, status: finalStatus };
    if (finalStatus === 'shipped') body.setDelivery = true;
    fetch('/api/store/orders/status', {
        method: 'POST', headers: {'Content-Type':'application/json'},
        body: JSON.stringify(body)
    }).catch(() => {});
    try {
        const bills = getTableBills();
        let changed = false;
        Object.values(bills).forEach(bill => {
            (bill.submitted || []).forEach(item => {
                if (String(item.orderId) === String(orderId) && !item.delivered) {
                    item.delivered = true;
                    item.deliveredAt = new Date().toISOString();
                    changed = true;
                }
            });
        });
        if (changed) saveTableBills(bills);
    } catch(e) {}
    if (document.getElementById('waiter-pos-modal')) window.waiterRenderCart();
    refreshWaiterReadySection();
};

// ─── WAITER POS (מסך הזמנה מותאם מלצר) ────────────────────────────────────
// Table bill structure: {tableId: {openedAt, submitted:[{id,name,price,qty,kitchenStation,note,submittedAt,orderId,delivered}], pending:[{id,name,price,qty,kitchenStation,note}]}}
window.waiterPOSCart = []; // pending items for current table (new, not yet sent)
window.waiterSelectedTable = null;

function getTableBills() {
    try { return JSON.parse(localStorage.getItem(`table_bills_${currentGroup.id}`) || '{}'); } catch(e) { return {}; }
}
function saveTableBills(bills) {
    localStorage.setItem(`table_bills_${currentGroup.id}`, JSON.stringify(bills));
    _tableBillsLastServerJson = null; // force next poll to detect change
    syncTableBillsToServer(bills);
}

// Save current pending items before switching table
function waiterSavePendingForCurrentTable() {
    const t = window.waiterSelectedTable;
    if (!t) return;
    const bills = getTableBills();
    if (!bills[t]) bills[t] = { openedAt: new Date().toISOString(), submitted: [], pending: [] };
    bills[t].pending = JSON.parse(JSON.stringify(window.waiterPOSCart));
    saveTableBills(bills);
}

window.showWaiterPOS = async function() {
    document.getElementById('waiter-pos-modal')?.remove();

    // Listen for table assignment changes from manager
    if (!window._waiterStorageListenerAdded) {
        window._waiterStorageListenerAdded = true;
        window.addEventListener('storage', (e) => {
            if (e.key?.startsWith('table_assign_') && e.newValue !== e.oldValue) {
                showToast('info', '📊 שולחנות עודכנו — לחץ רענן');
            }
        });
    }

    // Ensure catalog is loaded (fix: products not showing)
    if (!storeCatalogCache || !storeCatalogCache.length) {
        try {
            const r = await fetch(`/api/store/catalog/${currentGroup.id}`);
            const d = await r.json();
            if (Array.isArray(d) && d.length) storeCatalogCache = d;
        } catch(e) {}
    }

    const products = (storeCatalogCache||[]).filter(p => p.is_active !== false);
    const count = parseInt(currentGroup.table_count || 8);
    const bills = getTableBills();
    const assigns = getTableAssignments ? getTableAssignments() : {};

    // Table selector chips
    const tableBtns = Array.from({length:count}, (_, i) => {
        const tid = i+1;
        const bill = bills[tid];
        const subCount = bill ? (bill.submitted||[]).length : 0;
        const pendCount = bill ? (bill.pending||[]).length : 0;
        const hasBill = subCount > 0 || pendCount > 0;
        const selected = window.waiterSelectedTable === tid;
        const chipClass = selected ? 'bg-amber-500 text-white shadow' : hasBill ? 'bg-indigo-100 text-indigo-800 border border-indigo-300' : 'bg-slate-100 text-slate-600 border border-slate-200';
        const sub = hasBill ? `<span class="text-[8px] block font-normal opacity-80">${subCount} הוזמן${pendCount?` +${pendCount} חדש`:''}</span>` : `<span class="text-[8px] block opacity-50">${assigns[tid]||'פנוי'}</span>`;
        return `<button type="button" ontouchend="event.preventDefault();waiterSelectTable(${tid},this);" onclick="waiterSelectTable(${tid},this)"
            class="waiter-table-chip shrink-0 rounded-xl px-3 py-2 font-black text-sm transition min-w-[52px] text-center ${chipClass}" style="touch-action:manipulation;cursor:pointer;">
            ${tid}${sub}</button>`;
    }).join('');

    // Product grid
    const prodHtml = products.length ? products.map(p => {
        const isComp = !!(p.is_complimentary);
        const handler = isComp ? `waiterAddComplimentary(${p.id})` : `waiterAddItem(${p.id})`;
        const border = isComp ? 'border-amber-200' : 'border-slate-200';
        const icon = p.image_url ? `<img src="${p.image_url}" class="w-full h-full object-cover">` : `<i class="${isComp?'fa-solid fa-gift text-amber-300':'fa-solid fa-utensils text-slate-300'} text-2xl"></i>`;
        const priceLabel = isComp ? `<span class="text-[10px] font-black text-amber-600">ללא חיוב</span>` : `<span class="font-black text-indigo-600 text-sm">₪${parseFloat(p.price||0).toFixed(0)}</span>`;
        const compBadge = isComp ? `<span class="absolute top-1 left-1 bg-amber-400 text-white text-[8px] font-black px-1 py-0.5 rounded z-10">🎁</span>` : '';
        return `<div onclick="${handler}" class="bg-white rounded-xl border ${border} shadow-sm cursor-pointer active:scale-95 transition flex flex-col relative overflow-hidden" style="touch-action:manipulation;">
            ${compBadge}
            <div class="h-16 bg-slate-50 flex items-center justify-center border-b border-slate-100 overflow-hidden">${icon}</div>
            <div class="p-2 text-right flex-1 flex flex-col justify-between">
                <div class="text-xs font-bold text-slate-800 leading-tight line-clamp-2">${safeStr(p.name)}</div>
                ${priceLabel}
            </div>
        </div>`;
    }).join('') : '<p class="col-span-3 text-center text-slate-400 text-sm py-6">אין מוצרים — הוסף מוצרים בניהול חנות</p>';

    const html = `<div id="waiter-pos-modal" class="fixed inset-0 bg-white z-[9990] flex flex-col" style="direction:rtl;">
        <div class="flex items-center gap-3 px-4 py-3 bg-amber-600 text-white shrink-0">
            <button ontouchend="event.preventDefault();waiterCloseModal();" onclick="waiterCloseModal()" class="text-white text-xl" style="touch-action:manipulation;"><i class="fa-solid fa-xmark"></i></button>
            <h2 class="font-black text-base flex-1">🍽️ הזמנה לשולחן</h2>
            <button id="waiter-reload-catalog-btn" ontouchend="event.preventDefault();waiterReloadCatalog(this);" onclick="waiterReloadCatalog(this)" class="text-[11px] font-bold bg-white/20 hover:bg-white/30 px-2 py-1 rounded-lg transition" style="touch-action:manipulation;" title="טען מוצרים"><i class="fa-solid fa-rotate"></i> טען</button>
            <button id="waiter-refresh-tables-btn" ontouchend="event.preventDefault();waiterRefreshTables(this);" onclick="waiterRefreshTables(this)" class="text-[11px] font-bold bg-white/20 hover:bg-white/30 px-2 py-1 rounded-lg transition" style="touch-action:manipulation;" title="רענן שולחנות"><i class="fa-solid fa-arrows-rotate"></i></button>
            <span id="waiter-pos-table-label" class="text-sm font-black bg-white/20 px-3 py-1 rounded-lg">${window.waiterSelectedTable ? `שולחן ${window.waiterSelectedTable}` : 'בחר שולחן'}</span>
        </div>
        <div class="bg-amber-50 border-b border-amber-200 px-3 py-2 shrink-0">
            <div id="waiter-table-chips" class="flex flex-wrap gap-2 pb-1 max-h-28 overflow-y-auto" style="scrollbar-width:thin;">${tableBtns}</div>
        </div>
        <div class="flex-1 flex overflow-hidden">
            <div class="flex-1 overflow-y-auto p-3 bg-slate-50">
                <div id="waiter-prod-grid" class="grid grid-cols-3 sm:grid-cols-4 gap-2">${prodHtml}</div>
            </div>
            <div class="w-72 shrink-0 border-r border-slate-200 bg-white flex flex-col overflow-hidden">
                <div class="px-3 py-2 border-b border-slate-100 flex items-center justify-between shrink-0">
                    <span class="font-black text-slate-700 text-sm">🛒 חשבון שולחן</span>
                    <div class="flex gap-2">
                        <button ontouchend="event.preventDefault();waiterClearPending();" onclick="waiterClearPending()" class="text-[10px] text-red-400 font-bold" style="touch-action:manipulation;">נקה חדש</button>
                        <button ontouchend="event.preventDefault();waiterCloseBill();" onclick="waiterCloseBill()" class="text-[10px] text-indigo-600 font-bold" style="touch-action:manipulation;">סגור חשבון 💳</button>
                    </div>
                </div>
                <div id="waiter-cart-list" class="flex-1 overflow-y-auto p-2 space-y-1"></div>
                <div class="p-3 border-t border-slate-100 shrink-0">
                    <div class="flex justify-between mb-2">
                        <span class="text-xs text-slate-500">חדש לשליחה:</span>
                        <span id="waiter-cart-total" class="font-black text-slate-800 text-sm">₪0</span>
                    </div>
                    <button id="waiter-submit-btn" ontouchend="event.preventDefault();waiterSubmitOrder();" onclick="waiterSubmitOrder()"
                        class="w-full bg-green-600 text-white rounded-xl py-3 font-black text-sm active:scale-95 transition shadow"
                        style="touch-action:manipulation;">שלח למטבח ✓</button>
                </div>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
    window.waiterRenderCart();

    // Auto-refresh table assignments every 5 seconds (in case manager assigns new tables)
    if (window._waiterTablePollingInterval) clearInterval(window._waiterTablePollingInterval);
    window._waiterTablePollingInterval = setInterval(async () => {
        await syncTableAssignmentsFromServer(); // Pull latest from server first
        const assigns = getTableAssignments() || {};
        const count = parseInt(currentGroup?.table_count || 8);
        const bills = getTableBills();
        let changed = false;

        // Check if any assignments changed
        Array.from({length:count}, (_, i) => i+1).forEach(tid => {
            const btn = document.querySelector(`.waiter-table-chip:nth-child(${tid})`);
            if (btn) {
                const currentAssign = assigns[tid] || 'פנוי';
                const bill = bills[tid];
                const subCount = bill ? (bill.submitted||[]).length : 0;
                const pendCount = bill ? (bill.pending||[]).length : 0;
                const hasBill = subCount > 0 || pendCount > 0;
                const expectedSub = hasBill ? `<span class="text-[8px] block font-normal opacity-80">${subCount} הוזמן${pendCount?` +${pendCount} חדש`:''}</span>` : `<span class="text-[8px] block opacity-50">${currentAssign}</span>`;
                if (btn.innerHTML !== expectedSub && !hasBill) changed = true;
            }
        });

        // If changes detected, show notification
        if (changed && !window._waiterJustShown) {
            const chipsContainer = document.getElementById('waiter-table-chips');
            if (chipsContainer) {
                const tableBtns = Array.from({length:count}, (_, i) => {
                    const tid = i+1;
                    const bill = bills[tid];
                    const subCount = bill ? (bill.submitted||[]).length : 0;
                    const pendCount = bill ? (bill.pending||[]).length : 0;
                    const hasBill = subCount > 0 || pendCount > 0;
                    const selected = window.waiterSelectedTable === tid;
                    const chipClass = selected ? 'bg-amber-500 text-white shadow' : hasBill ? 'bg-indigo-100 text-indigo-800 border border-indigo-300' : 'bg-slate-100 text-slate-600 border border-slate-200';
                    const sub = hasBill ? `<span class="text-[8px] block font-normal opacity-80">${subCount} הוזמן${pendCount?` +${pendCount} חדש`:''}</span>` : `<span class="text-[8px] block opacity-50">${assigns[tid]||'פנוי'}</span>`;
                    return `<button type="button" ontouchend="event.preventDefault();waiterSelectTable(${tid},this);" onclick="waiterSelectTable(${tid},this)"
                        class="waiter-table-chip shrink-0 rounded-xl px-3 py-2 font-black text-sm transition min-w-[52px] text-center ${chipClass}" style="touch-action:manipulation;cursor:pointer;">
                        ${tid}${sub}</button>`;
                }).join('');
                chipsContainer.innerHTML = tableBtns;
            }
        }
    }, 5000);
};


window.waiterReloadCatalog = async function(btn) {
    if (btn) btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
    try {
        const r = await fetch(`/api/store/catalog/${currentGroup.id}`);
        const d = await r.json();
        if (Array.isArray(d) && d.length) {
            storeCatalogCache = d;
            const products = d.filter(p => p.is_active !== false);
            const prodHtml = products.length ? products.map(p => {
                const isComp = !!(p.is_complimentary);
                const handler = isComp ? `waiterAddComplimentary(${p.id})` : `waiterAddItem(${p.id})`;
                const border = isComp ? 'border-amber-200' : 'border-slate-200';
                const icon = p.image_url ? `<img src="${p.image_url}" class="w-full h-full object-cover">` : `<i class="${isComp?'fa-solid fa-gift text-amber-300':'fa-solid fa-utensils text-slate-300'} text-2xl"></i>`;
                const priceLabel = isComp ? `<span class="text-[10px] font-black text-amber-600">ללא חיוב</span>` : `<span class="font-black text-indigo-600 text-sm">₪${parseFloat(p.price||0).toFixed(0)}</span>`;
                const compBadge = isComp ? `<span class="absolute top-1 left-1 bg-amber-400 text-white text-[8px] font-black px-1 py-0.5 rounded z-10">🎁</span>` : '';
                return `<div onclick="${handler}" class="bg-white rounded-xl border ${border} shadow-sm cursor-pointer active:scale-95 transition flex flex-col relative overflow-hidden" style="touch-action:manipulation;">${compBadge}<div class="h-16 bg-slate-50 flex items-center justify-center border-b border-slate-100 overflow-hidden">${icon}</div><div class="p-2 text-right flex-1 flex flex-col justify-between"><div class="text-xs font-bold text-slate-800 leading-tight line-clamp-2">${safeStr(p.name)}</div>${priceLabel}</div></div>`;
            }).join('') : '<p class="col-span-3 text-center text-slate-400 text-sm py-6">אין מוצרים — הוסף מוצרים בניהול חנות</p>';
            const grid = document.getElementById('waiter-prod-grid');
            if (grid) grid.innerHTML = prodHtml;
            showToast('success', `נטענו ${products.length} מוצרים`);
        } else {
            showToast('error', 'לא נמצאו מוצרים');
        }
    } catch(e) {
        showToast('error', 'שגיאה בטעינת מוצרים');
    } finally {
        if (btn) btn.innerHTML = '<i class="fa-solid fa-rotate"></i> טען';
    }
};

window.waiterRefreshTables = async function(btn) {
    if (btn) {
        btn.classList.add('opacity-50', 'pointer-events-none');
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
    }
    try {
        await syncTableAssignmentsFromServer(); // Pull latest from server
        // Rebuild table chips with refreshed assignments
        const count = parseInt(currentGroup.table_count || 8);
        const bills = getTableBills();
        const assigns = getTableAssignments() || {};
        const tableBtns = Array.from({length:count}, (_, i) => {
            const tid = i+1;
            const bill = bills[tid];
            const subCount = bill ? (bill.submitted||[]).length : 0;
            const pendCount = bill ? (bill.pending||[]).length : 0;
            const hasBill = subCount > 0 || pendCount > 0;
            const selected = window.waiterSelectedTable === tid;
            const chipClass = selected ? 'bg-amber-500 text-white shadow' : hasBill ? 'bg-indigo-100 text-indigo-800 border border-indigo-300' : 'bg-slate-100 text-slate-600 border border-slate-200';
            const sub = hasBill ? `<span class="text-[8px] block font-normal opacity-80">${subCount} הוזמן${pendCount?` +${pendCount} חדש`:''}</span>` : `<span class="text-[8px] block opacity-50">${assigns[tid]||'פנוי'}</span>`;
            return `<button type="button" ontouchend="event.preventDefault();waiterSelectTable(${tid},this);" onclick="waiterSelectTable(${tid},this)"
                class="waiter-table-chip shrink-0 rounded-xl px-3 py-2 font-black text-sm transition min-w-[52px] text-center ${chipClass}" style="touch-action:manipulation;cursor:pointer;">
                ${tid}${sub}</button>`;
        }).join('');
        const chipsContainer = document.getElementById('waiter-table-chips');
        if (chipsContainer) chipsContainer.innerHTML = tableBtns;
        showToast('success', 'שולחנות עודכנו');
    } catch(e) {
        showToast('error', 'שגיאה בעדכון שולחנות');
    } finally {
        if (btn) {
            btn.classList.remove('opacity-50', 'pointer-events-none');
            btn.innerHTML = '<i class="fa-solid fa-arrows-rotate"></i>';
        }
    }
};

window.waiterCloseModal = function() {
    waiterSavePendingForCurrentTable();
    if (window._waiterTablePollingInterval) {
        clearInterval(window._waiterTablePollingInterval);
        window._waiterTablePollingInterval = null;
    }
    document.getElementById('waiter-pos-modal')?.remove();
};

window.waiterSelectTable = function(tid, btn) {
    // Save pending items for old table before switching
    waiterSavePendingForCurrentTable();
    window.waiterSelectedTable = tid;
    // Load pending items for new table
    const bills = getTableBills();
    window.waiterPOSCart = bills[tid]?.pending ? JSON.parse(JSON.stringify(bills[tid].pending)) : [];
    document.querySelectorAll('.waiter-table-chip').forEach(b => {
        b.className = b.className.replace('bg-amber-500 text-white shadow', 'bg-slate-100 text-slate-600 border border-slate-200');
        b.className = b.className.replace('bg-indigo-100 text-indigo-800 border border-indigo-300', 'bg-slate-100 text-slate-600 border border-slate-200');
    });
    if (btn) btn.className = btn.className.replace('bg-slate-100 text-slate-600 border border-slate-200', 'bg-amber-500 text-white shadow');
    const lbl = document.getElementById('waiter-pos-table-label');
    if (lbl) lbl.textContent = `שולחן ${tid}`;
    window.waiterRenderCart();
};

window.waiterAddItem = function(id) {
    if (!window.waiterSelectedTable) { showToast('info', 'בחר שולחן תחילה'); return; }
    const p = (storeCatalogCache||[]).find(x => x.id === id); if (!p) return;
    // Handle complex dishes (modifiers, pizza, bundle) same as regular POS
    if (p.options_text && p.options_text.length > 10) {
        try {
            const parsed = JSON.parse(p.options_text);
            window._waiterPOSMode = true;
            if (parsed && (parsed.isBundle || parsed.isComplex)) { window.openPOSBundleModal(p, parsed); return; }
            if (parsed && parsed.isPizza) { window.openPOSPizzaModal(p, parsed); return; }
            if (Array.isArray(parsed)) { window.openPOSModifiersModal(p, parsed); return; }
        } catch(e) { window._waiterPOSMode = false; }
    }
    const existing = window.waiterPOSCart.find(i => i.id === id && !i.modifiers);
    if (existing) existing.qty++;
    else window.waiterPOSCart.push({ id: p.id, name: p.name, price: parseFloat(p.price)||0, qty: 1, kitchenStation: p.kitchen_station || 'other', note: '', category: p.category||'' });
    window.waiterRenderCart();
    if (window.waiterSelectedTable) waiterSavePendingForCurrentTable();
};

window.waiterAddComplimentary = function(id) {
    window.addPOSComplimentary(id);
};

window.waiterChangeQty = function(idx, delta) {
    if (!window.waiterPOSCart[idx]) return;
    window.waiterPOSCart[idx].qty += delta;
    if (window.waiterPOSCart[idx].qty <= 0) window.waiterPOSCart.splice(idx, 1);
    window.waiterRenderCart();
    if (window.waiterSelectedTable) waiterSavePendingForCurrentTable();
};

window.waiterSetNote = function(idx, val) {
    if (window.waiterPOSCart[idx]) window.waiterPOSCart[idx].note = val;
};

window.waiterClearPending = function() {
    if (!window.waiterPOSCart.length) {
        showToast('info', 'אין פריטים חדשים לניקוי');
        return;
    }
    window.waiterPOSCart = [];
    window.waiterRenderCart();
    showToast('success', 'פריטים חדשים נוקו ✓');
};

window.waiterMarkDelivered = function(tableId, subIdx) {
    const bills = getTableBills();
    if (bills[tableId]?.submitted?.[subIdx]) {
        bills[tableId].submitted[subIdx].delivered = true;
        bills[tableId].submitted[subIdx].deliveredAt = new Date().toISOString();
        saveTableBills(bills);
        window.waiterRenderCart();
    }
};

window.waiterRemoveSubmitted = async function(tableId, subIdx) {
    const bills = getTableBills();
    if (!bills[tableId]?.submitted?.[subIdx]) return;
    const item = bills[tableId].submitted[subIdx];
    if (!await window._uiConfirm(`להסיר "${item.name}" מחשבון שולחן ${tableId}?`)) return;
    bills[tableId].submitted.splice(subIdx, 1);
    if (!bills[tableId].submitted.length && !bills[tableId].pending?.length) {
        delete bills[tableId];
    }
    saveTableBills(bills);
    window.waiterRenderCart();
    showToast('success', `"${item.name}" הוסר מהחשבון`);
};

window.waiterRenderCart = function() {
    const list = document.getElementById('waiter-cart-list');
    const totalEl = document.getElementById('waiter-cart-total');
    if (!list) return;

    const table = window.waiterSelectedTable;
    const bills = getTableBills();
    const bill = table ? (bills[table] || { submitted: [], pending: [] }) : null;
    const submitted = bill?.submitted || [];

    let html = '';

    // Section 1: Already submitted items
    if (submitted.length) {
        html += `<div class="text-[9px] font-black text-slate-400 uppercase px-1 pt-1 pb-0.5">הוזמן</div>`;
        html += submitted.map((i, idx) => {
            const isDelivered = !!i.delivered;
            const isBON = !isDelivered && (window._waiterItemReadyList||[]).some(ir => ir.orderId == i.orderId && ir.name === i.name);
            const noteStr = i.note ? `<div class="text-[9px] text-slate-400 truncate">${safeStr(i.note)}</div>` : '';
            const bonBadge = isBON ? `<span class="text-[9px] font-black text-orange-600 bg-orange-50 border border-orange-200 px-1 py-0.5 rounded leading-none">🍽️ מוכן</span>` : '';
            return `<div class="rounded-lg p-2 flex items-center gap-1.5 ${isDelivered ? 'bg-green-50 opacity-60' : isBON ? 'bg-orange-50 border border-orange-100' : 'bg-slate-50'}">
                <div class="flex-1 min-w-0">
                    <div class="text-xs font-bold text-slate-700 truncate">${safeStr(i.name)} ${i.qty>1?`×${i.qty}`:''}</div>
                    ${noteStr}
                    <div class="text-[9px] text-slate-400">₪${((i.price||0)*i.qty).toFixed(0)}</div>
                </div>
                <div class="flex items-center gap-1 shrink-0">
                ${isDelivered
                    ? `<span class="text-green-500 text-base">✓</span>`
                    : `${bonBadge}<button ontouchend="event.preventDefault();waiterMarkDelivered(${table},${idx});" onclick="waiterMarkDelivered(${table},${idx})" class="bg-green-100 text-green-700 text-[9px] font-black px-1.5 py-1 rounded" style="touch-action:manipulation;">סופק</button>`
                }
                <button ontouchend="event.preventDefault();waiterRemoveSubmitted(${table},${idx});" onclick="waiterRemoveSubmitted(${table},${idx})" class="w-5 h-5 bg-red-100 text-red-500 rounded-full text-xs font-black flex items-center justify-center" style="touch-action:manipulation;" title="הסר מהחשבון">×</button>
                </div>
            </div>`;
        }).join('');
        if (html) html += `<div class="border-t border-slate-100 my-1"></div>`;
    }

    // Section 2: Pending (new items to send)
    if (window.waiterPOSCart.length) {
        html += `<div class="text-[9px] font-black text-amber-600 uppercase px-1 pb-0.5">חדש — טרם נשלח</div>`;
        html += window.waiterPOSCart.map((i, idx) => `
            <div class="bg-amber-50 border border-amber-100 rounded-lg p-2">
                <div class="flex items-center gap-1.5 mb-1">
                    <div class="flex-1 min-w-0">
                        <div class="text-xs font-bold text-slate-800 truncate">${safeStr(i.name)}</div>
                        <div class="text-[9px] text-slate-500">₪${(i.price*i.qty).toFixed(0)}</div>
                    </div>
                    <div class="flex items-center gap-1 shrink-0">
                        <button ontouchend="event.preventDefault();waiterChangeQty(${idx},-1);" onclick="waiterChangeQty(${idx},-1)" class="w-5 h-5 bg-slate-200 rounded-full text-slate-600 font-black text-xs flex items-center justify-center" style="touch-action:manipulation;">−</button>
                        <span class="text-xs font-black w-4 text-center">${i.qty}</span>
                        <button ontouchend="event.preventDefault();waiterChangeQty(${idx},1);" onclick="waiterChangeQty(${idx},1)" class="w-5 h-5 bg-amber-500 text-white rounded-full font-black text-xs flex items-center justify-center" style="touch-action:manipulation;">+</button>
                    </div>
                </div>
                <input type="text" placeholder="הערה למנה..." value="${safeStr(i.note||'')}"
                    oninput="waiterSetNote(${idx},this.value)"
                    class="w-full text-[10px] border border-amber-200 rounded px-2 py-1 bg-white focus:outline-none focus:border-amber-400"
                    style="touch-action:manipulation;">
            </div>`).join('');
    } else if (!submitted.length) {
        html = '<p class="text-center text-slate-400 text-xs py-6">' + (table ? 'הוסף פריטים מהתפריט' : 'בחר שולחן תחילה') + '</p>';
    }

    list.innerHTML = html;

    const newTotal = window.waiterPOSCart.reduce((s,i) => s + i.price*i.qty, 0);
    if (totalEl) totalEl.textContent = `₪${newTotal.toFixed(0)}`;

    const submitBtn = document.getElementById('waiter-submit-btn');
    if (submitBtn) {
        const hasPending = window.waiterPOSCart.length > 0;
        const allDelivered = submitted.length > 0 && submitted.every(i => !!i.delivered);
        const canClose = !hasPending && allDelivered && table;
        if (canClose) {
            submitBtn.disabled = false;
            submitBtn.textContent = '💳 סגור חשבון';
            submitBtn.className = 'w-full rounded-xl py-3 font-black text-sm active:scale-95 transition shadow bg-blue-600 text-white';
            submitBtn.onclick = () => window.waiterCloseBill();
        } else {
            submitBtn.disabled = !hasPending;
            submitBtn.textContent = 'שלח למטבח ✓';
            submitBtn.onclick = () => window.waiterSubmitOrder();
            submitBtn.className = `w-full rounded-xl py-3 font-black text-sm active:scale-95 transition shadow ${hasPending ? 'bg-green-600 text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`;
        }
    }
};

window.waiterSubmitOrder = async function() {
    if (!window.waiterSelectedTable) { showToast('info', 'בחר שולחן תחילה'); return; }
    if (!window.waiterPOSCart.length) { showToast('info', 'אין פריטים חדשים לשליחה'); return; }
    const table = window.waiterSelectedTable;
    const cartSnapshot = JSON.parse(JSON.stringify(window.waiterPOSCart)); // snapshot before clear
    const total = cartSnapshot.reduce((s,i) => s + i.price*i.qty, 0);
    const items = cartSnapshot.map(i => ({ catalogId: i.id, name: i.name, quantity: i.qty, price: i.price, note: i.note||'', kitchenStation: i.kitchenStation || 'other' }));
    const meta = { tableNumber: table, waiter: currentUser?.nickname || '' };
    items.push({ catalogId: null, is_quote_metadata: true, data: JSON.stringify(meta) });

    const submitBtn = document.getElementById('waiter-submit-btn');
    if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = 'שולח...'; }
    try {
        const res = await fetch(`${API}/store/orders`, {
            method: 'POST', headers: {'Content-Type':'application/json'},
            body: JSON.stringify({ groupId: currentGroup.id, customerName: `שולחן ${table}`, customerPhone: '', items, totalAmount: total, isDelivery: false, notes: JSON.stringify(meta), orderSource: 'table' })
        });
        const d = await res.json();
        if (d.success) {
            const bills = getTableBills();
            if (!bills[table]) bills[table] = { openedAt: new Date().toISOString(), submitted: [], pending: [] };
            // Move pending → submitted
            bills[table].submitted = [...(bills[table].submitted||[]), ...cartSnapshot.map(i => ({ ...i, submittedAt: new Date().toISOString(), orderId: d.orderId, delivered: false }))];
            bills[table].pending = []; // clear pending
            saveTableBills(bills);
            window.waiterPOSCart = [];
            showToast('success', `הזמנה לשולחן ${table} נשלחה למטבח ✅`);
            window.waiterRenderCart();
            // Refresh table chips
            const bills2 = getTableBills();
            document.querySelectorAll('.waiter-table-chip').forEach((btn, i) => {
                const tid = i+1;
                const b2 = bills2[tid];
                const subC = b2 ? (b2.submitted||[]).length : 0;
                const penC = b2 ? (b2.pending||[]).length : 0;
                const hasBill2 = subC > 0 || penC > 0;
                const isSel = tid === table;
                btn.className = btn.className.replace(/bg-\w+-\d+ text-\w+-\d+( border border-\w+-\d+)?( shadow)?/g, isSel ? 'bg-amber-500 text-white shadow' : hasBill2 ? 'bg-indigo-100 text-indigo-800 border border-indigo-300' : 'bg-slate-100 text-slate-600 border border-slate-200');
            });
        } else {
            showToast('error', d.error || 'שגיאה בשליחה');
            if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = 'שלח למטבח ✓'; }
        }
    } catch(e) {
        showToast('error', 'שגיאת רשת');
        if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = 'שלח למטבח ✓'; }
    }
};

window.waiterCloseBill = function() {
    const table = window.waiterSelectedTable;
    if (!table) { showToast('info', 'בחר שולחן תחילה'); return; }
    const bills = getTableBills();
    const bill = bills[table];
    if (!bill || (!bill.submitted?.length && !bill.pending?.length)) { showToast('info', 'אין חשבון פתוח לשולחן זה'); return; }
    const allItems = [...(bill.submitted||[]), ...(bill.pending||[])];
    const total = allItems.reduce((s,i) => s + (i.price||0)*(i.qty||1), 0);
    const itemsHtml = allItems.map(i => `
        <div class="flex justify-between items-center py-1.5 border-b border-slate-50 last:border-0">
            <span class="text-sm text-slate-700">${safeStr(i.name||'פריט')} ${(i.qty||1)>1?`×${i.qty}`:''}</span>
            <span class="text-sm font-bold text-slate-800">₪${((i.price||0)*(i.qty||1)).toFixed(0)}</span>
        </div>`).join('');
    document.getElementById('waiter-close-bill-modal')?.remove();
    const html = `<div id="waiter-close-bill-modal" class="fixed inset-0 bg-black/70 z-[9995] flex items-end justify-center" style="direction:rtl;">
        <div class="bg-white w-full max-w-sm rounded-t-[2rem] shadow-2xl p-5 pb-8">
            <div class="flex items-center justify-between mb-4">
                <h3 class="font-black text-slate-800 text-lg">💳 סגירת חשבון</h3>
                <span class="bg-amber-100 text-amber-700 font-black text-sm px-3 py-1 rounded-xl">שולחן ${table}</span>
            </div>
            <div class="bg-slate-50 rounded-xl p-3 mb-4 max-h-40 overflow-y-auto">${itemsHtml}</div>
            <div class="flex justify-between items-center mb-4 px-1">
                <span class="text-slate-500 font-bold">סה"כ לתשלום</span>
                <span class="text-2xl font-black text-indigo-700">₪${total.toFixed(0)}</span>
            </div>
            <div class="mb-4">
                <div class="text-xs font-bold text-slate-500 mb-2">אמצעי תשלום</div>
                <div class="grid grid-cols-3 gap-2">
                    ${['מזומן 💵','כרטיס 💳','אפליקציה 📱'].map((m,i) => `<button type="button"
                        ontouchend="event.preventDefault();document.querySelectorAll('.pay-method-btn').forEach(b=>b.classList.remove('ring-2','ring-indigo-500','bg-indigo-50'));this.classList.add('ring-2','ring-indigo-500','bg-indigo-50');this.dataset.selected='1';"
                        onclick="document.querySelectorAll('.pay-method-btn').forEach(b=>b.classList.remove('ring-2','ring-indigo-500','bg-indigo-50'));this.classList.add('ring-2','ring-indigo-500','bg-indigo-50');this.dataset.selected='1';"
                        class="pay-method-btn border-2 border-slate-200 rounded-xl py-3 text-sm font-bold text-slate-700 active:scale-95 transition" data-method="${m.split(' ')[0]}" style="touch-action:manipulation;">${m}</button>`).join('')}
                </div>
            </div>
            <div class="flex gap-3">
                <button type="button" ontouchend="event.preventDefault();document.getElementById('waiter-close-bill-modal')?.remove();" onclick="document.getElementById('waiter-close-bill-modal')?.remove()" class="flex-1 bg-slate-100 text-slate-600 py-3 rounded-xl font-bold" style="touch-action:manipulation;">ביטול</button>
                <button type="button" ontouchend="event.preventDefault();waiterConfirmCloseBill(${table});" onclick="waiterConfirmCloseBill(${table})" class="flex-1 bg-green-600 text-white py-3 rounded-xl font-black shadow active:scale-95 transition" style="touch-action:manipulation;">אישור תשלום ✅</button>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
};

window.waiterConfirmCloseBill = function(table) {
    const methodBtn = document.querySelector('.pay-method-btn[data-selected="1"]');
    const method = methodBtn?.dataset?.method || 'לא צוין';
    const bills = getTableBills();
    const bill = bills[table];
    if (!bill) return;
    const allItems = [...(bill.submitted||[]), ...(bill.pending||[])];
    const total = allItems.reduce((s,i) => s + (i.price||0)*(i.qty||1), 0);
    // Archive closed bill
    const archiveKey = `closed_bills_${currentGroup.id}`;
    let archive = [];
    try { archive = JSON.parse(localStorage.getItem(archiveKey)||'[]'); } catch(e) {}
    archive.unshift({ table, total, method, items: allItems, closedAt: new Date().toISOString(), waiter: currentUser?.nickname || '' });
    if (archive.length > 200) archive = archive.slice(0, 200);
    localStorage.setItem(archiveKey, JSON.stringify(archive));
    // Clear bill
    delete bills[table];
    saveTableBills(bills);
    const states = getTableStates();
    states[table] = 'free';
    delete states[`_t${table}`];
    localStorage.setItem(`tables_${currentGroup.id}`, JSON.stringify(states));
    _tableLastServerJson = null;
    syncTableStatesToServer(states);
    window.waiterPOSCart = [];
    window.waiterSelectedTable = null;
    document.getElementById('waiter-close-bill-modal')?.remove();
    showToast('success', `שולחן ${table} — ₪${total.toFixed(0)} (${method}) ✅`);
    window.showWaiterPOS();
};

window.addPOSItem = function(id) {
    const p = storeCatalogCache.find(x => x.id === id); if(!p) return;
    if (p.options_text && p.options_text.length > 10) {
        try { 
            const parsed = JSON.parse(p.options_text);
            if (parsed && parsed.isBundle) { window.openPOSBundleModal(p, parsed); return; }
            if (parsed && parsed.isPizza) { window.openPOSPizzaModal(p, parsed); return; }
            if (parsed && parsed.isComplex) { window.openPOSBundleModal(p, parsed); return; }
            if (Array.isArray(parsed)) { window.openPOSModifiersModal(p, parsed); return; }
        } catch(e) {}
    }
    const existing = window.posCart.find(i => i.real_id === p.id && !i.modifiers);
    if(existing) existing.qty++;
    else window.posCart.push({ id: 'pos_' + Date.now(), real_id: p.id, name: p.name, price: parseFloat(p.price), qty: 1, modifiers: null, kitchenStation: p.kitchen_station || 'other' });
    window.renderPOSCart();
};

window.renderPOSCart = function() {
    const list = document.getElementById('pos-cart-list');
    const totalEl = document.getElementById('pos-total-display');
    const countEl = document.getElementById('pos-items-count');
    
    let vatDisplay = document.getElementById('pos-vat-display');
    let promoDisplay = document.getElementById('pos-promo-display');

    if (totalEl) {
        const totalContainer = totalEl.parentNode;
        if(totalContainer) {
            if (!promoDisplay) {
                totalContainer.insertAdjacentHTML('afterend', `<div id="pos-promo-display" class="text-left text-[11px] text-pink-500 font-bold mb-1 hidden">מבצע <span id="pos-promo-name"></span>: -₪<span id="pos-promo-val">0.00</span></div>`);
                promoDisplay = document.getElementById('pos-promo-display');
            }
            if (!vatDisplay) {
                totalContainer.insertAdjacentHTML('afterend', `<div id="pos-vat-display" class="text-left text-[11px] text-indigo-400 font-bold mb-4 hidden">סכום נטו: ₪<span id="pos-net-val">0.00</span> | מע"מ: ₪<span id="pos-vat-val">0.00</span></div>`);
                vatDisplay = document.getElementById('pos-vat-display');
            }
        }
    }

    if(!list) return;
    if(window.posCart.length === 0) {
        list.innerHTML = `<div class="flex flex-col items-center justify-center h-full text-slate-300 py-10 opacity-60"><i class="fa-solid fa-cart-shopping text-5xl mb-4"></i><p class="font-bold text-sm">העגלה ריקה</p></div>`;
        if(totalEl) totalEl.innerText = '₪0.00'; 
        if(countEl) countEl.innerText = '0 פריטים'; 
        if(vatDisplay) vatDisplay.classList.add('hidden');
        if(promoDisplay) promoDisplay.classList.add('hidden');
        return;
    }
    
    let netTotal = 0; let count = 0;
    list.innerHTML = window.posCart.map((item, idx) => {
        const rowTotal = item.price * item.qty; netTotal += rowTotal; count += item.qty;
        const modTxt = item.modifiers ? `<div class="text-[10px] text-slate-500 mt-2 font-medium leading-relaxed">${item.modifiers.map(m => `<span class="bg-indigo-50 text-indigo-700 px-1.5 py-0.5 rounded border border-indigo-100 ml-1 inline-block">+ ${m.name}</span>`).join('')}</div>` : '';
        return `
        <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm mb-3 slide-up text-right relative overflow-hidden">
            <div class="absolute right-0 top-0 bottom-0 w-1 bg-indigo-500 rounded-r-2xl"></div>
            <div class="flex justify-between items-start mb-3 pr-2">
                <div class="flex-1 pr-1 overflow-hidden">
                    <h5 class="font-bold text-slate-800 text-sm leading-tight">${safeStr(item.name)}</h5>
                    ${modTxt}
                </div>
                <div class="text-left">
                    <span class="font-black text-slate-800 text-sm dir-ltr block">₪${rowTotal.toFixed(2)}</span>
                </div>
            </div>
            <div class="flex justify-between items-center bg-slate-50 rounded-xl p-1.5 border border-slate-100 pr-2">
                <button onclick="window.posRemoveItem(${idx})" class="text-slate-400 hover:text-red-500 bg-white w-8 h-8 rounded-lg shadow-sm border border-slate-200 flex items-center justify-center transition"><i class="fa-solid fa-trash-can text-xs"></i></button>
                <div class="flex items-center gap-4 bg-white rounded-lg border border-slate-200 shadow-sm px-1.5">
                    <button onclick="window.updatePOSQty(${idx}, -1)" class="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-indigo-600 transition text-lg font-black">-</button>
                    <span class="font-black text-base w-6 text-center text-slate-800">${item.qty}</span>
                    <button onclick="window.updatePOSQty(${idx}, 1)" class="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-indigo-600 transition text-lg font-black">+</button>
                </div>
            </div>
        </div>`;
    }).join('');
    
    const isDebtPayment = window.posCart.length === 1 && window.posCart[0].real_id === null && window.posCart[0].name.includes('חוב');
    let promo = { amount: 0, text: '' };
    if (!isDebtPayment) {
        promo = window.calcPOSPromotions(netTotal, window.posCart);
    }
    
    const manualDisc = window.currentPOSManualDiscount || 0;
    let grandTotal = netTotal - promo.amount - manualDisc;
    if (grandTotal < 0) grandTotal = 0;
    window.currentPOSDiscount = promo.amount;
    
    if (promoDisplay) {
        if (promo.amount > 0) {
            document.getElementById('pos-promo-name').innerText = promo.text;
            document.getElementById('pos-promo-val').innerText = promo.amount.toFixed(2);
            promoDisplay.classList.remove('hidden');
        } else {
            promoDisplay.classList.add('hidden');
        }
    }

    if(vatDisplay) {
        const vatSettings = window.getVatSettings();
        if(vatSettings && vatSettings.enabled && !isDebtPayment) {
            const rate = vatSettings.rate || 18;
            const totalBeforeVat = grandTotal / (1 + (rate / 100));
            const vatAmount = grandTotal - totalBeforeVat;
            
            const netValEl = document.getElementById('pos-net-val');
            if(netValEl) netValEl.innerText = totalBeforeVat.toFixed(2);
            const vatValEl = document.getElementById('pos-vat-val');
            if(vatValEl) vatValEl.innerText = vatAmount.toFixed(2);
            vatDisplay.classList.remove('hidden');
        } else {
            vatDisplay.classList.add('hidden');
        }
    }
    
    if(totalEl) totalEl.innerText = `₪${grandTotal.toFixed(2)}`;
    if(countEl) countEl.innerText = `${count} פריטים`;
    
    const btnSubmitPos = document.getElementById('btn-submit-pos');
    if (btnSubmitPos) btnSubmitPos.setAttribute('onclick', 'window.handlePosTenderClick()');
};

window.updatePOSQty = (idx, d) => { if(window.posCart[idx]) { window.posCart[idx].qty += d; if(window.posCart[idx].qty <= 0) window.posCart.splice(idx,1); window.renderPOSCart(); } };
window.posRemoveItem = (idx) => { window.posCart.splice(idx,1); window.renderPOSCart(); };
window.clearPOSCart = async () => { if(await window._uiConfirm('לרוקן את הסל?')) { window.posCart = []; window.renderPOSCart(); document.getElementById('pos-customer-phone').value = ''; window.checkPOSCustomer(); } };

window._posNewCustDebounce = null;
window.checkPOSCustomer = function() {
    const raw = document.getElementById('pos-customer-phone').value;
    const phone = raw.replace(/\D/g, '');
    const indicator = document.getElementById('pos-cust-indicator');

    // ביטול טיימר ויזאר קיים
    if (window._posNewCustDebounce) { clearTimeout(window._posNewCustDebounce); window._posNewCustDebounce = null; }

    if (phone.length >= 9 && storeCustomersCache) {
        // חיפוש עם normalize (מסיר תווים שאינם ספרות)
        const c = storeCustomersCache.find(x => (x.phone || '').replace(/\D/g, '') === phone);
        if (c) {
            window.posCurrentCustomer = c;
            if (indicator) {
                const debt = window.getCustomerDebt(c.phone);
                if (debt > 0) {
                    indicator.innerHTML = `<span class="text-red-700 bg-red-50 px-3 py-1.5 rounded-xl border border-red-200 flex items-center gap-1.5 shadow-sm text-xs mt-1"><i class="fa-solid fa-triangle-exclamation"></i> לקוח מזוהה (חוב: ₪${debt.toFixed(2)}): <strong>${safeStr(c.name)}</strong></span>`;
                } else {
                    indicator.innerHTML = `<span class="text-emerald-700 bg-emerald-50 px-3 py-1.5 rounded-xl border border-emerald-200 flex items-center gap-1.5 shadow-sm text-xs mt-1"><i class="fa-solid fa-circle-check"></i> לקוח מזוהה: <strong>${safeStr(c.name)}</strong></span>`;
                }
                indicator.classList.remove('hidden');
            }
            return;
        }
        // לקוח לא נמצא — לאחר 1.2 שניות פתח ויזאר הוספת לקוח חדש
        if (indicator) {
            indicator.innerHTML = `<span class="text-slate-500 bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-200 flex items-center gap-1.5 shadow-sm text-xs mt-1"><i class="fa-solid fa-user-question"></i> מספר לא מוכר — <button onclick="window.openNewMemberFromPOS('${raw}')" class="text-indigo-600 font-bold underline mr-1">הוסף כלקוח חדש</button></span>`;
            indicator.classList.remove('hidden');
        }
        // לא פותח ויזאר אוטומטי — הכפתור בלבד
        window.posCurrentCustomer = null;
        return;
    }
    window.posCurrentCustomer = null;
    if (indicator) indicator.classList.add('hidden');
};

window.openNewMemberFromPOS = function(phone) {
    if (window._posNewCustDebounce) { clearTimeout(window._posNewCustDebounce); window._posNewCustDebounce = null; }
    if (typeof window.fetchStoreCustomers === 'function') window.fetchStoreCustomers();
    if (typeof window.openCustomerModal === 'function') {
        window.openCustomerModal(null, 'details');
        setTimeout(() => {
            const phoneEl = document.getElementById('cust-phone');
            if (phoneEl) phoneEl.value = phone;
            const nameEl = document.getElementById('cust-name');
            if (nameEl) nameEl.focus();
            // הבטח שהמודל מעל מסך קופה מלא
            const modal = document.getElementById('customer-modal');
            if (modal) {
                document.body.appendChild(modal);
                modal.style.zIndex = '99999999';
                modal.classList.remove('hidden');
            }
        }, 200);
    }
};

window.handlePosTenderClick = function() {
    if(window.posCart.length === 0) return showToast('error', 'העגלה ריקה!');
    const isDebtPayment = window.posCart.length === 1 && window.posCart[0].real_id === null && window.posCart[0].name.includes('חוב');
    
    if (window.posCurrentCustomer && !isDebtPayment) {
        const debt = window.getCustomerDebt(window.posCurrentCustomer.phone);
        if (debt > 0) {
            let modal = document.getElementById('pos-debt-alert-modal');
            if(modal) modal.remove();
            const targetNode = document.fullscreenElement || document.body;
            targetNode.insertAdjacentHTML('beforeend', `
                <div id="pos-debt-alert-modal" style="z-index: 999999999 !important;" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4 fade-in">
                    <div class="bg-white w-full max-w-sm rounded-[2rem] p-6 shadow-2xl relative text-center border-2 border-red-100">
                        <div class="w-16 h-16 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-4 text-3xl shadow-inner border border-red-100">
                            <i class="fa-solid fa-triangle-exclamation"></i>
                        </div>
                        <h3 class="text-xl font-black text-slate-800 mb-2">חוב פתוח ללקוח!</h3>
                        <p class="text-sm text-slate-600 mb-6 leading-relaxed">ללקוח <strong>${safeStr(window.posCurrentCustomer.name)}</strong> קיים חוב פתוח על סך <strong class="text-red-600 dir-ltr inline-block">₪${debt.toFixed(2)}</strong>.<br>האם להמשיך בסליקת ההזמנה החדשה?</p>
                        <div class="flex gap-3">
                            <button onclick="document.getElementById('pos-debt-alert-modal').remove()" class="flex-1 bg-slate-100 text-slate-600 py-3 rounded-xl font-bold hover:bg-slate-200 transition text-sm">ביטול סליקה</button>
                            <button onclick="document.getElementById('pos-debt-alert-modal').remove(); window.openPOSTender(true);" class="flex-[1.5] bg-red-500 text-white py-3 rounded-xl font-bold shadow-md hover:bg-red-600 transition text-sm flex items-center justify-center gap-2">המשך סליקה <i class="fa-solid fa-arrow-left"></i></button>
                        </div>
                    </div>
                </div>
            `);
            return;
        }
    }
    window.openPOSTender(true);
};

// ─── Manual Discount & Tip ───────────────────────────────────────────────────
window.currentPOSManualDiscount = 0;

window.openPOSDiscountModal = function() {
    const existing = document.getElementById('pos-discount-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'pos-discount-modal';
    modal.className = 'fixed inset-0 z-[99999] flex items-center justify-center bg-black/60';
    modal.innerHTML = `<div class="bg-white w-80 rounded-3xl p-6 shadow-2xl text-right">
        <h3 class="font-black text-slate-800 text-lg mb-4">🏷️ הנחה ידנית</h3>
        <div class="flex gap-2 mb-3">
            <button onclick="window._setPOSDiscountType('pct')" id="disc-type-pct" class="flex-1 py-2 rounded-xl font-bold text-sm border-2 border-rose-400 bg-rose-50 text-rose-700">אחוז %</button>
            <button onclick="window._setPOSDiscountType('fixed')" id="disc-type-fixed" class="flex-1 py-2 rounded-xl font-bold text-sm border-2 border-slate-200 bg-white text-slate-600">סכום ₪</button>
        </div>
        <input type="number" id="pos-discount-input" min="0" placeholder="0" class="w-full text-center bg-slate-100 rounded-2xl py-4 text-2xl font-black text-slate-800 border-none outline-none focus:ring-4 focus:ring-rose-100 dir-ltr mb-4">
        <div class="flex gap-2">
            <button onclick="document.getElementById('pos-discount-modal').remove()" class="flex-1 bg-slate-100 text-slate-600 py-3 rounded-xl font-bold text-sm">ביטול</button>
            <button onclick="window.applyPOSManualDiscount()" class="flex-[2] bg-rose-500 text-white py-3 rounded-xl font-bold text-sm shadow-md">החל הנחה</button>
        </div>
    </div>`;
    document.body.appendChild(modal);
    modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
    window._posDiscountType = 'pct';
    document.getElementById('pos-discount-input').focus();
};

window._setPOSDiscountType = function(type) {
    window._posDiscountType = type;
    document.getElementById('disc-type-pct').className = `flex-1 py-2 rounded-xl font-bold text-sm border-2 ${type==='pct'?'border-rose-400 bg-rose-50 text-rose-700':'border-slate-200 bg-white text-slate-600'}`;
    document.getElementById('disc-type-fixed').className = `flex-1 py-2 rounded-xl font-bold text-sm border-2 ${type==='fixed'?'border-rose-400 bg-rose-50 text-rose-700':'border-slate-200 bg-white text-slate-600'}`;
};

window.applyPOSManualDiscount = function() {
    const val = parseFloat(document.getElementById('pos-discount-input')?.value) || 0;
    if (!val) { document.getElementById('pos-discount-modal')?.remove(); return; }
    let netTotal = 0; window.posCart.forEach(i => netTotal += (i.price * i.qty));
    const promo = window.currentPOSDiscount || 0;
    const baseTotal = netTotal - promo;
    let discountAmount = 0;
    if (window._posDiscountType === 'pct') { discountAmount = Math.min(baseTotal, baseTotal * (val / 100)); }
    else { discountAmount = Math.min(baseTotal, val); }
    window.currentPOSManualDiscount = discountAmount;
    document.getElementById('pos-discount-modal')?.remove();
    const row = document.getElementById('pos-manual-discount-row');
    const disp = document.getElementById('pos-manual-discount-display');
    if (row && disp) {
        row.classList.remove('hidden');
        disp.textContent = `₪${discountAmount.toFixed(2)}`;
    }
    // update cart total display
    const totalEl = document.getElementById('pos-total-display');
    if (totalEl) {
        const newTotal = Math.max(0, netTotal - promo - discountAmount);
        totalEl.textContent = `₪${newTotal.toFixed(2)}`;
    }
    showToast('success', `הנחה של ₪${discountAmount.toFixed(2)} הוגדרה`);
};

window.clearPOSManualDiscount = function() {
    window.currentPOSManualDiscount = 0;
    const row = document.getElementById('pos-manual-discount-row');
    if (row) row.classList.add('hidden');
    window.renderPOSCart();
};

window.currentTipAmount = 0;

window.setTenderTip = function(pct) {
    const baseEl = document.getElementById('tender-total-due');
    const base = parseFloat(baseEl?.textContent?.replace(/[₪,]/g,'')) || 0;
    const tip = pct > 0 ? Math.round(base * pct / 100 * 100) / 100 : 0;
    window.currentTipAmount = tip;
    const inputEl = document.getElementById('tender-tip-amount');
    if (inputEl) inputEl.value = tip > 0 ? tip.toFixed(2) : '';
    window.updateTenderTip();
};

window.updateTenderTip = function() {
    const val = parseFloat(document.getElementById('tender-tip-amount')?.value) || 0;
    window.currentTipAmount = val;
};

window.openPOSTender = function(skipCheck = false) {
    window.posSplitPayments = []; window.tenderMethod = 'cash';
    window.currentTipAmount = 0;
    window.posItemSplitParts = []; window.posItemSplitAssignments = {};
    const splitEl = document.getElementById('tender-item-split-summary');
    if (splitEl) splitEl.remove();
    const tipInput = document.getElementById('tender-tip-amount');
    if (tipInput) tipInput.value = '';
    let netTotal = 0; window.posCart.forEach(i => netTotal += (i.price * i.qty));
    const isDebtPayment = window.posCart.length === 1 && window.posCart[0].real_id === null && window.posCart[0].name.includes('חוב');
    
    let promoAmount = (window.currentPOSDiscount || 0) + (window.currentPOSManualDiscount || 0);
    let grandTotal = netTotal - promoAmount;
    if (grandTotal < 0) grandTotal = 0;

    // show tip row for restaurant/cafe
    const tipRow = document.getElementById('tender-tip-row');
    if (tipRow) {
        const isRest = ['restaurant','cafe'].includes(currentGroup?.business_type);
        tipRow.classList.toggle('hidden', !isRest || isDebtPayment);
    }

    let tenderVatDisplay = document.getElementById('tender-vat-display');
    if (!tenderVatDisplay) {
        const tenderDueEl = document.getElementById('tender-total-due');
        if (tenderDueEl && tenderDueEl.parentNode) {
            tenderDueEl.parentNode.classList.add('relative');
            tenderDueEl.parentNode.insertAdjacentHTML('beforeend', `<div id="tender-vat-display" class="absolute bottom-2 left-0 right-0 text-[10px] text-indigo-400 font-bold hidden">סכום נטו: ₪<span id="tender-net-val">0.00</span> | מע"מ: ₪<span id="tender-vat-val">0.00</span></div>`);
            tenderVatDisplay = document.getElementById('tender-vat-display');
        }
    }

    if (tenderVatDisplay) {
        const vatSettings = window.getVatSettings();
        if (vatSettings && vatSettings.enabled && !isDebtPayment) {
            const rate = vatSettings.rate || 18;
            const totalBeforeVat = grandTotal / (1 + (rate / 100));
            const vatAmount = grandTotal - totalBeforeVat;
            
            const tNetVal = document.getElementById('tender-net-val');
            if(tNetVal) tNetVal.innerText = totalBeforeVat.toFixed(2);
            const tVatVal = document.getElementById('tender-vat-val');
            if(tVatVal) tVatVal.innerText = vatAmount.toFixed(2);
            tenderVatDisplay.classList.remove('hidden');
        } else {
            tenderVatDisplay.classList.add('hidden');
        }
    }
    
    document.getElementById('tender-total-due').innerText = `₪${grandTotal.toFixed(2)}`;
    document.getElementById('tender-input-amount').value = grandTotal.toFixed(2);

    const modal = document.getElementById('pos-tender-modal');
    if (modal) {
        const targetNode = document.fullscreenElement || document.body;
        if (modal.parentNode !== targetNode) {
            targetNode.appendChild(modal);
        }
        modal.style.position = 'fixed';
        modal.style.zIndex = '999999999';
        modal.classList.remove('hidden');
    }
    window.setTenderMethod('cash'); window.updateTenderDisplay();
};

window.setTenderMethod = function(m) {
    if (m === 'on_account' && !window.posCurrentCustomer) {
        showToast('error', 'חובה להזין טלפון ולזהות לקוח כדי לרשום הקפה!');
        document.getElementById('pos-customer-phone').focus();
        return;
    }
    window.tenderMethod = m;
    const tenderBtnIds = ['btn-tender-cash','btn-tender-credit','btn-tender-bit','btn-tender-paybox','btn-tender-account'];
    tenderBtnIds.forEach(id => {
        const b = document.getElementById(id);
        if(b) { b.classList.remove('border-indigo-600', 'bg-indigo-50/50'); }
    });
    const methodBtnMap = { cash:'btn-tender-cash', credit:'btn-tender-credit', bit:'btn-tender-bit', paybox:'btn-tender-paybox', on_account:'btn-tender-account' };
    const activeBtn = document.getElementById(methodBtnMap[m]);
    if(activeBtn) activeBtn.classList.add('border-indigo-600', 'bg-indigo-50/50');
};

window.addTenderShortcut = (a) => document.getElementById('tender-input-amount').value = a;

// ===== פיצול חשבון לפי מנות =====
window.posItemSplitAssignments = {};
window.posItemSplitCount = 2;
window.posItemSplitParts = [];

const _SPLIT_COLORS = [
    { light: 'bg-indigo-50', border: 'border-indigo-300', text: 'text-indigo-700', badge: 'bg-indigo-500 text-white' },
    { light: 'bg-emerald-50', border: 'border-emerald-300', text: 'text-emerald-700', badge: 'bg-emerald-500 text-white' },
    { light: 'bg-amber-50', border: 'border-amber-300', text: 'text-amber-700', badge: 'bg-amber-500 text-white' },
    { light: 'bg-rose-50', border: 'border-rose-300', text: 'text-rose-700', badge: 'bg-rose-500 text-white' },
    { light: 'bg-purple-50', border: 'border-purple-300', text: 'text-purple-700', badge: 'bg-purple-500 text-white' },
    { light: 'bg-teal-50', border: 'border-teal-300', text: 'text-teal-700', badge: 'bg-teal-500 text-white' },
];
const _SPLIT_LABELS = ['חלק א', 'חלק ב', 'חלק ג', 'חלק ד', 'חלק ה', 'חלק ו'];

window._renderSplitItemsList = function() {
    return window.posCart.map(item => {
        const assigned = window.posItemSplitAssignments[item.id];
        const itemTotal = (item.price * item.qty).toFixed(2);
        const modStr = item.modifiers ? item.modifiers.map(m => m.name).join(', ') : '';
        const c = assigned ? _SPLIT_COLORS[assigned - 1] : null;
        const rowBg = c ? `${c.light} ${c.border}` : 'bg-slate-50 border-slate-200';
        const partBtns = Array.from({ length: window.posItemSplitCount }, (_, i) => {
            const bc = _SPLIT_COLORS[i];
            const isActive = assigned === (i + 1);
            return `<button onclick="window._itemSplitAssign('${item.id}',${i+1})" class="w-8 h-8 rounded-full font-black text-xs transition border-2 ${isActive ? bc.badge+' border-transparent' : 'bg-white border-slate-200 text-slate-500'}">${i+1}</button>`;
        }).join('');
        return `<div class="flex items-center gap-3 p-3 rounded-2xl border-2 ${rowBg} transition">
            <div class="flex-1 min-w-0">
                <div class="font-black text-slate-800 text-sm truncate">${safeStr(item.name)}</div>
                ${modStr ? `<div class="text-[10px] text-slate-400 truncate">${safeStr(modStr)}</div>` : ''}
                <div class="text-[11px] font-bold text-slate-500 mt-0.5">×${item.qty} · ₪${itemTotal}</div>
            </div>
            <div class="flex gap-1.5 shrink-0">${partBtns}</div>
        </div>`;
    }).join('');
};

window._renderSplitTotals = function() {
    const parts = {};
    for (let i = 1; i <= window.posItemSplitCount; i++) parts[i] = 0;
    window.posCart.forEach(item => {
        const p = window.posItemSplitAssignments[item.id];
        if (p) parts[p] += item.price * item.qty;
    });
    const unassigned = window.posCart.reduce((s, item) => !window.posItemSplitAssignments[item.id] ? s + item.price * item.qty : s, 0);
    return Object.entries(parts).map(([p, total]) => {
        const c = _SPLIT_COLORS[p - 1];
        return `<div class="flex justify-between text-xs font-bold ${c.text}"><span>${_SPLIT_LABELS[p-1]}:</span><span class="dir-ltr">₪${total.toFixed(2)}</span></div>`;
    }).join('') + (unassigned > 0.005 ? `<div class="flex justify-between text-xs font-bold text-slate-400 border-t border-slate-100 pt-1.5 mt-1"><span>לא שויך:</span><span class="dir-ltr">₪${unassigned.toFixed(2)}</span></div>` : '');
};

window._itemSplitRender = function() {
    const list = document.getElementById('split-items-list');
    if (list) list.innerHTML = window._renderSplitItemsList();
    const totals = document.getElementById('split-parts-totals');
    if (totals) totals.innerHTML = window._renderSplitTotals();
};

window._itemSplitAssign = function(itemId, partNum) {
    window.posItemSplitAssignments[itemId] = partNum;
    window._itemSplitRender();
};

window._itemSplitSetParts = function(n) {
    n = Math.max(2, Math.min(6, n));
    window.posItemSplitCount = n;
    Object.keys(window.posItemSplitAssignments).forEach(k => { if (window.posItemSplitAssignments[k] > n) delete window.posItemSplitAssignments[k]; });
    const countEl = document.getElementById('split-parts-count');
    if (countEl) countEl.textContent = n;
    window._itemSplitRender();
};

window.openItemSplitModal = function() {
    if (!window.posCart || window.posCart.length === 0) { showToast('error', 'העגלה ריקה!'); return; }
    window.posItemSplitAssignments = {};
    window.posItemSplitCount = 2;
    let old = document.getElementById('pos-item-split-modal');
    if (old) old.remove();
    const html = `<div id="pos-item-split-modal" style="z-index:9999999999 !important;" class="fixed inset-0 bg-slate-900/85 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4 fade-in">
        <div class="bg-white w-full max-w-lg rounded-t-[2rem] sm:rounded-[2rem] shadow-2xl flex flex-col max-h-[92vh]">
            <div class="p-5 border-b border-slate-100 flex justify-between items-center shrink-0">
                <div><h3 class="text-lg font-black text-slate-800">✂️ פיצול לפי מנות</h3><p class="text-[11px] text-slate-400 font-bold mt-0.5">בחר אילו מנות שייכות לכל חלק</p></div>
                <button onclick="document.getElementById('pos-item-split-modal').remove()" class="w-9 h-9 bg-slate-100 rounded-full text-slate-500 hover:bg-slate-200 flex items-center justify-center transition"><i class="fa-solid fa-xmark"></i></button>
            </div>
            <div class="px-5 py-3 border-b border-slate-100 shrink-0 flex items-center justify-between">
                <span class="text-xs font-black text-slate-600">מספר חלקים:</span>
                <div class="flex items-center gap-3">
                    <button onclick="window._itemSplitSetParts(window.posItemSplitCount-1)" class="w-8 h-8 rounded-full bg-slate-100 font-bold text-slate-700 hover:bg-slate-200 flex items-center justify-center text-lg">−</button>
                    <span id="split-parts-count" class="text-xl font-black text-indigo-700 min-w-[24px] text-center">2</span>
                    <button onclick="window._itemSplitSetParts(window.posItemSplitCount+1)" class="w-8 h-8 rounded-full bg-slate-100 font-bold text-slate-700 hover:bg-slate-200 flex items-center justify-center text-lg">+</button>
                </div>
            </div>
            <div class="flex-1 overflow-y-auto modal-scroll p-5 space-y-2" id="split-items-list">${window._renderSplitItemsList()}</div>
            <div id="split-parts-totals" class="px-5 py-3 border-t border-slate-100 shrink-0 space-y-1.5">${window._renderSplitTotals()}</div>
            <div class="p-5 border-t border-slate-100 shrink-0">
                <button onclick="window.confirmItemSplit()" class="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-base shadow-lg hover:bg-indigo-700 transition">אשר פיצול <i class="fa-solid fa-check mr-1"></i></button>
            </div>
        </div>
    </div>`;
    (document.fullscreenElement || document.body).insertAdjacentHTML('beforeend', html);
};

window.confirmItemSplit = async function() {
    const unassigned = window.posCart.filter(item => !window.posItemSplitAssignments[item.id]);
    if (unassigned.length > 0) {
        if (!await window._uiConfirm(`${unassigned.length} מנות לא שויכו. הן יתווספו לחלק א. להמשיך?`)) return;
        unassigned.forEach(item => { window.posItemSplitAssignments[item.id] = 1; });
    }
    const parts = {};
    for (let i = 1; i <= window.posItemSplitCount; i++) parts[i] = { partNum: i, total: 0 };
    window.posCart.forEach(item => {
        const p = window.posItemSplitAssignments[item.id] || 1;
        parts[p].total += item.price * item.qty;
    });
    window.posItemSplitParts = Object.values(parts).filter(p => p.total > 0.005);
    const modal = document.getElementById('pos-item-split-modal');
    if (modal) modal.remove();
    window._showItemSplitInTender();
    showToast('success', `פיצול נוצר — ${window.posItemSplitParts.length} חלקים`);
};

window._showItemSplitInTender = function() {
    let el = document.getElementById('tender-item-split-summary');
    if (!el) {
        const listEl = document.getElementById('tender-payments-list');
        if (!listEl) return;
        listEl.parentNode.insertAdjacentHTML('afterbegin', `<div id="tender-item-split-summary" class="mb-3"></div>`);
        el = document.getElementById('tender-item-split-summary');
    }
    el.innerHTML = `<h4 class="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">פיצול לפי מנות:</h4>
        ${window.posItemSplitParts.map(part => {
            const c = _SPLIT_COLORS[part.partNum - 1];
            return `<div class="flex items-center justify-between p-2.5 rounded-xl border mb-1.5 ${c.light} ${c.border} ${c.text}">
                <span class="text-xs font-black">${_SPLIT_LABELS[part.partNum - 1]}:</span>
                <div class="flex items-center gap-2">
                    <span class="text-xs font-black dir-ltr">₪${part.total.toFixed(2)}</span>
                    <button onclick="window._fillSplitPartAmount(${part.total})" class="text-[9px] font-black bg-white border ${c.border} px-2 py-1 rounded-lg hover:opacity-75 transition">הכנס ▶</button>
                </div>
            </div>`;
        }).join('')}
        <button onclick="window._clearItemSplit()" class="text-[9px] text-slate-400 hover:text-slate-600 transition underline">ביטול פיצול</button>
        <div class="border-t border-slate-200 mt-2 mb-1"></div>`;
};

window._fillSplitPartAmount = function(amount) {
    const input = document.getElementById('tender-input-amount');
    if (input) { input.value = amount.toFixed(2); input.focus(); }
};

window._clearItemSplit = function() {
    window.posItemSplitParts = [];
    window.posItemSplitAssignments = {};
    const el = document.getElementById('tender-item-split-summary');
    if (el) el.remove();
};

window.applyFullDiscount = async function() {
    if (!await window._uiConfirm('לאשר שי / ביטול חיוב מלא?')) return;
    // מסמן את כל ההזמנה כ"שי" — מוסיף תשלום בסכום המלא עם שיטה gift
    let netTotal = 0; window.posCart.forEach(i => netTotal += (i.price * i.qty));
    const promoAmount = (window.currentPOSDiscount || 0) + (window.currentPOSManualDiscount || 0);
    const grandTotal = Math.max(0, netTotal - promoAmount);
    window.posSplitPayments = [{ method: 'gift', name: 'שי / חינם', amount: grandTotal }];
    window.updateTenderDisplay();
    const giftBtn = document.getElementById('btn-tender-gift');
    if (giftBtn) { giftBtn.classList.add('border-pink-500','bg-pink-50/50'); }
    showToast('success', 'הוגדר כשי — ניתן לסיים העסקה');
};

window.addPaymentToSplit = function() {
    const amt = parseFloat(document.getElementById('tender-input-amount').value) || 0; if(amt <= 0) return;
    const names = { 'cash': 'מזומן', 'credit': 'כרטיס אשראי', 'bit': 'ביט', 'paybox': 'פייבוקס', 'on_account': 'הקפה', 'gift': 'שי / חינם' };
    window.posSplitPayments.push({ method: window.tenderMethod, name: names[window.tenderMethod] || window.tenderMethod, amount: amt });
    window.updateTenderDisplay();
};

window.updateTenderDisplay = function() {
    const list = document.getElementById('tender-payments-list');
    let netTotal = 0; window.posCart.forEach(i => netTotal += (i.price * i.qty));
    let promoAmount = (window.currentPOSDiscount || 0) + (window.currentPOSManualDiscount || 0);
    const tipAmt = parseFloat(document.getElementById('tender-tip-amount')?.value) || window.currentTipAmount || 0;
    let grandTotal = netTotal - promoAmount + tipAmt;
    if (grandTotal < 0) grandTotal = 0;
    
    let paid = 0; window.posSplitPayments.forEach(p => paid += p.amount);
    
    list.innerHTML = window.posSplitPayments.map((p, i) => `<div class="flex justify-between items-center bg-white p-3 rounded-xl border border-slate-200 text-sm shadow-sm mb-2"><span class="font-bold text-slate-700">${p.name}</span><div class="flex items-center gap-3"><strong class="text-base text-slate-800">₪${p.amount.toFixed(2)}</strong><button onclick="window.posSplitPayments.splice(${i},1); window.updateTenderDisplay();" class="text-red-400 hover:text-red-600 bg-red-50 w-7 h-7 rounded flex items-center justify-center transition"><i class="fa-solid fa-times"></i></button></div></div>`).join('');
    
    const balance = grandTotal - paid;
    const btn = document.getElementById('btn-finalize-pos');
    if (balance <= 0.01) {
        document.getElementById('tender-balance-label').innerText = "עודף להחזרה:"; document.getElementById('tender-balance-val').innerText = `₪${Math.abs(balance).toFixed(2)}`;
        btn.disabled = false; btn.classList.replace('bg-slate-300', 'bg-emerald-500'); btn.classList.remove('cursor-not-allowed', 'opacity-50');
    } else {
        document.getElementById('tender-balance-label').innerText = "יתרה לתשלום:"; document.getElementById('tender-balance-val').innerText = `₪${balance.toFixed(2)}`;
        document.getElementById('tender-input-amount').value = balance.toFixed(2);
        btn.disabled = true; btn.classList.replace('bg-emerald-500', 'bg-slate-300'); btn.classList.add('cursor-not-allowed', 'opacity-50');
    }
};

window.openPOSModifiersModal = function(p, mods) {
    window.currentPOSProduct = p; window.currentPOSModifiers = mods;
    let modal = document.getElementById('pos-modifiers-modal');
    if (modal) modal.remove();
    let html = `
    <div id="pos-modifiers-modal" style="z-index: 999999999 !important;" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4 fade-in">
        <div class="bg-white w-full max-w-md rounded-[2rem] p-6 shadow-2xl relative flex flex-col max-h-[90vh]">
            <div class="border-b border-slate-100 pb-3 mb-4 flex justify-between items-center shrink-0">
                <h3 class="text-xl font-black text-slate-800"><i class="fa-solid fa-list-ul text-indigo-500 mr-2"></i> ${safeStr(p.name)}</h3>
                <button onclick="document.getElementById('pos-modifiers-modal').remove()" class="w-8 h-8 bg-slate-100 rounded-full text-slate-500 hover:bg-slate-200"><i class="fa-solid fa-xmark"></i></button>
            </div>
            <div class="flex-1 overflow-y-auto modal-scroll pr-1 space-y-3 pb-4">
                ${mods.map((g, gi) => `
                    <div class="bg-slate-50 p-4 rounded-2xl border border-slate-200 shadow-sm">
                        <div class="flex justify-between items-center mb-4 border-b border-slate-200 pb-2">
                            <h4 class="font-black text-slate-800 text-base">${safeStr(g.name)}</h4>
                            <span class="text-[10px] font-bold text-indigo-500 bg-indigo-50 px-2 py-1 rounded-md shadow-sm">${g.type==='multiple' ? 'בחירה חופשית' : 'חובה (1)'}</span>
                        </div>
                        <div class="space-y-2">
                            ${g.options.map((o, oi) => `
                                <label class="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-xl cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition group shadow-sm">
                                    <div class="flex items-center gap-3">
                                        <input type="${g.type==='multiple'?'checkbox':'radio'}" name="mod_g_${gi}" value="${oi}" class="w-4 h-4 accent-indigo-600" ${!g.type==='multiple' && oi===0 ? 'checked' : ''}>
                                        <span class="text-xs font-bold text-slate-700 group-hover:text-indigo-800">${safeStr(o.name)}</span>
                                    </div>
                                    ${o.price>0?`<span class="text-[10px] font-black text-indigo-600 bg-indigo-50 px-2 py-1 rounded-lg border border-indigo-100 shadow-sm dir-ltr">+₪${o.price}</span>`:''}
                                </label>
                            `).join('')}
                        </div>
                    </div>
                `).join('')}
            </div>
            <div class="pt-3 border-t border-slate-100 shrink-0">
                <button onclick="window.submitPOSModifiers()" class="w-full bg-indigo-600 text-white py-3.5 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition">הוסף לעגלה</button>
            </div>
        </div>
    </div>`;
    const targetNode = document.fullscreenElement || document.body;
    targetNode.insertAdjacentHTML('beforeend', html);
};

window.submitPOSModifiers = function() {
    let finalPrice = parseFloat(window.currentPOSProduct.price);
    let selected = [];
    window.currentPOSModifiers.forEach((g, gi) => {
        const checked = document.querySelectorAll(`input[name="mod_g_${gi}"]:checked`);
        checked.forEach(inp => { const o = g.options[parseInt(inp.value)]; finalPrice += parseFloat(o.price); selected.push(o); });
    });
    const modal = document.getElementById('pos-modifiers-modal');
    if (window._waiterPOSMode) {
        window._waiterPOSMode = false;
        const p = window.currentPOSProduct;
        const modStr = selected.length ? ` (${selected.map(s=>s.name).join(', ')})` : '';
        window.waiterPOSCart.push({ id: p.id, name: p.name + modStr, price: finalPrice, qty: 1, kitchenStation: p.kitchen_station||'other', note: '', modifiers: selected });
        if(modal) modal.remove();
        window.waiterRenderCart(); return;
    }
    if (window.kioskModeCapture) {
        window.kioskModeCapture = false;
        if(modal) modal.remove();
        const p = window.currentPOSProduct;
        kioskCart.push({ id: p.id + '_' + Date.now(), name: p.name, price: finalPrice, qty: 1, modifiers: selected });
        kioskUpdateCartBar(); kioskRenderGrid(); return;
    }
    window.posCart.push({ id: 'pos_' + Date.now(), real_id: window.currentPOSProduct.id, name: window.currentPOSProduct.name, price: finalPrice, qty: 1, modifiers: selected });
    if(modal) modal.remove();
    window.renderPOSCart();
};

window.openPOSPizzaModal = function(p, pizzaData) {
    window.currentPOSProduct = p;
    const toppings = pizzaData.toppings || [];
    window.posPizzaState = {};
    window.posActivePizzaTopping = toppings.length > 0 ? toppings[0].name : null;
    window.posPizzaToppings = toppings;
    toppings.forEach(t => window.posPizzaState[t.name] = [0, 0, 0, 0]);

    let modal = document.getElementById('pos-pizza-modal');
    if (modal) modal.remove();
    let html = `
    <div id="pos-pizza-modal" style="z-index: 999999999 !important;" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4 fade-in">
        <div class="bg-white w-full max-w-md rounded-[2rem] p-6 shadow-2xl relative flex flex-col max-h-[90vh]">
            <div class="border-b border-slate-100 pb-3 mb-4 flex justify-between items-center shrink-0">
                <h3 class="text-xl font-black text-slate-800"><i class="fa-solid fa-pizza-slice text-orange-500 mr-2"></i> הרכבת ${safeStr(p.name)}</h3>
                <button onclick="document.getElementById('pos-pizza-modal').remove()" class="w-8 h-8 bg-slate-100 rounded-full text-slate-500 hover:bg-slate-200 transition"><i class="fa-solid fa-xmark"></i></button>
            </div>
            <div class="flex-1 overflow-y-auto modal-scroll pr-1 pb-4">
                <div id="pos-pizza-builder-wrapper"></div>
            </div>
            <div class="pt-3 border-t border-slate-100 shrink-0">
                <button onclick="window.submitPOSPizza()" class="w-full bg-orange-500 text-white py-3.5 rounded-xl font-bold shadow-lg hover:bg-orange-600 transition">הוסף פיצה להזמנה</button>
            </div>
        </div>
    </div>`;
    const targetNode = document.fullscreenElement || document.body;
    targetNode.insertAdjacentHTML('beforeend', html);
    window.renderPosPizzaBuilderUI();
};

window.renderPosPizzaBuilderUI = function() {
    const wrapper = document.getElementById('pos-pizza-builder-wrapper');
    if (!wrapper) return;
    const toppings = window.posPizzaToppings || [];
    const pizzaState = window.posPizzaState || {};
    const active = window.posActivePizzaTopping;

    const getFill = (q) => {
        if (!active || !pizzaState[active]) return 'transparent';
        const v = pizzaState[active][q];
        return v === 2 ? '#ef4444' : v === 1 ? '#fca5a5' : 'transparent';
    };
    const getX2 = (q, x, y) => {
        if (!active || !pizzaState[active] || pizzaState[active][q] !== 2) return '';
        return `<text x="${x}" y="${y}" font-size="10" font-weight="900" fill="#ffffff" class="pointer-events-none" text-anchor="middle">X2</text>`;
    };

    const toppingsHtml = toppings.map(t => `
        <button type="button" class="px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap shadow-sm transition border ${t.name === active ? 'bg-red-600 text-white border-red-700' : 'bg-white text-slate-700 border-slate-200 hover:bg-red-50'}" onclick="window.selectPosPizzaTopping('${safeStr(t.name).replace(/'/g,"\\'")}')">
            ${safeStr(t.name)} (+₪${t.price})
        </button>
    `).join('');

    let summaryArr = [];
    toppings.forEach(t => {
        const total = (pizzaState[t.name] || [0,0,0,0]).reduce((s,v) => s + Number(v||0), 0);
        if (total > 0) {
            let q1=[], q2=[];
            pizzaState[t.name].forEach((v,i) => { if(v===1) q1.push(i+1); if(v===2) q2.push(i+1); });
            let parts = [];
            if (q1.length) parts.push(q1.length===4 ? 'מגש שלם' : `רבעים ${q1.join(', ')}`);
            if (q2.length) parts.push(q2.length===4 ? 'כפול על הכל' : `כפול רבעים ${q2.join(', ')}`);
            summaryArr.push(`<span class="bg-red-100 text-red-700 px-2 py-1 rounded-md text-[10px] font-bold m-1 inline-block">${safeStr(t.name)} - ${parts.join(' | ')}</span>`);
        }
    });
    const summaryHtml = summaryArr.length > 0 ? summaryArr.join('') : '<p class="text-[10px] text-slate-400">פיצה חלקה (ללא תוספות)</p>';

    wrapper.innerHTML = `
    <div class="bg-red-50/50 rounded-2xl p-4 border border-red-100 shadow-sm fade-in">
        <h4 class="font-bold text-red-900 text-center mb-1 text-sm"><i class="fa-solid fa-pizza-slice text-red-500 mr-1"></i> הרכבת מגש פיצה</h4>
        <p class="text-[10px] text-red-600 text-center mb-4">בחרו תוספת מהסרגל, ולחצו על חלקי הפיצה.<br><span class="font-bold">לחיצה כפולה = כמות כפולה (X2).</span></p>
        <div class="flex overflow-x-auto gap-2 mb-5 pb-2" style="scrollbar-width:none;">${toppingsHtml}</div>
        <div class="relative w-52 h-52 mx-auto mb-5">
            <svg viewBox="0 0 100 100" class="w-full h-full drop-shadow-lg">
                <circle cx="50" cy="50" r="48" fill="#fef08a" stroke="#f59e0b" stroke-width="2"/>
                <path d="M 50 50 L 50 2 A 48 48 0 0 1 98 50 Z" fill="${getFill(0)}" class="cursor-pointer transition" style="transition:fill .15s" onclick="window.togglePosPizzaSlice(0)" />
                <path d="M 50 50 L 98 50 A 48 48 0 0 1 50 98 Z" fill="${getFill(1)}" class="cursor-pointer transition" style="transition:fill .15s" onclick="window.togglePosPizzaSlice(1)" />
                <path d="M 50 50 L 50 98 A 48 48 0 0 1 2 50 Z" fill="${getFill(2)}" class="cursor-pointer transition" style="transition:fill .15s" onclick="window.togglePosPizzaSlice(2)" />
                <path d="M 50 50 L 2 50 A 48 48 0 0 1 50 2 Z" fill="${getFill(3)}" class="cursor-pointer transition" style="transition:fill .15s" onclick="window.togglePosPizzaSlice(3)" />
                <line x1="50" y1="2" x2="50" y2="98" stroke="#f59e0b" stroke-width="2" class="pointer-events-none"/>
                <line x1="2" y1="50" x2="98" y2="50" stroke="#f59e0b" stroke-width="2" class="pointer-events-none"/>
                <text x="75" y="25" font-size="14" font-weight="900" fill="#b45309" class="pointer-events-none" text-anchor="middle" dominant-baseline="middle">1</text>
                <text x="75" y="75" font-size="14" font-weight="900" fill="#b45309" class="pointer-events-none" text-anchor="middle" dominant-baseline="middle">2</text>
                <text x="25" y="75" font-size="14" font-weight="900" fill="#b45309" class="pointer-events-none" text-anchor="middle" dominant-baseline="middle">3</text>
                <text x="25" y="25" font-size="14" font-weight="900" fill="#b45309" class="pointer-events-none" text-anchor="middle" dominant-baseline="middle">4</text>
                ${getX2(0,75,40)}${getX2(1,75,90)}${getX2(2,25,90)}${getX2(3,25,40)}
            </svg>
            <div class="absolute inset-0 pointer-events-none flex items-center justify-center">
                <div class="bg-white/90 backdrop-blur-md px-3 py-1 rounded-full text-red-900 text-[11px] font-black shadow-md border border-red-200">
                    ${active ? 'פעיל: ' + safeStr(active) : 'בחרו תוספת'}
                </div>
            </div>
        </div>
        <div class="flex gap-2 justify-center mb-4 flex-wrap">
            <button type="button" onclick="window.fillPosPizza('whole')" class="bg-white border border-red-200 text-red-700 text-[10px] font-bold px-3 py-1.5 rounded-lg shadow-sm hover:bg-red-50 transition">מגש שלם</button>
            <button type="button" onclick="window.fillPosPizza('right')" class="bg-white border border-red-200 text-red-700 text-[10px] font-bold px-3 py-1.5 rounded-lg shadow-sm hover:bg-red-50 transition">חצי ימין (1+2)</button>
            <button type="button" onclick="window.fillPosPizza('left')" class="bg-white border border-red-200 text-red-700 text-[10px] font-bold px-3 py-1.5 rounded-lg shadow-sm hover:bg-red-50 transition">חצי שמאל (3+4)</button>
            <button type="button" onclick="window.fillPosPizza('clear')" class="bg-white border border-slate-200 text-slate-500 text-[10px] font-bold px-3 py-1.5 rounded-lg shadow-sm hover:bg-slate-50 transition">נקה הכל</button>
        </div>
        <div class="bg-white p-3 rounded-xl border border-red-100 min-h-[44px]">
            <p class="text-[9px] font-bold text-slate-400 mb-1">סיכום למטבח:</p>
            ${summaryHtml}
        </div>
    </div>`;
};

window.selectPosPizzaTopping = function(name) {
    window.posActivePizzaTopping = name;
    window.renderPosPizzaBuilderUI();
};

window.togglePosPizzaSlice = function(qIdx) {
    if (!window.posActivePizzaTopping) return;
    const s = window.posPizzaState[window.posActivePizzaTopping];
    const v = Number(s[qIdx] || 0);
    s[qIdx] = v === 0 ? 1 : v === 1 ? 2 : 0;
    window.renderPosPizzaBuilderUI();
};

window.fillPosPizza = function(action) {
    const a = window.posActivePizzaTopping;
    const s = window.posPizzaState;
    if (action === 'clear') {
        (window.posPizzaToppings || []).forEach(t => s[t.name] = [0,0,0,0]);
    } else if (!a) {
        return;
    } else if (action === 'whole') {
        s[a] = [1,1,1,1];
    } else if (action === 'right') {
        s[a][0] = 1; s[a][1] = 1;
    } else if (action === 'left') {
        s[a][2] = 1; s[a][3] = 1;
    }
    window.renderPosPizzaBuilderUI();
};

window.submitPOSPizza = function() {
    let finalPrice = parseFloat(window.currentPOSProduct.price);
    let selected = [];
    const toppings = window.posPizzaToppings || [];
    const pizzaState = window.posPizzaState || {};

    toppings.forEach(t => {
        const quarters = (pizzaState[t.name] || [0,0,0,0]).reduce((s,v) => s + Number(v||0), 0);
        if (quarters > 0) {
            const addPrice = (parseFloat(t.price) / 4) * quarters;
            finalPrice += addPrice;
            let q1=[], q2=[];
            pizzaState[t.name].forEach((v,i) => { if(v===1) q1.push(i+1); if(v===2) q2.push(i+1); });
            let parts = [];
            if (q1.length) parts.push(q1.length===4 ? 'מגש שלם' : `רבעים ${q1.join(', ')}`);
            if (q2.length) parts.push(q2.length===4 ? 'כפול על הכל' : `כפול רבעים ${q2.join(', ')}`);
            selected.push({ name: `${t.name} (${parts.join(' | ')})`, price: addPrice });
        }
    });
    const modal = document.getElementById('pos-pizza-modal');
    if (window._waiterPOSMode) {
        window._waiterPOSMode = false;
        const p = window.currentPOSProduct;
        const modStr = selected.length ? ` (${selected.map(s=>s.name).join(', ')})` : '';
        window.waiterPOSCart.push({ id: p.id, name: p.name + modStr, price: finalPrice, qty: 1, kitchenStation: p.kitchen_station||'other', note: '', modifiers: selected });
        if(modal) modal.remove();
        window.waiterRenderCart(); return;
    }
    if (window.kioskModeCapture) {
        window.kioskModeCapture = false;
        if (modal) modal.remove();
        const p = window.currentPOSProduct;
        kioskCart.push({ id: p.id + '_' + Date.now(), name: p.name, price: finalPrice, qty: 1, modifiers: selected });
        kioskUpdateCartBar(); kioskRenderGrid(); return;
    }
    window.posCart.push({ id: 'pos_' + Date.now(), real_id: window.currentPOSProduct.id, name: window.currentPOSProduct.name, price: finalPrice, qty: 1, modifiers: selected });
    if (modal) modal.remove();
    window.renderPOSCart();
};

window.openPOSBundleModal = function(p, bundleData) {
    window.currentPOSProduct = p;
    const steps = bundleData.steps || [];
    let modal = document.getElementById('pos-bundle-modal');
    if (modal) modal.remove();
    let html = `
    <div id="pos-bundle-modal" style="z-index: 999999999 !important;" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4 fade-in">
        <div class="bg-white w-full max-w-lg rounded-[2rem] p-6 shadow-2xl relative flex flex-col max-h-[90vh]">
            <div class="border-b border-slate-100 pb-3 mb-4 flex justify-between items-center shrink-0">
                <h3 class="text-xl font-black text-slate-800"><i class="fa-solid fa-boxes-stacked text-indigo-500 mr-2"></i> ${safeStr(p.name)}</h3>
                <button onclick="document.getElementById('pos-bundle-modal').remove()" class="w-8 h-8 bg-slate-100 rounded-full text-slate-500 hover:bg-slate-200 transition"><i class="fa-solid fa-xmark"></i></button>
            </div>
            <div class="flex-1 overflow-y-auto modal-scroll pr-1 space-y-4 pb-4">
                ${steps.map((step, idx) => {
                    let availableItems = [];
                    if (step.selectionType === 'category') {
                        availableItems = storeCatalogCache.filter(c => c.category === step.category && c.is_available);
                    } else {
                        availableItems = storeCatalogCache.filter(c => step.items && step.items.includes(c.id) && c.is_available);
                    }
                    let optionsHtml = '';
                    if (availableItems.length === 0) {
                        optionsHtml = '<p class="text-[10px] text-slate-400 font-bold bg-white p-3 rounded-lg border border-dashed text-center">אין פריטים זמינים לבחירה בשלב זה.</p>';
                    } else {
                        optionsHtml = availableItems.map((item, itemIdx) => `
                            <label class="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-xl cursor-pointer hover:border-indigo-400 transition shadow-sm mb-2 group relative">
                                <div class="flex items-center gap-3">
                                    <input type="${step.qty === 1 ? 'radio' : 'checkbox'}" name="bundle_step_${idx}" value="${safeStr(item.name)}" data-price="${item.price}" class="w-4 h-4 accent-indigo-600 bundle-step-input-${idx}" ${step.qty === 1 && itemIdx === 0 ? 'checked' : ''}>
                                    <span class="font-bold text-slate-700 text-sm group-hover:text-indigo-800">${safeStr(item.name)}</span>
                                </div>
                            </label>
                        `).join('');
                    }
                    return `
                    <div class="bg-slate-50 p-4 rounded-2xl border border-slate-200 shadow-sm">
                        <div class="flex justify-between items-center mb-3 border-b border-slate-200 pb-2">
                            <h4 class="font-bold text-slate-800 text-sm">${safeStr(step.name)}</h4>
                            <span class="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded-md border border-indigo-100 shadow-sm">בחר ${step.qty} ${step.qty===1 ? 'פריט' : 'פריטים'}</span>
                        </div>
                        <div class="bundle-options-wrapper" data-max="${step.qty}">
                            ${optionsHtml}
                        </div>
                    </div>`;
                }).join('')}
            </div>
            <div class="pt-3 border-t border-slate-100 shrink-0">
                <button onclick="window.submitPOSBundle()" class="w-full bg-indigo-600 text-white py-3.5 rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition">סיים הרכבה והוסף לעגלה</button>
            </div>
        </div>
    </div>`;
    const targetNode = document.fullscreenElement || document.body;
    targetNode.insertAdjacentHTML('beforeend', html);
    
    steps.forEach((step, idx) => {
        if (step.qty > 1) {
            const inputs = document.querySelectorAll(`.bundle-step-input-${idx}`);
            inputs.forEach(inp => {
                inp.addEventListener('change', () => {
                    const checked = document.querySelectorAll(`.bundle-step-input-${idx}:checked`);
                    if (checked.length > step.qty) {
                        inp.checked = false;
                        showToast('info', `ניתן לבחור עד ${step.qty} פריטים בשלב: ${step.name}`);
                    }
                });
            });
        }
    });
};

window.submitPOSBundle = function() {
    let finalPrice = parseFloat(window.currentPOSProduct.price);
    let selected = [];
    const parsed = JSON.parse(window.currentPOSProduct.options_text);
    const steps = parsed.steps || [];
    let isValid = true;
    
    steps.forEach((step, idx) => {
        const checked = document.querySelectorAll(`input[name="bundle_step_${idx}"]:checked`);
        if (checked.length === 0) {
            showToast('error', `חובה לבחור פריטים בשלב: ${step.name}`);
            isValid = false;
        }
        checked.forEach(inp => {
            selected.push({ name: inp.value, price: 0 }); 
        });
    });
    
    if (!isValid) return;
    const modal = document.getElementById('pos-bundle-modal');
    if (window._waiterPOSMode) {
        window._waiterPOSMode = false;
        const p = window.currentPOSProduct;
        const modStr = selected.length ? ` (${selected.map(s=>s.name).join(', ')})` : '';
        window.waiterPOSCart.push({ id: p.id, name: p.name + modStr, price: finalPrice, qty: 1, kitchenStation: p.kitchen_station||'other', note: '', modifiers: selected });
        if(modal) modal.remove();
        window.waiterRenderCart(); return;
    }
    if (window.kioskModeCapture) {
        window.kioskModeCapture = false;
        if(modal) modal.remove();
        const p = window.currentPOSProduct;
        kioskCart.push({ id: p.id + '_' + Date.now(), name: p.name, price: finalPrice, qty: 1, modifiers: selected });
        kioskUpdateCartBar(); kioskRenderGrid(); return;
    }
    window.posCart.push({ id: 'pos_' + Date.now(), real_id: window.currentPOSProduct.id, name: window.currentPOSProduct.name, price: finalPrice, qty: 1, modifiers: selected });
    if (modal) modal.remove();
    window.renderPOSCart();
};

// 🎁 פונקציות הנחה ידנית בקופה
window.togglePOSDiscountPanel = function() {
    const panel = document.getElementById('pos-manual-discount-row');
    if (panel) panel.classList.toggle('hidden');
};

window.calcPOSDiscountFromPercent = function() {
    const percent = parseFloat(document.getElementById('pos-discount-percent').value) || 0;
    let netTotal = 0;
    window.posCart.forEach(i => netTotal += (i.price * i.qty));
    const discount = (netTotal * percent / 100);
    window.currentPOSManualDiscount = Math.min(discount, netTotal);
    document.getElementById('pos-discount-fixed').value = '';
    window.renderPOSCart();
    window.showDiscountDisplay();
};

window.calcPOSDiscountFromFixed = function() {
    const fixed = parseFloat(document.getElementById('pos-discount-fixed').value) || 0;
    let netTotal = 0;
    window.posCart.forEach(i => netTotal += (i.price * i.qty));
    window.currentPOSManualDiscount = Math.min(fixed, netTotal);
    document.getElementById('pos-discount-percent').value = '';
    window.renderPOSCart();
    window.showDiscountDisplay();
};

window.clearPOSDiscount = function() {
    window.currentPOSManualDiscount = 0;
    document.getElementById('pos-discount-percent').value = '';
    document.getElementById('pos-discount-fixed').value = '';
    const panel = document.getElementById('pos-manual-discount-row');
    if (panel) panel.classList.add('hidden');
    const display = document.getElementById('pos-discount-display');
    if (display) display.classList.add('hidden');
    window.renderPOSCart();
};

window.setPOSDiscount = function(type) {
    // סמן את הכפתור הנבחר
    if (type === null) {
        document.getElementById('pos-discount-fixed').value = '';
        document.getElementById('pos-discount-fixed').focus();
    } else if (type === 'fixed') {
        document.getElementById('pos-discount-percent').value = '';
        document.getElementById('pos-discount-fixed').focus();
    }
};

window.showDiscountDisplay = function() {
    const disc = window.currentPOSManualDiscount || 0;
    const display = document.getElementById('pos-discount-display');
    const amount = document.getElementById('pos-discount-amount');
    if (display && amount) {
        if (disc > 0) {
            amount.innerText = disc.toFixed(2);
            display.classList.remove('hidden');
        } else {
            display.classList.add('hidden');
        }
    }
};

window.finalizePOSOrder = async function() {
    const btn = document.getElementById('btn-finalize-pos'); 
    btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> סולק ומדפיס...';
    
    const isDebtPayment = window.posCart.length === 1 && window.posCart[0].real_id === null && window.posCart[0].name.includes('חוב');
    let netTotal = 0; window.posCart.forEach(i => netTotal += (i.price * i.qty));
    let promoAmount = (window.currentPOSDiscount || 0) + (window.currentPOSManualDiscount || 0);
    const tipAmount = parseFloat(document.getElementById('tender-tip-amount')?.value) || window.currentTipAmount || 0;
    let grandTotal = netTotal - promoAmount + tipAmount;
    if (grandTotal < 0) grandTotal = 0;

    const phone = document.getElementById('pos-customer-phone').value;
    const customerName = window.posCurrentCustomer ? window.posCurrentCustomer.name : 'לקוח קופה';
    const items = window.posCart.map(i => ({ catalogId: i.real_id, name: i.name, quantity: i.qty, price: i.price, note: i.modifiers ? i.modifiers.map(m => m.name).join(', ') : '', kitchenStation: i.kitchenStation || 'other' }));
    
    const vatSettings = window.getVatSettings();
    let vatDetails = null;
    if (vatSettings && vatSettings.enabled && !isDebtPayment) {
        const rate = vatSettings.rate || 18;
        const totalBeforeVat = grandTotal / (1 + (rate / 100));
        const vatAmount = grandTotal - totalBeforeVat;
        vatDetails = { enabled: true, rate: rate, subtotal: totalBeforeVat, vatAmount: vatAmount };
    }
    
    const metaData = { payments: window.posSplitPayments, vat: vatDetails, is_debt_recovery: isDebtPayment, promoDiscount: promoAmount, manualDiscount: window.currentPOSManualDiscount || 0, tip: tipAmount || 0, tableNumber: window.posSelectedTable || null };
    items.push({ catalogId: null, is_quote_metadata: true, data: JSON.stringify(metaData) });

    const modal = document.getElementById('pos-tender-modal');
    if (modal) modal.classList.add('hidden');

    try {
        const res = await fetch(`${API}/store/orders`, { 
            method: 'POST', headers: {'Content-Type': 'application/json'}, 
            body: JSON.stringify({ groupId: currentGroup.id, customerName: customerName, customerPhone: phone, items, totalAmount: grandTotal, isDelivery: false, notes: JSON.stringify(metaData), orderSource: metaData.tableNumber ? 'table' : 'internal' }) 
        });
        const data = await res.json();
        
        if(data.success) {
            const newOrderId = data.orderId || data.id;
            try {
                if (newOrderId) {
                    fetch(`${API}/store/orders/status`, { 
                        method: 'POST', headers: {'Content-Type':'application/json'}, 
                        body: JSON.stringify({ orderId: newOrderId, status: 'completed' }) 
                    }).catch(e=>{});
                }
            } catch(e){}

            const rawOrderObj = {
                id: newOrderId || 'קופה',
                created_at: new Date().toISOString(),
                total_amount: grandTotal,
                items: items,
                notes: JSON.stringify(metaData)
            };
            try { window.printPOSReceipt(newOrderId, rawOrderObj); } catch(e){}

            showToast('success', 'העסקה הושלמה ונשמרה בהצלחה!'); 
            try { triggerConfetti(); } catch(e){}
            setTimeout(() => { try { if(typeof window.fetchStoreOrders === 'function') window.fetchStoreOrders(); } catch(e){} }, 2000);

            window.posCart = []; window.renderPOSCart();
            window.currentPOSManualDiscount = 0; window.currentTipAmount = 0;
            const discRow = document.getElementById('pos-manual-discount-row');
            if (discRow) discRow.classList.add('hidden');
            // עדכן שולחן ל-"ממתין לתשלום" אחרי סגירת הזמנה
            if (window.posSelectedTable) { try { window.setTableAwaitingPayment(window.posSelectedTable); } catch(e){} }
            const phoneInput = document.getElementById('pos-customer-phone');
            if(phoneInput) phoneInput.value = '';
            try { window.checkPOSCustomer(); } catch(e){}
            
        } else {
            showToast('error', data.error || 'שגיאה בשמירת ההזמנה במסד הנתונים');
        }
    } catch(e) { 
        showToast('error', 'שגיאת רשת בסיום העסקה. העסקה לא נשמרה בשרת.'); 
    } finally { 
        btn.disabled = false; btn.innerHTML = 'סיום והפקת קבלה <i class="fa-solid fa-receipt"></i>'; 
    }
};

window.printPOSReceipt = function(orderId = null, rawOrderObj = null) {
    const idToPrint = orderId || (typeof currentStoreOrderId !== 'undefined' ? currentStoreOrderId : null);
    if(!idToPrint && !rawOrderObj) return;
    
    let order = rawOrderObj;
    if (!order) {
        order = storeOrdersCache.find(o => String(o.id) === String(idToPrint));
        if(!order) return showToast('error', 'לא נמצאו נתוני הזמנה להדפסה');
    }
    
    let itemsHtml = '';
    const rawItems = Array.isArray(order.items) ? order.items : (typeof order.items === 'string' ? JSON.parse(order.items) : []);
    
    rawItems.forEach(i => {
        if (i.is_quote_metadata || i.is_delivery_metadata || (i.name && i.name.startsWith('DELIVERY_META|')) || i.catalogId === 999999) return;

        itemsHtml += `<div style="display:flex; justify-content:space-between; margin-bottom:4px; font-weight:bold;"><span>${i.item_name || i.name} x${i.quantity}</span><span dir="ltr">₪${((i.price_at_order || i.price || 0) * i.quantity).toFixed(2)}</span></div>`;
        if (i.note) itemsHtml += `<div style="font-size:11px; color:#555; margin-bottom:4px; padding-right:10px;">${safeStr(i.note)}</div>`;
        
        if (i.options_text && i.options_text !== 'null' && i.options_text !== 'undefined') {
            try {
                const parsed = JSON.parse(i.options_text);
                if (parsed && (parsed.isComplex || parsed.isBundle) && parsed.steps) {
                    parsed.steps.forEach(step => {
                        if (step.options) {
                            step.options.forEach(opt => {
                                if (opt.selected === true || opt.selected === 'true') {
                                    const optQty = (parseFloat(i.quantity) || 1) * (parseFloat(opt.qty) || 1);
                                    const optPrice = (parseFloat(opt.price) || 0) * optQty;
                                    itemsHtml += `<div style="display:flex; justify-content:space-between; margin-bottom:2px; padding-right:15px; font-size:11px; color:#333;"><span style="text-align:right;">- ${safeStr(opt.name)} ${optQty !== 1 ? `(x${optQty})` : ''}</span><span dir="ltr">${optPrice > 0 ? `+₪${optPrice.toFixed(2)}` : ''}</span></div>`;
                                    if (opt.note) itemsHtml += `<div style="font-size:10px; color:#777; margin-bottom:2px; padding-right:25px; text-align:right;">* הערה: ${safeStr(opt.note)}</div>`;
                                }
                            });
                        }
                    });
                } else if (Array.isArray(parsed)) {
                    parsed.forEach(opt => {
                        if (opt.name) {
                             itemsHtml += `<div style="display:flex; justify-content:space-between; margin-bottom:2px; padding-right:15px; font-size:11px; color:#333;"><span style="text-align:right;">- ${safeStr(opt.name)}</span></div>`;
                        }
                    });
                }
            } catch(e) {}
        }
        itemsHtml += `<div style="height:6px;"></div>`; 
    });
    
    let titleStr = 'קבלה';
    let paymentsHtml = '';
    const totalAmount = parseFloat(order.total_amount || order.total || 0);
    const vatSettings = window.getVatSettings();
    let vatHtml = '';
    let promoHtml = '';
    
    try {
        let metaStr = order.notes;
        if (!metaStr || !metaStr.includes('{')) {
            const rawMetaItem = rawItems.find(i => i.is_quote_metadata);
            if (rawMetaItem) metaStr = rawMetaItem.data;
        }

        if(metaStr && metaStr.includes('{')) {
            const meta = JSON.parse(metaStr);
            if (meta.is_debt_recovery) titleStr = 'פירעון_חוב';
            
            if (meta.promoDiscount && meta.promoDiscount > 0) {
                promoHtml = `
                    <div style="border-top:1px dashed #000; margin:10px 0; padding-top:10px; font-size:12px;">
                        <div style="display:flex; justify-content:space-between; color:#ef4444; font-weight:bold;"><span>הנחת מבצעים:</span><span dir="ltr">-₪${meta.promoDiscount.toFixed(2)}</span></div>
                    </div>
                `;
            }
            
            if (meta.payments && meta.payments.length > 0) {
                paymentsHtml = `<div style="margin-top:10px; font-size:12px; border-top:1px dashed #000; padding-top:10px;"><b>אמצעי תשלום:</b><br>`;
                meta.payments.forEach(p => {
                    paymentsHtml += `<div style="display:flex; justify-content:space-between; margin-top:2px;"><span>${p.name || p.method}</span><span dir="ltr">₪${parseFloat(p.amount).toFixed(2)}</span></div>`;
                });
                paymentsHtml += `</div>`;
            }
        }
    } catch(e) {}
    
    if (vatSettings && vatSettings.enabled) {
        const vatRate = vatSettings.rate || 18;
        const totalBeforeVat = totalAmount / (1 + (vatRate / 100));
        const vatAmountCalc = totalAmount - totalBeforeVat;
        vatHtml = `
            <div style="border-top:1px dashed #000; margin:10px 0; padding-top:10px; font-size:12px;">
                <div style="display:flex; justify-content:space-between; margin-bottom:3px;"><span>סה"כ לפני מע"מ:</span><span dir="ltr">₪${totalBeforeVat.toFixed(2)}</span></div>
                <div style="display:flex; justify-content:space-between;"><span>מע"מ (${vatRate}%):</span><span dir="ltr">₪${vatAmountCalc.toFixed(2)}</span></div>
            </div>
        `;
    }
    
    const dateObj = new Date(order.created_at || Date.now());
    const dateStr = `${String(dateObj.getDate()).padStart(2, '0')}-${String(dateObj.getMonth() + 1).padStart(2, '0')}-${dateObj.getFullYear()}`;
    const timeStr = `${String(dateObj.getHours()).padStart(2, '0')}:${String(dateObj.getMinutes()).padStart(2, '0')}:${String(dateObj.getSeconds()).padStart(2, '0')}`;
    const docTitle = `קבלה-${order.id}_${dateStr}`;
    
    const receiptHtml = `
        <!DOCTYPE html>
        <html dir="rtl">
        <head>
        <title>${docTitle}</title>
        <style>
            @page { size: auto; margin: 0mm; }
            body { font-family:sans-serif; padding:10px; font-size:13px; max-width: 300px; margin:0 auto; position: relative; min-height: 100vh; box-sizing: border-box; } 
            .print-footer { position: absolute; bottom: 10px; left: 0; right: 0; text-align: center; font-size: 11px; color: #64748b; font-weight: bold; border-top: 1px dashed #ccc; padding-top: 5px; }
        </style>
        </head>
        <body>
            <h2 style="text-align:center; margin-bottom:5px;">${safeStr(typeof currentGroup !== 'undefined' && currentGroup ? currentGroup.name : 'קבלה')}</h2>
            <div style="text-align:center; margin-bottom:15px; font-size:12px;">${titleStr.replace('_',' ')} #${order.id}<br>${timeStr} ,${dateStr}</div>
            <div style="border-top:1px dashed #000; border-bottom:1px dashed #000; padding:10px 0; margin-bottom:10px;">
                ${itemsHtml}
            </div>
            ${promoHtml}
            ${vatHtml}
            <div style="display:flex; justify-content:space-between; font-weight:bold; font-size:16px;">
                <span>סה"כ לתשלום:</span><span dir="ltr">₪${totalAmount.toFixed(2)}</span>
            </div>
            ${paymentsHtml}
            <div style="text-align:center; margin-top:20px; font-size:12px; font-weight:bold;">תודה שקנית אצלנו! 🙏</div>
            <div class="print-footer">Oneflowlife.co.il כל מה שאתם צריכים במערכת אחת</div>
        </body>
        </html>
    `;

    let iframe = document.getElementById('receipt-printer-frame');
    if(!iframe) {
        iframe = document.createElement('iframe');
        iframe.id = 'receipt-printer-frame';
        iframe.style.display = 'none';
        document.body.appendChild(iframe);
    }
    iframe.contentWindow.document.open();
    iframe.contentWindow.document.write(receiptHtml);
    iframe.contentWindow.document.close();
    
    setTimeout(() => {
        iframe.contentWindow.focus();
        iframe.contentWindow.print();
        showToast('info', 'הקבלה נשלחה להדפסה!');
    }, 500);
};

// רענון אוטומטי של מבצעים למניעת חוסרים
setInterval(() => {
    if (typeof currentGroup !== 'undefined' && currentGroup && currentGroup.id) {
        if(typeof window.fetchStorePromotions === 'function') window.fetchStorePromotions();
    }
}, 30000);

window.updatePOSQty = (idx, d) => { if(window.posCart[idx]) { window.posCart[idx].qty += d; if(window.posCart[idx].qty <= 0) window.posCart.splice(idx,1); window.renderPOSCart(); } };
window.posRemoveItem = (idx) => { window.posCart.splice(idx,1); window.renderPOSCart(); };
window.clearPOSCart = async () => { if(await window._uiConfirm('לרוקן את הסל?')) { window.posCart = []; window.renderPOSCart(); document.getElementById('pos-customer-phone').value = ''; window.checkPOSCustomer(); } };

// ─── 86 Item (Out of Stock quick toggle) ─────────────────────────────────────
window.pos86Item = async function(itemId) {
    const item = (storeCatalogCache || []).find(p => p.id === itemId);
    if (!item) return;
    const newAvail = !item.is_available;
    try {
        await fetch(`${API}/store/catalog/toggle`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ itemId, isAvailable: newAvail }) });
        item.is_available = newAvail;
        showToast(newAvail ? 'success' : 'info', newAvail ? `✅ "${item.name}" זמין שוב` : `🚫 "${item.name}" סומן כאזל`);
        window.renderPOSCatalog();
    } catch(e) { showToast('error', 'שגיאה בעדכון מוצר'); }
};

// ─── Daily Close Report ───────────────────────────────────────────────────────
window.openDailyCloseReport = function() {
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];
    const orders = (storeOrdersCache || []).filter(o => {
        const d = new Date(o.created_at);
        return d.toISOString().split('T')[0] === todayStr && !['cancelled','quote'].includes(o.status);
    });

    let totalRevenue = 0, totalTips = 0, totalDiscounts = 0;
    const byMethod = {};
    const itemCounts = {};

    orders.forEach(o => {
        const amt = parseFloat(o.total_amount || o.total || 0);
        totalRevenue += amt;
        let meta = {};
        try { meta = JSON.parse(o.notes || '{}'); } catch(e) {}
        totalTips += parseFloat(meta.tip || 0);
        totalDiscounts += parseFloat(meta.promoDiscount || 0) + parseFloat(meta.manualDiscount || 0);
        const payments = meta.payments || [];
        if (payments.length > 0) {
            payments.forEach(p => { byMethod[p.name] = (byMethod[p.name] || 0) + parseFloat(p.amount || 0); });
        } else {
            const m = o.payment_method || 'מזומן';
            byMethod[m] = (byMethod[m] || 0) + amt;
        }
        let items = [];
        try { items = JSON.parse(o.items || '[]'); } catch(e) {}
        items.forEach(it => {
            if (!it.is_quote_metadata && it.item_name) {
                itemCounts[it.item_name] = (itemCounts[it.item_name] || 0) + (parseFloat(it.quantity) || 1);
            }
        });
    });

    const topItems = Object.entries(itemCounts).sort((a,b) => b[1]-a[1]).slice(0,5);
    const methodRows = Object.entries(byMethod).map(([m,v]) => `<div class="flex justify-between py-2 border-b border-slate-100 last:border-0"><span class="text-sm font-bold text-slate-600">${safeStr(m)}</span><span class="font-black text-slate-800 dir-ltr">₪${v.toFixed(2)}</span></div>`).join('') || '<div class="text-slate-400 text-sm text-center py-2">אין נתונים</div>';
    const itemRows = topItems.map(([n,c],i) => `<div class="flex items-center gap-3 py-2 border-b border-slate-50 last:border-0"><span class="w-6 h-6 rounded-full bg-indigo-100 text-indigo-700 text-[10px] font-black flex items-center justify-center shrink-0">${i+1}</span><span class="text-sm text-slate-700 flex-1 truncate">${safeStr(n)}</span><span class="text-xs font-bold text-slate-500">${c} יח'</span></div>`).join('') || '<div class="text-slate-400 text-sm text-center py-2">אין נתונים</div>';

    const existing = document.getElementById('daily-close-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'daily-close-modal';
    modal.className = 'fixed inset-0 z-[9999] flex items-end sm:items-center justify-center bg-black/60';
    modal.innerHTML = `<div class="bg-white w-full max-w-md rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden" style="max-height:90vh;overflow-y:auto;">
        <div class="bg-gradient-to-r from-slate-800 to-slate-900 p-5 flex items-center justify-between">
            <div><h3 class="font-black text-white text-lg">📊 דוח סגירת יום</h3><p class="text-slate-400 text-xs">${today.toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'})}</p></div>
            <button onclick="document.getElementById('daily-close-modal').remove()" class="w-8 h-8 rounded-full bg-white/10 text-white flex items-center justify-center hover:bg-white/20 transition">✕</button>
        </div>
        <div class="p-5 space-y-4">
            <div class="grid grid-cols-3 gap-3">
                <div class="bg-emerald-50 border border-emerald-100 rounded-2xl p-3 text-center"><div class="text-[10px] font-bold text-emerald-600">הכנסות</div><div class="text-xl font-black text-emerald-700 dir-ltr">₪${totalRevenue.toFixed(0)}</div></div>
                <div class="bg-blue-50 border border-blue-100 rounded-2xl p-3 text-center"><div class="text-[10px] font-bold text-blue-600">הזמנות</div><div class="text-xl font-black text-blue-700">${orders.length}</div></div>
                <div class="bg-amber-50 border border-amber-100 rounded-2xl p-3 text-center"><div class="text-[10px] font-bold text-amber-600">ממוצע</div><div class="text-xl font-black text-amber-700 dir-ltr">₪${orders.length > 0 ? (totalRevenue/orders.length).toFixed(0) : 0}</div></div>
            </div>
            ${totalTips > 0 || totalDiscounts > 0 ? `<div class="flex gap-3">${totalTips > 0 ? `<div class="flex-1 bg-purple-50 border border-purple-100 rounded-xl p-3 text-center"><div class="text-[10px] font-bold text-purple-600">טיפים</div><div class="font-black text-purple-700 dir-ltr">₪${totalTips.toFixed(2)}</div></div>` : ''}${totalDiscounts > 0 ? `<div class="flex-1 bg-rose-50 border border-rose-100 rounded-xl p-3 text-center"><div class="text-[10px] font-bold text-rose-600">הנחות</div><div class="font-black text-rose-700 dir-ltr">₪${totalDiscounts.toFixed(2)}</div></div>` : ''}</div>` : ''}
            <div class="bg-slate-50 rounded-2xl p-4"><h4 class="font-black text-slate-700 text-sm mb-3">💳 פירוט לפי אמצעי תשלום</h4>${methodRows}</div>
            ${topItems.length > 0 ? `<div class="bg-slate-50 rounded-2xl p-4"><h4 class="font-black text-slate-700 text-sm mb-3">🏆 מנות מובילות היום</h4>${itemRows}</div>` : ''}
        </div>
        <div class="p-4 border-t border-slate-100">
            <button onclick="window.downloadBizReport && window.downloadBizReport('orders'); document.getElementById('daily-close-modal').remove();" class="w-full bg-slate-800 text-white py-3 rounded-2xl font-bold text-sm">📥 ייצא דוח יומי לאקסל</button>
        </div>
    </div>`;
    document.body.appendChild(modal);
    modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
};

// הפעלה כפויה של מבצעים בעת טעינת האפליקציה או מעבר טאב
setInterval(() => {
    const posContainer = document.getElementById('content-pos');
    if (posContainer && !posContainer.classList.contains('hidden') && (!window.storePromotionsCache || window.storePromotionsCache.length === 0)) {
        if(typeof window.fetchStorePromotions === 'function') window.fetchStorePromotions();
    }
}, 2000);
// ============================================================
// --- COMPLEX BUILDER (CATERING / PROJECTS) MODULE V2 ---
// ============================================================

window.currentComplexStepsUI = [];

window.openComplexBuilderModal = async function(id = null) {
    window.currentComplexStepsUI = [];

    let modal = document.getElementById('complex-builder-modal');
    if (modal) modal.remove();

    const _cxBizType = currentGroup?.business_type || '';
    const _cxIsRestaurant = _cxBizType === 'restaurant';
    const _cxTitle = _cxIsRestaurant ? 'מפרט פרויקט / תפריט קייטרינג'
        : _cxBizType === 'beauty' ? 'בניית חבילת שירות / מנוי'
        : _cxBizType === 'sport' ? 'בניית תוכנית אימון / חבילה'
        : _cxBizType === 'logistics' ? 'מפרט שינוע / חבילת הסכם'
        : 'מפרט שירות / חבילת פרויקט';
    const _cxTypeCheckboxes = [
        {val:'event', label:'ארוע'},
        {val:'catering', label:'קייטרינג'},
        {val:'project', label:'פרויקט'},
        {val:'other', label:'אחר'}
    ].map(t => `<label class="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 cursor-pointer hover:bg-emerald-50 hover:border-emerald-300 transition"><input type="checkbox" id="cx-type-${t.val}" value="${t.val}" class="accent-emerald-600 w-4 h-4"><span class="text-sm font-bold text-slate-700">${t.label}</span></label>`).join('');
    const _cxNameLabel = _cxIsRestaurant ? 'שם המפרט / התפריט (חובה):'
        : _cxBizType === 'beauty' ? 'שם החבילה / הסדרה (חובה):'
        : _cxBizType === 'sport' ? 'שם התוכנית / החבילה (חובה):'
        : 'שם המפרט / החבילה (חובה):';
    const _cxNamePlaceholder = _cxIsRestaurant ? 'למשל: תפריט חתונה 2026 / שיפוץ חדר רחצה'
        : _cxBizType === 'beauty' ? 'למשל: חבילת טיפוח פנים / מנוי חודשי'
        : _cxBizType === 'sport' ? 'למשל: תוכנית כושר 3 חודשים / מנוי שנתי'
        : 'למשל: חבילת שירות שנתית / פרויקט הקמה';
    const _cxBasePriceLabel = _cxIsRestaurant ? 'מחיר בסיס (למנה/לפרויקט):' : 'מחיר בסיס (לחבילה/לפרויקט):';
    const _cxStepsLabel = _cxIsRestaurant ? 'שלבי המפרט / בחירות:'
        : _cxBizType === 'beauty' ? 'שלבי הטיפול / אפשרויות:'
        : _cxBizType === 'sport' ? 'שלבי התוכנית / אפשרויות:'
        : 'שלבי הפרויקט / אפשרויות:';
    const _cxCategoryPlaceholder = _cxIsRestaurant ? 'למשל: תפריטי אירועים'
        : _cxBizType === 'beauty' ? 'למשל: חבילות טיפוח'
        : 'למשל: חבילות שירות';
    const _cxDescPlaceholder = _cxIsRestaurant ? 'הסבר קצר על המפרט והאפשרויות...'
        : 'הסבר קצר על החבילה והאפשרויות...';

    document.body.insertAdjacentHTML('beforeend', `
    <div id="complex-builder-modal" class="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[90] flex items-center justify-center p-2 sm:p-4 fade-in">
        <div class="bg-slate-50 w-full max-w-4xl rounded-[2rem] shadow-2xl relative flex flex-col h-[95vh] sm:max-h-[90vh] overflow-hidden border border-slate-200">
            <div class="flex justify-between items-center p-4 sm:p-5 border-b border-slate-200 shrink-0 bg-white z-10">
                <h3 class="text-xl font-black text-slate-800"><i class="fa-solid fa-list-check text-emerald-500 mr-2"></i> ${_cxTitle}</h3>
                <button type="button" onclick="document.getElementById('complex-builder-modal').remove()" class="w-8 h-8 bg-slate-100 rounded-full text-slate-500 hover:bg-slate-200 transition flex items-center justify-center border border-slate-200"><i class="fa-solid fa-xmark"></i></button>
            </div>
            
            <div class="flex-1 overflow-y-auto p-4 sm:p-5 space-y-5 modal-scroll">
                <input type="hidden" id="cx-id" value="">
                
                <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4">
                    <div>
                        <label class="text-xs font-bold text-slate-600 block mb-2">סוג המפרט (ניתן לבחור מספר):</label>
                        <div class="flex flex-wrap gap-2">${_cxTypeCheckboxes}</div>
                    </div>
                    <div>
                        <label class="text-xs font-bold text-slate-600 block mb-1">${_cxNameLabel}</label>
                        <input type="text" id="cx-name" class="modern-input py-2.5 text-sm font-bold text-slate-800 shadow-sm bg-slate-50 focus:bg-white transition" placeholder="${_cxNamePlaceholder}">
                    </div>
                    <div class="grid grid-cols-1 md:grid-cols-3 gap-3 border-t border-slate-100 pt-4">
                        <div>
                            <label class="text-xs font-bold text-slate-600 block mb-1" title="ניתן להשאיר 0 אם התמחור מבוסס רק על הרכיבים בפנים">${_cxBasePriceLabel}</label>
                            <input type="number" id="cx-price" class="modern-input py-2.5 text-base font-black text-slate-800 shadow-sm bg-slate-50 focus:bg-white transition text-center dir-ltr" placeholder="0.00">
                        </div>
                        <div>
                            <label class="text-xs font-bold text-slate-600 block mb-1">אופן חישוב מחיר:</label>
                            <select id="cx-price-mode" class="modern-input py-2.5 text-sm font-bold text-slate-700 shadow-sm bg-slate-50 focus:bg-white transition outline-none cursor-pointer">
                                <option value="per_guest">מחיר למנה × מוזמנים</option>
                                <option value="per_total">מחיר לפי סך הבחירות</option>
                            </select>
                        </div>
                        <div>
                            <label class="text-xs font-bold text-slate-600 block mb-1">קטגוריה בחנות:</label>
                            <input type="text" id="cx-category" class="modern-input py-2.5 text-sm font-bold text-slate-800 shadow-sm bg-slate-50 focus:bg-white transition" placeholder="${_cxCategoryPlaceholder}">
                        </div>
                    </div>
                    <div>
                        <label class="text-xs font-bold text-slate-600 block mb-2">תמונה לתפריט (אופציונלי):</label>
                        <div class="flex gap-3 items-start">
                            <div class="flex-1 flex flex-col items-center justify-center bg-slate-50 border-2 border-dashed border-slate-300 rounded-2xl p-3 cursor-pointer hover:bg-slate-100 transition" onclick="document.getElementById('cx-image-upload').click()">
                                <div id="cx-image-placeholder" class="text-center py-1"><i class="fa-solid fa-cloud-arrow-up text-2xl text-slate-400 mb-1"></i><p class="text-xs font-bold text-slate-500">לחץ להעלאת תמונה</p></div>
                                <img id="cx-image-preview" class="hidden h-24 w-full object-cover rounded-xl">
                            </div>
                            <button type="button" onclick="window.clearComplexImage()" class="text-[10px] font-bold text-red-400 bg-red-50 border border-red-100 rounded-xl px-2 py-2 hover:bg-red-100 transition shrink-0"><i class="fa-solid fa-trash"></i></button>
                        </div>
                        <input type="file" id="cx-image-upload" accept="image/*" class="hidden" onchange="window.handleComplexImageUpload(event)">
                        <input type="hidden" id="cx-image-base64">
                    </div>
                    <div>
                        <label class="text-xs font-bold text-slate-600 block mb-1">תיאור קצר (יופיע ללקוח):</label>
                        <textarea id="cx-desc" class="modern-input py-2 text-sm h-16 bg-slate-50 focus:bg-white transition" placeholder="${_cxDescPlaceholder}"></textarea>
                    </div>
                </div>

                <div class="bg-emerald-50/50 p-4 sm:p-5 rounded-2xl border border-emerald-100 shadow-sm mt-4">
                    <div class="flex justify-between items-center mb-4 border-b border-emerald-200/50 pb-3">
                        <label class="text-sm font-black text-emerald-900 block"><i class="fa-solid fa-layer-group mr-1"></i> ${_cxStepsLabel}</label>
                        <button type="button" onclick="window.addComplexStep()" class="text-[10px] sm:text-xs font-bold text-white bg-emerald-600 px-4 py-2 rounded-lg shadow-sm hover:bg-emerald-700 transition"><i class="fa-solid fa-plus mr-1"></i> הוסף שלב</button>
                    </div>
                    <div id="cx-steps-container" class="space-y-6"></div>
                </div>
            </div>

            <div class="p-4 sm:p-5 border-t border-slate-200 bg-white shrink-0 flex gap-3 z-10">
                <button type="button" onclick="document.getElementById('complex-builder-modal').remove()" class="flex-[0.8] bg-slate-100 py-3.5 rounded-xl font-bold text-slate-600 hover:bg-slate-200 transition text-sm">ביטול</button>
                <button type="button" id="btn-submit-cx" onclick="window.submitComplexBuilder()" class="flex-[1.2] bg-emerald-600 text-white py-3.5 rounded-xl font-bold shadow-lg hover:bg-emerald-700 transition text-base flex justify-center items-center gap-2"><i class="fa-solid fa-save"></i> שמור מפרט</button>
            </div>
        </div>
    </div>
    `);

    modal = document.getElementById('complex-builder-modal');

    if (id) {
        if (!storeCatalogCache || !storeCatalogCache.length) {
            try {
                const res = await fetch(`${API}/store/catalog/${currentGroup.id}`);
                storeCatalogCache = await res.json();
            } catch(e) {}
        }
        const p = storeCatalogCache ? storeCatalogCache.find(item => item.id === id) : null;
        if(p) {
            document.getElementById('cx-id').value = p.id; 
            document.getElementById('cx-name').value = p.name || ''; 
            document.getElementById('cx-price').value = p.price || ''; 
            document.getElementById('cx-category').value = p.category || ''; 
            document.getElementById('cx-desc').value = p.description || ''; 
            
            if (p.options_text) {
                try {
                    const parsed = JSON.parse(p.options_text);
                    if (parsed && parsed.isComplex) {
                        window.currentComplexStepsUI = parsed.steps || [];
                        // types (new array format, or legacy string)
                        const types = Array.isArray(parsed.complexTypes) ? parsed.complexTypes
                            : parsed.complexType ? [parsed.complexType] : [];
                        types.forEach(t => { const el = document.getElementById(`cx-type-${t}`); if (el) el.checked = true; });
                        if (parsed.priceMode) { const el = document.getElementById('cx-price-mode'); if (el) el.value = parsed.priceMode; }
                        if (parsed.imageUrl) {
                            document.getElementById('cx-image-base64').value = parsed.imageUrl;
                            const prev = document.getElementById('cx-image-preview');
                            if (prev) { prev.src = parsed.imageUrl; prev.classList.remove('hidden'); document.getElementById('cx-image-placeholder').classList.add('hidden'); }
                        }
                    }
                } catch(e) { }
            }
        }
    } else {
        window.addComplexStep(); // מכין שלב ראשון ריק בדיפולט
    }
    
    window.renderComplexStepsUI(); 
    modal.classList.remove('hidden');
};

window.addComplexStep = function() {
    window.currentComplexStepsUI.push({ name: '', min: 1, max: 1, stepPrice: 0, options: [{name: '', price: 0, note: ''}] });
    window.renderComplexStepsUI();
};

window.removeComplexStep = async function(idx) {
    if(!await window._uiConfirm('למחוק שלב זה על כל אפשרויותיו?', {danger:true, okLabel:'מחק'})) return;
    window.currentComplexStepsUI.splice(idx, 1);
    window.renderComplexStepsUI();
};

window.addComplexOption = function(stepIdx) {
    window.currentComplexStepsUI[stepIdx].options.push({name: '', price: 0, note: ''});
    window.renderComplexStepsUI();
};

window.handleComplexImageUpload = function(event) {
    const file = event.target.files[0]; if (!file) return;
    compressImage(file, 800, 600, 0.85, (dataUrl) => {
        document.getElementById('cx-image-preview').src = dataUrl;
        document.getElementById('cx-image-preview').classList.remove('hidden');
        document.getElementById('cx-image-placeholder').classList.add('hidden');
        document.getElementById('cx-image-base64').value = dataUrl;
    });
};

window.clearComplexImage = function() {
    document.getElementById('cx-image-base64').value = '';
    document.getElementById('cx-image-preview').src = '';
    document.getElementById('cx-image-preview').classList.add('hidden');
    document.getElementById('cx-image-placeholder').classList.remove('hidden');
    const inp = document.getElementById('cx-image-upload');
    if (inp) inp.value = '';
};

window.openCatalogPickerForStep = async function(stepIdx) {
    if (!storeCatalogCache || !storeCatalogCache.length) {
        try {
            const res = await fetch(`${API}/store/catalog/${currentGroup.id}`);
            storeCatalogCache = await res.json();
        } catch(e) { showToast('error', 'שגיאה בטעינת קטלוג'); return; }
    }
    const catalog = (storeCatalogCache || []).filter(p => p.product_type !== 'complex_builder' && p.is_available !== false);
    if (!catalog.length) { showToast('info', 'הקטלוג ריק'); return; }
    window._catalogPickerItems = catalog;

    // קיבוץ לפי קטגוריה
    const byCategory = {};
    catalog.forEach(p => {
        const cat = p.category || 'כללי';
        if (!byCategory[cat]) byCategory[cat] = [];
        byCategory[cat].push(p);
    });

    let html = `<div id="cx-catalog-picker" class="fixed inset-0 z-[9999] flex items-center justify-center bg-black/50 backdrop-blur-sm" onclick="if(event.target===this)window.closeCatalogPicker()">
    <div class="bg-white rounded-2xl shadow-2xl w-full max-w-lg mx-4 max-h-[80vh] flex flex-col">
        <div class="flex items-center justify-between px-5 py-4 border-b border-slate-100 shrink-0">
            <h3 class="font-bold text-slate-800 text-base">בחר מוצרים מהקטלוג</h3>
            <button onclick="window.closeCatalogPicker()" class="w-8 h-8 flex items-center justify-center rounded-lg bg-slate-100 hover:bg-red-100 text-slate-500 hover:text-red-500 transition"><i class="fa-solid fa-times text-sm"></i></button>
        </div>
        <div class="overflow-y-auto p-4 flex flex-col gap-4">`;

    Object.entries(byCategory).forEach(([cat, items]) => {
        html += `<div><p class="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 px-1">${escHtml(cat)}</p><div class="flex flex-col gap-1.5">`;
        items.forEach((p, localIdx) => {
            const globalIdx = catalog.indexOf(p);
            html += `<button type="button" onclick="window.addCatalogItemToStep(${stepIdx}, ${globalIdx})"
                class="flex items-center justify-between gap-3 w-full bg-slate-50 hover:bg-emerald-50 border border-slate-200 hover:border-emerald-300 rounded-xl px-3 py-2.5 transition group text-right">
                <span class="font-bold text-slate-700 text-sm group-hover:text-emerald-700">${escHtml(p.name)}</span>
                <span class="text-emerald-600 font-bold text-sm shrink-0">${p.price ? '₪' + Number(p.price).toLocaleString() : 'ללא מחיר'}</span>
            </button>`;
        });
        html += `</div></div>`;
    });

    html += `</div></div></div>`;
    document.body.insertAdjacentHTML('beforeend', html);
};

window.closeCatalogPicker = function() {
    const el = document.getElementById('cx-catalog-picker');
    if (el) el.remove();
};

window.addCatalogItemToStep = function(stepIdx, itemIdx) {
    const item = (window._catalogPickerItems || [])[itemIdx];
    if (!item) return;
    window.currentComplexStepsUI[stepIdx].options.push({ name: item.name, price: item.price || 0, note: '' });
    window.closeCatalogPicker();
    window.renderComplexStepsUI();
};

window.removeComplexOption = function(stepIdx, optIdx) {
    window.currentComplexStepsUI[stepIdx].options.splice(optIdx, 1);
    window.renderComplexStepsUI();
};

window.updateComplexStepField = function(stepIdx, field, val) {
    window.currentComplexStepsUI[stepIdx][field] = val;
};

window.updateComplexOptionField = function(stepIdx, optIdx, field, val) {
    window.currentComplexStepsUI[stepIdx].options[optIdx][field] = val;
};

window.renderComplexStepsUI = function() {
    const container = document.getElementById('cx-steps-container');
    if (!container) return;
    
    if (window.currentComplexStepsUI.length === 0) {
        container.innerHTML = '<p class="text-[11px] text-slate-500 text-center py-8 bg-white rounded-2xl border border-dashed border-slate-300 font-medium shadow-sm">המפרט ריק.<br>לחצו על "הוסף שלב" למעלה כדי ליצור תפריט עשיר (למשל: "מנות פתיחה", "תוספות בתשלום").</p>';
        return;
    }
    
    let html = '';
    window.currentComplexStepsUI.forEach((step, stepIdx) => {
        let optionsHtml = '';
        step.options.forEach((opt, optIdx) => {
            optionsHtml += `
            <div class="flex flex-col sm:flex-row gap-2 items-start sm:items-center mb-2 bg-slate-50 p-2 rounded-xl border border-slate-200 fade-in w-full group hover:border-emerald-300 transition shadow-sm">
                <div class="w-full sm:w-[40%]">
                    <input type="text" class="w-full bg-white border border-slate-200 rounded-lg text-xs px-3 py-2.5 outline-none focus:border-emerald-400 text-slate-700 font-bold" value="${safeStr(opt.name)}" onchange="window.updateComplexOptionField(${stepIdx}, ${optIdx}, 'name', this.value)" placeholder="שם האופציה (למשל: סלמון / נקודת חשמל)">
                </div>
                
                <div class="w-full sm:w-[35%]">
                    <input type="text" class="w-full bg-white border border-slate-200 rounded-lg text-xs px-3 py-2.5 outline-none focus:border-emerald-400 text-slate-500" value="${safeStr(opt.note || '')}" onchange="window.updateComplexOptionField(${stepIdx}, ${optIdx}, 'note', this.value)" placeholder="הערה תפעולית (אופציונלי)">
                </div>

                <div class="w-full sm:w-[25%] flex gap-2 items-center">
                    <div class="relative w-full">
                        <input type="number" class="w-full bg-white border border-slate-200 rounded-lg text-xs pl-2 pr-6 py-2.5 outline-none focus:border-emerald-400 text-emerald-700 font-bold text-left dir-ltr" value="${opt.price || ''}" onchange="window.updateComplexOptionField(${stepIdx}, ${optIdx}, 'price', parseFloat(this.value)||0)" placeholder="ללא תוספת">
                        <span class="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] text-slate-400 font-bold">₪+</span>
                    </div>
                    <button type="button" onclick="window.removeComplexOption(${stepIdx}, ${optIdx})" class="text-slate-300 hover:text-red-500 w-8 h-8 shrink-0 flex items-center justify-center transition bg-white rounded-lg shadow-sm border border-slate-200"><i class="fa-solid fa-times text-xs"></i></button>
                </div>
            </div>`;
        });

        html += `
        <div class="bg-white p-4 sm:p-5 rounded-2xl border border-emerald-200 shadow-sm relative flex flex-col gap-3 fade-in group transition-all">
            <button type="button" onclick="window.removeComplexStep(${stepIdx})" class="absolute top-3 left-3 text-slate-400 hover:text-white w-8 h-8 flex items-center justify-center transition bg-slate-50 hover:bg-red-500 rounded-lg border border-slate-200 z-10 shadow-sm" title="מחיקת שלב"><i class="fa-solid fa-trash-can text-sm"></i></button>
            
            <div class="grid grid-cols-1 sm:grid-cols-12 gap-3 w-full border-b border-slate-100 pb-4 mb-2">
                <div class="sm:col-span-6 pr-6 sm:pr-0">
                    <label class="text-[10px] font-bold text-slate-500 block mb-1">שם השלב (למשל: בחירת מנה ראשונה):</label>
                    <input type="text" class="w-full bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold px-3 py-2.5 outline-none focus:border-emerald-400 focus:bg-white text-slate-800 transition shadow-inner" value="${safeStr(step.name)}" onchange="window.updateComplexStepField(${stepIdx}, 'name', this.value)" placeholder="כותרת השלב ללקוח">
                </div>
                
                <div class="sm:col-span-3">
                    <label class="text-[10px] font-bold text-slate-500 block mb-1">מחיר בסיס לשלב (₪):</label>
                    <input type="number" class="w-full bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold text-center dir-ltr px-2 py-2.5 outline-none focus:border-emerald-400 focus:bg-white text-slate-800 transition" value="${step.stepPrice || ''}" onchange="window.updateComplexStepField(${stepIdx}, 'stepPrice', parseFloat(this.value)||0)" placeholder="חינם / מגולם">
                </div>

                <div class="sm:col-span-3 flex gap-2">
                    <div class="flex-1">
                        <label class="text-[10px] font-bold text-slate-500 block mb-1 text-center">מינימום <span class="font-normal">(0=רשות):</span></label>
                        <input type="number" class="w-full bg-slate-50 border border-slate-200 rounded-xl text-sm text-center px-2 py-2.5 outline-none focus:border-emerald-400 focus:bg-white text-slate-800 transition font-bold" value="${step.min}" onchange="window.updateComplexStepField(${stepIdx}, 'min', parseInt(this.value)||0)">
                    </div>
                    <div class="flex-1">
                        <label class="text-[10px] font-bold text-slate-500 block mb-1 text-center">מקסימום <span class="font-normal">(0=ללא):</span></label>
                        <input type="number" class="w-full bg-slate-50 border border-slate-200 rounded-xl text-sm text-center px-2 py-2.5 outline-none focus:border-emerald-400 focus:bg-white text-slate-800 transition font-bold" value="${step.max}" onchange="window.updateComplexStepField(${stepIdx}, 'max', parseInt(this.value)||0)">
                    </div>
                </div>
            </div>
            
            <div class="space-y-1">
                ${optionsHtml}
                <div class="mt-2 flex gap-2">
                    <button type="button" onclick="window.addComplexOption(${stepIdx})" class="flex-1 bg-emerald-50/50 border border-dashed border-emerald-300 text-emerald-700 py-2.5 rounded-xl text-xs font-bold hover:bg-emerald-100 transition shadow-sm"><i class="fa-solid fa-plus mr-1"></i> הוסף אפשרות ידנית</button>
                    <button type="button" onclick="window.openCatalogPickerForStep(${stepIdx})" class="flex-1 bg-blue-50 border border-dashed border-blue-300 text-blue-700 py-2.5 rounded-xl text-xs font-bold hover:bg-blue-100 transition shadow-sm"><i class="fa-solid fa-box-open mr-1"></i> הוסף מהקטלוג</button>
                </div>
            </div>
        </div>`;
    });
    container.innerHTML = html;
};

window.submitComplexBuilder = async function() {
    const id = document.getElementById('cx-id').value;
    const complexTypes = ['event','catering','project','other'].filter(t => { const el = document.getElementById(`cx-type-${t}`); return el && el.checked; });
    const priceMode = document.getElementById('cx-price-mode')?.value || 'per_guest';
    const imageUrl = (document.getElementById('cx-image-base64')?.value || '').trim();
    const name = document.getElementById('cx-name').value;
    const price = document.getElementById('cx-price').value;
    const category = document.getElementById('cx-category').value || 'פרויקטים וקייטרינג';
    const description = document.getElementById('cx-desc').value;
    
    if(!name) return showToast('error', 'שם המפרט הוא שדה חובה');
    
    const validSteps = window.currentComplexStepsUI.filter(s => s.name.trim() !== '');
    if(validSteps.length === 0) return showToast('error', 'חובה להגדיר לפחות שלב אחד במפרט');

    // ניקוי אפשרויות ריקות בתוך השלבים
    validSteps.forEach(s => {
        s.options = s.options.filter(o => o.name.trim() !== '');
        s.stepPrice = parseFloat(s.stepPrice) || 0; // וידוא מספריות
    });

    const finalOptionsText = JSON.stringify({
        isComplex: true,
        complexTypes,
        priceMode,
        imageUrl,
        steps: validSteps
    });
    
    const btn = document.getElementById('btn-submit-cx'); 
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> שומר...'; }
    
    try {
        const payload = { 
            groupId: currentGroup.id, 
            name: name, 
            price: price || 0, 
            category: category, 
            description: description, 
            optionsText: finalOptionsText, 
            productType: 'complex_builder', 
            isAvailable: true 
        };
        const res = await fetch(id ? `${API}/store/catalog/${id}` : `${API}/store/catalog`, { method: id ? 'PUT' : 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
        const data = await res.json();
        if (data.success) { 
            showToast('success', 'המפרט נשמר בהצלחה והוא זמין ללקוחות בחנות!'); 
            document.getElementById('complex-builder-modal').remove(); 
            if (typeof fetchStoreCatalog === 'function') await fetchStoreCatalog();
            window.renderComplexList();
        } 
        else { showToast('error', data.error || 'שגיאה בשמירה'); }
    } catch(e) { showToast('error', 'שגיאה בתקשורת מול השרת'); } finally { if(btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-save"></i> שמור מפרט'; } }
};

window.renderComplexList = function() {
    const list = document.getElementById('store-complex-list');
    if (!list) return;

    if (!storeCatalogCache) {
        list.innerHTML = '<p class="text-center text-slate-400 py-8"><i class="fa-solid fa-spinner fa-spin"></i> טוען...</p>';
        return;
    }

    const complexes = storeCatalogCache.filter(p => p.product_type === 'complex_builder');

    if (complexes.length === 0) {
        list.innerHTML = '<p class="text-center text-slate-400 py-8 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-sm">לא הוגדרו תפריטים או מפרטים מורכבים במערכת.</p>';
        return;
    }

    list.innerHTML = complexes.map(p => {
        const activeColor = p.is_available ? 'text-green-600 bg-green-50 border-green-200' : 'text-slate-500 bg-slate-100 border-slate-200';
        let stepsCount = 0;
        let cType = 'קייטרינג / פרויקט';
        let iconType = 'fa-layer-group';

        try {
            const parsed = JSON.parse(p.options_text);
            if (parsed && parsed.steps) stepsCount = parsed.steps.length;
            if (parsed && parsed.complexType === 'catering') { cType = 'תפריט אירועים'; iconType = 'fa-utensils'; }
            if (parsed && parsed.complexType === 'project') { cType = 'מפרט פרויקט'; iconType = 'fa-helmet-safety'; }
        } catch(e){}

        return `
        <div class="bg-white p-4 rounded-2xl border border-emerald-100 shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-2 group hover:shadow-md transition hover:border-emerald-300">
            <div class="flex items-start gap-4 min-w-0 flex-1">
                <div class="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center border border-emerald-100 shadow-inner shrink-0 mt-1">
                    <i class="fa-solid ${iconType} text-xl"></i>
                </div>
                <div class="min-w-0 flex-1">
                    <h4 class="font-bold text-slate-800 text-base truncate pr-1">${safeStr(p.name)}</h4>
                    <p class="text-[10px] text-slate-500 mt-1 flex flex-wrap gap-2">
                        <span class="bg-slate-50 px-2 py-0.5 rounded-md border border-slate-100 shadow-sm font-bold text-slate-600"><i class="fa-solid fa-list-ol mr-0.5 text-slate-400"></i> ${stepsCount} שלבים לבחירה</span>
                        <span class="bg-slate-50 px-2 py-0.5 rounded-md border border-slate-100 shadow-sm">${cType}</span>
                    </p>
                    <p class="text-sm font-black text-emerald-600 mt-2">₪${p.price} <span class="font-normal text-[9px] text-slate-400 ml-1 bg-emerald-50 px-1.5 py-0.5 rounded border border-emerald-100">מחיר בסיס התחלתי</span></p>
                </div>
            </div>
            <div class="flex items-center gap-2 self-start sm:self-auto shrink-0 bg-slate-50 p-1.5 rounded-xl border border-slate-100">
                <button onclick="toggleStoreProduct(${p.id}, ${!p.is_available})" class="text-[10px] font-bold px-4 py-2 rounded-lg border transition shadow-sm ${activeColor}">${p.is_available ? 'זמין לחנות' : 'מוסתר'}</button>
                <button onclick="window.openComplexBuilderModal(${p.id})" class="text-slate-500 hover:text-emerald-600 bg-white shadow-sm w-9 h-9 rounded-lg flex items-center justify-center transition border border-slate-100" title="עריכה"><i class="fa-solid fa-pen text-xs"></i></button>
                <button onclick="deleteStoreProduct(${p.id})" class="text-slate-400 hover:text-red-500 bg-white shadow-sm w-9 h-9 rounded-lg flex items-center justify-center transition border border-slate-100" title="מחיקה"><i class="fa-solid fa-trash text-xs"></i></button>
            </div>
        </div>`;
    }).join('');
};
window.editingComplexItemId = null;

window.openQuoteComplexEditor = function(itemId) {
    const item = window.selectedQuoteItems[itemId];
    if(!item) return;
    window.editingComplexItemId = itemId;
    const searchInput = document.getElementById('complex-search-item');
    if (searchInput) searchInput.value = '';
    window.renderComplexEditorList();
    document.getElementById('quote-complex-modal').classList.remove('hidden');
};

window.renderComplexEditorList = function() {
    const itemId = window.editingComplexItemId;
    const item = window.selectedQuoteItems[itemId];
    const list = document.getElementById('complex-items-selector');
    if (!list) return;
    const searchInput = document.getElementById('complex-search-item');
    const searchQ = searchInput ? searchInput.value.toLowerCase() : '';
    
    if(!item || !item.complex_data) return;
    let parsed = { steps: [] };
    try { parsed = JSON.parse(item.complex_data); } catch(e){}
    
    let html = '';
    parsed.steps.forEach((step, sIdx) => {
        let optionsHtml = '';
        step.options.forEach((opt, oIdx) => {
            if(searchQ && !opt.name.toLowerCase().includes(searchQ)) return;
            
            const isChecked = (opt.selected === true || opt.selected === 'true') ? 'checked' : '';
            optionsHtml += `
            <div class="flex flex-col sm:flex-row sm:items-center justify-between p-3 bg-white border border-slate-200 rounded-xl mb-2 hover:border-emerald-300 transition gap-2">
                <label class="flex items-center gap-3 cursor-pointer flex-1">
                    <input type="${step.qty === 1 ? 'radio' : 'checkbox'}" name="cx_step_${sIdx}" value="${oIdx}" ${isChecked} onchange="window.toggleComplexOption(${sIdx}, ${oIdx}, this)" class="w-4 h-4 accent-emerald-600">
                    <span class="font-bold text-slate-700 text-sm">${safeStr(opt.name)}</span>
                </label>
                <div class="flex items-center gap-3 w-full sm:w-auto">
                    ${opt.price > 0 ? `<span class="text-xs font-bold text-emerald-600 dir-ltr bg-emerald-50 px-2 py-1 rounded border border-emerald-100">+₪${opt.price}</span>` : ''}
                    <div class="relative w-16 shrink-0">
                        <span class="text-[8px] text-slate-400 absolute -top-1.5 right-2 bg-white px-1 font-bold">כמות</span>
                        <input type="number" min="1" value="${opt.qty || 1}" onchange="window.updateComplexOptionData(${sIdx}, ${oIdx}, 'qty', this.value)" class="modern-input py-1.5 px-1 text-xs text-center w-full bg-slate-50 border-slate-200 shadow-sm">
                    </div>
                    <input type="text" value="${safeStr(opt.note || '')}" onchange="window.updateComplexOptionData(${sIdx}, ${oIdx}, 'note', this.value)" placeholder="הערה לטבח..." class="modern-input py-1.5 px-2 text-xs w-full sm:w-32 bg-slate-50 border-slate-200 shadow-sm flex-1 sm:flex-none">
                </div>
            </div>`;
        });
        
        if(optionsHtml) {
            html += `
            <div class="bg-slate-50 p-4 rounded-xl border border-slate-200 shadow-sm mb-4">
                <div class="flex justify-between items-center mb-3 border-b border-slate-200 pb-2">
                    <h4 class="font-bold text-slate-800"><i class="fa-solid fa-caret-left text-emerald-500 mr-1"></i> ${safeStr(step.name)}</h4>
                    <span class="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-md border border-emerald-100">בחר ${step.qty} פריטים</span>
                </div>
                <div class="bundle-options-wrapper" data-max="${step.qty}" data-step="${sIdx}">
                    ${optionsHtml}
                </div>
            </div>`;
        }
    });
    list.innerHTML = html || '<p class="text-center text-xs text-slate-400 py-4">אין אפשרויות תואמות לחיפוש.</p>';
};

window.toggleComplexOption = function(sIdx, oIdx, el) {
    const itemId = window.editingComplexItemId;
    const item = window.selectedQuoteItems[itemId];
    let parsed = JSON.parse(item.complex_data);
    
    const step = parsed.steps[sIdx];
    if (step.qty === 1) {
        step.options.forEach(o => o.selected = false);
        step.options[oIdx].selected = el.checked;
    } else {
        const currentlyChecked = step.options.filter(o => o.selected === true || o.selected === 'true').length;
        if (el.checked && currentlyChecked >= step.qty) {
            el.checked = false;
            showToast('info', `ניתן לבחור עד ${step.qty} פריטים בשלב זה.`);
            return;
        }
        step.options[oIdx].selected = el.checked;
    }
    item.complex_data = JSON.stringify(parsed);
};

window.updateComplexOptionData = function(sIdx, oIdx, field, val) {
    const itemId = window.editingComplexItemId;
    const item = window.selectedQuoteItems[itemId];
    let parsed = JSON.parse(item.complex_data);
    parsed.steps[sIdx].options[oIdx][field] = val;
    item.complex_data = JSON.stringify(parsed);
};

window.saveComplexEditor = function() {
    document.getElementById('quote-complex-modal').classList.add('hidden');
    window.calcQuoteTotal();
    window.renderQuoteSelectedItems();
};

window.updateQuoteItemPrice = function(id, val) {
    if (window.selectedQuoteItems[id]) {
        window.selectedQuoteItems[id].price_at_order = parseFloat(val) || 0;
        window.calcQuoteTotal();
        window.renderQuoteSelectedItems();
    }
};

window.updateQuoteItemQty = function(id, val) {
    if (window.selectedQuoteItems[id]) {
        window.selectedQuoteItems[id].quantity = parseFloat(val) || 1;
        window.calcQuoteTotal();
        window.renderQuoteSelectedItems();
    }
};

window.updateQuoteItemNote = function(id, val) {
    if (window.selectedQuoteItems[id]) window.selectedQuoteItems[id].note = val;
};

window.removeQuoteItem = function(id) {
    delete window.selectedQuoteItems[id];
    window.calcQuoteTotal();
    window.renderQuoteSelectedItems();
};
