// Navigate to class-types booking rules from within the sales tab
window._openSportClassTypesFromSales = function() {
    if (typeof window.showSportClassTypes === 'function') {
        window.showSportClassTypes();
    }
};

window._sportToggleInlineAddType = function() {
    const form = document.getElementById('sport-inline-add-type-form');
    if (form) form.classList.toggle('hidden');
};

window._sportSaveInlineType = async function() {
    const name = document.getElementById('sport-inline-type-name')?.value?.trim();
    const type = document.getElementById('sport-inline-type-kind')?.value;
    const price = parseFloat(document.getElementById('sport-inline-type-price')?.value) || 0;
    const sessions = parseInt(document.getElementById('sport-inline-type-sessions')?.value) || null;
    if (!name) { showToast('error', 'יש להזין שם'); return; }
    const durationMap = { monthly:30, yearly:365, punch_card: null, day_pass:1, pt_sessions: null };
    try {
        const r = await fetch(`${API}/sport/membership-types`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ groupId: currentGroup.id, name, type, price, durationDays: durationMap[type], sessions })
        });
        const d = await r.json();
        if (!d.success) { showToast('error', d.error || 'שגיאה'); return; }
        showToast('success', 'נוסף בהצלחה ✅');
        document.getElementById('sport-inline-type-name').value = '';
        document.getElementById('sport-inline-type-price').value = '';
        document.getElementById('sport-inline-type-sessions').value = '';
        const form = document.getElementById('sport-inline-add-type-form');
        if (form) form.classList.add('hidden');
        window.renderSportSalesCatalogView();
    } catch(e) { showToast('error', 'שגיאת תקשורת'); }
};

window._sportDeleteTypeInline = async function(typeId) {
    if (!await window._uiConfirm('למחוק סוג מנוי זה?', {danger:true, okLabel:'מחק'})) return;
    try {
        await fetch(`${API}/sport/membership-types/${typeId}`, { method: 'DELETE' });
        showToast('success', 'נמחק ✅');
        window.renderSportSalesCatalogView();
    } catch(e) { showToast('error', 'שגיאת תקשורת'); }
};

window._sportEditTypeInline = function(id, name, type, price, sessions) {
    const panel = document.getElementById(`sport-inline-edit-${id}`);
    if (!panel) return;
    panel.classList.toggle('hidden');
};

window._sportSaveTypeInline = async function(id) {
    const name = document.getElementById(`siet-name-${id}`)?.value?.trim();
    const type = document.getElementById(`siet-type-${id}`)?.value;
    const price = parseFloat(document.getElementById(`siet-price-${id}`)?.value) || 0;
    const sessions = parseInt(document.getElementById(`siet-sess-${id}`)?.value) || null;
    if (!name) { showToast('error', 'יש להזין שם'); return; }
    try {
        const r = await fetch(`${API}/sport/membership-types/${id}`, {
            method: 'PUT', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name, type, price, sessions })
        }).then(r => r.json());
        if (!r.success) { showToast('error', r.error || 'שגיאה'); return; }
        showToast('success', 'נשמר ✅');
        window.renderSportSalesCatalogView();
    } catch(e) { showToast('error', 'שגיאת תקשורת'); }
};

// ─── Sport store settings: load & save ───────────────────────────────────────

window._loadSportStoreSettings = async function() {
    try {
        const r = await fetch(`${API}/store/settings/${currentGroup.id}`);
        const d = await r.json();
        const s = d.settings || {};
        const sp = s.sport_settings ? (typeof s.sport_settings === 'string' ? JSON.parse(s.sport_settings) : s.sport_settings) : {};

        const trialEl = document.getElementById('sport-trial-enabled');
        const cancelEl = document.getElementById('sport-cancellation-policy');
        const freezeEl = document.getElementById('sport-freeze-policy');
        const waiverEl = document.getElementById('sport-waiver-text');
        const minAgeEl = document.getElementById('sport-min-age');
        const noticeDaysEl = document.getElementById('sport-cancel-notice-days');

        if (trialEl) trialEl.checked = !!sp.trial_enabled;
        if (cancelEl) cancelEl.value = sp.cancellation_policy || '';
        if (freezeEl) freezeEl.value = sp.freeze_policy || '';
        if (waiverEl) waiverEl.value = sp.waiver_text || '';
        if (minAgeEl) minAgeEl.value = sp.min_age || '';
        if (noticeDaysEl) noticeDaysEl.value = sp.cancel_notice_days || '';
    } catch(e) {}
};

// ============================================================
// --- DELIVERY ZONES ---
// ============================================================
let deliveryZonesCache = [];

window.loadDeliveryZones = async function() {
    if (!currentGroup?.id) return;
    const isDeliveryBiz = ['restaurant','cafe','logistics','retail','services'].includes(currentGroup?.business_type);
    const section = document.getElementById('delivery-zones-section');
    if (section) section.classList.toggle('hidden', !isDeliveryBiz);
    if (!isDeliveryBiz) return;
    try {
        const res = await fetch(`${API}/store/delivery-zones/${currentGroup.id}`);
        const data = await res.json();
        if (data.success) { deliveryZonesCache = data.zones; window.renderDeliveryZonesList(); }
    } catch(e) {}
};

window.renderDeliveryZonesList = function() {
    const list = document.getElementById('delivery-zones-list');
    if (!list) return;
    if (!deliveryZonesCache.length) {
        list.innerHTML = '<p class="text-xs text-slate-400 text-center py-3">לא הוגדרו אזורי משלוח</p>';
        return;
    }
    list.innerHTML = deliveryZonesCache.map(z => `
        <div class="flex justify-between items-center bg-slate-50 border border-slate-200 rounded-xl px-3 py-2">
            <div>
                <span class="text-sm font-bold text-slate-700">${safeStr(z.name)}</span>
                <span class="text-[11px] text-slate-400 mr-2">מינימום ₪${z.min_order||0} · משלוח ₪${z.delivery_fee||0}</span>
            </div>
            <button onclick="window.deleteDeliveryZone(${z.id})" class="text-red-400 hover:text-red-600 w-7 h-7 flex items-center justify-center rounded-full hover:bg-red-50 transition"><i class="fa-solid fa-trash text-xs"></i></button>
        </div>
    `).join('');
};

window.openDeliveryZoneModal = function() {
    const existing = document.getElementById('delivery-zone-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'delivery-zone-modal';
    modal.className = 'fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[99999] flex items-center justify-center p-4';
    modal.innerHTML = `
        <div class="bg-white rounded-[2rem] w-full max-w-sm p-6 shadow-2xl">
            <h3 class="font-black text-slate-800 text-lg mb-4">🛵 אזור משלוח חדש</h3>
            <div class="space-y-3">
                <input type="text" id="dz-name" placeholder="שם האזור (למשל: תל אביב, אזור מרכז)" class="modern-input py-2.5 text-sm w-full">
                <div class="grid grid-cols-2 gap-3">
                    <div><label class="text-[10px] font-bold text-slate-500 block mb-1">מינימום הזמנה ₪</label><input type="number" id="dz-min" value="0" min="0" class="modern-input py-2 text-sm w-full"></div>
                    <div><label class="text-[10px] font-bold text-slate-500 block mb-1">עלות משלוח ₪</label><input type="number" id="dz-fee" value="0" min="0" class="modern-input py-2 text-sm w-full"></div>
                </div>
            </div>
            <div class="flex gap-3 mt-5">
                <button onclick="document.getElementById('delivery-zone-modal').remove()" class="flex-1 bg-slate-100 text-slate-600 py-3 rounded-xl font-bold hover:bg-slate-200 transition text-sm">ביטול</button>
                <button onclick="window.saveDeliveryZone()" class="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold shadow-md hover:bg-indigo-700 transition text-sm">שמור אזור</button>
            </div>
        </div>`;
    document.body.appendChild(modal);
    document.getElementById('dz-name').focus();
};

window.saveDeliveryZone = async function() {
    const name = document.getElementById('dz-name')?.value.trim();
    if (!name) { showToast('error', 'נדרש שם אזור'); return; }
    const min_order = parseFloat(document.getElementById('dz-min')?.value) || 0;
    const delivery_fee = parseFloat(document.getElementById('dz-fee')?.value) || 0;
    try {
        const res = await fetch(`${API}/store/delivery-zones`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ groupId: currentGroup.id, name, min_order, delivery_fee }) });
        const data = await res.json();
        if (data.success) { showToast('success', 'אזור משלוח נשמר!'); document.getElementById('delivery-zone-modal')?.remove(); await window.loadDeliveryZones(); }
        else showToast('error', data.error||'שגיאה');
    } catch(e) { showToast('error', 'שגיאת רשת'); }
};

window.deleteDeliveryZone = async function(id) {
    if (!await window._uiConfirm('למחוק אזור משלוח?', {danger:true, okLabel:'מחק'})) return;
    try {
        const res = await fetch(`${API}/store/delivery-zones/${id}`, { method:'DELETE' });
        const data = await res.json();
        if (data.success) { showToast('success', 'אזור נמחק'); await window.loadDeliveryZones(); }
    } catch(e) {}
};

// הצגת בורר אזור משלוח בקופה בעת בחירת "משלוח"
window.showPOSDeliveryZoneSelector = async function(container) {
    if (!deliveryZonesCache.length) { try { await window.loadDeliveryZones(); } catch(e) {} }
    if (!deliveryZonesCache.length || !container) return;
    const existing = container.querySelector('.pos-zone-selector');
    if (existing) existing.remove();
    const div = document.createElement('div');
    div.className = 'pos-zone-selector mt-2';
    div.innerHTML = `<label class="text-[10px] font-bold text-slate-500 block mb-1">אזור משלוח:</label>
        <select id="pos-delivery-zone" onchange="window.applyDeliveryZoneFee(this.value)" class="modern-input py-2 text-xs w-full">
            <option value="">— בחר אזור —</option>
            ${deliveryZonesCache.map(z=>`<option value="${z.id}" data-fee="${z.delivery_fee}" data-min="${z.min_order}">${safeStr(z.name)} (₪${z.delivery_fee} משלוח, מינימום ₪${z.min_order})</option>`).join('')}
        </select>`;
    container.appendChild(div);
};

window.applyDeliveryZoneFee = function(zoneId) {
    const sel = document.getElementById('pos-delivery-zone');
    const opt = sel?.options[sel?.selectedIndex];
    if (!opt || !zoneId) return;
    const fee = parseFloat(opt.dataset.fee) || 0;
    const feeInput = document.getElementById('pos-delivery-fee-input');
    if (feeInput) feeInput.value = fee;
    window.posDeliveryFee = fee;
};

// Hook into saveStoreSettings to also persist sport fields
(function() {
    const _origSave = window.saveStoreSettings;
    window.saveStoreSettings = async function() {
        if (currentGroup?.business_type === 'sport') {
            const sportSettings = {
                trial_enabled: document.getElementById('sport-trial-enabled')?.checked || false,
                cancellation_policy: document.getElementById('sport-cancellation-policy')?.value || '',
                freeze_policy: document.getElementById('sport-freeze-policy')?.value || '',
                waiver_text: document.getElementById('sport-waiver-text')?.value || '',
                min_age: parseInt(document.getElementById('sport-min-age')?.value) || null,
                cancel_notice_days: parseInt(document.getElementById('sport-cancel-notice-days')?.value) || null,
            };
            try {
                await fetch(`${API}/sport/store-settings`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ groupId: currentGroup.id, sportSettings })
                });
            } catch(e) {}
        }
        if (typeof _origSave === 'function') await _origSave();
    };
})();

// ─── rdAction routing for sport ───────────────────────────────────────────────
(function() {
    const orig = rdAction;
    window.rdAction = function(tab, action) {
        if (action === 'sport-checkin') { window.showSportCheckIn(); return; }
        if (action === 'sport-members') { window.showSportMembers(); return; }
        if (action === 'sport-add-member') { window.showSportAddMember(); return; }
        orig(tab, action);
    };
})();

// ─── Sport screen navigation (within app shell) ───────────────────────────────
function _ensureSportModal() {
    window._sportScreenActive = true;
    // Show content-feed directly without calling switchTab (avoids renderDashboard recursion)
    ['timeclock','shifts','calendar','shop','pantry','equipment','sales','pos','foodcost',
     'customers','bank','cashflow','budget','forecast','tasks','deliveries','academy',
     'community','members','surveys','role-dashboard'].forEach(x => {
        const el = document.getElementById(`content-${x}`); if (el) el.classList.add('hidden');
    });
    const _f = document.getElementById('content-feed');
    if (_f) _f.classList.remove('hidden');
    const _fb = document.getElementById('tab-feed');
    if (_fb) { document.querySelectorAll('[id^="tab-"]').forEach(b=>b.classList.remove('tab-active')); _fb.classList.add('tab-active'); }
    ['tour-balance-card','quick-tiles','admin-kpi-cards'].forEach(id => {
        const el = document.getElementById(id); if (el) el.classList.add('hidden');
    });
    const feedEl = document.getElementById('content-feed');
    if (!feedEl) return;
    // If sport-modal is already a direct child, reuse it. Otherwise clear and create.
    if (!feedEl.querySelector(':scope > #sport-modal')) {
        feedEl.innerHTML = '';
        const div = document.createElement('div');
        div.id = 'sport-modal';
        div.className = 'w-full flex flex-col min-h-0';
        div.style.minHeight = 'calc(100dvh - 130px)';
        feedEl.appendChild(div);
    }
}

window._sportBack = function() {
    window._sportScreenActive = false;
    const feedEl = document.getElementById('content-feed');
    if (feedEl) feedEl.innerHTML = '';
    if (window._roleDashInterval) clearInterval(window._roleDashInterval);
    if (currentGroup?.business_type === 'sport' && feedEl) {
        renderSportDashboard(feedEl);
        window._roleDashInterval = setInterval(() => {
            if (window._sportScreenActive) return;
            const feed = document.getElementById('content-feed');
            if (feed && !feed.classList.contains('hidden') && currentGroup?.business_type === 'sport') {
                renderSportDashboard(feed);
            } else { clearInterval(window._roleDashInterval); window._roleDashInterval = null; }
        }, 30000);
    }
};

