// ─── Alerts Screen ────────────────────────────────────────────────────────────
window.showSportAlerts = async function() {
    _ensureSportModal();
    const modal = document.getElementById('sport-modal');
    modal.innerHTML = `<div class="flex flex-col h-full">
        <div class="flex items-center justify-between p-4 border-b border-slate-100">
            <button onclick="window._sportBack()" class="text-slate-400 text-xl">✕</button>
            <h2 class="text-lg font-black text-slate-800">התראות 🔔</h2><span></span>
        </div>
        <div id="sport-alerts-content" class="flex-1 overflow-y-auto p-4"><div class="text-center py-8 text-slate-400">טוען...</div></div>
    </div>`;
    modal.classList.remove('hidden');
    try {
        const d = await fetch(`${API}/sport/alerts/${currentGroup.id}`).then(r=>r.json());
        const el = document.getElementById('sport-alerts-content');
        let html = '';
        if (d.expiring?.length) {
            html += `<div class="text-xs font-black text-orange-600 mb-2 text-right">⏳ פגים בקרוב (${d.expiring.length})</div>`;
            html += d.expiring.map(m => {
                const days = Math.ceil((new Date(m.end_date)-new Date())/86400000);
                return `<div class="bg-orange-50 border border-orange-100 rounded-xl p-3 mb-2 flex items-center justify-between">
                    <div class="flex gap-2">
                        <button onclick="window.showSportRenewMember(${m.id},'${(m.member_name||'').replace(/'/g,"\\'")}',${m.membership_type_id||'null'})" class="text-[11px] font-bold text-white bg-indigo-600 px-2 py-1 rounded-lg">חדש</button>
                        ${m.member_phone?`<a href="tel:${m.member_phone}" class="text-[11px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg">📞</a>`:''}
                    </div>
                    <div class="text-right"><div class="font-bold text-slate-800 text-sm">${m.member_name}</div>
                    <div class="text-[11px] text-orange-600">${days<=0?'פג!':'עוד '+days+' ימים'} · ${new Date(m.end_date).toLocaleDateString('he-IL')}</div></div>
                </div>`;
            }).join('');
        }
        if (d.atRisk?.length) {
            html += `<div class="text-xs font-black text-red-600 mt-4 mb-2 text-right">⚠️ לא אימנו 30 יום+ (${d.atRisk.length})</div>`;
            html += d.atRisk.map(m => `<div class="bg-red-50 border border-red-100 rounded-xl p-3 mb-2 flex items-center justify-between">
                <div>${m.member_phone?`<a href="tel:${m.member_phone}" class="text-[11px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg">📞</a>`:''}</div>
                <div class="text-right"><div class="font-bold text-slate-800 text-sm">${m.member_name}</div>
                <div class="text-[11px] text-red-500">ביקור אחרון: ${m.last_checkin?new Date(m.last_checkin).toLocaleDateString('he-IL'):'מעולם לא'}</div></div>
            </div>`).join('');
        }
        if (d.frozen?.length) {
            html += `<div class="text-xs font-black text-blue-600 mt-4 mb-2 text-right">❄️ מוקפאים (${d.frozen.length})</div>`;
            html += d.frozen.map(m => `<div class="bg-blue-50 border border-blue-100 rounded-xl p-3 mb-2 flex items-center justify-between">
                <button onclick="window.sportUnfreeze(${m.id})" class="text-[11px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg">הפשר</button>
                <div class="text-right"><div class="font-bold text-slate-800 text-sm">${m.member_name}</div>
                <div class="text-[11px] text-blue-500">הוקפא: ${m.frozen_at?new Date(m.frozen_at).toLocaleDateString('he-IL'):''} ${m.frozen_reason?'· '+m.frozen_reason:''}</div></div>
            </div>`).join('');
        }
        // Waitlist pending confirmations
        try {
            const wp = await fetch(`${API}/sport/waitlist-pending/${currentGroup.id}`).then(r=>r.json());
            if (wp.pending?.length) {
                html = `<div class="bg-amber-50 border border-amber-300 rounded-2xl p-3 mb-4 flex items-center justify-between cursor-pointer" onclick="window.showSportWaitlistPending()">
                    <span class="text-xs font-black text-amber-700">צפה ב-${wp.pending.length} ממתינים →</span>
                    <div class="text-right"><div class="font-black text-amber-800 text-sm">⏳ ממתינים לאישור מקום (${wp.pending.length})</div>
                    <div class="text-xs text-amber-600">פנה מקום מרשימת המתנה — יפוג תוך 30 דקות</div></div>
                </div>` + html;
            }
        } catch(e2) {}
        if (!html) html = `<div class="text-center py-8 text-slate-400 text-sm">אין התראות כרגע 🎉</div>`;
        el.innerHTML = html;
    } catch(e) { document.getElementById('sport-alerts-content').innerHTML = `<div class="text-center py-8 text-red-400 text-sm">שגיאה</div>`; }
};

// ─── Renew Member ─────────────────────────────────────────────────────────────
window.showSportRenewMember = async function(memberId, memberName, currentTypeId) {
    let types = [];
    try { types = (await fetch(`${API}/sport/membership-types/${currentGroup.id}`).then(r=>r.json())).types||[]; } catch(e) {}
    _ensureSportModal();
    const modal = document.getElementById('sport-modal');
    modal.innerHTML = `<div class="flex flex-col h-full">
        <div class="flex items-center justify-between p-4 border-b border-slate-100">
            <button onclick="window.showSportAlerts()" class="text-slate-400 text-xl">←</button>
            <h2 class="text-lg font-black text-slate-800">חידוש מנוי 🔄</h2><span></span>
        </div>
        <div class="flex-1 overflow-y-auto p-4 flex flex-col gap-4">
            <div class="bg-indigo-50 rounded-xl p-3 text-right"><div class="font-black text-indigo-800">${memberName}</div></div>
            <div>
                <label class="text-xs font-bold text-slate-600 block mb-1 text-right">סוג מנוי *</label>
                <select id="sport-renew-type" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-right text-sm">
                    <option value="">-- בחר --</option>
                    ${types.map(t=>`<option value="${t.id}" ${t.id==currentTypeId?'selected':''}>${t.name} — ₪${t.price}</option>`).join('')}
                </select>
            </div>
            <div>
                <label class="text-xs font-bold text-slate-600 block mb-1 text-right">תאריך התחלה</label>
                <input id="sport-renew-start" type="date" value="${new Date().toISOString().split('T')[0]}" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm"/>
            </div>
            <div class="border-t pt-4">
                <div class="text-xs font-black text-slate-600 mb-2 text-right">תשלום (אופציונלי)</div>
                <div class="grid grid-cols-2 gap-2">
                    <select id="sport-renew-pay-method" class="border border-slate-200 rounded-xl px-3 py-2 text-right text-sm">
                        <option value="cash">מזומן</option><option value="credit">אשראי</option>
                        <option value="transfer">העברה</option><option value="app">אפליקציה</option>
                    </select>
                    <input id="sport-renew-pay-amount" type="number" placeholder="סכום ₪" class="border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
                </div>
            </div>
        </div>
        <div class="p-4 border-t">
            <button onclick="window._sportSubmitRenew(${memberId},'${(memberName||'').replace(/'/g,"\\'")}')" class="w-full bg-indigo-600 text-white font-black py-3 rounded-2xl text-sm">חדש מנוי ✅</button>
        </div>
    </div>`;
    modal.classList.remove('hidden');
};

window._sportSubmitRenew = async function(memberId, memberName) {
    const typeId = document.getElementById('sport-renew-type')?.value;
    const startDate = document.getElementById('sport-renew-start')?.value;
    const payAmount = document.getElementById('sport-renew-pay-amount')?.value;
    const payMethod = document.getElementById('sport-renew-pay-method')?.value;
    if (!typeId) { showToast('error','יש לבחור סוג מנוי'); return; }
    try {
        const d = await fetch(`${API}/sport/members/${memberId}/renew`,{
            method:'POST',headers:{'Content-Type':'application/json'},
            body:JSON.stringify({membershipTypeId:parseInt(typeId),startDate,paymentAmount:payAmount?parseFloat(payAmount):null,paymentMethod:payMethod})
        }).then(r=>r.json());
        if (!d.success){showToast('error',d.error||'שגיאה');return;}
        showToast('success',`מנויו של ${memberName} חודש 🎉`);
        window._sportBack();
    } catch(e){showToast('error','שגיאת תקשורת');}
};

// ─── Member Detail Screen ─────────────────────────────────────────────────────
window.showSportMemberDetail = async function(memberId) {
    _ensureSportModal();
    const modal = document.getElementById('sport-modal');
    modal.innerHTML = `<div class="flex flex-col h-full">
        <div class="flex items-center justify-between p-4 border-b border-slate-100">
            <button onclick="window.showSportMembers()" class="text-slate-400 text-xl">←</button>
            <h2 class="text-lg font-black text-slate-800">פרופיל חבר</h2><span></span>
        </div>
        <div id="sport-member-detail-content" class="flex-1 overflow-y-auto p-4"><div class="text-center py-8 text-slate-400">טוען...</div></div>
    </div>`;
    modal.classList.remove('hidden');
    try {
        const d = await fetch(`${API}/sport/member-detail/${memberId}`).then(r=>r.json());
        if (!d.member){document.getElementById('sport-member-detail-content').innerHTML='<div class="text-center py-8 text-red-400">לא נמצא</div>';return;}
        const m = d.member;
        const sc = {active:'emerald',frozen:'blue',expired:'red',cancelled:'slate'}[m.status]||'slate';
        const sl = {active:'פעיל',frozen:'מוקפא',expired:'פג תוקף',cancelled:'בוטל'}[m.status]||m.status;
        const endFmt = m.end_date?new Date(m.end_date).toLocaleDateString('he-IL'):'—';
        const startFmt = m.start_date?new Date(m.start_date).toLocaleDateString('he-IL'):'—';
        const sessions = m.sessions_total!=null?`<div class="text-sm text-slate-600 text-right mt-1">כניסות: <span class="font-bold">${m.sessions_total-(m.sessions_used||0)}/${m.sessions_total}</span> נותרו</div>`:'';
        const totalPaid = (d.payments||[]).reduce((s,p)=>s+parseFloat(p.amount||0),0);
        const checkinRows = (d.checkins||[]).slice(0,10).map(c=>{
            const t=c.checked_in_at?new Date(c.checked_in_at).toLocaleString('he-IL',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'';
            return `<div class="flex justify-between text-xs py-1 border-b border-slate-50"><span class="text-slate-400">${t}</span><span class="text-slate-600">כניסה</span></div>`;
        }).join('')||'<div class="text-xs text-slate-400 text-center py-2">אין כניסות</div>';
        const classRows = (d.classes||[]).slice(0,10).map(c=>`<div class="flex justify-between text-xs py-1 border-b border-slate-50">
            <span class="${c.attended?'text-emerald-500':'text-slate-400'}">${c.attended?'✅':'❌'}</span>
            <span class="text-slate-600">${c.class_name||''} · ${c.class_date?new Date(c.class_date).toLocaleDateString('he-IL'):''}</span>
        </div>`).join('');
        const payRows = (d.payments||[]).map(p=>{
            const mt={cash:'מזומן',credit:'אשראי',transfer:'העברה',app:'אפליקציה'}[p.payment_method]||p.payment_method;
            return `<div class="flex justify-between text-xs py-1 border-b border-slate-50">
                <span class="text-slate-400">${p.paid_at?new Date(p.paid_at).toLocaleDateString('he-IL'):''} · ${mt}</span>
                <span class="font-bold text-emerald-600">₪${parseFloat(p.amount).toLocaleString('he-IL')}</span>
            </div>`;
        }).join('')||'<div class="text-xs text-slate-400 text-center py-2">אין תשלומים</div>';

        document.getElementById('sport-member-detail-content').innerHTML = `
            <div class="bg-indigo-50 rounded-2xl p-4 mb-4 text-right">
                <div class="flex items-center justify-between mb-2">
                    <span class="text-xs font-bold px-2 py-0.5 rounded-full bg-${sc}-100 text-${sc}-700">${sl}</span>
                    <div><div class="text-lg font-black text-indigo-800">${m.member_name}</div>
                    ${m.member_phone?`<div class="text-xs text-slate-500">${m.member_phone}</div>`:''}
                    ${m.member_email?`<div class="text-xs text-slate-400">${m.member_email}</div>`:''}
                    </div>
                </div>
                <div class="grid grid-cols-2 gap-2 text-xs text-right mt-2">
                    <div><span class="text-slate-500">מנוי:</span> <span class="font-bold">${m.type_name||'—'}</span></div>
                    <div><span class="text-slate-500">סה"כ שילם:</span> <span class="font-bold text-emerald-600">₪${totalPaid.toLocaleString('he-IL')}</span></div>
                    <div><span class="text-slate-500">התחלה:</span> <span class="font-bold">${startFmt}</span></div>
                    <div><span class="text-slate-500">סיום:</span> <span class="font-bold">${endFmt}</span></div>
                </div>${sessions}
            </div>
            <div class="flex gap-2 mb-4 flex-wrap">
                <button onclick="window.showSportRenewMember(${m.id},'${(m.member_name||'').replace(/'/g,"\\'")}',${m.membership_type_id||'null'})" class="flex-1 min-w-[80px] bg-indigo-600 text-white font-bold py-2 rounded-xl text-xs">חדש 🔄</button>
                ${m.status==='active'?`<button onclick="window.showSportFreeze(${m.id},'${(m.member_name||'').replace(/'/g,"\\'")}');window.showSportMembers()" class="flex-1 min-w-[80px] bg-blue-100 text-blue-700 font-bold py-2 rounded-xl text-xs">הקפא ❄️</button>`:''}
                ${m.status==='frozen'?`<button onclick="window.sportUnfreeze(${m.id})" class="flex-1 min-w-[80px] bg-emerald-100 text-emerald-700 font-bold py-2 rounded-xl text-xs">הפשר ☀️</button>`:''}
                <button onclick="window._sportAddPayment(${m.id},'${(m.member_name||'').replace(/'/g,"\\'")}',${m.type_price||0})" class="flex-1 min-w-[80px] bg-emerald-100 text-emerald-700 font-bold py-2 rounded-xl text-xs">תשלום 💰</button>
            </div>
            <div class="mb-4"><div class="text-xs font-black text-slate-600 mb-2 text-right">כניסות אחרונות</div>${checkinRows}</div>
            ${d.classes?.length?`<div class="mb-4"><div class="text-xs font-black text-slate-600 mb-2 text-right">שיעורים</div>${classRows}</div>`:''}
            <div class="mb-4"><div class="text-xs font-black text-slate-600 mb-2 text-right">תשלומים</div>${payRows}</div>`;
    } catch(e){document.getElementById('sport-member-detail-content').innerHTML='<div class="text-center py-8 text-red-400">שגיאה</div>';}
};

window._sportAddPayment = function(memberId, memberName, suggestedAmount) {
    const existing = document.getElementById('sport-payment-overlay');
    if (existing) existing.remove();
    const overlay = document.createElement('div');
    overlay.id = 'sport-payment-overlay';
    overlay.className = 'fixed inset-0 bg-black/50 z-[300] flex items-end sm:items-center justify-center p-0 sm:p-4';
    overlay.innerHTML = `<div class="bg-white w-full sm:max-w-sm rounded-t-3xl sm:rounded-2xl p-6 text-right shadow-2xl">
        <div class="flex items-center justify-between mb-4">
            <button onclick="document.getElementById('sport-payment-overlay').remove()" class="w-8 h-8 bg-slate-100 rounded-full flex items-center justify-center text-slate-500">✕</button>
            <div>
                <div class="text-lg font-black text-slate-800">רישום תשלום 💰</div>
                <div class="text-sm text-slate-500">${memberName}</div>
            </div>
        </div>
        <div class="space-y-3">
            <div>
                <label class="text-xs font-bold text-slate-600 block mb-1">סכום (₪)</label>
                <input id="sport-pay-amount" type="number" value="${suggestedAmount||''}" placeholder="0"
                    class="w-full border border-slate-200 rounded-xl px-4 py-3 text-right text-sm focus:outline-none focus:ring-2 focus:ring-emerald-300"/>
            </div>
            <div>
                <label class="text-xs font-bold text-slate-600 block mb-1">אמצעי תשלום</label>
                <div class="grid grid-cols-4 gap-2">
                    <button onclick="window._sportSelectPayMethod(this,'cash')" data-method="cash" class="sport-pay-method-btn py-2 rounded-xl text-xs font-bold border-2 border-emerald-500 bg-emerald-50 text-emerald-700">מזומן</button>
                    <button onclick="window._sportSelectPayMethod(this,'credit')" data-method="credit" class="sport-pay-method-btn py-2 rounded-xl text-xs font-bold border border-slate-200 bg-slate-50 text-slate-600">אשראי</button>
                    <button onclick="window._sportSelectPayMethod(this,'transfer')" data-method="transfer" class="sport-pay-method-btn py-2 rounded-xl text-xs font-bold border border-slate-200 bg-slate-50 text-slate-600">העברה</button>
                    <button onclick="window._sportSelectPayMethod(this,'app')" data-method="app" class="sport-pay-method-btn py-2 rounded-xl text-xs font-bold border border-slate-200 bg-slate-50 text-slate-600">אפליקציה</button>
                </div>
                <input type="hidden" id="sport-pay-method" value="cash"/>
            </div>
            <div id="sport-pay-result"></div>
            <button onclick="window._sportConfirmPayment(${memberId},'${memberName.replace(/'/g,"\\'")}')" class="w-full bg-emerald-600 text-white font-black py-3.5 rounded-2xl text-sm active:scale-95 transition">אשר תשלום ✅</button>
            <button onclick="document.getElementById('sport-payment-overlay').remove()" class="w-full bg-slate-100 text-slate-600 font-bold py-2.5 rounded-2xl text-sm">ביטול</button>
        </div>
    </div>`;
    document.body.appendChild(overlay);
};

window._sportSelectPayMethod = function(btn, method) {
    document.querySelectorAll('.sport-pay-method-btn').forEach(b => {
        b.className = 'sport-pay-method-btn py-2 rounded-xl text-xs font-bold border border-slate-200 bg-slate-50 text-slate-600';
    });
    btn.className = 'sport-pay-method-btn py-2 rounded-xl text-xs font-bold border-2 border-emerald-500 bg-emerald-50 text-emerald-700';
    document.getElementById('sport-pay-method').value = method;
};

window._sportConfirmPayment = async function(memberId, memberName) {
    const amount = parseFloat(document.getElementById('sport-pay-amount')?.value);
    const method = document.getElementById('sport-pay-method')?.value || 'cash';
    const resEl  = document.getElementById('sport-pay-result');
    if (!amount || isNaN(amount) || amount <= 0) {
        if (resEl) resEl.innerHTML = `<div class="text-red-500 text-sm text-center mb-2">יש להזין סכום תקין</div>`;
        return;
    }
    try {
        const d = await fetch(`${API}/sport/payments`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ groupId: currentGroup.id, membershipId: memberId, memberName, amount, paymentMethod: method })
        }).then(r => r.json());
        if (d.success) {
            document.getElementById('sport-payment-overlay')?.remove();
            showToast('success', `תשלום ₪${amount} נרשם ✅`);
            window.showSportMemberDetail(memberId);
        } else {
            if (resEl) resEl.innerHTML = `<div class="text-red-500 text-sm text-center mb-2">${d.error||'שגיאה'}</div>`;
        }
    } catch(e) { showToast('error', 'שגיאת תקשורת'); }
};

// ─── Updated Member Card (with detail tap + expiry warning) ──────────────────
function _sportMemberCard(m) {
    const sc={active:'emerald',frozen:'blue',expired:'red',cancelled:'slate'}[m.status]||'slate';
    const sl={active:'פעיל',frozen:'מוקפא',expired:'פג תוקף',cancelled:'בוטל'}[m.status]||m.status;
    const endDate=m.end_date?new Date(m.end_date).toLocaleDateString('he-IL'):'—';
    const sessions=m.sessions_total!=null?`<span class="text-xs text-slate-500">${m.sessions_total-(m.sessions_used||0)}/${m.sessions_total}</span>`:'';
    const frozen=m.status==='frozen'?`<div class="text-[11px] text-blue-500 mt-0.5">מוקפא: ${m.frozen_reason||''}</div>`:'';
    const days=m.end_date?Math.ceil((new Date(m.end_date)-new Date())/86400000):null;
    const warn=days!==null&&days<=14&&m.status==='active'?`<span class="text-[10px] text-orange-500 font-bold">⏳ עוד ${days} ימים</span>`:'';
    return `<div class="bg-white border border-slate-100 rounded-2xl p-3 shadow-sm">
        <div class="flex items-center gap-3 mb-2 cursor-pointer" onclick="window.showSportMemberDetail(${m.id})">
            <div class="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-lg font-black text-indigo-600 flex-shrink-0">${(m.member_name||'?')[0]}</div>
            <div class="flex-1 min-w-0 text-right">
                <div class="font-bold text-slate-800 text-sm">${m.member_name||''}</div>
                <div class="text-[11px] text-slate-500">${m.member_phone||''} ${m.type_name?'· '+m.type_name:''}</div>${frozen}
            </div>
            <span class="text-xs font-bold px-2 py-0.5 rounded-full bg-${sc}-100 text-${sc}-700 flex-shrink-0">${sl}</span>
        </div>
        <div class="flex items-center justify-between text-[11px] border-t border-slate-50 pt-2">
            <div class="flex gap-1.5">
                ${m.status==='active'?`<button onclick="window._sportDoCheckin(${m.id},'${(m.member_name||'').replace(/'/g,"\\'")}','${m.status}')" class="font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded-lg">כניסה ✅</button>`:''}
                ${m.status==='active'?`<button onclick="window.showSportFreeze(${m.id},'${(m.member_name||'').replace(/'/g,"\\'")}')}" class="font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-lg">❄️</button>`:''}
                ${m.status==='frozen'?`<button onclick="window.sportUnfreeze(${m.id})" class="font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg">הפשר ☀️</button>`:''}
                ${(m.status==='expired'||(days!==null&&days<=7))?`<button onclick="window.showSportRenewMember(${m.id},'${(m.member_name||'').replace(/'/g,"\\'")}',${m.membership_type_id||'null'})" class="font-bold text-orange-600 bg-orange-50 px-2 py-1 rounded-lg">חדש</button>`:''}
            </div>
            <div class="text-right text-slate-500">${warn} ${sessions} עד ${endDate}</div>
        </div>
    </div>`;
}

// ─── Group Classes Schedule ───────────────────────────────────────────────────
window.showSportSchedule = async function() {
    _ensureSportModal();
    const modal = document.getElementById('sport-modal');
    const today = new Date().toISOString().split('T')[0];
    const toD = new Date(); toD.setDate(toD.getDate()+14);
    const toDate = toD.toISOString().split('T')[0];
    modal.innerHTML = `<div class="flex flex-col h-full">
        <div class="flex items-center justify-between p-4 border-b border-slate-100">
            <button onclick="window._sportBack()" class="text-slate-400 text-xl">✕</button>
            <h2 class="text-lg font-black text-slate-800">לוח שיעורים 🗓️</h2>
            <button onclick="window.showSportAddClass()" class="bg-indigo-600 text-white text-xs font-bold px-3 py-1.5 rounded-lg">+ שיעור</button>
        </div>
        <div id="sport-schedule-list" class="flex-1 overflow-y-auto p-4"><div class="text-center py-8 text-slate-400">טוען...</div></div>
    </div>`;
    modal.classList.remove('hidden');
    window._sportLoadSchedule(today, toDate);
};

window._sportLoadSchedule = async function(from, to) {
    const el = document.getElementById('sport-schedule-list');
    if (!el) return;
    try {
        const d = await fetch(`${API}/sport/classes/${currentGroup.id}?from=${from}&to=${to}`).then(r=>r.json());
        const classes = d.classes||[];
        if (!classes.length){el.innerHTML=`<div class="text-center py-8 text-slate-400 text-sm">אין שיעורים מתוכננים<br><button onclick="window.showSportAddClass()" class="mt-3 text-indigo-600 font-bold text-sm underline">הוסף שיעור ראשון</button></div>`;return;}
        const byDate={};
        classes.forEach(c=>{if(!byDate[c.class_date])byDate[c.class_date]=[];byDate[c.class_date].push(c);});
        const days=['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
        const colorMap={indigo:'bg-indigo-50 border-indigo-200 text-indigo-700',violet:'bg-violet-50 border-violet-200 text-violet-700',emerald:'bg-emerald-50 border-emerald-200 text-emerald-700',orange:'bg-orange-50 border-orange-200 text-orange-700',red:'bg-red-50 border-red-200 text-red-700',blue:'bg-blue-50 border-blue-200 text-blue-700',teal:'bg-teal-50 border-teal-200 text-teal-700'};
        el.innerHTML = Object.keys(byDate).sort().map(date=>{
            const d2=new Date(date);
            const isToday=date===new Date().toISOString().split('T')[0];
            return `<div class="mb-4">
                <div class="text-xs font-black ${isToday?'text-indigo-600':'text-slate-500'} mb-2 text-right">${isToday?'📍 היום — ':''}${days[d2.getDay()]} ${d2.toLocaleDateString('he-IL',{day:'2-digit',month:'2-digit'})}</div>
                ${byDate[date].map(c=>{
                    const cls=colorMap[c.color]||colorMap.indigo;
                    const fill=Math.min(100,Math.round((c.registered_count/(c.capacity||20))*100));
                    const full=parseInt(c.registered_count)>=(c.capacity||20);
                    return `<div class="border rounded-2xl p-3 mb-2 ${cls}">
                        <div class="flex items-start justify-between">
                            <div class="flex gap-1.5">
                                <button onclick="window.showSportClassDetail(${c.id})" class="text-[11px] font-bold px-2 py-1 rounded-lg bg-white/70">נוכחות</button>
                                <button onclick="window._sportDeleteClass(${c.id})" class="text-[11px] text-red-400 px-1">🗑️</button>
                            </div>
                            <div class="text-right">
                                <div class="font-black text-sm">${c.class_name||c.type_name||'שיעור'}</div>
                                <div class="text-[11px]">${c.start_time?c.start_time.substring(0,5):''}${c.end_time?'–'+c.end_time.substring(0,5):''}${c.trainer_name?' · '+c.trainer_name:''}</div>
                            </div>
                        </div>
                        <div class="mt-2 flex items-center justify-between">
                            <span class="text-[11px] font-bold ${full?'text-red-600':''}">${c.registered_count}/${c.capacity} ${full?'🔴 מלא':''}</span>
                            <div class="w-24 h-1.5 bg-white/50 rounded-full overflow-hidden"><div class="h-full rounded-full ${full?'bg-red-500':'bg-current opacity-60'}" style="width:${fill}%"></div></div>
                        </div>
                    </div>`;
                }).join('')}
            </div>`;
        }).join('');
    } catch(e){el.innerHTML=`<div class="text-center py-8 text-red-400 text-sm">שגיאה</div>`;}
};

window.showSportAddClass = async function() {
    let types=[];
    try{types=(await fetch(`${API}/sport/class-types/${currentGroup.id}`).then(r=>r.json())).types||[];}catch(e){}
    _ensureSportModal();
    const modal=document.getElementById('sport-modal');
    modal.innerHTML=`<div class="flex flex-col h-full">
        <div class="flex items-center justify-between p-4 border-b border-slate-100">
            <button onclick="window.showSportSchedule()" class="text-slate-400 text-xl">←</button>
            <h2 class="text-lg font-black text-slate-800">שיעור חדש</h2><span></span>
        </div>
        <div class="flex-1 overflow-y-auto p-4 flex flex-col gap-3">
            <div><label class="text-xs font-bold text-slate-600 block mb-1 text-right">שם השיעור *</label>
                <input id="sport-cls-name" type="text" placeholder="לדוג׳ יוגה, ספינינג..." class="w-full border border-slate-200 rounded-xl px-4 py-3 text-right text-sm"/></div>
            ${types.length?`<div><label class="text-xs font-bold text-slate-600 block mb-1 text-right">סוג שיעור</label>
                <select id="sport-cls-type" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-right text-sm">
                    <option value="">-- ללא --</option>${types.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}
                </select></div>`:''}
            <div><label class="text-xs font-bold text-slate-600 block mb-1 text-right">מאמן/ת</label>
                <input id="sport-cls-trainer" type="text" placeholder="שם המאמן" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-right text-sm"/></div>
            <div><label class="text-xs font-bold text-slate-600 block mb-1 text-right">תאריך *</label>
                <input id="sport-cls-date" type="date" value="${new Date().toISOString().split('T')[0]}" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm"/></div>
            <div class="grid grid-cols-2 gap-2">
                <div><label class="text-xs font-bold text-slate-600 block mb-1 text-right">שעת סיום</label>
                    <input id="sport-cls-end" type="time" class="w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"/></div>
                <div><label class="text-xs font-bold text-slate-600 block mb-1 text-right">שעת התחלה</label>
                    <input id="sport-cls-start" type="time" class="w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"/></div>
            </div>
            <div><label class="text-xs font-bold text-slate-600 block mb-1 text-right">קיבולת</label>
                <input id="sport-cls-cap" type="number" value="20" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm"/></div>
        </div>
        <div class="p-4 border-t">
            <button onclick="window._sportSubmitClass()" class="w-full bg-indigo-600 text-white font-black py-3 rounded-2xl text-sm">שמור שיעור ✅</button>
        </div>
    </div>`;
    modal.classList.remove('hidden');
};

window._sportSubmitClass = async function() {
    const name=document.getElementById('sport-cls-name')?.value?.trim();
    const date=document.getElementById('sport-cls-date')?.value;
    if(!name||!date){showToast('error','שם ותאריך הם שדות חובה');return;}
    try{
        const d=await fetch(`${API}/sport/classes`,{method:'POST',headers:{'Content-Type':'application/json'},
            body:JSON.stringify({groupId:currentGroup.id,classTypeId:document.getElementById('sport-cls-type')?.value||null,
            className:name,trainerName:document.getElementById('sport-cls-trainer')?.value?.trim()||'',
            classDate:date,startTime:document.getElementById('sport-cls-start')?.value||null,
            endTime:document.getElementById('sport-cls-end')?.value||null,
            capacity:parseInt(document.getElementById('sport-cls-cap')?.value)||20})
        }).then(r=>r.json());
        if(!d.success){showToast('error',d.error||'שגיאה');return;}
        showToast('success','שיעור נוסף ✅');
        window.showSportSchedule();
    }catch(e){showToast('error','שגיאת תקשורת');}
};

window._sportDeleteClass = async function(classId) {
    if(!await window._uiConfirm('למחוק שיעור זה?', {danger:true, okLabel:'מחק'}))return;
    try{await fetch(`${API}/sport/classes/${classId}`,{method:'DELETE'});showToast('success','נמחק');window.showSportSchedule();}
    catch(e){showToast('error','שגיאת תקשורת');}
};

// ─── Class Detail & Attendance ────────────────────────────────────────────────
window.showSportClassDetail = async function(classId) {
    _ensureSportModal();
    const modal=document.getElementById('sport-modal');
    modal.innerHTML=`<div class="flex flex-col h-full">
        <div class="flex items-center justify-between p-4 border-b border-slate-100">
            <button onclick="window.showSportSchedule()" class="text-slate-400 text-xl">←</button>
            <h2 class="text-lg font-black text-slate-800">נוכחות בשיעור</h2><span></span>
        </div>
        <div id="sport-class-detail-content" class="flex-1 overflow-y-auto p-4"><div class="text-center py-8 text-slate-400">טוען...</div></div>
    </div>`;
    modal.classList.remove('hidden');
    try{
        const d=await fetch(`${API}/sport/classes/${classId}/registrations`).then(r=>r.json());
        const regs=d.registrations||[];
        const el=document.getElementById('sport-class-detail-content');
        if(!regs.length){
            el.innerHTML=`<div class="text-center py-8 text-slate-400 text-sm">אין נרשמים לשיעור זה</div>
                <div class="p-4"><button onclick="window._sportRegisterToClass(${classId})" class="w-full bg-indigo-600 text-white font-black py-3 rounded-2xl text-sm">הוסף נרשם ➕</button></div>`;
            return;
        }
        el.innerHTML=`<div class="text-xs font-black text-slate-500 mb-3 text-right">סמן נוכחות (${regs.length} נרשמים)</div>
            ${regs.map(r2=>`<label class="flex items-center justify-between bg-slate-50 rounded-xl p-3 mb-2 cursor-pointer">
                <input type="checkbox" id="att-${r2.membership_id}" ${r2.attended?'checked':''} class="w-5 h-5 accent-indigo-600"/>
                <span class="font-bold text-slate-800 text-sm">${r2.member_name||''}</span>
            </label>`).join('')}
            <div class="mt-4 flex gap-2">
                <button onclick="window._sportSaveAttendance(${classId},[${regs.map(r2=>r2.membership_id).join(',')}])" class="flex-1 bg-indigo-600 text-white font-black py-3 rounded-2xl text-sm">שמור נוכחות ✅</button>
                <button onclick="window._sportRegisterToClass(${classId})" class="flex-1 bg-slate-100 text-slate-700 font-bold py-3 rounded-2xl text-sm">+ הוסף</button>
            </div>`;
    }catch(e){document.getElementById('sport-class-detail-content').innerHTML='<div class="text-center py-8 text-red-400 text-sm">שגיאה</div>';}
};

window._sportSaveAttendance = async function(classId, memberIds) {
    const presentIds=memberIds.filter(id=>document.getElementById(`att-${id}`)?.checked);
    try{
        const d=await fetch(`${API}/sport/classes/${classId}/attendance`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({presentIds})}).then(r=>r.json());
        if(!d.success){showToast('error',d.error||'שגיאה');return;}
        showToast('success',`נוכחות נשמרה ✅ (${presentIds.length} נוכחים)`);
        window.showSportSchedule();
    }catch(e){showToast('error','שגיאת תקשורת');}
};

window._sportRegisterToClass = async function(classId) {
    const q=await window._uiPrompt('שם חבר לרישום:');
    if(!q)return;
    try{
        const members=(await fetch(`${API}/sport/members/${currentGroup.id}?q=${encodeURIComponent(q)}`).then(r=>r.json())).members||[];
        if(!members.length){showToast('error','חבר לא נמצא');return;}
        const m=members[0];
        const d=await fetch(`${API}/sport/classes/${classId}/register`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({membershipId:m.id,memberName:m.member_name})}).then(r=>r.json());
        if(!d.success){showToast('error',d.error||'שגיאה');return;}
        showToast('success',`${m.member_name} נרשם/ה ✅`);
        window.showSportClassDetail(classId);
    }catch(e){showToast('error','שגיאת תקשורת');}
};

// ─── Reports Screen ───────────────────────────────────────────────────────────
window.showSportReports = async function() {
    _ensureSportModal();
    const modal=document.getElementById('sport-modal');
    modal.innerHTML=`<div class="flex flex-col h-full">
        <div class="flex items-center justify-between p-4 border-b border-slate-100">
            <button onclick="window._sportBack()" class="text-slate-400 text-xl">✕</button>
            <h2 class="text-lg font-black text-slate-800">דוחות 📊</h2>
            <select id="sport-report-period" onchange="window._sportLoadReports(this.value)" class="text-xs border border-slate-200 rounded-lg px-2 py-1">
                <option value="month">החודש</option><option value="year">השנה</option>
            </select>
        </div>
        <div id="sport-reports-content" class="flex-1 overflow-y-auto p-4"><div class="text-center py-8 text-slate-400">טוען...</div></div>
    </div>`;
    modal.classList.remove('hidden');
    window._sportLoadReports('month');
};

window._sportLoadReports = async function(period) {
    const el=document.getElementById('sport-reports-content');
    if(!el)return;
    try{
        const d=await fetch(`${API}/sport/reports/${currentGroup.id}?period=${period}`).then(r=>r.json());
        const sl={active:'פעיל',frozen:'מוקפא',expired:'פג',cancelled:'בוטל'};
        const totalRev=(d.revenueByType||[]).reduce((s,t)=>s+parseFloat(t.total||0),0);
        const totalMem=(d.membersByStatus||[]).reduce((s,m)=>s+parseInt(m.count||0),0);
        const revRows=(d.revenueByType||[]).map(t=>`<div class="flex items-center justify-between py-2 border-b border-slate-50">
            <span class="font-bold text-emerald-600">₪${parseFloat(t.total||0).toLocaleString('he-IL',{maximumFractionDigits:0})}</span>
            <div class="text-right"><div class="text-sm font-bold text-slate-700">${t.type_name||'לא מוגדר'}</div><div class="text-xs text-slate-400">${t.count} מנויים</div></div>
        </div>`).join('')||'<div class="text-xs text-slate-400 text-center py-4">אין נתונים</div>';
        const memRows=(d.membersByStatus||[]).map(m=>`<div class="flex items-center justify-between py-2 border-b border-slate-50">
            <span class="font-bold text-slate-700">${m.count}</span>
            <span class="text-sm text-slate-600">${sl[m.status]||m.status}</span>
        </div>`).join('');
        const maxCheckins=Math.max(1,...(d.checkinsByDay||[]).map(c=>parseInt(c.count)));
        const checkinRows=(d.checkinsByDay||[]).slice(-14).map(c=>{
            const dt=new Date(c.day).toLocaleDateString('he-IL',{day:'2-digit',month:'2-digit'});
            const pct=Math.round((parseInt(c.count)/maxCheckins)*100);
            return `<div class="flex items-center gap-2 py-1">
                <span class="text-xs text-slate-400 w-12 text-left">${dt}</span>
                <div class="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden"><div class="h-full bg-indigo-400 rounded-full" style="width:${pct}%"></div></div>
                <span class="text-xs font-bold text-indigo-600 w-6">${c.count}</span>
            </div>`;
        }).join('')||'<div class="text-xs text-slate-400 text-center py-4">אין נתונים</div>';
        const monthRows=(d.revenueByMonth||[]).map(m=>{
            const[y,mo]=m.month.split('-');
            return `<div class="flex items-center justify-between py-1.5 border-b border-slate-50">
                <span class="font-bold text-emerald-600">₪${parseFloat(m.total||0).toLocaleString('he-IL',{maximumFractionDigits:0})}</span>
                <span class="text-xs text-slate-500">${mo}/${y} · ${m.count} עסקאות</span>
            </div>`;
        }).join('')||'<div class="text-xs text-slate-400 text-center py-4">אין נתונים</div>';
        el.innerHTML=`
            <div class="grid grid-cols-2 gap-3 mb-4">
                <div class="bg-emerald-50 rounded-2xl p-3 text-right"><div class="text-lg font-black text-emerald-700">₪${totalRev.toLocaleString('he-IL',{maximumFractionDigits:0})}</div><div class="text-[11px] text-emerald-500">${period==='year'?'הכנסות השנה':'הכנסות החודש'}</div></div>
                <div class="bg-indigo-50 rounded-2xl p-3 text-right"><div class="text-lg font-black text-indigo-700">${totalMem}</div><div class="text-[11px] text-indigo-500">סה"כ חברים</div></div>
            </div>
            <div class="mb-4"><div class="text-xs font-black text-slate-600 mb-2 text-right">הכנסות לפי סוג מנוי</div>${revRows}</div>
            <div class="mb-4"><div class="text-xs font-black text-slate-600 mb-2 text-right">סטטוס חברים</div>${memRows}</div>
            <div class="mb-4"><div class="text-xs font-black text-slate-600 mb-2 text-right">כניסות יומיות (14 ימים)</div>${checkinRows}</div>
            <div class="mb-4"><div class="text-xs font-black text-slate-600 mb-2 text-right">הכנסות לפי חודש</div>${monthRows}</div>`;
    }catch(e){el.innerHTML='<div class="text-center py-8 text-red-400 text-sm">שגיאה</div>';}
};

// ─── rdAction routing — sport Phase 2 ────────────────────────────────────────
(function(){
    const prev=window.rdAction;
    window.rdAction=function(tab,action){
        if(action==='sport-schedule'){window.showSportSchedule();return;}
        if(action==='sport-alerts')  {window.showSportAlerts();return;}
        if(action==='sport-reports') {window.showSportReports();return;}
        if(action==='sport-waivers') {window.showSportWaiverSettings();return;}
        prev(tab,action);
    };
})();

// ─── FamliAI sport AI — full implementation ──────────────────────────────────
(function(){
    const origSubmit = window.submitGlobalAI;
    window.submitGlobalAI = async function() {
        if (currentGroup?.business_type !== 'sport') {
            return origSubmit ? origSubmit.apply(this, arguments) : undefined;
        }
        const inputEl = getEl('global-ai-input');
        const query = inputEl ? inputEl.value.trim() : '';
        if (!query) return;
        const chatBox = getEl('global-ai-chat');
        if (chatBox) chatBox.innerHTML += `<div class="bg-indigo-600 text-white p-3 rounded-xl rounded-tl-none shadow-sm text-sm self-end max-w-[85%] fade-in">${safeStr(query)}</div>`;
        if (inputEl) inputEl.value = '';
        const btn = getEl('btn-global-ai-submit');
        if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i>'; }

        try {
            // Fetch rich sport data in parallel
            const [dashR, alertR, classR, payR] = await Promise.allSettled([
                fetch(`${API}/sport/dashboard/${currentGroup.id}`).then(r=>r.json()).catch(()=>({})),
                fetch(`${API}/sport/alerts/${currentGroup.id}`).then(r=>r.json()).catch(()=>({})),
                fetch(`${API}/sport/classes/${currentGroup.id}`).then(r=>r.json()).catch(()=>({})),
                fetch(`${API}/sport/payments/${currentGroup.id}`).then(r=>r.json()).catch(()=>({}))
            ]);
            const dash    = dashR.status==='fulfilled'    ? dashR.value    : {};
            const alerts  = alertR.status==='fulfilled'   ? alertR.value   : {};
            const clsData = classR.status==='fulfilled'   ? classR.value   : {};
            const payData = payR.status==='fulfilled'     ? payR.value     : {};

            const stats    = dash.stats || {};
            const classes  = clsData.classes || (Array.isArray(clsData) ? clsData : []);
            const payments = payData.payments || (Array.isArray(payData) ? payData : []);
            const now = new Date();

            // Revenue trend: current vs previous month
            const thisM = now.getMonth(), thisY = now.getFullYear();
            const prevMDate = new Date(thisY, thisM - 1, 1);
            const monthRevenue = payments.filter(p=>{ const d=new Date(p.payment_date||p.created_at); return d.getMonth()===thisM&&d.getFullYear()===thisY; }).reduce((s,p)=>s+(parseFloat(p.amount)||0),0);
            const prevRevenue  = payments.filter(p=>{ const d=new Date(p.payment_date||p.created_at); return d.getMonth()===prevMDate.getMonth()&&d.getFullYear()===prevMDate.getFullYear(); }).reduce((s,p)=>s+(parseFloat(p.amount)||0),0);

            // Churn risk: inactive 14+ days
            const atRisk = (alerts.atRisk||[]).map(m=>({
                id: m.id, name: m.member_name, phone: m.member_phone,
                days_inactive: m.last_checkin ? Math.floor((now-new Date(m.last_checkin))/86400000) : 99,
                last_visit: m.last_checkin
            })).sort((a,b)=>b.days_inactive-a.days_inactive);

            // Expiring soon with churn risk score
            const expiring = (alerts.expiring||[]).map(m=>({
                id: m.id, name: m.member_name, phone: m.member_phone,
                days_left: Math.ceil((new Date(m.end_date)-now)/86400000),
                type: m.membership_type || m.type_name
            })).sort((a,b)=>a.days_left-b.days_left);

            // Class occupancy analysis
            const upcoming = classes.filter(c=>new Date(c.start_time)>now).slice(0,10)
                .map(c=>({id:c.id,name:c.class_name||c.name,time:c.start_time,trainer:c.trainer_name,registered:c.registration_count||0,capacity:c.max_participants||0,fill_pct:c.max_participants>0?Math.round(((c.registration_count||0)/c.max_participants)*100):0}));
            const recentCls = classes.filter(c=>new Date(c.start_time)<=now).slice(0,5)
                .map(c=>({id:c.id,name:c.class_name||c.name,time:c.start_time,registered:c.registration_count||0,capacity:c.max_participants||0}));

            const sportContext = {
                business_type: 'sport',
                business_name: currentGroup.name,
                date_today: now.toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),
                kpis: {
                    total_members:    stats.total_members    || 0,
                    active_members:   stats.active_members   || 0,
                    frozen_members:   stats.frozen_members   || 0,
                    expiring_week:    stats.expiring_soon    || 0,
                    checkins_today:   stats.checkins_today   || 0,
                    checkins_week:    stats.checkins_week    || 0,
                    retention_pct:    stats.total_members>0 ? Math.round((stats.active_members/stats.total_members)*100) : 0
                },
                revenue: {
                    month_revenue:     monthRevenue,
                    prev_month_revenue: prevRevenue,
                    trend_pct:         prevRevenue>0 ? (((monthRevenue-prevRevenue)/prevRevenue)*100).toFixed(1) : null,
                    recent_payments:   payments.slice(0,8).map(p=>({name:p.member_name,amount:p.amount,type:p.payment_type,date:p.payment_date||p.created_at}))
                },
                churn_risk: {
                    at_risk_count:   atRisk.length,
                    top_at_risk:     atRisk.slice(0,8),
                    frozen_count:    (alerts.frozen||[]).length,
                    frozen_members:  (alerts.frozen||[]).slice(0,5).map(m=>({id:m.id,name:m.member_name,reason:m.frozen_reason}))
                },
                renewals: {
                    expiring_count:   expiring.length,
                    expiring_members: expiring.slice(0,10)
                },
                classes: {
                    upcoming_classes: upcoming,
                    recent_classes:   recentCls
                },
                open_tasks: (allTasks||[]).filter(t=>t.status==='pending').slice(0,5).map(t=>({title:t.title,assignee:t.assignee_name}))
            };

            const res = await fetch(`${API}/biz/chat-assistant`, {
                method: 'POST',
                headers: {'Content-Type':'application/json'},
                body: JSON.stringify({ query, context: JSON.stringify(sportContext), groupId: currentGroup.id })
            });
            const data = await res.json();
            if (!handleAIResponseCheck(data)) { getEl('global-ai-modal')?.classList.add('hidden'); return; }

            if (data.success && data.answer) {
                let answerText = data.answer;
                let actionHtml = '';

                // Excel exports (sport + generic)
                const excelMatch = answerText.match(/\[ACTION:EXPORT_EXCEL\|(.*?)\]/);
                if (excelMatch) {
                    const exportType = excelMatch[1].trim();
                    answerText = answerText.replace(excelMatch[0], '');
                    const exportLabels = {'sport-members':'חברים','sport-checkins':'כניסות','sport-revenue':'הכנסות','sport-classes':'שיעורים',orders:'הזמנות',cashflow:'תזרים',staff:'צוות'};
                    actionHtml += `<button onclick="window.downloadBizReport('${exportType}')" class="mt-3 w-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-file-excel"></i> הורד דוח ${exportLabels[exportType]||exportType} (Excel)</button>`;
                }
                // Task creation
                const taskMatch = answerText.match(/\[ACTION:ADD_TASK\|(.*?)\]/);
                if (taskMatch) {
                    const taskTitle = taskMatch[1].trim();
                    answerText = answerText.replace(taskMatch[0], '');
                    actionHtml += `<button onclick="document.getElementById('global-ai-modal').classList.add('hidden'); openTaskModal(); setTimeout(()=>document.getElementById('task-title').value='${safeStr(taskTitle)}',300);" class="mt-3 w-full bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-list-check"></i> פתיחת משימה: ${safeStr(taskTitle)}</button>`;
                }
                // Tab navigation
                const tabMatch = answerText.match(/\[ACTION:OPEN_TAB\|(.*?)\]/);
                if (tabMatch) {
                    const tabId = tabMatch[1].trim();
                    answerText = answerText.replace(tabMatch[0], '');
                    const tabLabels = {'sport-members':'חברים','sport-schedule':'לוח שיעורים','sport-alerts':'התראות','sport-payments':'תשלומים','sport-trainers':'מאמנים'};
                    actionHtml += `<button onclick="document.getElementById('global-ai-modal').classList.add('hidden'); switchTab('${tabId}')" class="mt-3 w-full bg-slate-50 text-slate-700 hover:bg-slate-100 border border-slate-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-arrow-left"></i> עבור ל${tabLabels[tabId]||tabId}</button>`;
                }
                // AI Action: הקפאת מנוי
                const freezeMatch = answerText.match(/\[ACTION:FREEZE_MEMBER\|(\d+)\|([^\]]*)\]/);
                if (freezeMatch) {
                    const fmId = freezeMatch[1], fmReason = freezeMatch[2];
                    answerText = answerText.replace(freezeMatch[0], '');
                    actionHtml += `<button onclick="window._aiFreezeMember(${fmId},'${safeStr(fmReason)}',this)" class="mt-3 w-full bg-blue-50 text-blue-700 hover:bg-blue-100 border border-blue-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-snowflake"></i> הקפא מנוי #${fmId}${fmReason?' — '+safeStr(fmReason):''}</button>`;
                }
                // AI Action: ביטול הקפאה
                const unfreezeMatch = answerText.match(/\[ACTION:UNFREEZE_MEMBER\|(\d+)\|([^\]]*)\]/);
                if (unfreezeMatch) {
                    const ufmId = unfreezeMatch[1], ufmName = unfreezeMatch[2];
                    answerText = answerText.replace(unfreezeMatch[0], '');
                    actionHtml += `<button onclick="window._aiUnfreezeMember(${ufmId},'${safeStr(ufmName)}',this)" class="mt-3 w-full bg-cyan-50 text-cyan-700 hover:bg-cyan-100 border border-cyan-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-fire"></i> הפשר מנוי: ${safeStr(ufmName)}</button>`;
                }
                // AI Action: כניסה ידנית
                const checkinMatch = answerText.match(/\[ACTION:CHECKIN_MEMBER\|(\d+)\|([^\]]*)\]/);
                if (checkinMatch) {
                    const chId = checkinMatch[1], chName = checkinMatch[2];
                    answerText = answerText.replace(checkinMatch[0], '');
                    actionHtml += `<button onclick="window._aiCheckinMember(${chId},'${safeStr(chName)}',this)" class="mt-3 w-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-person-walking-dashed-line-arrow-right"></i> רשום כניסה: ${safeStr(chName)}</button>`;
                }
                // AI Action: רישום לשיעור
                const regClassMatch = answerText.match(/\[ACTION:REGISTER_CLASS\|(\d+)\|(\d+)\|([^\]]*)\]/);
                if (regClassMatch) {
                    const rcClassId = regClassMatch[1], rcMembId = regClassMatch[2], rcName = regClassMatch[3];
                    answerText = answerText.replace(regClassMatch[0], '');
                    actionHtml += `<button onclick="window._aiRegisterClass(${rcClassId},${rcMembId},'${safeStr(rcName)}',this)" class="mt-3 w-full bg-violet-50 text-violet-700 hover:bg-violet-100 border border-violet-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-calendar-plus"></i> רשום ${safeStr(rcName)} לשיעור</button>`;
                }
                // AI Action Parser — יצירת משימה ישירה (גנרי)
                const createTaskMatch = answerText.match(/\[ACTION:CREATE_TASK\|([^|^\]]+)\|([^|^\]]*)\|?(\d*)\]/);
                if (createTaskMatch) {
                    const ctTitle = createTaskMatch[1].trim(), ctAssignee = (createTaskMatch[2]||'self').trim(), ctDays = parseInt(createTaskMatch[3])||1;
                    answerText = answerText.replace(createTaskMatch[0], '');
                    const ctLabel = ctAssignee === 'self' ? 'לי' : ctAssignee;
                    actionHtml += `<button onclick="window._aiCreateTask('${safeStr(ctTitle)}','${safeStr(ctAssignee)}',${ctDays},this)" class="mt-3 w-full bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-list-check"></i> צור משימה ל${ctLabel}: ${safeStr(ctTitle)}</button>`;
                }
                // AI Action Parser — יצירת כלל התראה (גנרי)
                const createAlertMatch = answerText.match(/\[ACTION:CREATE_ALERT_RULE\|([^|^\]]+)\|([^|^\]]+)\|(\d*)\|?([^\]]*)\]/);
                if (createAlertMatch) {
                    const arName = createAlertMatch[1].trim(), arTrigger = createAlertMatch[2].trim(), arCooldown = parseInt(createAlertMatch[3])||60, arDesc = (createAlertMatch[4]||'').trim();
                    answerText = answerText.replace(createAlertMatch[0], '');
                    const arTriggerLabels = {new_order:'הזמנה חדשה',order_timeout_15:'הזמנה לא מטופלת 15 דקות',order_timeout_30:'הזמנה לא מטופלת 30 דקות',new_lead:'פנייה חדשה',new_booking:'הזמנה/תור חדש',new_service_call:'קריאת שירות חדשה',payment_received:'תשלום התקבל',low_stock:'מלאי נמוך'};
                    actionHtml += `<button onclick="window._aiCreateAlertRule('${safeStr(arName)}','${arTrigger}',${arCooldown},'${safeStr(arDesc)}',this)" class="mt-3 w-full bg-yellow-50 text-yellow-700 hover:bg-yellow-100 border border-yellow-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-bell"></i> צור התראה: ${safeStr(arName)} — ${arTriggerLabels[arTrigger]||arTrigger}</button>`;
                }

                answerText = answerText.trim().replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');
                if (chatBox) { chatBox.innerHTML += `<div class="bg-white p-3.5 rounded-xl rounded-tr-none shadow-sm border border-slate-100 text-sm text-slate-700 self-start max-w-[85%] fade-in leading-relaxed">${answerText}${actionHtml}</div>`; chatBox.scrollTop = chatBox.scrollHeight; }
            } else { showToast('error', 'שגיאה בתשובת ה-AI'); }
        } catch(e) { showToast('error', 'תקלת רשת מול מנוע ה-AI'); }
        finally { if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-arrow-up"></i>'; } }
    };
})();

// ===== END SPORT PHASE 2+ =====

// ===== SPORT PHASE 3 EXTRAS — CLASS TYPES, RECURRING, WAITLIST =====

// ─── Class Types Management Screen ───────────────────────────────────────────
window.showSportClassTypes = async function() {
    _ensureSportModal();
    const modal = document.getElementById('sport-modal');
    const colors = ['indigo','violet','emerald','orange','red','blue','teal','pink'];
    modal.innerHTML = `<div class="flex flex-col h-full">
        <div class="flex items-center justify-between p-4 border-b border-slate-100">
            <button onclick="window.showSportSchedule()" class="text-slate-400 text-xl">←</button>
            <h2 class="text-lg font-black text-slate-800">סוגי שיעורים 🎽</h2>
            <span></span>
        </div>
        <div id="sport-class-types-list" class="flex-1 overflow-y-auto p-4 flex flex-col gap-2">
            <div class="text-center py-6 text-slate-400 text-sm">טוען...</div>
        </div>
        <div class="p-4 border-t border-slate-100">
            <div class="bg-slate-50 rounded-2xl p-4 flex flex-col gap-3">
                <div class="text-sm font-black text-slate-700 text-right">הוסף סוג שיעור</div>
                <input id="sport-ct-name" type="text" placeholder="שם (לדוג׳ יוגה, ספינינג...)" class="w-full border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
                <div class="grid grid-cols-2 gap-2">
                    <input id="sport-ct-dur" type="number" placeholder="משך (דקות)" value="60" class="border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
                    <select id="sport-ct-color" class="border border-slate-200 rounded-xl px-3 py-2 text-right text-sm">
                        ${colors.map(c=>`<option value="${c}">${{indigo:'כחול',violet:'סגול',emerald:'ירוק',orange:'כתום',red:'אדום',blue:'תכלת',teal:'טורקיז',pink:'ורוד'}[c]||c}</option>`).join('')}
                    </select>
                </div>
                <div class="grid grid-cols-2 gap-2">
                    <div>
                        <label class="text-[10px] font-bold text-slate-500 block mb-1">פתיחת הרשמה (ימים מראש, ריק=תמיד)</label>
                        <input id="sport-ct-open-days" type="number" min="0" placeholder="ריק = תמיד פתוח" class="w-full border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
                    </div>
                    <div>
                        <label class="text-[10px] font-bold text-slate-500 block mb-1">סגירת הרשמה (שעות לפני)</label>
                        <input id="sport-ct-close-hours" type="number" min="0" value="1" class="w-full border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
                    </div>
                </div>
                <div>
                    <label class="text-[10px] font-bold text-slate-500 block mb-1">מנויים מאושרים (ריק = כולם)</label>
                    <div id="sport-ct-membership-checkboxes" class="flex flex-wrap gap-2 mt-1"></div>
                </div>
                <button onclick="window._sportAddClassType()" class="w-full bg-indigo-600 text-white font-black py-2.5 rounded-xl text-sm">הוסף ➕</button>
            </div>
        </div>
    </div>`;
    modal.classList.remove('hidden');
    window._sportLoadClassTypesList();
    // Load membership types for checkboxes
    fetch(`${API}/sport/membership-types/${currentGroup.id}`).then(r=>r.json()).then(d => {
        const container = document.getElementById('sport-ct-membership-checkboxes');
        if (!container) return;
        const types = d.types || [];
        if (!types.length) { container.innerHTML = '<span class="text-xs text-slate-400">אין מנויים מוגדרים</span>'; return; }
        container.innerHTML = types.map(t => `<label class="flex items-center gap-1 text-xs font-bold text-slate-700 bg-white border border-slate-200 rounded-lg px-2 py-1 cursor-pointer">
            <input type="checkbox" value="${t.id}" class="accent-indigo-600"> ${t.name}
        </label>`).join('');
    });
};

window._sportLoadClassTypesList = async function() {
    const el = document.getElementById('sport-class-types-list');
    if (!el) return;
    try {
        const [typesData, memData] = await Promise.all([
            fetch(`${API}/sport/class-types/${currentGroup.id}`).then(r=>r.json()),
            fetch(`${API}/sport/membership-types/${currentGroup.id}`).then(r=>r.json())
        ]);
        const types = typesData.types || [];
        const memTypes = memData.types || [];
        const colorBg = {indigo:'bg-indigo-100 text-indigo-700',violet:'bg-violet-100 text-violet-700',emerald:'bg-emerald-100 text-emerald-700',orange:'bg-orange-100 text-orange-700',red:'bg-red-100 text-red-700',blue:'bg-blue-100 text-blue-700',teal:'bg-teal-100 text-teal-700',pink:'bg-pink-100 text-pink-700'};
        if (!types.length) { el.innerHTML = `<div class="text-center py-6 text-slate-400 text-sm">אין סוגי שיעורים עדיין</div>`; return; }
        el.innerHTML = types.map(t => {
            const allowedIds = Array.isArray(t.allowed_membership_type_ids) ? t.allowed_membership_type_ids : (t.allowed_membership_type_ids ? JSON.parse(t.allowed_membership_type_ids) : []);
            const allowedNames = allowedIds.length ? memTypes.filter(m => allowedIds.includes(m.id)).map(m=>m.name).join(', ') : 'כולם';
            const bookingRule = t.booking_open_days != null ? `נפתח ${t.booking_open_days} ימים מראש · ` : '';
            const closeRule = `נסגר ${t.booking_close_hours ?? 1}ש׳ לפני`;
            return `<div class="bg-white border border-slate-100 rounded-xl p-3 shadow-sm">
                <div class="flex items-center justify-between">
                    <button onclick="window._sportDeleteClassType(${t.id})" class="text-red-400 text-lg px-2">🗑️</button>
                    <div class="flex items-center gap-2">
                        <span class="text-xs font-bold px-2 py-0.5 rounded-full ${colorBg[t.color]||colorBg.indigo}">${{indigo:'כחול',violet:'סגול',emerald:'ירוק',orange:'כתום',red:'אדום',blue:'תכלת',teal:'טורקיז',pink:'ורוד'}[t.color]||t.color}</span>
                        <div class="text-right">
                            <div class="font-bold text-slate-800 text-sm">${t.name}</div>
                            <div class="text-[10px] text-slate-500">${t.default_duration_min} דקות</div>
                        </div>
                    </div>
                </div>
                <div class="mt-2 pt-2 border-t border-slate-50 text-right space-y-1">
                    <div class="text-[10px] text-slate-500">🎟️ מנויים: <span class="font-bold text-slate-700">${allowedNames}</span></div>
                    <div class="text-[10px] text-slate-500">🗓️ הרשמה: <span class="font-bold text-slate-700">${bookingRule}${closeRule}</span></div>
                </div>
                <button onclick="window._sportEditClassType(${t.id})" class="w-full mt-2 bg-slate-100 text-slate-600 text-xs font-bold py-1.5 rounded-lg hover:bg-slate-200 transition">✏️ עריכה</button>
            </div>`;
        }).join('');
    } catch(e) { el.innerHTML = `<div class="text-center py-6 text-red-400 text-sm">שגיאה</div>`; }
};

window._sportAddClassType = async function() {
    const name = document.getElementById('sport-ct-name')?.value?.trim();
    const dur = parseInt(document.getElementById('sport-ct-dur')?.value) || 60;
    const color = document.getElementById('sport-ct-color')?.value || 'indigo';
    const openDays = document.getElementById('sport-ct-open-days')?.value;
    const closeHours = document.getElementById('sport-ct-close-hours')?.value;
    const checkboxes = document.querySelectorAll('#sport-ct-membership-checkboxes input[type=checkbox]:checked');
    const allowedIds = Array.from(checkboxes).map(cb => parseInt(cb.value));
    if (!name) { showToast('error','יש להזין שם'); return; }
    try {
        const d = await fetch(`${API}/sport/class-types`, {
            method:'POST', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({
                groupId: currentGroup.id, name, color,
                defaultDurationMin: dur,
                allowedMembershipTypeIds: allowedIds,
                bookingOpenDays: openDays ? parseInt(openDays) : null,
                bookingCloseHours: closeHours !== '' ? parseInt(closeHours) : 1
            })
        }).then(r=>r.json());
        if (!d.success) { showToast('error', d.error||'שגיאה'); return; }
        showToast('success','נוסף ✅');
        document.getElementById('sport-ct-name').value = '';
        window._sportLoadClassTypesList();
    } catch(e) { showToast('error','שגיאת תקשורת'); }
};

window._sportDeleteClassType = async function(id) {
    if (!await window._uiConfirm('למחוק סוג שיעור זה?', {danger:true, okLabel:'מחק'})) return;
    try {
        await fetch(`${API}/sport/class-types/${id}`, {method:'DELETE'});
        showToast('success','נמחק');
        window._sportLoadClassTypesList();
    } catch(e) { showToast('error','שגיאת תקשורת'); }
};

window._sportEditClassType = async function(typeId) {
    const [typesData, memData] = await Promise.all([
        fetch(`${API}/sport/class-types/${currentGroup.id}`).then(r=>r.json()),
        fetch(`${API}/sport/membership-types/${currentGroup.id}`).then(r=>r.json())
    ]);
    const t = (typesData.types || []).find(x => x.id === typeId);
    if (!t) return;
    const memTypes = memData.types || [];
    const allowedIds = Array.isArray(t.allowed_membership_type_ids) ? t.allowed_membership_type_ids : (t.allowed_membership_type_ids ? JSON.parse(t.allowed_membership_type_ids) : []);
    const colors = ['indigo','violet','emerald','orange','red','blue','teal','pink'];
    const colorNames = {indigo:'כחול',violet:'סגול',emerald:'ירוק',orange:'כתום',red:'אדום',blue:'תכלת',teal:'טורקיז',pink:'ורוד'};

    const overlay = document.createElement('div');
    overlay.className = 'fixed inset-0 bg-black/60 z-[300] flex items-end sm:items-center justify-center p-0 sm:p-4';
    overlay.innerHTML = `<div class="bg-white w-full sm:max-w-sm rounded-t-3xl sm:rounded-2xl p-5 text-right space-y-3">
        <div class="flex justify-between items-center mb-1">
            <button onclick="this.closest('.fixed').remove()" class="text-slate-400 text-xl">✕</button>
            <h3 class="font-black text-slate-800">עריכת סוג שיעור</h3>
            <span></span>
        </div>
        <input id="sct-edit-name" type="text" value="${t.name}" class="w-full border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
        <div class="grid grid-cols-2 gap-2">
            <input id="sct-edit-dur" type="number" value="${t.default_duration_min}" class="border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
            <select id="sct-edit-color" class="border border-slate-200 rounded-xl px-3 py-2 text-right text-sm">
                ${colors.map(c=>`<option value="${c}" ${t.color===c?'selected':''}>${colorNames[c]}</option>`).join('')}
            </select>
        </div>
        <div class="grid grid-cols-2 gap-2">
            <div>
                <label class="text-[10px] font-bold text-slate-500 block mb-1">פתיחת הרשמה (ימים, ריק=תמיד)</label>
                <input id="sct-edit-open-days" type="number" min="0" value="${t.booking_open_days ?? ''}" placeholder="תמיד פתוח" class="w-full border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
            </div>
            <div>
                <label class="text-[10px] font-bold text-slate-500 block mb-1">סגירת הרשמה (שעות לפני)</label>
                <input id="sct-edit-close-hours" type="number" min="0" value="${t.booking_close_hours ?? 1}" class="w-full border border-slate-200 rounded-xl px-3 py-2 text-right text-sm"/>
            </div>
        </div>
        <div>
            <label class="text-[10px] font-bold text-slate-500 block mb-1">מנויים מאושרים (ריק = כולם)</label>
            <div class="flex flex-wrap gap-2 mt-1">
                ${memTypes.length ? memTypes.map(m => `<label class="flex items-center gap-1 text-xs font-bold text-slate-700 bg-white border border-slate-200 rounded-lg px-2 py-1 cursor-pointer">
                    <input type="checkbox" value="${m.id}" class="sct-edit-mem-cb accent-indigo-600" ${allowedIds.includes(m.id)?'checked':''}> ${m.name}
                </label>`).join('') : '<span class="text-xs text-slate-400">אין מנויים מוגדרים</span>'}
            </div>
        </div>
        <button onclick="window._sportSaveClassType(${typeId}, this.closest('.fixed'))" class="w-full bg-indigo-600 text-white font-black py-3 rounded-xl text-sm">שמור ✅</button>
    </div>`;
    document.body.appendChild(overlay);
};

window._sportSaveClassType = async function(typeId, overlay) {
    const name = document.getElementById('sct-edit-name')?.value?.trim();
    const dur = parseInt(document.getElementById('sct-edit-dur')?.value) || 60;
    const color = document.getElementById('sct-edit-color')?.value || 'indigo';
    const openDays = document.getElementById('sct-edit-open-days')?.value;
    const closeHours = document.getElementById('sct-edit-close-hours')?.value;
    const checkboxes = document.querySelectorAll('.sct-edit-mem-cb:checked');
    const allowedIds = Array.from(checkboxes).map(cb => parseInt(cb.value));
    if (!name) { showToast('error','יש להזין שם'); return; }
    try {
        const d = await fetch(`${API}/sport/class-types/${typeId}`, {
            method:'PUT', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({
                name, color, defaultDurationMin: dur,
                allowedMembershipTypeIds: allowedIds,
                bookingOpenDays: openDays ? parseInt(openDays) : null,
                bookingCloseHours: closeHours !== '' ? parseInt(closeHours) : 1
            })
        }).then(r=>r.json());
        if (!d.success) { showToast('error', d.error||'שגיאה'); return; }
        showToast('success','נשמר ✅');
        overlay.remove();
        window._sportLoadClassTypesList();
    } catch(e) { showToast('error','שגיאת תקשורת'); }
};

