// ===== LOGISTICS MODULE UI v2 — Full Spec =====

// ─── Full 13-status helpers (override v1) ─────────────────────────────────────
window._logStatusLabel = function(s) {
    const m = {
        new:'חדש', pending_quote:'ממתין להצעה', quote_sent:'הצעה נשלחה',
        confirmed:'אושר', assigned:'שויך לנהג', picked_up:'נאסף',
        in_transit:'בדרך', arrived:'הגיע לכתובת', delivered:'נמסר',
        partial:'נמסר חלקית', failed_attempt:'לא ענה', returned:'הוחזר', cancelled:'בוטל'
    };
    return m[s] || s;
};
window._logStatusColor = function(s) {
    const m = {
        new:'bg-slate-100 text-slate-600',
        pending_quote:'bg-yellow-100 text-yellow-700',
        quote_sent:'bg-blue-100 text-blue-700',
        confirmed:'bg-cyan-100 text-cyan-700',
        assigned:'bg-indigo-100 text-indigo-700',
        picked_up:'bg-violet-100 text-violet-700',
        in_transit:'bg-purple-100 text-purple-700',
        arrived:'bg-amber-100 text-amber-700',
        delivered:'bg-emerald-100 text-emerald-700',
        partial:'bg-lime-100 text-lime-700',
        failed_attempt:'bg-red-100 text-red-700',
        returned:'bg-slate-200 text-slate-700',
        cancelled:'bg-rose-100 text-rose-600'
    };
    return m[s] || 'bg-slate-100 text-slate-600';
};

// ─── Routes tab ───────────────────────────────────────────────────────────────
async function loadLogisticsRoutes() {
    const el = document.getElementById('content-logistics_routes'); if (!el) return;
    el.innerHTML = `<div class="py-8 text-center text-slate-400 text-sm"><i class="fa-solid fa-circle-notch fa-spin ml-2"></i>טוען מסלולים...</div>`;
    let routes = [];
    const today = new Date().toISOString().split('T')[0];
    try {
        const r = await fetch(`${API}/logistics/routes/${currentGroup.id}?date=${today}`);
        routes = r.ok ? await r.json() : [];
        window._logisticsState.routes = routes;
        const dr = await fetch(`${API}/logistics/drivers/${currentGroup.id}`);
        window._logisticsState.drivers = dr.ok ? await dr.json() : [];
        const vr = await fetch(`${API}/logistics/vehicles/${currentGroup.id}`);
        window._logisticsState.vehicles = vr.ok ? await vr.json() : [];
    } catch(e) { routes = []; }
    _renderLogisticsRoutes(routes, today);
}

function _renderLogisticsRoutes(routes, today) {
    const el = document.getElementById('content-logistics_routes'); if (!el) return;
    const statusBadge = s => ({ planned:'bg-slate-100 text-slate-600', active:'bg-green-100 text-green-700', completed:'bg-emerald-100 text-emerald-700' }[s] || 'bg-slate-100 text-slate-600');
    const statusLabel = s => ({ planned:'מתוכנן', active:'פעיל', completed:'הסתיים' }[s] || s);
    el.innerHTML = `
    <div class="flex items-center justify-between mb-4 mt-1">
        <h2 class="font-black text-slate-800 text-base">🗺️ מסלולי חלוקה</h2>
        <button onclick="window._logisticsNewRoute()" class="bg-orange-500 text-white px-4 py-2 rounded-xl text-sm font-black shadow-sm flex items-center gap-1"><i class="fa-solid fa-plus"></i> מסלול חדש</button>
    </div>
    <div class="mb-3">
        <input type="date" value="${today}" onchange="window._logisticsRoutesDate=this.value; loadLogisticsRoutes()" class="border border-slate-200 rounded-xl px-3 py-2 text-sm"/>
    </div>
    ${routes.length === 0 ? `<div class="py-10 text-center text-slate-400 text-sm">אין מסלולים ל-${today}</div>` :
    routes.map(r => `
    <div class="bg-white rounded-2xl border border-slate-100 p-4 mb-3 shadow-sm">
        <div class="flex items-center justify-between mb-2">
            <div class="font-black text-slate-800 text-sm">${r.name || 'מסלול ' + r.id}</div>
            <span class="text-xs font-bold px-2 py-0.5 rounded-full ${statusBadge(r.status)}">${statusLabel(r.status)}</span>
        </div>
        <div class="flex gap-3 text-xs text-slate-500 mb-3">
            ${r.driver_name ? `<span>🚗 ${r.driver_name}</span>` : ''}
            ${r.vehicle_name ? `<span>🚚 ${r.vehicle_name}</span>` : ''}
            <span>📍 ${r.stop_count} עצירות</span>
        </div>
        <div class="flex gap-2">
            <button onclick="window._logisticsRouteDetail(${r.id})" class="flex-1 py-2 border border-slate-200 text-slate-700 rounded-xl text-xs font-bold">פרטים</button>
            ${r.status === 'planned' ? `<button onclick="window._logisticsRouteStatus(${r.id},'active')" class="flex-1 py-2 bg-green-500 text-white rounded-xl text-xs font-bold">הפעל</button>` : ''}
            ${r.status === 'active' ? `<button onclick="window._logisticsRouteStatus(${r.id},'completed')" class="flex-1 py-2 bg-emerald-600 text-white rounded-xl text-xs font-bold">סיים</button>` : ''}
            <button onclick="window._logisticsDeleteRoute(${r.id})" class="w-9 h-9 border border-red-200 text-red-400 rounded-xl flex items-center justify-center text-sm"><i class="fa-solid fa-trash"></i></button>
        </div>
    </div>`).join('')}`;
}

window._logisticsNewRoute = function() {
    const drivers = window._logisticsState.drivers || [];
    const vehicles = window._logisticsState.vehicles || [];
    const today = new Date().toISOString().split('T')[0];
    const m = document.createElement('div');
    m.id = 'log-route-modal';
    m.className = 'fixed inset-0 bg-black/60 z-50 flex items-end justify-center';
    m.innerHTML = `<div class="bg-white rounded-t-3xl w-full max-w-lg p-6 pb-10 space-y-4">
        <div class="flex items-center justify-between mb-1">
            <h3 class="font-black text-slate-800">מסלול חדש</h3>
            <button onclick="document.getElementById('log-route-modal').remove()" class="text-slate-400 text-xl">✕</button>
        </div>
        <input id="lroute-name" placeholder="שם המסלול" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm text-right"/>
        <input id="lroute-date" type="date" value="${today}" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm text-right"/>
        <select id="lroute-driver" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm text-right">
            <option value="">בחר נהג (אופציונלי)</option>
            ${drivers.map(d=>`<option value="${d.id}">${d.name}</option>`).join('')}
        </select>
        <select id="lroute-vehicle" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm text-right">
            <option value="">בחר רכב (אופציונלי)</option>
            ${vehicles.map(v=>`<option value="${v.id}">${v.name}</option>`).join('')}
        </select>
        <textarea id="lroute-notes" placeholder="הערות" rows="2" class="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm text-right resize-none"></textarea>
        <button onclick="window._logisticsSaveRoute()" class="w-full py-3 bg-orange-500 text-white rounded-2xl font-black">צור מסלול</button>
    </div>`;
    document.body.appendChild(m);
};

window._logisticsSaveRoute = async function() {
    const name = document.getElementById('lroute-name')?.value?.trim();
    if (!name) { showToast('error','נדרש שם מסלול'); return; }
    try {
        await fetch(`${API}/logistics/routes`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({
            group_id: currentGroup.id,
            name,
            route_date: document.getElementById('lroute-date')?.value || new Date().toISOString().split('T')[0],
            driver_id: document.getElementById('lroute-driver')?.value || null,
            vehicle_id: document.getElementById('lroute-vehicle')?.value || null,
            notes: document.getElementById('lroute-notes')?.value || null
        })});
        showToast('success','מסלול נוצר!');
        document.getElementById('log-route-modal')?.remove();
        loadLogisticsRoutes();
    } catch(e) { showToast('error','שגיאה'); }
};

window._logisticsRouteStatus = async function(routeId, status) {
    try {
        await fetch(`${API}/logistics/routes/${routeId}/status`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ status }) });
        loadLogisticsRoutes();
    } catch(e) { showToast('error','שגיאה'); }
};

window._logisticsDeleteRoute = async function(routeId) {
    if (!await window._uiConfirm('למחוק את המסלול?', {danger:true, okLabel:'מחק'})) return;
    try {
        await fetch(`${API}/logistics/routes/${routeId}`, { method:'DELETE' });
        showToast('success','נמחק');
        loadLogisticsRoutes();
    } catch(e) { showToast('error','שגיאה'); }
};

window._logisticsRouteDetail = async function(routeId) {
    let stops = [];
    try {
        const r = await fetch(`${API}/logistics/routes/${currentGroup.id}/${routeId}/stops`);
        stops = r.ok ? await r.json() : [];
    } catch(e) {}
    const m = document.createElement('div');
    m.id = 'log-route-detail-modal';
    m.className = 'fixed inset-0 bg-black/60 z-50 flex items-end justify-center';
    m.innerHTML = `<div class="bg-white rounded-t-3xl w-full max-w-lg p-6 pb-10 max-h-[85vh] overflow-y-auto">
        <div class="flex items-center justify-between mb-4">
            <h3 class="font-black text-slate-800">עצירות במסלול</h3>
            <button onclick="document.getElementById('log-route-detail-modal').remove()" class="text-slate-400 text-xl">✕</button>
        </div>
        ${stops.length === 0 ? '<div class="py-6 text-center text-slate-400 text-sm">אין עצירות עדיין</div>' :
        stops.map((s,i) => `
        <div class="flex gap-3 mb-3 border-b border-slate-100 pb-3">
            <div class="w-7 h-7 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center text-xs font-black flex-shrink-0 mt-0.5">${i+1}</div>
            <div class="flex-1">
                <div class="font-bold text-slate-800 text-sm">${s.customer_name || 'לקוח'}</div>
                <div class="text-xs text-slate-500">${s.delivery_address || ''}</div>
                ${s.customer_phone ? `<div class="text-xs text-slate-400">${s.customer_phone}</div>` : ''}
                <div class="flex gap-2 mt-1">
                    <span class="text-xs px-2 py-0.5 rounded-full ${window._logStatusColor(s.order_status)}">${window._logStatusLabel(s.order_status)}</span>
                    ${s.cod_amount > 0 ? `<span class="text-xs text-orange-600 font-bold">COD ₪${s.cod_amount}</span>` : ''}
                    ${s.eta ? `<span class="text-xs text-slate-500">ETA ${s.eta}</span>` : ''}
                </div>
            </div>
        </div>`).join('')}
        <div class="mt-4 pt-3 border-t border-slate-100">
            <div class="text-xs text-slate-400 mb-2 font-medium">הוסף הזמנה למסלול</div>
            <div class="flex gap-2">
                <input id="lroute-stop-order" placeholder="מס׳ הזמנה / ID" class="flex-1 border border-slate-200 rounded-xl px-3 py-2 text-sm text-right"/>
                <input id="lroute-stop-eta" placeholder="ETA 14:30" class="w-24 border border-slate-200 rounded-xl px-3 py-2 text-sm text-right"/>
                <button onclick="window._logisticsAddStop(${routeId})" class="px-4 bg-orange-500 text-white rounded-xl text-sm font-bold">הוסף</button>
            </div>
        </div>
    </div>`;
    document.body.appendChild(m);
};

window._logisticsAddStop = async function(routeId) {
    const orderId = document.getElementById('lroute-stop-order')?.value?.trim();
    const eta = document.getElementById('lroute-stop-eta')?.value?.trim();
    if (!orderId) { showToast('error','נדרש מזהה הזמנה'); return; }
    try {
        const allOrders = window._logisticsState.orders || [];
        const stops = parseInt(document.querySelectorAll('#log-route-detail-modal .border-b').length) || 0;
        await fetch(`${API}/logistics/routes/${routeId}/stops`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ order_id: parseInt(orderId), stop_order: stops+1, eta: eta||null }) });
        showToast('success','נוסף!');
        document.getElementById('log-route-detail-modal')?.remove();
        window._logisticsRouteDetail(routeId);
    } catch(e) { showToast('error','שגיאה'); }
};

// ─── Tracking tab ─────────────────────────────────────────────────────────────
async function loadLogisticsTracking() {
    const el = document.getElementById('content-logistics_tracking'); if (!el) return;
    el.innerHTML = `<div class="py-8 text-center text-slate-400 text-sm"><i class="fa-solid fa-circle-notch fa-spin ml-2"></i>טוען...</div>`;
    let orders = [];
    try {
        const r = await fetch(`${API}/logistics/orders/${currentGroup.id}`);
        orders = r.ok ? await r.json() : [];
    } catch(e) {}
    _renderLogisticsTracking(orders);
}

function _renderLogisticsTracking(orders) {
    const el = document.getElementById('content-logistics_tracking'); if (!el) return;
    const active = orders.filter(o => !['delivered','cancelled','returned'].includes(o.status));
    el.innerHTML = `
    <div class="flex items-center justify-between mb-4 mt-1">
        <h2 class="font-black text-slate-800 text-base">🔗 לינקי מעקב ציבורי</h2>
        <span class="text-xs text-slate-400">${active.length} פעילים</span>
    </div>
    <div class="bg-orange-50 border border-orange-200 rounded-2xl p-4 mb-4 text-sm text-orange-800">
        <div class="font-bold mb-1">📱 כיצד זה עובד?</div>
        לחץ "צור לינק" על הזמנה — יישלח ללקוח ויציג את מצב המשלוח בזמן אמת
    </div>
    ${orders.length === 0 ? '<div class="py-8 text-center text-slate-400 text-sm">אין הזמנות</div>' :
    orders.map(o => `
    <div class="bg-white rounded-2xl border border-slate-100 p-4 mb-3 shadow-sm">
        <div class="flex items-center justify-between mb-1">
            <div class="font-bold text-slate-800 text-sm">${o.customer_name || 'לקוח'} ${o.order_number ? `· #${o.order_number}` : ''}</div>
            <span class="text-xs px-2 py-0.5 rounded-full ${window._logStatusColor(o.status)}">${window._logStatusLabel(o.status)}</span>
        </div>
        <div class="text-xs text-slate-500 mb-3">${o.delivery_address || ''}</div>
        ${o.tracking_token ?
            `<div class="bg-slate-50 rounded-xl px-3 py-2 text-xs font-mono text-slate-600 mb-2 break-all">/track/${o.tracking_token}</div>
            <div class="flex gap-2">
                <button onclick="window._logisticsCopyTracking('${o.tracking_token}')" class="flex-1 py-2 border border-slate-200 text-slate-600 rounded-xl text-xs font-bold">📋 העתק לינק</button>
                <a href="/track/${o.tracking_token}" target="_blank" class="flex-1 py-2 bg-blue-500 text-white rounded-xl text-xs font-bold text-center">🔍 פתח</a>
            </div>` :
            `<button onclick="window._logisticsCreateTracking(${o.id})" class="w-full py-2 bg-orange-500 text-white rounded-xl text-xs font-bold">🔗 צור לינק מעקב</button>`
        }
    </div>`).join('')}`;
}

window._logisticsCreateTracking = async function(orderId) {
    try {
        const r = await fetch(`${API}/logistics/orders/${orderId}/tracking-token`, { method:'POST' });
        if (r.ok) {
            const data = await r.json();
            showToast('success','לינק נוצר!');
            loadLogisticsTracking();
        }
    } catch(e) { showToast('error','שגיאה'); }
};

window._logisticsCopyTracking = function(token) {
    const url = `${location.origin}/track/${token}`;
    navigator.clipboard?.writeText(url).then(() => showToast('success','הועתק!')).catch(() => showToast('info', url));
};

// ─── Reports tab ──────────────────────────────────────────────────────────────
async function loadLogisticsReports() {
    const el = document.getElementById('content-logistics_reports'); if (!el) return;
    el.innerHTML = `<div class="py-8 text-center text-slate-400 text-sm"><i class="fa-solid fa-circle-notch fa-spin ml-2"></i>טוען נתונים...</div>`;
    let data = null;
    try {
        const r = await fetch(`${API}/logistics/reports/${currentGroup.id}?period=month`);
        data = r.ok ? await r.json() : null;
    } catch(e) {}
    _renderLogisticsReports(data);
}

function _renderLogisticsReports(data) {
    const el = document.getElementById('content-logistics_reports'); if (!el) return;
    if (!data) { el.innerHTML = `<div class="py-10 text-center text-slate-400 text-sm">שגיאה בטעינת דוחות</div>`; return; }
    const d = data.delivery || {};
    const cod = data.cod || {};
    const byDriver = data.by_driver || [];
    const fmt = n => Number(n||0).toLocaleString('he-IL', { maximumFractionDigits:0 });
    const pct = (a,b) => b > 0 ? Math.round((a/b)*100) : 0;
    el.innerHTML = `
    <div class="flex items-center justify-between mb-4 mt-1">
        <h2 class="font-black text-slate-800 text-base">📊 דוחות לוגיסטיקה</h2>
        <select onchange="window._logisticsReportPeriod=this.value; loadLogisticsReports()" class="border border-slate-200 rounded-xl px-3 py-1.5 text-xs text-right">
            <option value="month">החודש</option>
            <option value="week">השבוע</option>
            <option value="today">היום</option>
        </select>
    </div>

    <!-- KPIs -->
    <div class="grid grid-cols-2 gap-3 mb-4">
        ${[
            { label:'סה"כ משלוחים', value: fmt(d.total_orders), icon:'📦', color:'slate' },
            { label:'נמסרו', value: `${fmt(d.delivered_orders)} (${pct(d.delivered_orders, d.total_orders)}%)`, icon:'✅', color:'emerald' },
            { label:'הכנסה משלוחים', value:`₪${fmt(d.total_revenue)}`, icon:'💰', color:'blue' },
            { label:'COD שנגבה', value:`₪${fmt(cod.collected)}`, icon:'💵', color:'orange' },
        ].map(k => `
        <div class="bg-white rounded-2xl border border-slate-100 p-4 shadow-sm">
            <div class="text-xl mb-1">${k.icon}</div>
            <div class="text-lg font-black text-slate-800">${k.value}</div>
            <div class="text-xs text-slate-400">${k.label}</div>
        </div>`).join('')}
    </div>

    <!-- By driver -->
    ${byDriver.length > 0 ? `
    <div class="bg-white rounded-2xl border border-slate-100 p-4 shadow-sm mb-4">
        <div class="font-bold text-slate-700 text-sm mb-3">ביצועי נהגים</div>
        <table class="w-full text-xs">
            <thead><tr class="text-slate-400 border-b border-slate-100">
                <th class="pb-2 text-right">נהג</th>
                <th class="pb-2 text-center">משלוחים</th>
                <th class="pb-2 text-center">הצלחה</th>
                <th class="pb-2 text-left">הכנסה</th>
            </tr></thead>
            <tbody>
            ${byDriver.map(d => `<tr class="border-b border-slate-50">
                <td class="py-2 font-medium">${d.driver_name || 'ללא נהג'}</td>
                <td class="py-2 text-center">${d.total_orders}</td>
                <td class="py-2 text-center">${pct(d.delivered_orders, d.total_orders)}%</td>
                <td class="py-2 text-right text-emerald-700 font-bold">₪${fmt(d.revenue)}</td>
            </tr>`).join('')}
            </tbody>
        </table>
    </div>` : ''}

    <!-- Alerts -->
    ${cod.pending > 0 ? `
    <div class="bg-orange-50 border border-orange-200 rounded-2xl p-4 flex gap-3">
        <span class="text-2xl">⚠️</span>
        <div>
            <div class="font-bold text-orange-800 text-sm">COD ממתין לגבייה</div>
            <div class="text-sm text-orange-700">₪${fmt(cod.pending)} לא נגבו עדיין</div>
            <button onclick="switchTab('logistics_cod')" class="text-xs text-orange-600 underline mt-1">עבור לגבייה</button>
        </div>
    </div>` : ''}`;
}

// ─── Failed attempt button in order detail (extend _logisticsOrderDetail) ────
const _origOrderDetail = window._logisticsOrderDetail;
window._logisticsOrderDetail = async function(orderId) {
    if (_origOrderDetail) await _origOrderDetail(orderId);
    // Inject failed-attempt + tracking buttons after modal opens
    setTimeout(() => {
        const modal = document.getElementById('log-order-detail-modal');
        if (!modal) return;
        const order = window._logisticsState.orders?.find(o => o.id === orderId);
        if (!order) return;
        const btnArea = modal.querySelector('.log-order-extra-actions');
        if (btnArea) return; // already injected
        const footer = modal.querySelector('div[class*="flex gap"]');
        if (!footer) return;
        const extraDiv = document.createElement('div');
        extraDiv.className = 'log-order-extra-actions flex gap-2 mt-2';
        extraDiv.innerHTML = `
            ${['in_transit','arrived'].includes(order.status) ? `<button onclick="window._logisticsFailedAttempt(${orderId})" class="flex-1 py-2.5 bg-red-500 text-white rounded-xl text-sm font-bold">📵 לא ענה</button>` : ''}
            <button onclick="window._logisticsCreateTracking(${orderId})" class="flex-1 py-2.5 bg-blue-500 text-white rounded-xl text-sm font-bold">🔗 לינק מעקב</button>
        `;
        footer.parentNode.insertBefore(extraDiv, footer.nextSibling);
    }, 100);
};

window._logisticsFailedAttempt = async function(orderId) {
    const notes = await window._uiPrompt('הערות לניסיון כושל (אופציונלי):') || '';
    try {
        const r = await fetch(`${API}/logistics/orders/${orderId}/failed-attempt`, {
            method:'POST', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({ notes, actor_name: currentUser?.name || 'מערכת' })
        });
        if (r.ok) {
            showToast('warning','סומן כ"לא ענה"');
            document.getElementById('log-order-detail-modal')?.remove();
            loadLogisticsOrders();
        }
    } catch(e) { showToast('error','שגיאה'); }
};

// ─── Driver Companion view (for EMPLOYEE role in logistics) ───────────────────
async function renderLogisticsDriverDashboard(el) {
    el.innerHTML = `<div class="py-8 text-center text-slate-400 text-sm"><i class="fa-solid fa-circle-notch fa-spin ml-2"></i>טוען רשימת משלוחים...</div>`;
    const today = new Date().toISOString().split('T')[0];

    // Find driver by user
    let driverId = null;
    try {
        const allDrivers = await fetch(`${API}/logistics/drivers/${currentGroup.id}`).then(r=>r.json());
        const myDriver = allDrivers.find(d => d.user_id === currentUser?.id || (currentUser?.name && d.name === currentUser?.name));
        driverId = myDriver?.id || null;
        window._logisticsState.myDriverId = driverId;
        window._logisticsState.myDriver = myDriver;
    } catch(e) {}

    if (!driverId) {
        el.innerHTML = `<div class="py-10 text-center">
            <div class="text-4xl mb-3">🚗</div>
            <div class="font-bold text-slate-700 text-sm">לא נמצא פרופיל נהג</div>
            <div class="text-xs text-slate-400 mt-1">פנה למנהל לקישור חשבונך לפרופיל נהג</div>
        </div>`;
        return;
    }

    let orders = [];
    try {
        const r = await fetch(`${API}/logistics/driver-orders/${currentGroup.id}/${driverId}?date=${today}`);
        orders = r.ok ? await r.json() : [];
    } catch(e) {}

    _renderDriverCompanion(el, orders, window._logisticsState.myDriver);
}

function _renderDriverCompanion(el, orders, driver) {
    const pending = orders.filter(o => ['assigned','picked_up'].includes(o.status));
    const inTransit = orders.filter(o => o.status === 'in_transit');
    const done = orders.filter(o => ['delivered','partial'].includes(o.status));
    const failed = orders.filter(o => o.status === 'failed_attempt');
    const codTotal = orders.reduce((s,o) => s + (o.cod_amount > 0 && !o.cod_collected ? parseFloat(o.cod_amount)||0 : 0), 0);

    el.innerHTML = `
    <!-- Driver header -->
    <div class="bg-gradient-to-l from-orange-500 to-amber-400 rounded-3xl p-5 text-white mb-4 shadow-lg">
        <div class="flex items-center gap-3 mb-3">
            <div class="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-2xl">🚗</div>
            <div>
                <div class="font-black text-lg">${driver?.name || 'נהג'}</div>
                <div class="text-sm opacity-80">יום ${new Date().toLocaleDateString('he-IL', {weekday:'long'})}</div>
            </div>
        </div>
        <div class="grid grid-cols-3 gap-2 text-center">
            <div class="bg-white/20 rounded-xl p-2"><div class="font-black text-lg">${orders.length}</div><div class="text-xs opacity-80">סה"כ</div></div>
            <div class="bg-white/20 rounded-xl p-2"><div class="font-black text-lg">${done.length}</div><div class="text-xs opacity-80">נמסרו</div></div>
            <div class="bg-white/20 rounded-xl p-2"><div class="font-black text-lg text-yellow-200">${codTotal > 0 ? '₪'+Math.round(codTotal) : '—'}</div><div class="text-xs opacity-80">COD גבייה</div></div>
        </div>
    </div>

    <!-- Active orders -->
    ${[...inTransit, ...pending].length > 0 ? `
    <div class="font-bold text-slate-700 text-sm mb-3">🚚 פעיל עכשיו (${[...inTransit, ...pending].length})</div>
    ${[...inTransit, ...pending].map(o => _driverOrderCard(o, true)).join('')}` : ''}

    <!-- Failed attempts -->
    ${failed.length > 0 ? `
    <div class="font-bold text-red-600 text-sm mb-3 mt-4">📵 לא ענה (${failed.length})</div>
    ${failed.map(o => _driverOrderCard(o, true)).join('')}` : ''}

    <!-- Done today -->
    ${done.length > 0 ? `
    <div class="font-bold text-emerald-600 text-sm mb-3 mt-4">✅ הושלמו (${done.length})</div>
    ${done.map(o => _driverOrderCard(o, false)).join('')}` : ''}

    ${orders.length === 0 ? `<div class="py-10 text-center text-slate-400 text-sm">אין משלוחים לסדרן היום</div>` : ''}`;
}

function _driverOrderCard(o, showActions) {
    const codBadge = o.cod_amount > 0 && !o.cod_collected ? `<span class="text-xs font-black text-orange-600 bg-orange-50 px-2 py-0.5 rounded-full">COD ₪${o.cod_amount}</span>` : '';
    const phone = o.customer_phone ? `<a href="tel:${o.customer_phone}" class="w-9 h-9 bg-green-500 text-white rounded-xl flex items-center justify-center text-sm flex-shrink-0"><i class="fa-solid fa-phone"></i></a>` : '';
    const nav = o.delivery_address ? `<a href="https://waze.com/ul?q=${encodeURIComponent(o.delivery_address)}" target="_blank" class="w-9 h-9 bg-blue-500 text-white rounded-xl flex items-center justify-center text-sm flex-shrink-0"><i class="fa-solid fa-location-arrow"></i></a>` : '';
    return `
    <div class="bg-white rounded-2xl border border-slate-100 p-4 mb-3 shadow-sm">
        <div class="flex items-start justify-between mb-2">
            <div>
                <div class="font-black text-slate-800 text-sm">${o.customer_name || 'לקוח'}</div>
                ${o.order_number ? `<div class="text-xs text-slate-400">#${o.order_number}</div>` : ''}
            </div>
            <span class="text-xs px-2 py-0.5 rounded-full font-bold ${window._logStatusColor(o.status)}">${window._logStatusLabel(o.status)}</span>
        </div>
        <div class="text-xs text-slate-600 mb-1">📍 ${o.delivery_address || '—'}</div>
        ${o.scheduled_time_window ? `<div class="text-xs text-slate-400 mb-2">🕐 ${o.scheduled_time_window}</div>` : ''}
        ${codBadge}
        ${showActions ? `
        <div class="flex gap-2 mt-3">
            ${phone}
            ${nav}
            ${o.status === 'assigned' ? `<button onclick="window._driverUpdateStatus(${o.id},'picked_up')" class="flex-1 py-2 bg-indigo-500 text-white rounded-xl text-xs font-bold">נאסף</button>` : ''}
            ${o.status === 'picked_up' ? `<button onclick="window._driverUpdateStatus(${o.id},'in_transit')" class="flex-1 py-2 bg-violet-500 text-white rounded-xl text-xs font-bold">בדרך</button>` : ''}
            ${o.status === 'in_transit' ? `<button onclick="window._driverUpdateStatus(${o.id},'arrived')" class="flex-1 py-2 bg-amber-500 text-white rounded-xl text-xs font-bold">הגעתי</button>` : ''}
            ${o.status === 'arrived' ? `<button onclick="window._driverUpdateStatus(${o.id},'delivered')" class="flex-1 py-2 bg-emerald-600 text-white rounded-xl text-xs font-bold">נמסר ✓</button>` : ''}
            ${['in_transit','arrived'].includes(o.status) ? `<button onclick="window._logisticsFailedAttempt(${o.id})" class="px-3 py-2 bg-red-50 text-red-500 border border-red-200 rounded-xl text-xs font-bold">📵</button>` : ''}
        </div>` : ''}
    </div>`;
}

window._driverUpdateStatus = async function(orderId, newStatus) {
    try {
        const r = await fetch(`${API}/logistics/orders/${orderId}/status`, {
            method:'PATCH', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({ status: newStatus, actor_name: currentUser?.name || 'נהג' })
        });
        if (r.ok) {
            showToast('success', window._logStatusLabel(newStatus));
            // Re-render driver dashboard
            const el = document.getElementById('content-role-dashboard');
            if (el && currentUser?.role !== 'ADMIN') renderLogisticsDriverDashboard(el);
        }
    } catch(e) { showToast('error','שגיאה'); }
};

// ─── Hook driver view into renderDashboard ────────────────────────────────────
// Extends existing renderDashboard to add EMPLOYEE/MEMBER view for logistics
const _origRenderDashboard_v2 = window.renderDashboard;
if (_origRenderDashboard_v2) {
    // Already handled in the main renderDashboard block for ADMIN
    // Add EMPLOYEE/MEMBER/MANAGER companion view
    const _patchRenderDashboard = async function() {
        if (currentGroup?.business_type !== 'logistics') return _origRenderDashboard_v2?.apply(this, arguments);
        if (currentUser?.role === 'ADMIN') return _origRenderDashboard_v2?.apply(this, arguments);
        // EMPLOYEE/MEMBER/MANAGER in logistics get driver companion
        const el = document.getElementById('content-role-dashboard');
        if (!el) return;
        if (window._logisticsDriverDashRendering) return;
        window._logisticsDriverDashRendering = true;
        try { await renderLogisticsDriverDashboard(el); } catch(e) {}
        window._logisticsDriverDashRendering = false;
    };
    // We don't replace the whole renderDashboard — instead we extend the EMPLOYEE branch
}


// ─── Logistics Customers Module ───────────────────────────────────────────────
async function loadLogisticsCustomers() {
    const el = document.getElementById('content-logistics_customers'); if (!el) return;
    el.innerHTML = `<div class="flex items-center justify-center h-40"><div class="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500"></div></div>`;
    try {
        const r = await fetch(`/api/logistics/customers/${currentGroup.id}`, { headers: { Authorization: `Bearer ${window._bizToken}` } });
        const customers = await r.json();
        renderLogisticsCustomers(customers);
    } catch(e) {
        el.innerHTML = `<div class="text-red-500 p-4">שגיאה בטעינה: ${e.message}</div>`;
    }
}

function renderLogisticsCustomers(customers) {
    const el = document.getElementById('content-logistics_customers'); if (!el) return;
    const typeLabels = { private:'פרטי', business:'עסקי', subscription:'מנוי', monthly_billing:'חיוב שוטף' };
    const typeColors = { private:'blue', business:'purple', subscription:'green', monthly_billing:'orange' };
    el.innerHTML = `
    <div class="p-4 space-y-4">
      <div class="flex items-center justify-between">
        <div>
          <h2 class="text-xl font-black text-gray-800">🤝 מזמינים ונמענים</h2>
          <p class="text-sm text-gray-500">${customers.length} לקוחות פעילים</p>
        </div>
        <button onclick="openAddLogisticsCustomer()" class="bg-cyan-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-cyan-700 transition">+ לקוח חדש</button>
      </div>

      <div class="grid gap-3">
        ${customers.length === 0 ? `
          <div class="text-center py-16 text-gray-400">
            <div class="text-5xl mb-3">🤝</div>
            <div class="text-lg font-bold">אין לקוחות עדיין</div>
            <div class="text-sm mt-1">הוסף מזמינים ונמענים חוזרים לחיסכון בזמן</div>
          </div>
        ` : customers.map(c => `
          <div class="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
            <div class="flex items-start justify-between">
              <div class="flex items-center gap-3">
                <div class="w-12 h-12 rounded-xl bg-cyan-100 flex items-center justify-center text-2xl font-black text-cyan-700">
                  ${c.name.charAt(0)}
                </div>
                <div>
                  <div class="font-black text-gray-900">${c.name}</div>
                  <div class="text-sm text-gray-500">${c.phone || ''} ${c.email ? '· '+c.email : ''}</div>
                  ${c.default_address ? `<div class="text-xs text-gray-400 mt-0.5">📍 ${c.default_address}</div>` : ''}
                </div>
              </div>
              <div class="flex items-center gap-2">
                <span class="px-2 py-1 rounded-full text-xs font-bold bg-${typeColors[c.customer_type]||'gray'}-100 text-${typeColors[c.customer_type]||'gray'}-700">${typeLabels[c.customer_type]||c.customer_type}</span>
                ${c.discount_pct > 0 ? `<span class="px-2 py-1 rounded-full text-xs font-bold bg-green-100 text-green-700">${c.discount_pct}% הנחה</span>` : ''}
              </div>
            </div>
            ${c.delivery_instructions ? `<div class="mt-2 text-xs text-amber-700 bg-amber-50 rounded-lg px-3 py-1.5">💬 ${c.delivery_instructions}</div>` : ''}
            <div class="flex gap-2 mt-3">
              <button onclick="editLogisticsCustomer(${JSON.stringify(c).replace(/"/g,'&quot;')})" class="flex-1 text-xs bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold py-1.5 rounded-lg transition">✏️ עריכה</button>
              ${c.phone ? `<a href="tel:${c.phone}" class="flex-1 text-center text-xs bg-green-100 hover:bg-green-200 text-green-700 font-bold py-1.5 rounded-lg transition">📞 התקשר</a>` : ''}
              <button onclick="deleteLogisticsCustomer(${c.id})" class="text-xs bg-red-50 hover:bg-red-100 text-red-600 font-bold py-1.5 px-3 rounded-lg transition">🗑️</button>
            </div>
          </div>
        `).join('')}
      </div>
    </div>

    <div id="modal-logistics-customer" class="hidden fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div class="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6">
        <div class="flex items-center justify-between mb-4">
          <h3 class="text-lg font-black" id="customer-modal-title">לקוח חדש</h3>
          <button onclick="closeLogisticsCustomerModal()" class="text-gray-400 hover:text-gray-600 text-xl">✕</button>
        </div>
        <form id="form-logistics-customer" onsubmit="saveLogisticsCustomer(event)" class="space-y-3">
          <input type="hidden" id="edit-customer-id" value="">
          <div class="grid grid-cols-2 gap-3">
            <div class="col-span-2">
              <label class="text-xs font-bold text-gray-600">שם מלא / שם עסק *</label>
              <input id="cust-name" required class="w-full border rounded-xl px-3 py-2 text-sm mt-1" placeholder="ישראל ישראלי">
            </div>
            <div>
              <label class="text-xs font-bold text-gray-600">טלפון</label>
              <input id="cust-phone" class="w-full border rounded-xl px-3 py-2 text-sm mt-1" placeholder="050-0000000">
            </div>
            <div>
              <label class="text-xs font-bold text-gray-600">מייל</label>
              <input id="cust-email" type="email" class="w-full border rounded-xl px-3 py-2 text-sm mt-1" placeholder="mail@example.com">
            </div>
            <div class="col-span-2">
              <label class="text-xs font-bold text-gray-600">כתובת ברירת מחדל</label>
              <input id="cust-address" class="w-full border rounded-xl px-3 py-2 text-sm mt-1" placeholder="רח' הרצל 1, תל אביב">
            </div>
            <div>
              <label class="text-xs font-bold text-gray-600">סוג לקוח</label>
              <select id="cust-type" class="w-full border rounded-xl px-3 py-2 text-sm mt-1">
                <option value="private">פרטי</option>
                <option value="business">עסקי</option>
                <option value="subscription">מנוי</option>
                <option value="monthly_billing">חיוב שוטף</option>
              </select>
            </div>
            <div>
              <label class="text-xs font-bold text-gray-600">% הנחה</label>
              <input id="cust-discount" type="number" min="0" max="100" step="0.5" class="w-full border rounded-xl px-3 py-2 text-sm mt-1" placeholder="0">
            </div>
            <div class="col-span-2">
              <label class="text-xs font-bold text-gray-600">הוראות מסירה</label>
              <textarea id="cust-instructions" rows="2" class="w-full border rounded-xl px-3 py-2 text-sm mt-1" placeholder='למשל: "להשאיר אצל השכנה בקומה 2"'></textarea>
            </div>
          </div>
          <div class="flex gap-3 pt-2">
            <button type="submit" class="flex-1 bg-cyan-600 text-white py-2.5 rounded-xl font-bold text-sm hover:bg-cyan-700">שמור</button>
            <button type="button" onclick="closeLogisticsCustomerModal()" class="px-4 py-2.5 border rounded-xl text-sm font-bold text-gray-600">ביטול</button>
          </div>
        </form>
      </div>
    </div>`;
}

function openAddLogisticsCustomer() {
    document.getElementById('customer-modal-title').textContent = 'לקוח חדש';
    document.getElementById('edit-customer-id').value = '';
    ['name','phone','email','address','instructions'].forEach(f => { const el = document.getElementById(`cust-${f}`); if(el) el.value=''; });
    document.getElementById('cust-type').value = 'private';
    document.getElementById('cust-discount').value = '0';
    document.getElementById('modal-logistics-customer').classList.remove('hidden');
}

function editLogisticsCustomer(c) {
    document.getElementById('customer-modal-title').textContent = 'עריכת לקוח';
    document.getElementById('edit-customer-id').value = c.id;
    document.getElementById('cust-name').value = c.name || '';
    document.getElementById('cust-phone').value = c.phone || '';
    document.getElementById('cust-email').value = c.email || '';
    document.getElementById('cust-address').value = c.default_address || '';
    document.getElementById('cust-type').value = c.customer_type || 'private';
    document.getElementById('cust-discount').value = c.discount_pct || 0;
    document.getElementById('cust-instructions').value = c.delivery_instructions || '';
    document.getElementById('modal-logistics-customer').classList.remove('hidden');
}

function closeLogisticsCustomerModal() {
    document.getElementById('modal-logistics-customer').classList.add('hidden');
}

async function saveLogisticsCustomer(e) {
    e.preventDefault();
    const id = document.getElementById('edit-customer-id').value;
    const body = {
        group_id: currentGroup.id,
        name: document.getElementById('cust-name').value.trim(),
        phone: document.getElementById('cust-phone').value.trim(),
        email: document.getElementById('cust-email').value.trim(),
        default_address: document.getElementById('cust-address').value.trim(),
        customer_type: document.getElementById('cust-type').value,
        discount_pct: parseFloat(document.getElementById('cust-discount').value)||0,
        delivery_instructions: document.getElementById('cust-instructions').value.trim()
    };
    const url = id ? `/api/logistics/customers/${id}` : '/api/logistics/customers';
    const method = id ? 'PATCH' : 'POST';
    try {
        const r = await fetch(url, { method, headers: { 'Content-Type':'application/json', Authorization:`Bearer ${window._bizToken}` }, body: JSON.stringify(body) });
        if (!r.ok) throw new Error(await r.text());
        closeLogisticsCustomerModal();
        loadLogisticsCustomers();
    } catch(err) { await window._uiAlert('שגיאה: ' + err.message); }
}

async function deleteLogisticsCustomer(id) {
    if (!await window._uiConfirm('למחוק לקוח זה?', {danger:true, okLabel:'מחק'})) return;
    await fetch(`/api/logistics/customers/${id}`, { method:'DELETE', headers:{ Authorization:`Bearer ${window._bizToken}` } });
    loadLogisticsCustomers();
}

// ─── Logistics Invoices Module ────────────────────────────────────────────────
async function loadLogisticsInvoices() {
    const el = document.getElementById('content-logistics_invoices'); if (!el) return;
    el.innerHTML = `<div class="flex items-center justify-center h-40"><div class="animate-spin rounded-full h-8 w-8 border-b-2 border-violet-500"></div></div>`;
    try {
        const r = await fetch(`/api/logistics/invoices/${currentGroup.id}`, { headers: { Authorization: `Bearer ${window._bizToken}` } });
        const invoices = await r.json();
        renderLogisticsInvoices(invoices);
    } catch(e) {
        el.innerHTML = `<div class="text-red-500 p-4">שגיאה: ${e.message}</div>`;
    }
}

function renderLogisticsInvoices(invoices) {
    const el = document.getElementById('content-logistics_invoices'); if (!el) return;
    const statusLabel = { pending:'ממתין', sent:'נשלח', paid:'שולם', cancelled:'בוטל' };
    const statusColor = { pending:'amber', sent:'blue', paid:'green', cancelled:'red' };
    const totalRevenue = invoices.filter(i=>i.status==='paid').reduce((s,i)=>s+parseFloat(i.total_amount||0),0);
    const pendingCount = invoices.filter(i=>i.status==='pending').length;
    el.innerHTML = `
    <div class="p-4 space-y-4">
      <div class="flex items-center justify-between">
        <div>
          <h2 class="text-xl font-black text-gray-800">🧾 חשבוניות</h2>
          <p class="text-sm text-gray-500">${invoices.length} חשבוניות</p>
        </div>
        <div class="flex gap-2">
          <div class="text-center bg-green-50 rounded-xl px-3 py-1.5">
            <div class="text-sm font-black text-green-700">₪${totalRevenue.toLocaleString('he-IL',{maximumFractionDigits:0})}</div>
            <div class="text-xs text-gray-500">גבוי</div>
          </div>
          <div class="text-center bg-amber-50 rounded-xl px-3 py-1.5">
            <div class="text-sm font-black text-amber-700">${pendingCount}</div>
            <div class="text-xs text-gray-500">ממתינות</div>
          </div>
        </div>
      </div>

      ${invoices.length === 0 ? `
        <div class="text-center py-16 text-gray-400">
          <div class="text-5xl mb-3">🧾</div>
          <div class="text-lg font-bold">אין חשבוניות עדיין</div>
          <div class="text-sm mt-1">חשבוניות נוצרות אוטומטית כשמשלוח מסומן כ"נמסר"</div>
        </div>
      ` : `
        <div class="space-y-2">
          ${invoices.map(inv => `
            <div class="bg-white rounded-xl border border-gray-100 shadow-sm p-3">
              <div class="flex items-center justify-between">
                <div class="flex items-center gap-3">
                  <div class="w-10 h-10 rounded-xl bg-violet-100 flex items-center justify-center text-lg">🧾</div>
                  <div>
                    <div class="font-black text-gray-800 text-sm">${inv.invoice_number}</div>
                    <div class="text-xs text-gray-500">${inv.customer_name} ${inv.order_number ? '· הזמנה #'+inv.order_number : ''}</div>
                    <div class="text-xs text-gray-400">${new Date(inv.created_at).toLocaleDateString('he-IL')}</div>
                  </div>
                </div>
                <div class="text-left">
                  <div class="font-black text-gray-800">₪${parseFloat(inv.total_amount||0).toLocaleString('he-IL',{maximumFractionDigits:0})}</div>
                  <span class="px-2 py-0.5 rounded-full text-xs font-bold bg-${statusColor[inv.status]||'gray'}-100 text-${statusColor[inv.status]||'gray'}-700">${statusLabel[inv.status]||inv.status}</span>
                </div>
              </div>
              <div class="flex gap-2 mt-2">
                ${inv.status === 'pending' ? `
                  <button onclick="updateInvoiceStatus(${inv.id},'sent')" class="flex-1 text-xs bg-blue-100 hover:bg-blue-200 text-blue-700 font-bold py-1.5 rounded-lg transition">📤 סמן כנשלח</button>
                  <button onclick="updateInvoiceStatus(${inv.id},'paid')" class="flex-1 text-xs bg-green-100 hover:bg-green-200 text-green-700 font-bold py-1.5 rounded-lg transition">✅ סמן כשולם</button>
                ` : inv.status === 'sent' ? `
                  <button onclick="updateInvoiceStatus(${inv.id},'paid')" class="flex-1 text-xs bg-green-100 hover:bg-green-200 text-green-700 font-bold py-1.5 rounded-lg transition">✅ סמן כשולם</button>
                ` : ''}
                <button onclick="deleteLogisticsInvoice(${inv.id})" class="text-xs bg-red-50 hover:bg-red-100 text-red-600 font-bold py-1.5 px-3 rounded-lg transition">🗑️</button>
              </div>
            </div>
          `).join('')}
        </div>
      `}
    </div>`;
}

async function updateInvoiceStatus(id, status) {
    await fetch(`/api/logistics/invoices/${id}/status`, { method:'PATCH', headers:{'Content-Type':'application/json', Authorization:`Bearer ${window._bizToken}`}, body: JSON.stringify({status}) });
    loadLogisticsInvoices();
}

async function deleteLogisticsInvoice(id) {
    if (!await window._uiConfirm('למחוק חשבונית זו?', {danger:true, okLabel:'מחק'})) return;
    await fetch(`/api/logistics/invoices/${id}`, { method:'DELETE', headers:{ Authorization:`Bearer ${window._bizToken}` } });
    loadLogisticsInvoices();
}

// ===== END LOGISTICS MODULE UI v2 =====

// ─── FamliAI logistics AI — full implementation ──────────────────────────────
(function(){
    const origSubmit = window.submitGlobalAI;
    window.submitGlobalAI = async function() {
        if (currentGroup?.business_type !== 'logistics') {
            return origSubmit ? origSubmit.apply(this, arguments) : undefined;
        }
        const inputEl = getEl('global-ai-input');
        const query = inputEl ? inputEl.value.trim() : '';
        if (!query) return;
        const chatBox = getEl('global-ai-chat');
        if (chatBox) chatBox.innerHTML += `<div class="bg-indigo-600 text-white p-3 rounded-xl rounded-tl-none shadow-sm text-sm self-end max-w-[85%] fade-in">${safeStr(query)}</div>`;
        if (inputEl) inputEl.value = '';
        const btn = getEl('btn-global-ai-submit');
        if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i>'; }

        try {
            const [dashR, ordersR, codR, custR, invR] = await Promise.allSettled([
                fetch(`${API}/logistics/dashboard/${currentGroup.id}`).then(r=>r.json()).catch(()=>({})),
                fetch(`${API}/logistics/orders/${currentGroup.id}?limit=200`).then(r=>r.json()).catch(()=>([])),
                fetch(`${API}/logistics/cod/${currentGroup.id}`).then(r=>r.json()).catch(()=>({})),
                fetch(`/api/logistics/customers/${currentGroup.id}`, { headers:{Authorization:`Bearer ${window._bizToken}`} }).then(r=>r.json()),
                fetch(`/api/logistics/invoices/${currentGroup.id}`, { headers:{Authorization:`Bearer ${window._bizToken}`} }).then(r=>r.json()),
            ]);
            const dash   = dashR.status==='fulfilled'   ? dashR.value   : {};
            const orders = ordersR.status==='fulfilled' ? (ordersR.value.orders || ordersR.value || []) : [];
            const cod    = codR.status==='fulfilled'    ? codR.value    : {};

            const stats = dash.stats || dash || {};
            const now   = new Date();
            const thisM = now.getMonth(), thisY = now.getFullYear();
            const prevMDate = new Date(thisY, thisM - 1, 1);

            // Orders by status
            const ordersByStatus = {};
            orders.forEach(o => { ordersByStatus[o.status] = (ordersByStatus[o.status]||0)+1; });

            // Revenue analysis
            const deliveredOrders = orders.filter(o => ['delivered','partial'].includes(o.status));
            const monthOrders = deliveredOrders.filter(o => { const d=new Date(o.delivered_at||o.updated_at||o.created_at); return d.getMonth()===thisM&&d.getFullYear()===thisY; });
            const prevMonthOrders = deliveredOrders.filter(o => { const d=new Date(o.delivered_at||o.updated_at||o.created_at); return d.getMonth()===prevMDate.getMonth()&&d.getFullYear()===prevMDate.getFullYear(); });
            const monthRevenue = monthOrders.reduce((s,o)=>s+(parseFloat(o.delivery_fee)||0),0);
            const prevRevenue  = prevMonthOrders.reduce((s,o)=>s+(parseFloat(o.delivery_fee)||0),0);

            // Success rate
            const totalOrders = orders.filter(o=>o.status!=='cancelled').length;
            const successRate = totalOrders>0 ? Math.round((deliveredOrders.length/totalOrders)*100) : 0;
            const failedOrders = orders.filter(o=>o.status==='failed_attempt').length;

            // Driver performance (top failed)
            const driverFails = {};
            orders.filter(o=>o.status==='failed_attempt'&&o.driver_name).forEach(o=>{
                driverFails[o.driver_name] = (driverFails[o.driver_name]||0)+1;
            });
            const topFailed = Object.entries(driverFails).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([name,count])=>({name,failed_count:count}));

            // COD summary
            const codPending = (cod.orders||[]).filter(o=>!o.cod_collected&&o.cod_amount>0);
            const totalCodPending = codPending.reduce((s,o)=>s+(parseFloat(o.cod_amount)||0),0);

            // Pending (not yet picked)
            const pendingPickup = orders.filter(o=>['new','confirmed','assigned'].includes(o.status)).length;

            const logisticsContext = {
                business_type: 'logistics',
                business_name: currentGroup.name,
                date_today: now.toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),
                kpis: {
                    new_orders:      stats.new_orders      || 0,
                    assigned_orders: stats.assigned_orders || 0,
                    in_transit:      stats.in_transit      || 0,
                    delivered_today: stats.delivered_today || 0,
                    no_answer:       stats.no_answer       || 0,
                    active_drivers:  stats.active_drivers  || 0,
                    vehicle_alerts:  stats.vehicle_alerts  || 0,
                    cod_pending_amount: stats.cod_pending  || totalCodPending
                },
                orders_by_status: ordersByStatus,
                performance: {
                    total_orders:   totalOrders,
                    delivered:      deliveredOrders.length,
                    failed_attempt: failedOrders,
                    success_rate_pct: successRate,
                    pending_pickup:  pendingPickup,
                    recent_orders:   orders.slice(0,8).map(o=>({id:o.id,customer:o.customer_name,status:o.status,driver:o.driver_name,fee:o.delivery_fee,date:o.created_at}))
                },
                orders_active: orders.filter(o=>!['delivered','cancelled'].includes(o.status)).slice(0,20).map(o=>({id:o.id,customer:o.customer_name,phone:o.customer_phone,status:o.status,driver:o.driver_name,address:o.delivery_address,date:o.scheduled_date})),
                revenue: {
                    month_revenue:      monthRevenue,
                    prev_month_revenue: prevRevenue,
                    trend_pct:          prevRevenue>0 ? (((monthRevenue-prevRevenue)/prevRevenue)*100).toFixed(1) : null,
                    revenue_today:      stats.revenue_today || 0
                },
                cod_summary: {
                    total_pending: totalCodPending,
                    pending_orders_count: codPending.length,
                    sample: codPending.slice(0,5).map(o=>({customer:o.customer_name,driver:o.driver_name,amount:o.cod_amount}))
                },
                driver_performance: {
                    top_failed_drivers: topFailed
                },
                customers_summary: {
                    total: (custR.value||[]).length,
                    business_clients: (custR.value||[]).filter(c=>c.customer_type==='business').length,
                    monthly_billing: (custR.value||[]).filter(c=>c.customer_type==='monthly_billing').length,
                    with_discount: (custR.value||[]).filter(c=>parseFloat(c.discount_pct)>0).length
                },
                invoices_summary: {
                    total: (invR.value||[]).length,
                    pending: (invR.value||[]).filter(i=>i.status==='pending').length,
                    sent: (invR.value||[]).filter(i=>i.status==='sent').length,
                    paid: (invR.value||[]).filter(i=>i.status==='paid').length,
                    total_revenue: (invR.value||[]).filter(i=>i.status==='paid').reduce((s,i)=>s+parseFloat(i.total_amount||0),0)
                },
                open_tasks: (allTasks||[]).filter(t=>t.status==='pending').slice(0,5).map(t=>({title:t.title,assignee:t.assignee_name}))
            };

            const res = await fetch(`${API}/biz/chat-assistant`, {
                method:'POST',
                headers:{'Content-Type':'application/json'},
                body: JSON.stringify({ query, context: JSON.stringify(logisticsContext), groupId: currentGroup.id })
            });
            const data = await res.json();
            if (!handleAIResponseCheck(data)) { getEl('global-ai-modal')?.classList.add('hidden'); return; }

            if (data.success && data.answer) {
                let answerText = data.answer;
                let actionHtml = '';

                // Excel exports (logistics + generic)
                const excelMatch = answerText.match(/\[ACTION:EXPORT_EXCEL\|(.*?)\]/);
                if (excelMatch) {
                    const exportType = excelMatch[1].trim();
                    answerText = answerText.replace(excelMatch[0], '');
                    const exportLabels = {'logistics-orders':'הזמנות לוגיסטיקה','logistics-drivers':'נהגים','logistics-revenue':'הכנסות לוגיסטיקה','logistics-vehicles':'צי רכבים',orders:'הזמנות',cashflow:'תזרים',staff:'צוות'};
                    actionHtml += `<button onclick="window.downloadBizReport('${exportType}')" class="mt-3 w-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-file-excel"></i> הורד דוח ${exportLabels[exportType]||exportType} (Excel)</button>`;
                }
                // Task creation
                const taskMatch = answerText.match(/\[ACTION:ADD_TASK\|(.*?)\]/);
                if (taskMatch) {
                    const taskTitle = taskMatch[1].trim();
                    answerText = answerText.replace(taskMatch[0], '');
                    actionHtml += `<button onclick="document.getElementById('global-ai-modal').classList.add('hidden'); openTaskModal(); setTimeout(()=>document.getElementById('task-title').value='${safeStr(taskTitle)}',300);" class="mt-3 w-full bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-list-check"></i> פתיחת משימה: ${safeStr(taskTitle)}</button>`;
                }
                // Tab navigation
                const tabMatch = answerText.match(/\[ACTION:OPEN_TAB\|(.*?)\]/);
                if (tabMatch) {
                    const tabId = tabMatch[1].trim();
                    answerText = answerText.replace(tabMatch[0], '');
                    const tabLabels = {'logistics_orders':'קנבן הזמנות','logistics_drivers':'נהגים','logistics_vehicles':'צי רכבים','logistics_cod':'גבייה COD','logistics_rfq':'הצעות מחיר','logistics_routes':'מסלולים'};
                    actionHtml += `<button onclick="document.getElementById('global-ai-modal').classList.add('hidden'); switchTab('${tabId}')" class="mt-3 w-full bg-slate-50 text-slate-700 hover:bg-slate-100 border border-slate-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-arrow-left"></i> עבור ל${tabLabels[tabId]||tabId}</button>`;
                }
                // AI Action Parser — עדכון סטטוס משלוח
                const deliveryStatusMatch = answerText.match(/\[ACTION:UPDATE_DELIVERY_STATUS\|(\d+)\|([\w_]+)\|([^\]]*)\]/);
                if (deliveryStatusMatch) {
                    const dsId = deliveryStatusMatch[1], dsStatus = deliveryStatusMatch[2], dsCustomer = deliveryStatusMatch[3];
                    answerText = answerText.replace(deliveryStatusMatch[0], '');
                    const dsLabels = {pending:'ממתין',assigned:'שויך לנהג',in_transit:'בדרך',delivered:'נמסר',failed:'נכשל',cancelled:'בוטל'};
                    const dsColors = {pending:'bg-slate-50 text-slate-700 border-slate-200',assigned:'bg-blue-50 text-blue-700 border-blue-200',in_transit:'bg-amber-50 text-amber-700 border-amber-200',delivered:'bg-green-50 text-green-700 border-green-200',failed:'bg-red-50 text-red-700 border-red-200',cancelled:'bg-slate-50 text-slate-500 border-slate-200'};
                    const dsColor = dsColors[dsStatus] || 'bg-slate-50 text-slate-700 border-slate-200';
                    actionHtml += `<button onclick="window._aiUpdateDeliveryStatus(${dsId},'${dsStatus}','${safeStr(dsCustomer)}',this)" class="mt-3 w-full ${dsColor} hover:opacity-80 border py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-truck"></i> עדכן משלוח ${safeStr(dsCustomer)} → ${dsLabels[dsStatus]||dsStatus}</button>`;
                }
                // AI Action Parser — יצירת משימה ישירה (גנרי)
                const createTaskMatch = answerText.match(/\[ACTION:CREATE_TASK\|([^|^\]]+)\|([^|^\]]*)\|?(\d*)\]/);
                if (createTaskMatch) {
                    const ctTitle = createTaskMatch[1].trim(), ctAssignee = (createTaskMatch[2]||'self').trim(), ctDays = parseInt(createTaskMatch[3])||1;
                    answerText = answerText.replace(createTaskMatch[0], '');
                    const ctLabel = ctAssignee === 'self' ? 'לי' : ctAssignee;
                    actionHtml += `<button onclick="window._aiCreateTask('${safeStr(ctTitle)}','${safeStr(ctAssignee)}',${ctDays},this)" class="mt-3 w-full bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-list-check"></i> צור משימה ל${ctLabel}: ${safeStr(ctTitle)}</button>`;
                }
                // AI Action Parser — יצירת כלל התראה (גנרי)
                const createAlertMatch = answerText.match(/\[ACTION:CREATE_ALERT_RULE\|([^|^\]]+)\|([^|^\]]+)\|(\d*)\|?([^\]]*)\]/);
                if (createAlertMatch) {
                    const arName = createAlertMatch[1].trim(), arTrigger = createAlertMatch[2].trim(), arCooldown = parseInt(createAlertMatch[3])||60, arDesc = (createAlertMatch[4]||'').trim();
                    answerText = answerText.replace(createAlertMatch[0], '');
                    const arTriggerLabels = {new_order:'הזמנה חדשה',order_timeout_15:'הזמנה לא מטופלת 15 דקות',order_timeout_30:'הזמנה לא מטופלת 30 דקות',new_lead:'פנייה חדשה',new_booking:'הזמנה/תור חדש',new_service_call:'קריאת שירות חדשה',payment_received:'תשלום התקבל',low_stock:'מלאי נמוך'};
                    actionHtml += `<button onclick="window._aiCreateAlertRule('${safeStr(arName)}','${arTrigger}',${arCooldown},'${safeStr(arDesc)}',this)" class="mt-3 w-full bg-yellow-50 text-yellow-700 hover:bg-yellow-100 border border-yellow-200 py-2.5 rounded-xl text-sm font-bold transition flex items-center justify-center gap-2 shadow-sm"><i class="fa-solid fa-bell"></i> צור התראה: ${safeStr(arName)} — ${arTriggerLabels[arTrigger]||arTrigger}</button>`;
                }

                answerText = answerText.trim().replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');
                if (chatBox) { chatBox.innerHTML += `<div class="bg-white p-3.5 rounded-xl rounded-tr-none shadow-sm border border-slate-100 text-sm text-slate-700 self-start max-w-[85%] fade-in leading-relaxed">${answerText}${actionHtml}</div>`; chatBox.scrollTop = chatBox.scrollHeight; }
            } else { showToast('error', 'שגיאה בתשובת ה-AI'); }
        } catch(e) { showToast('error', 'תקלת רשת מול מנוע ה-AI'); }
        finally { if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-arrow-up"></i>'; } }
    };
})();

// Patch beauty_clients header to expose the forms builder button
// (We monkey-patch _renderBeautyClients to inject the extra button)
const _origRenderClients = window._renderBeautyClients;
window._renderBeautyClients = function(search) {
    _origRenderClients(search);
    // inject forms builder button next to "לקוח חדש"
    const header = document.querySelector('#content-beauty_clients .bg-gradient-to-l.from-pink-50');
    if (header) {
        const existingBtn = header.querySelector('[data-forms-btn]');
        if (!existingBtn) {
            const btn = document.createElement('button');
            btn.setAttribute('data-forms-btn', '1');
            btn.className = 'bg-white border border-indigo-300 text-indigo-600 px-3 py-2 rounded-xl text-xs font-bold hover:bg-indigo-50 transition flex items-center gap-1';
            btn.innerHTML = '<i class="fa-solid fa-file-lines"></i> טפסי ייעוץ';
            btn.onclick = window._beautyFormsBuilderModal;
            header.appendChild(btn);
        }
    }
};

// ═══════════════════════════════════════════════════════════
// BEAUTY SERVICES — שירותים וטיפולים
// ═══════════════════════════════════════════════════════════

const BEAUTY_CATEGORIES = [
    { id:'hair',   label:'שיער',         icon:'💇', color:'#fbbf24' },
    { id:'nails',  label:'ציפורניים',    icon:'💅', color:'#f472b6' },
    { id:'face',   label:'טיפולי פנים',  icon:'✨', color:'#a78bfa' },
    { id:'body',   label:'טיפולי גוף',   icon:'🧖', color:'#34d399' },
    { id:'spa',    label:'ספא / עיסוי',  icon:'🌸', color:'#60a5fa' },
    { id:'laser',  label:'לייזר / IPL',  icon:'⚡', color:'#f87171' },
    { id:'makeup', label:'איפור',        icon:'💄', color:'#fb923c' },
    { id:'general',label:'כללי',         icon:'💎', color:'#94a3b8' }
];

let _beautySvcCache = {};
let _beautyPractCache = [];

async function loadBeautyServices() {
    const biz = _beautyBizId(); if (!biz) return;
    const el = document.getElementById('content-beauty_services'); if (!el) return;
    el.innerHTML = `<div class="py-10 text-center text-slate-400 text-sm"><i class="fa-solid fa-circle-notch fa-spin text-2xl mb-2 block"></i>טוען שירותים...</div>`;
    try {
        const [items, practitioners] = await Promise.all([
            fetch(`${API}/beauty/${biz}/services`).then(r => r.json()),
            fetch(`${API}/beauty/${biz}/practitioners`).then(r => r.json()).catch(() => [])
        ]);
        _beautySvcCache = {};
        (Array.isArray(items) ? items : []).forEach(s => { _beautySvcCache[s.id] = s; });
        _beautyPractCache = Array.isArray(practitioners) ? practitioners : [];
        _renderBeautyServices(el, Array.isArray(items) ? items : []);
    } catch(e) {
        el.innerHTML = `<div class="py-10 text-center text-red-400 text-sm">שגיאה בטעינה</div>`;
    }
}

function _renderBeautyServices(el, items) {
    const byCategory = {};
    BEAUTY_CATEGORIES.forEach(c => { byCategory[c.id] = []; });
    items.forEach(s => {
        const cat = s.category || 'general';
        if (!byCategory[cat]) byCategory[cat] = [];
        byCategory[cat].push(s);
    });

    const catHtml = BEAUTY_CATEGORIES
        .filter(c => byCategory[c.id]?.length > 0)
        .map(c => `
        <div class="mb-4">
            <div class="text-xs font-black text-slate-500 mb-2 flex items-center gap-1.5">
                <span>${c.icon}</span><span>${c.label}</span>
                <span class="bg-slate-100 text-slate-600 text-[10px] px-1.5 py-0.5 rounded-full">${byCategory[c.id].length}</span>
            </div>
            <div class="space-y-2">
                ${byCategory[c.id].map(s => `
                <div class="bg-white rounded-2xl border border-slate-100 shadow-sm p-4 flex items-center gap-3">
                    <div class="w-3 h-10 rounded-full shrink-0" style="background:${s.color_hex||c.color}"></div>
                    <div class="flex-1 min-w-0">
                        <div class="font-bold text-slate-800 text-sm">${s.name}
                            ${s.requires_patch_test ? '<span class="text-[9px] bg-red-100 text-red-600 font-black px-1.5 py-0.5 rounded-full mr-1">⚠️ Patch Test</span>' : ''}
                        </div>
                        <div class="text-[11px] text-slate-400">${s.duration_minutes} דק׳ · ₪${s.price}</div>
                        ${s.description ? `<div class="text-[11px] text-slate-500 mt-0.5 truncate">${s.description}</div>` : ''}
                    </div>
                    <button onclick="window._beautyEditService(${s.id})"
                        class="w-8 h-8 rounded-xl bg-slate-100 text-slate-500 flex items-center justify-center hover:bg-slate-200 transition shrink-0">
                        <i class="fa-solid fa-pen text-xs"></i>
                    </button>
                </div>`).join('')}
            </div>
        </div>`).join('');

    el.innerHTML = `
    <div class="space-y-3 pb-24">
        <div class="flex items-center justify-between mb-4">
            <div>
                <div class="text-lg font-black text-slate-800">שירותים וטיפולים 💎</div>
                <div class="text-xs text-slate-400">${items.length} שירותים פעילים</div>
            </div>
            <button onclick="window._beautyNewServiceModal()"
                class="bg-pink-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-sm hover:bg-pink-700 transition">
                + שירות חדש
            </button>
        </div>
        ${items.length === 0
            ? `<div class="text-center py-16 text-slate-400">
                <div class="text-4xl mb-3">💎</div>
                <div class="font-bold text-slate-600 mb-1">אין שירותים עדיין</div>
                <div class="text-sm mb-4">הגדר שירותים כדי שיופיעו ביומן ובחנות הציבורית</div>
                <button onclick="window._beautyNewServiceModal()" class="bg-pink-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold">+ הוסף שירות ראשון</button>
               </div>`
            : catHtml
        }
    </div>`;
}

window._beautyNewServiceModal = function() {
    _beautyServiceModal(null, _beautyPractCache);
};

window._beautyEditService = function(id) {
    const svc = _beautySvcCache[id];
    if (!svc) return;
    _beautyServiceModal(svc, _beautyPractCache);
};

function _beautyServiceModal(svc, practitioners) {
    const isEdit = !!svc;
    const allowedIds = svc?.allowed_practitioner_ids || [];
    const practHtml = (practitioners||[]).length > 0 ? `
        <div>
            <label class="text-xs font-bold text-slate-600 block mb-1.5">מטפלות מאושרות לשירות זה</label>
            <div class="bg-slate-50 rounded-xl p-3 space-y-1.5 border border-slate-200">
                ${(practitioners||[]).map(p => `
                <label class="flex items-center gap-2 cursor-pointer">
                    <input type="checkbox" class="bsvc-pract w-4 h-4 accent-pink-500" value="${p.id}"
                        ${allowedIds.includes(p.id)||allowedIds.includes(String(p.id))?'checked':''}>
                    <span class="text-sm text-slate-700">${p.display_name||p.name||'מטפלת'}</span>
                </label>`).join('')}
                <div class="text-[10px] text-slate-400 pt-1">ריק = כל המטפלות מאושרות</div>
            </div>
        </div>` : '';

    const modal = document.createElement('div');
    modal.className = 'fixed inset-0 z-[300] flex items-end sm:items-center justify-center bg-black/40 backdrop-blur-sm p-4';
    modal.innerHTML = `
    <div class="bg-white rounded-3xl shadow-2xl w-full max-w-md p-5 max-h-[90vh] overflow-y-auto">
        <div class="flex items-center justify-between mb-4">
            <button onclick="this.closest('.fixed').remove()" class="text-slate-400 text-xl">✕</button>
            <h2 class="text-lg font-black text-slate-800">${isEdit ? '✏️ עריכת שירות' : '+ שירות חדש'}</h2>
            <span></span>
        </div>
        <div class="space-y-3">
            <div>
                <label class="text-xs font-bold text-slate-600">שם השירות *</label>
                <input id="bsvc-name" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                    value="${svc?.name||''}" placeholder='למשל: "צביעה בסיסית", "מניקור ג׳ל"'>
            </div>
            <div class="grid grid-cols-2 gap-2">
                <div>
                    <label class="text-xs font-bold text-slate-600">קטגוריה</label>
                    <select id="bsvc-cat" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm">
                        ${BEAUTY_CATEGORIES.map(c => `<option value="${c.id}" ${(svc?.category||'general')===c.id?'selected':''}>${c.icon} ${c.label}</option>`).join('')}
                    </select>
                </div>
                <div>
                    <label class="text-xs font-bold text-slate-600">משך (דקות) *</label>
                    <input id="bsvc-dur" type="number" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                        value="${svc?.duration_minutes||60}" min="5" step="5">
                </div>
            </div>
            <div class="grid grid-cols-2 gap-2">
                <div>
                    <label class="text-xs font-bold text-slate-600">מחיר (₪)</label>
                    <input id="bsvc-price" type="number" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                        value="${svc?.price||0}" min="0">
                </div>
                <div>
                    <label class="text-xs font-bold text-slate-600">% עמלה לשירות</label>
                    <input id="bsvc-comm" type="number" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                        value="${svc?.commission_pct!=null?svc.commission_pct:''}" min="0" max="100" step="0.5"
                        placeholder="ריק = ברירת מחדל מטפלת">
                </div>
            </div>
            <div class="grid grid-cols-2 gap-2">
                <div>
                    <label class="text-xs font-bold text-slate-600">צבע ביומן</label>
                    <input id="bsvc-color" type="color" class="mt-1 w-full h-[38px] border border-slate-200 rounded-xl px-2 py-1 cursor-pointer"
                        value="${svc?.color_hex||'#6366f1'}">
                </div>
            </div>
            <div>
                <label class="text-xs font-bold text-slate-600">תיאור (אופציונלי)</label>
                <textarea id="bsvc-desc" rows="2" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm">${svc?.description||''}</textarea>
            </div>
            ${practHtml}
            <label class="flex items-center gap-2 cursor-pointer">
                <input id="bsvc-patch" type="checkbox" class="w-4 h-4 accent-red-500" ${svc?.requires_patch_test?'checked':''}>
                <span class="text-sm text-slate-700">⚠️ שירות זה דורש Patch Test מוקדם</span>
            </label>
        </div>
        <button onclick="window._beautySubmitService(${isEdit ? svc.id : 'null'}, this)"
            class="mt-4 w-full py-3 bg-pink-600 text-white rounded-2xl font-black hover:bg-pink-700 transition">
            ${isEdit ? 'שמור שינויים ✓' : 'הוסף שירות ✓'}
        </button>
        ${isEdit ? `<button onclick="window._beautyDeactivateService(${svc.id}, this)" class="mt-2 w-full py-2.5 bg-red-50 text-red-600 rounded-2xl font-bold text-sm hover:bg-red-100 transition">הסר שירות</button>` : ''}
    </div>`;
    document.body.appendChild(modal);
}

window._beautySubmitService = async function(id, btn) {
    const biz = _beautyBizId(); if (!biz) return;
    const name = document.getElementById('bsvc-name')?.value?.trim();
    const dur = parseInt(document.getElementById('bsvc-dur')?.value) || 60;
    if (!name) { showToast('error', 'שם שירות הוא שדה חובה'); return; }
    btn.disabled = true; btn.textContent = 'שומר...';
    const commRaw = document.getElementById('bsvc-comm')?.value;
    const allowedPractIds = [...document.querySelectorAll('.bsvc-pract:checked')].map(cb => parseInt(cb.value));
    const body = {
        name,
        category: document.getElementById('bsvc-cat')?.value,
        duration_minutes: dur,
        price: parseFloat(document.getElementById('bsvc-price')?.value) || 0,
        color_hex: document.getElementById('bsvc-color')?.value || '#6366f1',
        description: document.getElementById('bsvc-desc')?.value?.trim() || null,
        requires_patch_test: document.getElementById('bsvc-patch')?.checked || false,
        commission_pct: commRaw !== '' && commRaw != null ? parseFloat(commRaw) : null,
        allowed_practitioner_ids: allowedPractIds
    };
    try {
        if (id) {
            await fetch(`${API}/beauty/${biz}/services/${id}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body) });
        } else {
            await fetch(`${API}/beauty/${biz}/services`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body) });
        }
        btn.closest('.fixed').remove();
        showToast('success', id ? 'השירות עודכן' : 'השירות נוסף');
        loadBeautyServices();
    } catch(e) { showToast('error', 'שגיאה'); btn.disabled = false; btn.textContent = id ? 'שמור שינויים ✓' : 'הוסף שירות ✓'; }
};

window._beautyDeactivateService = async function(id, btn) {
    if (!await window._uiConfirm('להסיר שירות זה מהרשימה?')) return;
    const biz = _beautyBizId(); if (!biz) return;
    btn.disabled = true;
    try {
        await fetch(`${API}/beauty/${biz}/services/${id}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ is_active: false }) });
        btn.closest('.fixed').remove();
        showToast('success', 'השירות הוסר');
        loadBeautyServices();
    } catch(e) { showToast('error', 'שגיאה'); btn.disabled = false; }
};

// ═══════════════════════════════════════════════════════════
// BEAUTY SUBSCRIPTIONS — מנויים וחבילות
// ═══════════════════════════════════════════════════════════

async function loadBeautySubscriptions() {
    const biz = _beautyBizId(); if (!biz) return;
    const el = document.getElementById('content-beauty_subscriptions'); if (!el) return;
    el.innerHTML = `<div class="py-10 text-center text-slate-400 text-sm"><i class="fa-solid fa-circle-notch fa-spin text-2xl mb-2 block"></i>טוען מנויים...</div>`;
    try {
        const types = await fetch(`${API}/beauty/${biz}/subscription-types`).then(r => r.json());
        _renderBeautySubscriptions(el, Array.isArray(types) ? types : []);
    } catch(e) {
        el.innerHTML = `<div class="py-10 text-center text-red-400 text-sm">שגיאה בטעינה</div>`;
    }
}

function _renderBeautySubscriptions(el, types) {
    el.innerHTML = `
    <div class="space-y-3 pb-24">
        <div class="flex items-center justify-between mb-4">
            <div>
                <div class="text-lg font-black text-slate-800">מנויים וחבילות 🎁</div>
                <div class="text-xs text-slate-400">${types.length} חבילות פעילות · לניהול מנויי לקוחות — כנס לתיק הלקוחה</div>
            </div>
            <button onclick="window._beautyNewSubTypeModal()"
                class="bg-violet-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-sm hover:bg-violet-700 transition">
                + חבילה חדשה
            </button>
        </div>

        ${types.length === 0
            ? `<div class="text-center py-16 text-slate-400">
                <div class="text-4xl mb-3">🎁</div>
                <div class="font-bold text-slate-600 mb-1">אין חבילות מנוי עדיין</div>
                <div class="text-sm mb-4">צור חבילת כניסות ומכור אותה ללקוחות דרך הקופה</div>
                <button onclick="window._beautyNewSubTypeModal()" class="bg-violet-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold">+ צור חבילה ראשונה</button>
               </div>`
            : types.map(t => `
            <div class="bg-white rounded-2xl border border-slate-100 shadow-sm p-4">
                <div class="flex items-start gap-3">
                    <div class="w-11 h-11 rounded-2xl bg-violet-100 flex items-center justify-center text-xl shrink-0">🎁</div>
                    <div class="flex-1 min-w-0">
                        <div class="font-bold text-slate-800">${t.name}</div>
                        <div class="text-xs text-slate-400 mt-0.5">
                            ${t.sessions_count} כניסות · ₪${t.price}
                            ${t.validity_days ? `· תוקף ${t.validity_days} יום` : ''}
                        </div>
                        ${t.description ? `<div class="text-xs text-slate-500 mt-1">${t.description}</div>` : ''}
                    </div>
                    <button onclick="window._beautyEditSubType(${t.id},'${(t.name).replace(/'/g,"\\'")}',${t.sessions_count},${t.price},${t.validity_days||365})"
                        class="w-8 h-8 rounded-xl bg-slate-100 text-slate-500 flex items-center justify-center hover:bg-slate-200 transition shrink-0">
                        <i class="fa-solid fa-pen text-xs"></i>
                    </button>
                </div>
                <div class="mt-3 pt-3 border-t border-slate-100">
                    <div class="text-[11px] text-slate-500">💡 למכירה ללקוחה: כנס לתיק הלקוחה → כפתור "מכור מנוי"</div>
                </div>
            </div>`).join('')
        }

        <div class="bg-violet-50 border border-violet-200 rounded-2xl p-4">
            <div class="font-bold text-violet-800 text-sm mb-1">🎯 איך עובדים מנויים?</div>
            <div class="text-xs text-violet-700 space-y-1">
                <div>1. צור חבילה כאן (כמות כניסות + מחיר + תוקף)</div>
                <div>2. כנס לתיק הלקוחה → "מכור מנוי" → בחר חבילה → גבה תשלום</div>
                <div>3. בקביעת תור — המערכת מציגה מנויים פעילים ומאפשרת מימוש כניסה</div>
            </div>
        </div>
    </div>`;
}

window._beautyNewSubTypeModal = function() {
    _beautySubTypeModal(null);
};

window._beautyEditSubType = function(id, name, sessions, price, validity) {
    _beautySubTypeModal({ id, name, sessions_count: sessions, price, validity_days: validity });
};

function _beautySubTypeModal(t) {
    const isEdit = !!t;
    const modal = document.createElement('div');
    modal.className = 'fixed inset-0 z-[300] flex items-end sm:items-center justify-center bg-black/40 backdrop-blur-sm p-4';
    modal.innerHTML = `
    <div class="bg-white rounded-3xl shadow-2xl w-full max-w-md p-5">
        <div class="flex items-center justify-between mb-4">
            <button onclick="this.closest('.fixed').remove()" class="text-slate-400 text-xl">✕</button>
            <h2 class="text-lg font-black text-slate-800">${isEdit ? '✏️ עריכת חבילה' : '+ חבילה חדשה'}</h2>
            <span></span>
        </div>
        <div class="space-y-3">
            <div>
                <label class="text-xs font-bold text-slate-600">שם החבילה *</label>
                <input id="bsub-name" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                    value="${t?.name||''}" placeholder='למשל: "חבילת 5 טיפולי פנים", "מנוי ציפורניים חודשי"'>
            </div>
            <div class="grid grid-cols-3 gap-2">
                <div>
                    <label class="text-xs font-bold text-slate-600">כמות כניסות *</label>
                    <input id="bsub-sessions" type="number" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                        value="${t?.sessions_count||5}" min="1">
                </div>
                <div>
                    <label class="text-xs font-bold text-slate-600">מחיר כולל (₪)</label>
                    <input id="bsub-price" type="number" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                        value="${t?.price||0}" min="0">
                </div>
                <div>
                    <label class="text-xs font-bold text-slate-600">תוקף (ימים)</label>
                    <input id="bsub-validity" type="number" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                        value="${t?.validity_days||365}" min="30">
                </div>
            </div>
            <div>
                <label class="text-xs font-bold text-slate-600">תיאור (אופציונלי)</label>
                <input id="bsub-desc" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm"
                    value="${t?.description||''}" placeholder="למשל: כולל גיל ניקוי + מסכה">
            </div>
        </div>
        <button onclick="window._beautySubmitSubType(${isEdit?t.id:'null'}, this)"
            class="mt-4 w-full py-3 bg-violet-600 text-white rounded-2xl font-black hover:bg-violet-700 transition">
            ${isEdit ? 'שמור שינויים ✓' : 'צור חבילה ✓'}
        </button>
        ${isEdit ? `<button onclick="window._beautyDeactivateSubType(${t.id},this)" class="mt-2 w-full py-2.5 bg-red-50 text-red-600 rounded-2xl font-bold text-sm">הסר חבילה</button>` : ''}
    </div>`;
    document.body.appendChild(modal);
}

window._beautySubmitSubType = async function(id, btn) {
    const biz = _beautyBizId(); if (!biz) return;
    const name = document.getElementById('bsub-name')?.value?.trim();
    const sessions = parseInt(document.getElementById('bsub-sessions')?.value) || 5;
    if (!name) { showToast('error', 'שם חבילה הוא שדה חובה'); return; }
    btn.disabled = true; btn.textContent = 'שומר...';
    const body = {
        name,
        sessions_count: sessions,
        price: parseFloat(document.getElementById('bsub-price')?.value) || 0,
        validity_days: parseInt(document.getElementById('bsub-validity')?.value) || 365,
        description: document.getElementById('bsub-desc')?.value?.trim() || null
    };
    try {
        if (id) {
            await fetch(`${API}/beauty/${biz}/subscription-types/${id}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body) });
        } else {
            await fetch(`${API}/beauty/${biz}/subscription-types`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body) });
        }
        btn.closest('.fixed').remove();
        showToast('success', id ? 'החבילה עודכנה' : 'החבילה נוצרה');
        loadBeautySubscriptions();
    } catch(e) { showToast('error', 'שגיאה'); btn.disabled = false; btn.textContent = id ? 'שמור שינויים ✓' : 'צור חבילה ✓'; }
};

window._beautyDeactivateSubType = async function(id, btn) {
    if (!await window._uiConfirm('להסיר חבילה זו?')) return;
    const biz = _beautyBizId(); if (!biz) return;
    btn.disabled = true;
    try {
        await fetch(`${API}/beauty/${biz}/subscription-types/${id}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ is_active: false }) });
        btn.closest('.fixed').remove();
        showToast('success', 'החבילה הוסרה');
        loadBeautySubscriptions();
    } catch(e) { showToast('error', 'שגיאה'); btn.disabled = false; }
};

// ═══════════════════════════════════════════════════════════
// BEAUTY RFQ — ייעוץ ובקשות מ-ONEFLOW LIFE
// ═══════════════════════════════════════════════════════════

const RFQ_STATUS = {
    new:                  { label:'חדש',               color:'bg-sky-100 text-sky-700',      icon:'🆕' },
    questionnaire_sent:   { label:'שאלון נשלח',        color:'bg-indigo-100 text-indigo-700', icon:'📋' },
    photos_requested:     { label:'ממתין לתמונות',     color:'bg-amber-100 text-amber-700',   icon:'📸' },
    plan_sent:            { label:'תוכנית נשלחה',      color:'bg-violet-100 text-violet-700', icon:'📄' },
    accepted:             { label:'אושר',              color:'bg-emerald-100 text-emerald-700',icon:'✅' },
    rejected:             { label:'נדחה',              color:'bg-red-100 text-red-700',       icon:'❌' },
    booked:               { label:'תורים נקבעו',       color:'bg-green-100 text-green-700',   icon:'📅' }
};

async function loadBeautyRfq() {
    const biz = _beautyBizId(); if (!biz) return;
    const el = document.getElementById('content-beauty_rfq'); if (!el) return;
    el.innerHTML = `<div class="py-10 text-center text-slate-400 text-sm"><i class="fa-solid fa-circle-notch fa-spin text-2xl mb-2 block"></i>טוען בקשות ייעוץ...</div>`;
    try {
        const data = await fetch(`${API}/beauty/${biz}/rfq`).then(r => r.json());
        _renderBeautyRfq(el, Array.isArray(data) ? data : []);
    } catch(e) {
        el.innerHTML = `<div class="py-10 text-center text-red-400 text-sm">שגיאה בטעינת הנתונים</div>`;
    }
}

function _renderBeautyRfq(el, items) {
    const stats = {
        open: items.filter(r => !['accepted','rejected','booked'].includes(r.status)).length,
        pending_plan: items.filter(r => r.status === 'questionnaire_sent' || r.status === 'photos_requested').length,
        booked: items.filter(r => r.status === 'booked').length
    };

    el.innerHTML = `
    <div class="space-y-3 pb-24">
        <div class="bg-gradient-to-l from-pink-600 to-rose-700 rounded-3xl p-5 text-white shadow-lg mb-4">
            <div class="text-lg font-black mb-1">💬 ייעוץ ובקשות</div>
            <div class="text-sm opacity-80 mb-3">בקשות טיפול שהגיעו מלקוחות ONEFLOW LIFE</div>
            <div class="grid grid-cols-3 gap-3">
                <div class="bg-white/15 rounded-2xl p-3 text-center">
                    <div class="text-2xl font-black">${stats.open}</div>
                    <div class="text-[10px] opacity-80">פתוחות</div>
                </div>
                <div class="bg-white/15 rounded-2xl p-3 text-center">
                    <div class="text-2xl font-black">${stats.pending_plan}</div>
                    <div class="text-[10px] opacity-80">ממתינות לתגובה</div>
                </div>
                <div class="bg-white/15 rounded-2xl p-3 text-center">
                    <div class="text-2xl font-black">${stats.booked}</div>
                    <div class="text-[10px] opacity-80">הפכו לתורים</div>
                </div>
            </div>
        </div>

        ${items.length === 0
            ? `<div class="text-center py-16 text-slate-400">
                <div class="text-4xl mb-3">💬</div>
                <div class="font-bold text-slate-600 mb-1">אין בקשות ייעוץ עדיין</div>
                <div class="text-sm">לקוחות ONEFLOW LIFE יכולות לשלוח בקשות טיפול מהאפליקציה הקהילתית</div>
               </div>`
            : items.map(rfq => _beautyRfqCard(rfq)).join('')
        }
    </div>`;
}

function _beautyRfqCard(rfq) {
    const st = RFQ_STATUS[rfq.status] || { label: rfq.status, color: 'bg-slate-100 text-slate-600', icon: '•' };
    const msgs = Array.isArray(rfq.messages) ? rfq.messages : [];
    const lastMsg = msgs.length > 0 ? msgs[msgs.length - 1] : null;
    const date = new Date(rfq.created_at).toLocaleDateString('he-IL');
    const canSendQuestionnaire = rfq.status === 'new';
    const canSendPlan = rfq.status === 'questionnaire_sent' || rfq.status === 'photos_requested';

    return `
    <div class="bg-white rounded-2xl border border-slate-100 shadow-sm p-4">
        <div class="flex items-start justify-between gap-2 mb-3">
            <div class="flex-1 min-w-0">
                <div class="flex items-center gap-2 flex-wrap mb-1">
                    <span class="text-xs font-black px-2 py-0.5 rounded-full ${st.color}">${st.icon} ${st.label}</span>
                    <span class="text-[11px] text-slate-400">${date}</span>
                </div>
                <p class="text-sm text-slate-700 font-medium leading-snug">${rfq.service_description || '—'}</p>
                ${rfq.client_name ? `<p class="text-xs text-slate-400 mt-0.5">👤 ${rfq.client_name}</p>` : ''}
            </div>
        </div>

        ${lastMsg ? `
        <div class="bg-slate-50 rounded-xl p-2.5 mb-3 text-xs text-slate-600">
            <span class="font-bold text-slate-500">${lastMsg.from === 'biz' ? 'הסלון' : 'לקוחה'}:</span>
            ${lastMsg.text}
        </div>` : ''}

        ${rfq.questionnaire_data ? `
        <div class="bg-indigo-50 rounded-xl p-2.5 mb-3">
            <div class="text-[11px] font-black text-indigo-700 mb-1">📋 תשובות שאלון</div>
            ${Object.entries(rfq.questionnaire_data).map(([k,v]) =>
                `<div class="text-xs text-slate-600"><span class="font-bold">${k}:</span> ${v}</div>`
            ).join('')}
        </div>` : ''}

        ${Array.isArray(rfq.client_photos) && rfq.client_photos.length > 0 ? `
        <div class="flex gap-2 mb-3 overflow-x-auto">
            ${rfq.client_photos.slice(0,4).map(p =>
                `<img src="${p.url||p}" class="w-16 h-16 rounded-xl object-cover shrink-0 border border-slate-200" onerror="this.style.display='none'">`
            ).join('')}
        </div>` : ''}

        <div class="flex gap-2 flex-wrap">
            ${canSendQuestionnaire ? `
            <button onclick="window._beautyRfqSendQuestionnaire(${rfq.id})"
                class="flex-1 py-2 bg-indigo-600 text-white rounded-xl text-xs font-bold">
                📋 שלח שאלון
            </button>` : ''}
            ${canSendPlan ? `
            <button onclick="window._beautyRfqSendPlan(${rfq.id})"
                class="flex-1 py-2 bg-emerald-600 text-white rounded-xl text-xs font-bold">
                📄 שלח תוכנית טיפולים
            </button>` : ''}
            <button onclick="window._beautyRfqChat(${rfq.id})"
                class="flex-1 py-2 bg-slate-100 text-slate-700 rounded-xl text-xs font-bold">
                💬 צ'אט
            </button>
        </div>
    </div>`;
}

window._beautyRfqSendQuestionnaire = async function(rfqId) {
    const questions = await window._uiPrompt('הכנס שאלות לשאלון (מופרדות בפסיק):', {defaultValue:'האם יש אלרגיות?,האם בוצע Patch Test בעבר?,תאר את מצב העור/שיער הנוכחי'});
    if (!questions) return;
    const biz = _beautyBizId(); if (!biz) return;
    try {
        const qObj = {};
        questions.split(',').forEach((q, i) => { qObj[`שאלה ${i+1}`] = q.trim(); });
        await fetch(`${API}/beauty/rfq/${rfqId}/questionnaire`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ questions: qObj })
        });
        showToast('success', 'השאלון נשלח ללקוחה');
        loadBeautyRfq();
    } catch(e) { showToast('error', 'שגיאה בשליחת השאלון'); }
};

window._beautyRfqSendPlan = function(rfqId) {
    const biz = _beautyBizId(); if (!biz) return;
    const modal = document.createElement('div');
    modal.className = 'fixed inset-0 z-[300] flex items-end sm:items-center justify-center bg-black/40 backdrop-blur-sm p-4';
    modal.innerHTML = `
    <div class="bg-white rounded-3xl shadow-2xl w-full max-w-md p-5 max-h-[90vh] overflow-y-auto">
        <div class="flex items-center justify-between mb-4">
            <button onclick="this.closest('.fixed').remove()" class="text-slate-400 text-xl">✕</button>
            <h2 class="text-lg font-black text-slate-800">📄 שלח תוכנית טיפולים</h2>
            <span></span>
        </div>
        <div class="space-y-3">
            <div>
                <label class="text-xs font-bold text-slate-600">כותרת התוכנית</label>
                <input id="rfqplan-title" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm" placeholder="למשל: שיקום עור פנים מלא">
            </div>
            <div>
                <label class="text-xs font-bold text-slate-600">תיאור הטיפולים</label>
                <textarea id="rfqplan-desc" rows="3" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm" placeholder="תיאור מפורט של הטיפולים המוצעים..."></textarea>
            </div>
            <div class="grid grid-cols-2 gap-2">
                <div>
                    <label class="text-xs font-bold text-slate-600">מחיר כולל (₪)</label>
                    <input id="rfqplan-price" type="number" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm">
                </div>
                <div>
                    <label class="text-xs font-bold text-slate-600">מקדמה נדרשת (₪)</label>
                    <input id="rfqplan-deposit" type="number" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm" value="0">
                </div>
            </div>
            <div>
                <label class="text-xs font-bold text-slate-600">הודעה ללקוחה (אופציונלי)</label>
                <textarea id="rfqplan-note" rows="2" class="mt-1 w-full border border-slate-200 rounded-xl px-3 py-2 text-sm" placeholder="הסבר נוסף, שאלות, הנחיות..."></textarea>
            </div>
        </div>
        <button onclick="window._beautyRfqSubmitPlan(${rfqId}, this)"
            class="mt-4 w-full py-3 bg-emerald-600 text-white rounded-2xl font-black">שלח תוכנית ✉️</button>
    </div>`;
    document.body.appendChild(modal);
};

window._beautyRfqSubmitPlan = async function(rfqId, btn) {
    const title = document.getElementById('rfqplan-title')?.value?.trim();
    const desc = document.getElementById('rfqplan-desc')?.value?.trim();
    const price = parseFloat(document.getElementById('rfqplan-price')?.value) || 0;
    const deposit = parseFloat(document.getElementById('rfqplan-deposit')?.value) || 0;
    const note = document.getElementById('rfqplan-note')?.value?.trim();
    if (!title) { showToast('error', 'כותרת חובה'); return; }
    btn.disabled = true; btn.textContent = 'שולח...';
    try {
        await fetch(`${API}/beauty/rfq/${rfqId}/plan`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ treatment_plan: { title, description: desc, total_price: price, deposit_amount: deposit }, message: note })
        });
        btn.closest('.fixed').remove();
        showToast('success', 'תוכנית הטיפולים נשלחה ללקוחה');
        loadBeautyRfq();
    } catch(e) { showToast('error', 'שגיאה'); btn.disabled = false; btn.textContent = 'שלח תוכנית ✉️'; }
};

window._beautyRfqChat = async function(rfqId) {
    const biz = _beautyBizId(); if (!biz) return;
    const text = await window._uiPrompt('הכנס הודעה ללקוחה:');
    if (!text) return;
    try {
        await fetch(`${API}/beauty/rfq/${rfqId}/message`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ text, from: 'biz' })
        });
        showToast('success', 'ההודעה נשלחה');
        loadBeautyRfq();
    } catch(e) { showToast('error', 'שגיאה בשליחת ההודעה'); }
};


// ─── BEAUTY PRACTITIONERS — מטפלות וצוות יופי ──────────────────────────────
async function loadBeautyPractitioners() {
    const biz = currentGroup?.id; if (!biz) return;
    const el = document.getElementById('content-beauty_practitioners'); if (!el) return;
    el.innerHTML = `<div class="py-10 text-center text-slate-400 text-sm"><i class="fa-solid fa-circle-notch fa-spin text-2xl mb-2 block"></i>טוען מטפלות...</div>`;
    let practitioners = [];
    try {
        const r = await fetch(`${API}/beauty/${biz}/practitioners`);
        practitioners = r.ok ? (await r.json()) : [];
        if (!Array.isArray(practitioners)) practitioners = [];
    } catch(e) {}

    el.innerHTML = `
        <div class="flex items-center justify-between mb-4 px-1">
            <button onclick="window._beautyPractModal()" class="bg-pink-600 text-white px-4 py-2.5 rounded-xl text-sm font-bold shadow-sm hover:bg-pink-700 transition flex items-center gap-2">
                <i class="fa-solid fa-plus"></i> מטפלת חדשה
            </button>
            <h2 class="text-lg font-black text-slate-800">מטפלות 💆</h2>
        </div>
        ${practitioners.length === 0 ? `
            <div class="text-center py-12 bg-pink-50 rounded-2xl border border-pink-100">
                <div class="text-4xl mb-3">💆</div>
                <div class="font-bold text-slate-600 mb-1">אין מטפלות מוגדרות עדיין</div>
                <div class="text-xs text-slate-400 mb-4">הוסף מטפלת ראשונה להתחלת עבודה</div>
                <button onclick="window._beautyPractModal()" class="bg-pink-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow hover:bg-pink-700 transition">הוסף מטפלת</button>
            </div>
        ` : `
            <div class="space-y-3">
                ${practitioners.map(p => `
                    <div class="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex items-center justify-between">
                        <div class="flex gap-2">
                            <button onclick="window._beautyPractModal(${JSON.stringify(p).replace(/"/g,'&quot;')})" class="text-xs bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 py-1.5 rounded-lg font-bold transition">עריכה</button>
                            <button onclick="window._beautyPractToggle(${p.id}, ${p.is_active})" class="text-xs ${p.is_active ? 'bg-red-50 hover:bg-red-100 text-red-500' : 'bg-emerald-50 hover:bg-emerald-100 text-emerald-600'} px-3 py-1.5 rounded-lg font-bold transition">${p.is_active ? 'השבת' : 'הפעל'}</button>
                        </div>
                        <div class="flex items-center gap-3 text-right">
                            <div>
                                <div class="font-bold text-slate-800 text-sm">${safeStr(p.display_name)}</div>
                                <div class="text-[11px] text-slate-400">${safeStr(p.tier||'')}${p.commission_rate_svc ? ` · עמלת שירות: ${p.commission_rate_svc}%` : ''}${p.commission_rate_retail ? ` · עמלת קמעונאות: ${p.commission_rate_retail}%` : ''}</div>
                                ${p.specializations?.length ? `<div class="text-[10px] text-pink-500 mt-0.5">${p.specializations.join(' · ')}</div>` : ''}
                            </div>
                            <div class="w-10 h-10 rounded-full flex items-center justify-center font-black text-white text-sm shrink-0" style="background:${p.color_hex||'#ec4899'}">${(p.display_name||'?').charAt(0)}</div>
                        </div>
                    </div>
                `).join('')}
            </div>
        `}
    `;
}

window._beautyPractModal = function(p = null) {
    const isEdit = !!p;
    const TIERS = ['מטפלת ג׳וניור','מטפלת','מטפלת בכירה','מנהלת טיפולים'];
    const SPECS = ['פנים','גוף','ציפורניים','שיער','הסרת שיער','עיסוי','איפור','ריסים'];

    const modal = document.createElement('div');
    modal.id = 'beauty-pract-modal';
    modal.className = 'fixed inset-0 z-50 flex items-end justify-center bg-black/40 backdrop-blur-sm';
    modal.innerHTML = `
        <div class="bg-white w-full max-w-lg rounded-t-3xl p-6 pb-8 shadow-2xl max-h-[90vh] overflow-y-auto" dir="rtl">
            <div class="flex items-center justify-between mb-5">
                <button onclick="document.getElementById('beauty-pract-modal').remove()" class="text-slate-400 hover:text-slate-600 text-xl"><i class="fa-solid fa-xmark"></i></button>
                <h3 class="text-base font-black text-slate-800">${isEdit ? 'עריכת מטפלת' : 'מטפלת חדשה'}</h3>
            </div>
            <div class="space-y-4">
                <div>
                    <label class="text-xs font-bold text-slate-500 block mb-1">שם מלא *</label>
                    <input id="bp-name" type="text" value="${safeStr(p?.display_name||'')}" placeholder="שם המטפלת" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-pink-400">
                </div>
                <div class="grid grid-cols-2 gap-3">
                    <div>
                        <label class="text-xs font-bold text-slate-500 block mb-1">דרגה</label>
                        <select id="bp-tier" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-pink-400">
                            <option value="">בחר...</option>
                            ${TIERS.map(t => `<option value="${t}" ${p?.tier===t?'selected':''}>${t}</option>`).join('')}
                        </select>
                    </div>
                    <div>
                        <label class="text-xs font-bold text-slate-500 block mb-1">צבע זיהוי</label>
                        <input id="bp-color" type="color" value="${p?.color_hex||'#ec4899'}" class="w-full h-10 border border-slate-200 rounded-xl px-1 py-1 cursor-pointer">
                    </div>
                </div>
                <div class="grid grid-cols-2 gap-3">
                    <div>
                        <label class="text-xs font-bold text-slate-500 block mb-1">% עמלת שירות</label>
                        <input id="bp-comm-svc" type="number" min="0" max="100" step="0.5" value="${p?.commission_rate_svc??''}" placeholder="0" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-pink-400">
                    </div>
                    <div>
                        <label class="text-xs font-bold text-slate-500 block mb-1">% עמלת קמעונאות</label>
                        <input id="bp-comm-retail" type="number" min="0" max="100" step="0.5" value="${p?.commission_rate_retail??''}" placeholder="0" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-pink-400">
                    </div>
                </div>
                <div>
                    <label class="text-xs font-bold text-slate-500 block mb-1">התמחויות</label>
                    <div class="flex flex-wrap gap-2">
                        ${SPECS.map(s => `
                            <label class="flex items-center gap-1 cursor-pointer">
                                <input type="checkbox" class="bp-spec" value="${s}" ${p?.specializations?.includes(s)?'checked':''}>
                                <span class="text-xs text-slate-600">${s}</span>
                            </label>
                        `).join('')}
                    </div>
                </div>
                <button onclick="window._beautyPractSave(${isEdit ? p.id : 'null'})" class="w-full bg-pink-600 text-white py-3 rounded-xl font-bold shadow hover:bg-pink-700 transition mt-2">
                    <i class="fa-solid fa-check mr-1"></i> ${isEdit ? 'שמור שינויים' : 'הוסף מטפלת'}
                </button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
};

window._beautyPractSave = async function(id) {
    const biz = currentGroup?.id; if (!biz) return;
    const name = document.getElementById('bp-name')?.value?.trim();
    if (!name) { showToast('error', 'נא להזין שם מטפלת'); return; }
    const specs = [...document.querySelectorAll('.bp-spec:checked')].map(cb => cb.value);
    const body = {
        display_name: name,
        tier: document.getElementById('bp-tier')?.value || null,
        color_hex: document.getElementById('bp-color')?.value || '#ec4899',
        commission_rate_svc: parseFloat(document.getElementById('bp-comm-svc')?.value) || 0,
        commission_rate_retail: parseFloat(document.getElementById('bp-comm-retail')?.value) || 0,
        specializations: specs
    };
    try {
        const method = id ? 'PATCH' : 'POST';
        const url = id ? `${API}/beauty/${biz}/practitioners/${id}` : `${API}/beauty/${biz}/practitioners`;
        const r = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
        if (!r.ok) throw new Error();
        showToast('success', id ? 'פרטי המטפלת עודכנו' : 'מטפלת נוספה בהצלחה');
        document.getElementById('beauty-pract-modal')?.remove();
        loadBeautyPractitioners();
    } catch(e) { showToast('error', 'שגיאה בשמירה'); }
};

window._beautyPractToggle = async function(id, isActive) {
    const biz = currentGroup?.id; if (!biz) return;
    if (!await window._uiConfirm(isActive ? 'להשבית מטפלת זו?' : 'להפעיל מטפלת זו מחדש?')) return;
    try {
        await fetch(`${API}/beauty/${biz}/practitioners/${id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ is_active: !isActive })
        });
        showToast('success', isActive ? 'המטפלת הושבתה' : 'המטפלת הופעלה');
        loadBeautyPractitioners();
    } catch(e) { showToast('error', 'שגיאה בעדכון'); }
};

// ─── REVIEWS MODULE ───────────────────────────────────────────────────────────
window.loadReviews = async function() {
    const root = document.getElementById('reviews-root');
    if (!root || !currentGroup?.id) return;
    root.innerHTML = '<div class="py-12 text-center text-slate-400 text-sm">טוען דירוגים...</div>';
    try {
        const res = await fetch(`${API}/store/orders/${currentGroup.id}`);
        const all = await res.json();
        if (!Array.isArray(all)) { root.innerHTML = '<p class="text-center text-slate-400 py-8">שגיאה בטעינה</p>'; return; }

        const rated = all.filter(o => o.customer_rating > 0)
                         .sort((a,b) => new Date(b.customer_rated_at||b.created_at) - new Date(a.customer_rated_at||a.created_at));

        const total = rated.length;
        const avg = total ? (rated.reduce((s,o) => s + parseFloat(o.customer_rating), 0) / total).toFixed(1) : 0;
        const dist = [5,4,3,2,1].map(n => ({ n, cnt: rated.filter(o => o.customer_rating === n).length }));

        // ── טרנד שבועי ──
        const now = Date.now();
        const DAY = 86400000;
        const last7  = rated.filter(o => now - new Date(o.customer_rated_at||o.created_at) < 7*DAY);
        const prev7  = rated.filter(o => { const age = now - new Date(o.customer_rated_at||o.created_at); return age >= 7*DAY && age < 14*DAY; });
        const avg7   = last7.length  ? (last7.reduce((s,o)=>s+parseFloat(o.customer_rating),0)/last7.length).toFixed(1)  : null;
        const avgP7  = prev7.length  ? (prev7.reduce((s,o)=>s+parseFloat(o.customer_rating),0)/prev7.length).toFixed(1)  : null;
        let trendHtml = '';
        if (avg7 !== null && avgP7 !== null) {
            const diff = parseFloat(avg7) - parseFloat(avgP7);
            const trendIcon  = diff > 0.1 ? '↗️' : diff < -0.1 ? '↘️' : '→';
            const trendColor = diff > 0.1 ? 'text-green-300' : diff < -0.1 ? 'text-red-300' : 'text-yellow-100';
            trendHtml = `<div class="mt-2 text-[10px] ${trendColor} font-bold">${trendIcon} שבוע אחרון: ${avg7} (${diff>=0?'+':''}${diff.toFixed(1)} לעומת שבוע קודם)</div>`;
        }

        const kpiHtml = `
        <div class="bg-gradient-to-br from-yellow-400 to-orange-500 rounded-[2rem] p-5 text-white shadow-xl mb-4 relative overflow-hidden">
            <i class="fa-solid fa-star absolute -left-4 -bottom-4 text-8xl text-white opacity-10"></i>
            <h3 class="text-lg font-black mb-1">⭐ דירוגים וביקורות לקוח</h3>
            <p class="text-yellow-100 text-xs mb-3">כל הדירוגים שהתקבלו מלקוחות</p>
            <div class="flex items-center gap-6">
                <div class="text-center">
                    <div class="text-4xl font-black">${avg}</div>
                    <div class="text-[10px] text-yellow-100">ממוצע</div>
                </div>
                <div class="flex-1">
                    ${dist.map(d => {
                        const pct = total ? Math.round(d.cnt / total * 100) : 0;
                        return `<div class="flex items-center gap-1.5 mb-0.5">
                            <span class="text-[10px] text-yellow-100 w-3">${d.n}</span>
                            <div class="flex-1 bg-white/20 rounded-full h-1.5 overflow-hidden">
                                <div class="bg-white h-full rounded-full" style="width:${pct}%"></div>
                            </div>
                            <span class="text-[10px] text-yellow-100 w-4 text-left">${d.cnt}</span>
                        </div>`;
                    }).join('')}
                </div>
                <div class="text-center">
                    <div class="text-3xl font-black">${total}</div>
                    <div class="text-[10px] text-yellow-100">דירוגים</div>
                </div>
            </div>
            ${trendHtml}
        </div>`;

        if (total === 0) {
            root.innerHTML = kpiHtml + '<div class="py-12 text-center text-slate-400"><p class="text-4xl mb-2">⭐</p><p class="text-sm font-bold">עדיין אין דירוגים</p><p class="text-xs text-slate-400 mt-1">הדירוגים יופיעו כאן לאחר שלקוחות ידרגו הזמנות</p></div>';
            return;
        }

        // ── דירוגים שליליים — מחייבים תגובה ──
        const negative = rated.filter(o => o.customer_rating <= 2);
        const negativeHtml = negative.length ? `
        <div class="bg-red-50 border border-red-200 rounded-2xl p-4 mb-4">
            <div class="flex items-center gap-2 mb-3">
                <span class="text-red-500 text-lg">🚨</span>
                <h4 class="font-black text-red-700 text-sm">דירוגים שליליים — נדרשת פעולה (${negative.length})</h4>
            </div>
            ${negative.map(o => `
            <div class="bg-white border border-red-100 rounded-xl p-3 mb-2 last:mb-0">
                <div class="flex items-center justify-between gap-2 flex-wrap">
                    <div>
                        <span class="font-bold text-slate-800 text-sm">${safeStr(o.customer_name||'לקוח')}</span>
                        <span class="text-red-500 font-black ml-2">${'⭐'.repeat(o.customer_rating)}${'☆'.repeat(5-o.customer_rating)}</span>
                    </div>
                    ${o.customer_phone ? `<a href="tel:${safeStr(o.customer_phone)}" class="bg-red-500 text-white text-[11px] font-black px-3 py-1.5 rounded-xl flex items-center gap-1 shrink-0">📞 התקשר</a>` : ''}
                </div>
                ${o.customer_rating_notes ? `<p class="text-xs text-slate-600 mt-1 leading-relaxed">"${safeStr(o.customer_rating_notes)}"</p>` : ''}
            </div>`).join('')}
        </div>` : '';

        const listHtml = `<div class="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div class="px-4 py-3 border-b border-slate-100 flex items-center justify-between">
                <h3 class="font-black text-slate-800 text-sm">📋 כל הדירוגים (${total})</h3>
            </div>
            <div class="divide-y divide-slate-50">
            ${rated.map(o => {
                const stars = '⭐'.repeat(o.customer_rating) + '☆'.repeat(5 - o.customer_rating);
                const dateStr = o.customer_rated_at
                    ? new Date(o.customer_rated_at).toLocaleDateString('he-IL',{day:'numeric',month:'short',year:'numeric'})
                    : (o.created_at ? new Date(o.created_at).toLocaleDateString('he-IL',{day:'numeric',month:'short'}) : '');
                const ratingColor = o.customer_rating >= 4 ? 'text-green-600' : o.customer_rating === 3 ? 'text-yellow-600' : 'text-red-500';
                const isNeg = o.customer_rating <= 2;
                const deliveryBadge = o.is_delivery ? '<span class="text-[9px] bg-purple-50 text-purple-600 border border-purple-200 px-1.5 py-0.5 rounded-full font-bold">🚚 משלוח</span>' : '';
                const srcBadge = o.order_source === 'table' ? '<span class="text-[9px] bg-violet-50 text-violet-600 border border-violet-200 px-1.5 py-0.5 rounded-full font-bold">🍽️ שולחן</span>' : '<span class="text-[9px] bg-blue-50 text-blue-600 border border-blue-200 px-1.5 py-0.5 rounded-full font-bold">🌐 אתר</span>';
                return `<div class="px-4 py-3 hover:bg-slate-50 transition${isNeg?' bg-red-50/40':''}">
                    <div class="flex items-start gap-3">
                        <div class="w-10 h-10 rounded-xl ${isNeg?'bg-red-100 border-red-300':'bg-yellow-50 border-yellow-200'} border flex items-center justify-center shrink-0">
                            <span class="text-lg font-black ${ratingColor}">${o.customer_rating}</span>
                        </div>
                        <div class="flex-1 min-w-0">
                            <div class="flex items-center gap-2 flex-wrap">
                                <span class="text-sm font-black text-slate-800">${safeStr(o.customer_name||'לקוח אנונימי')}</span>
                                <span class="text-[10px] text-slate-400">#${o.id}</span>
                                ${deliveryBadge}${srcBadge}
                                ${isNeg ? '<span class="text-[9px] bg-red-100 text-red-600 border border-red-200 px-1.5 py-0.5 rounded-full font-bold">⚠️ שלילי</span>' : ''}
                            </div>
                            <div class="text-sm text-yellow-500 my-0.5">${stars}</div>
                            ${o.customer_rating_notes ? `<p class="text-xs text-slate-600 leading-relaxed">"${safeStr(o.customer_rating_notes)}"</p>` : ''}
                            <div class="flex items-center gap-3 mt-1">
                                <span class="text-[10px] text-slate-400">${dateStr}</span>
                                ${o.customer_phone ? `<a href="tel:${safeStr(o.customer_phone)}" class="text-[10px] text-blue-500 font-bold">${safeStr(o.customer_phone)}</a>` : ''}
                                <button onclick="window.openStoreOrderModal(${o.id})" class="text-[10px] text-indigo-500 font-bold hover:underline">הצג הזמנה</button>
                            </div>
                        </div>
                    </div>
                </div>`;
            }).join('')}
            </div>
        </div>`;

        root.innerHTML = kpiHtml + negativeHtml + listHtml;
    } catch(e) {
        root.innerHTML = '<p class="text-center text-red-400 py-8">שגיאה בטעינת דירוגים</p>';
    }
};

// ============================================================
// ===== PROFESSIONAL MODULE — תיקים ושעות עבודה =====
// ============================================================

// ─── מודול תיקים (Cases) ─────────────────────────────────────
window.renderCasesTab = async function() {
    const el = document.getElementById('content-cases');
    if (!el) return;
    el.innerHTML = '<div class="flex justify-center py-10"><div class="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div></div>';

    try {
        const res = await fetch(`${API}/store/orders/${currentGroup.id}`);
        const data = await res.json();
        const cases = (data.orders || []).filter(o => o.call_type === 'work_order');

        const statusLabel = { new:'חדש', processing:'בטיפול', completed:'הושלם', cancelled:'בוטל', pending:'ממתין' };
        const statusColor = { new:'bg-blue-100 text-blue-700', processing:'bg-amber-100 text-amber-700', completed:'bg-green-100 text-green-700', cancelled:'bg-red-100 text-red-700', pending:'bg-slate-100 text-slate-500' };

        el.innerHTML = `
        <div class="pb-20">
            <div class="bg-gradient-to-r from-indigo-700 to-slate-800 rounded-[2rem] p-5 text-white shadow-xl mb-4 relative overflow-hidden">
                <div class="absolute -top-6 -left-6 w-32 h-32 bg-white/5 rounded-full"></div>
                <h2 class="text-lg font-black mb-1">תיקים פעילים 📁</h2>
                <p class="text-indigo-200 text-xs">ניהול תיקי לקוחות ופרויקטים</p>
                <div class="flex gap-3 mt-3 flex-wrap">
                    <div class="bg-white/10 rounded-xl px-3 py-2 text-center min-w-[70px]">
                        <div class="text-xl font-black">${cases.filter(c=>c.status==='processing').length}</div>
                        <div class="text-[10px] text-indigo-200">בטיפול</div>
                    </div>
                    <div class="bg-white/10 rounded-xl px-3 py-2 text-center min-w-[70px]">
                        <div class="text-xl font-black">${cases.filter(c=>c.status==='new').length}</div>
                        <div class="text-[10px] text-indigo-200">חדשים</div>
                    </div>
                    <div class="bg-white/10 rounded-xl px-3 py-2 text-center min-w-[70px]">
                        <div class="text-xl font-black">${cases.filter(c=>c.status==='completed').length}</div>
                        <div class="text-[10px] text-indigo-200">הושלמו</div>
                    </div>
                </div>
            </div>

            <button onclick="window.openWorkOrderModal(null)" class="w-full bg-indigo-600 text-white rounded-2xl py-3 font-bold text-sm mb-4 shadow-md hover:bg-indigo-700 transition flex items-center justify-center gap-2">
                <i class="fa-solid fa-plus"></i> פתח תיק חדש
            </button>

            <div id="cases-filter-bar" class="flex gap-2 overflow-x-auto pb-2 mb-3">
                ${['all','new','processing','completed'].map((s,i) => `
                <button onclick="window.filterCases('${s}')" id="cases-filter-${s}" class="cases-filter-btn text-xs font-bold px-4 py-2 rounded-full border whitespace-nowrap transition ${i===0?'bg-indigo-600 text-white border-indigo-600':'bg-white text-slate-500 border-slate-200'}">
                    ${s==='all'?'הכל':statusLabel[s]||s}
                </button>`).join('')}
            </div>

            <div id="cases-list">
                ${cases.length === 0 ? `<div class="text-center py-12 text-slate-400"><i class="fa-solid fa-folder-open text-4xl mb-3 text-slate-200"></i><p class="font-medium">אין תיקים עדיין</p><p class="text-xs mt-1">לחץ "פתח תיק חדש" כדי להתחיל</p></div>` :
                cases.map(c => {
                    const st = c.status || 'new';
                    const total = parseFloat(c.total_amount || 0);
                    const date = c.created_at ? new Date(c.created_at).toLocaleDateString('he-IL') : '';
                    return `<div class="cases-item bg-white rounded-2xl border border-slate-100 shadow-sm p-4 mb-3 cursor-pointer hover:border-indigo-200 hover:shadow-md transition" data-status="${st}" onclick="window.openWorkOrderModal(${c.id})">
                        <div class="flex items-start justify-between mb-2">
                            <div class="flex-1 pr-2">
                                <p class="font-bold text-slate-800 text-sm">${safeStr(c.customer_name||'ללא שם')}</p>
                                <p class="text-xs text-slate-400 mt-0.5">${safeStr(c.title||c.description||'ללא תיאור')}</p>
                            </div>
                            <span class="text-[10px] font-bold px-2 py-1 rounded-full ${statusColor[st]||statusColor.new}">${statusLabel[st]||st}</span>
                        </div>
                        <div class="flex items-center justify-between text-xs text-slate-400">
                            <span>#${c.id} • ${date}</span>
                            ${total>0?`<span class="font-bold text-slate-700">₪${total.toFixed(2)}</span>`:''}
                        </div>
                    </div>`;
                }).join('')}
            </div>
        </div>`;
    } catch(e) {
        el.innerHTML = '<p class="text-center text-red-400 py-8">שגיאה בטעינת התיקים</p>';
    }
};

window.filterCases = function(status) {
    document.querySelectorAll('.cases-filter-btn').forEach(b => b.classList.replace('bg-indigo-600','bg-white') || b.classList.replace('text-white','text-slate-500') || b.classList.replace('border-indigo-600','border-slate-200'));
    const activeBtn = document.getElementById(`cases-filter-${status}`);
    if (activeBtn) { activeBtn.classList.replace('bg-white','bg-indigo-600'); activeBtn.classList.replace('text-slate-500','text-white'); activeBtn.classList.replace('border-slate-200','border-indigo-600'); }
    document.querySelectorAll('.cases-item').forEach(item => {
        item.style.display = (status==='all' || item.dataset.status===status) ? '' : 'none';
    });
};

// ─── מודול שעות עבודה (Timelog) ──────────────────────────────
let _timerInterval = null;
let _timerStart = null;
let _timerRunning = false;

window.renderTimelogTab = async function() {
    const el = document.getElementById('content-timelog');
    if (!el) return;
    el.innerHTML = '<div class="flex justify-center py-10"><div class="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div></div>';

    try {
        const [timeRes, woRes] = await Promise.all([
            fetch(`${API}/timelog/${currentGroup.id}`),
            fetch(`${API}/work-orders/list/${currentGroup.id}`)
        ]);
        const data = await timeRes.json();
        const entries = data.entries || [];
        const woData = await woRes.json();
        const openWOs = (woData.workOrders || []).filter(w => !['completed','cancelled'].includes(w.status));

        const totalUnbilledMin = entries.filter(e=>!e.is_billed).reduce((s,e)=>s+parseInt(e.minutes||0),0);
        const totalUnbilledVal = entries.filter(e=>!e.is_billed).reduce((s,e)=>s+(parseInt(e.minutes||0)/60)*parseFloat(e.hourly_rate||0),0);

        // Restore timer state from localStorage
        const savedTimer = JSON.parse(localStorage.getItem('_timelog_timer')||'null');
        if (savedTimer && savedTimer.groupId === currentGroup.id) {
            _timerStart = savedTimer.start;
            _timerRunning = true;
        }

        el.innerHTML = `
        <div class="pb-20">
            <div class="bg-gradient-to-r from-slate-800 to-indigo-800 rounded-[2rem] p-5 text-white shadow-xl mb-4 relative overflow-hidden">
                <div class="absolute -top-4 -right-4 w-24 h-24 bg-white/5 rounded-full"></div>
                <h2 class="text-lg font-black mb-1">שעות עבודה ⏱️</h2>
                <p class="text-slate-300 text-xs">מעקב שעות לחיוב לקוחות</p>
                <div class="flex gap-3 mt-3">
                    <div class="bg-white/10 rounded-xl px-3 py-2 text-center">
                        <div class="text-xl font-black">${Math.ceil(totalUnbilledMin/60)}</div>
                        <div class="text-[10px] text-slate-300">שעות לחיוב</div>
                    </div>
                    <div class="bg-white/10 rounded-xl px-3 py-2 text-center">
                        <div class="text-xl font-black">₪${totalUnbilledVal.toFixed(0)}</div>
                        <div class="text-[10px] text-slate-300">שווי לחיוב</div>
                    </div>
                    <div class="bg-white/10 rounded-xl px-3 py-2 text-center">
                        <div class="text-xl font-black">${entries.length}</div>
                        <div class="text-[10px] text-slate-300">רשומות</div>
                    </div>
                </div>
            </div>

            <!-- Timer Widget -->
            <div class="bg-white rounded-2xl border border-slate-100 shadow-sm p-4 mb-4">
                <p class="text-xs font-bold text-slate-500 mb-3">⏱ טיימר חי</p>
                ${openWOs.length ? `<select id="timelog-timer-wo" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-indigo-400 mb-3 bg-white">
                    <option value="">בחר תיק (אופציונלי)</option>
                    ${openWOs.map(w=>`<option value="${w.id}">${safeStr(w.customer_name||w.quote_title||'תיק #'+w.id)} #${w.id}</option>`).join('')}
                </select>` : ''}
                <div class="flex items-center gap-3">
                    <div id="timelog-timer-display" class="text-3xl font-black text-slate-800 tabular-nums tracking-tight flex-1">${_timerRunning?'מודד...':'00:00:00'}</div>
                    <button id="timelog-timer-btn" onclick="window.toggleTimer()" class="px-5 py-3 rounded-xl font-bold text-sm transition shadow-md ${_timerRunning?'bg-red-500 hover:bg-red-600 text-white':'bg-green-500 hover:bg-green-600 text-white'}">
                        ${_timerRunning?'⏹ עצור':'▶ התחל'}
                    </button>
                </div>
                ${_timerRunning?`<p class="text-xs text-green-600 mt-2 font-medium">טיימר פעיל...</p>`:''}
            </div>

            <!-- Manual Entry Form -->
            <div class="bg-white rounded-2xl border border-slate-100 shadow-sm p-4 mb-4">
                <p class="text-xs font-bold text-slate-500 mb-3">✏️ הזנה ידנית</p>
                <div class="space-y-3">
                    ${openWOs.length ? `<select id="timelog-wo-id" class="w-full border border-indigo-200 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-indigo-400 bg-white font-medium" onchange="window._timelogFillFromWO(this)">
                        <option value="">📁 בחר תיק (אופציונלי)</option>
                        ${openWOs.map(w=>`<option value="${w.id}" data-name="${safeStr(w.customer_name||'')}">${safeStr(w.customer_name||w.quote_title||'תיק')} — #${w.id}</option>`).join('')}
                    </select>` : '<input id="timelog-wo-id" type="hidden" value="">'}
                    <input id="timelog-desc" type="text" placeholder="תיאור העבודה" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-indigo-400">
                    <div class="grid grid-cols-2 gap-2">
                        <input id="timelog-minutes" type="number" placeholder="דקות" min="1" class="border border-slate-200 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-indigo-400">
                        <input id="timelog-rate" type="number" placeholder="₪/שעה" min="0" class="border border-slate-200 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-indigo-400">
                    </div>
                    <input id="timelog-customer" type="text" placeholder="שם לקוח (אופציונלי)" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-indigo-400">
                    <input id="timelog-date" type="date" value="${new Date().toISOString().slice(0,10)}" class="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-indigo-400">
                    <button onclick="window.saveTimelogEntry()" class="w-full bg-indigo-600 text-white rounded-xl py-2.5 font-bold text-sm hover:bg-indigo-700 transition">שמור רשומה</button>
                </div>
            </div>

            <!-- Entries List -->
            <div class="flex items-center justify-between mb-3 px-1">
                <p class="text-sm font-bold text-slate-700">רשומות אחרונות</p>
                <div class="flex gap-2 flex-wrap justify-end">
                    ${entries.length>0?`<button onclick="window.exportTimelogCSV()" class="text-xs font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 px-3 py-1.5 rounded-xl hover:bg-emerald-100 transition">📥 ייצא CSV</button>`:''}
                    ${totalUnbilledVal>0?`<button onclick="window.createInvoiceFromTimelog()" class="text-xs font-bold text-indigo-600 bg-indigo-50 border border-indigo-200 px-3 py-1.5 rounded-xl hover:bg-indigo-100 transition">💳 צור חשבונית מהשעות</button>`:''}
                </div>
            </div>
            <div id="timelog-entries-list">
                ${entries.length===0?`<div class="text-center py-10 text-slate-400"><i class="fa-solid fa-clock text-4xl mb-3 text-slate-200"></i><p class="font-medium">אין רשומות שעות</p></div>`:
                entries.slice(0,50).map(e=>{
                    const mins = parseInt(e.minutes||0);
                    const hrs = Math.floor(mins/60); const rem = mins%60;
                    const val = (mins/60)*parseFloat(e.hourly_rate||0);
                    const dt = e.logged_date?new Date(e.logged_date).toLocaleDateString('he-IL'):'';
                    return `<div class="bg-white rounded-2xl border ${e.is_billed?'border-green-100 opacity-60':'border-slate-100'} shadow-sm p-3.5 mb-2 flex items-start justify-between">
                        <div class="flex-1 pr-2">
                            <p class="text-sm font-bold text-slate-800">${safeStr(e.description||'ללא תיאור')}</p>
                            ${e.customer_name?`<p class="text-xs text-indigo-600 font-medium mt-0.5">${safeStr(e.customer_name)}</p>`:''}
                            ${e.wo_id?`<p class="text-xs text-teal-600 font-medium mt-0.5">📁 תיק #${e.wo_id}</p>`:''}
                            <p class="text-xs text-slate-400 mt-0.5">${dt} • ${hrs}:${String(rem).padStart(2,'0')} שעות${val>0?` • ₪${val.toFixed(0)}`:''}</p>
                        </div>
                        <div class="flex flex-col items-end gap-1">
                            ${e.is_billed?'<span class="text-[10px] bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-bold">חויב</span>':''}
                            <button onclick="window.deleteTimelogEntry(${e.id})" class="text-red-400 hover:text-red-600 text-xs"><i class="fa-solid fa-trash"></i></button>
                        </div>
                    </div>`;
                }).join('')}
            </div>
        </div>`;

        if (_timerRunning && _timerStart) window._startTimerDisplay();
    } catch(e) {
        el.innerHTML = '<p class="text-center text-red-400 py-8">שגיאה בטעינת שעות העבודה</p>';
    }
};

window.toggleTimer = function() {
    if (_timerRunning) {
        // Stop timer — prompt to save
        clearInterval(_timerInterval);
        _timerInterval = null;
        const elapsed = Math.round((Date.now() - _timerStart) / 60000);
        _timerRunning = false;
        _timerStart = null;
        localStorage.removeItem('_timelog_timer');
        const btn = document.getElementById('timelog-timer-btn');
        const disp = document.getElementById('timelog-timer-display');
        if (btn) { btn.textContent = '▶ התחל'; btn.className = btn.className.replace('bg-red-500 hover:bg-red-600','bg-green-500 hover:bg-green-600'); }
        if (disp) disp.textContent = '00:00:00';
        if (elapsed > 0) {
            document.getElementById('timelog-minutes').value = elapsed;
            const timerWo = document.getElementById('timelog-timer-wo');
            const manualWo = document.getElementById('timelog-wo-id');
            if (timerWo && manualWo && timerWo.value) {
                manualWo.value = timerWo.value;
                window._timelogFillFromWO(manualWo);
            }
            showToast('info', `עצרת לאחר ${elapsed} דקות — מלא פרטים ושמור`);
        }
    } else {
        _timerStart = Date.now();
        _timerRunning = true;
        localStorage.setItem('_timelog_timer', JSON.stringify({ groupId: currentGroup.id, start: _timerStart }));
        const btn = document.getElementById('timelog-timer-btn');
        if (btn) { btn.textContent = '⏹ עצור'; btn.className = btn.className.replace('bg-green-500 hover:bg-green-600','bg-red-500 hover:bg-red-600'); }
        window._startTimerDisplay();
    }
};

window._startTimerDisplay = function() {
    if (_timerInterval) clearInterval(_timerInterval);
    _timerInterval = setInterval(() => {
        const disp = document.getElementById('timelog-timer-display');
        if (!disp) { clearInterval(_timerInterval); return; }
        const elapsed = Math.floor((Date.now() - _timerStart) / 1000);
        const h = Math.floor(elapsed/3600); const m = Math.floor((elapsed%3600)/60); const s = elapsed%60;
        disp.textContent = `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
    }, 1000);
};

window._timelogFillFromWO = function(sel) {
    const opt = sel.options[sel.selectedIndex];
    const customerEl = document.getElementById('timelog-customer');
    if (customerEl && opt && opt.dataset.name) {
        customerEl.value = opt.dataset.name;
    }
};

window.saveTimelogEntry = async function() {
    const desc = document.getElementById('timelog-desc')?.value?.trim();
    const minutes = parseInt(document.getElementById('timelog-minutes')?.value || 0);
    const rate = parseFloat(document.getElementById('timelog-rate')?.value || 0);
    const customer = document.getElementById('timelog-customer')?.value?.trim();
    const date = document.getElementById('timelog-date')?.value;
    const woId = document.getElementById('timelog-wo-id')?.value || null;
    if (!minutes || minutes < 1) { showToast('error','הזן מספר דקות'); return; }
    try {
        const res = await fetch(`${API}/timelog/${currentGroup.id}`, {
            method:'POST', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({ description: desc, minutes, hourly_rate: rate, customer_name: customer, logged_date: date, wo_id: woId || null })
        });
        if (!res.ok) throw new Error();
        showToast('success','רשומה נשמרה');
        renderTimelogTab();
    } catch(e) { showToast('error','שגיאה בשמירה'); }
};

window.deleteTimelogEntry = async function(id) {
    if (!await window._uiConfirm('למחוק רשומה זו?')) return;
    try {
        const res = await fetch(`${API}/timelog/entry/${id}`, { method:'DELETE' });
        if (!res.ok) throw new Error();
        showToast('success','רשומה נמחקה');
        renderTimelogTab();
    } catch(e) { showToast('error','שגיאה במחיקה'); }
};

window.exportTimelogCSV = async function() {
    try {
        const res = await fetch(`${API}/timelog/${currentGroup.id}`);
        const data = await res.json();
        const entries = data.entries || [];
        if (!entries.length) { showToast('info', 'אין רשומות לייצוא'); return; }
        const headers = ['תאריך','שם לקוח','תיק #','תיאור','דקות','שעות','תעריף ₪/שעה','סכום ₪','חויב'];
        const rows = entries.map(e => {
            const mins = parseInt(e.minutes||0);
            const hrs = (mins/60).toFixed(2);
            const amount = ((mins/60)*parseFloat(e.hourly_rate||0)).toFixed(2);
            const date = e.logged_date ? new Date(e.logged_date).toLocaleDateString('he-IL') : '';
            return [date, e.customer_name||'', e.wo_id||'', e.description||'', mins, hrs, e.hourly_rate||0, amount, e.is_billed?'כן':'לא']
                .map(v => `"${String(v).replace(/"/g,'""')}"`).join(',');
        });
        const csv = '﻿' + [headers.join(','), ...rows].join('\n');
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const now = new Date();
        a.download = `דוח_שעות_${now.getFullYear()}_${String(now.getMonth()+1).padStart(2,'0')}.csv`;
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        URL.revokeObjectURL(url);
        showToast('success', `ייוצאו ${entries.length} רשומות`);
    } catch(e) { showToast('error', 'שגיאה בייצוא'); }
};

window.createInvoiceFromTimelog = async function() {
    showToast('info','פותח חשבונית מהשעות הלא מחויבות...');
    try {
        const res = await fetch(`${API}/timelog/${currentGroup.id}`);
        const data = await res.json();
        const unbilled = (data.entries||[]).filter(e=>!e.is_billed);
        if (!unbilled.length) { showToast('info','אין שעות לחיוב'); return; }
        const total = unbilled.reduce((s,e)=>(s + (parseInt(e.minutes||0)/60)*parseFloat(e.hourly_rate||0)),0);
        const desc = unbilled.map(e=>`${safeStr(e.description||'עבודה')} (${Math.floor(parseInt(e.minutes)/60)}:${String(parseInt(e.minutes)%60).padStart(2,'0')})`).join(', ');
        switchTab('cashflow');
        setTimeout(() => {
            showToast('info', `סה"כ לחיוב: ₪${total.toFixed(2)} — ${unbilled.length} רשומות`);
        }, 500);
    } catch(e) { showToast('error','שגיאה'); }
};

