window._renderArticlesList = function(articles, grp) {
    if (!articles || articles.length === 0) return '<p class="text-center text-slate-400 text-sm py-6">אין מאמרים עדיין</p>';
    const baseUrl = location.origin + '/storefront.html?store=' + (grp && grp.group_code ? grp.group_code : '') + '#articles';
    const storeUrl = encodeURIComponent(baseUrl);
    return articles.map(function(a) {
        const shareTitle = encodeURIComponent(a.title_he || '');
        const shareBtn = a.is_published
            ? '<button onclick="window.openArticleShare(\'' + storeUrl + '\',\'' + shareTitle + '\')" class="text-xs font-bold px-2 py-1 rounded-lg border border-indigo-200 text-indigo-600 hover:bg-indigo-50 transition"><i class="fa-solid fa-share-nodes" style="font-size:10px"></i> שתף</button>'
            : '';
        const dateStr = a.created_at ? new Date(a.created_at).toLocaleDateString('he-IL') : '';
        const statusBadge = a.is_published ? '<span class="text-green-600 font-bold">פורסם</span>' : '<span class="text-amber-600 font-bold">טיוטה</span>';
        const enTitle = a.title_en ? '<p class="text-xs text-slate-400">' + safeStr(a.title_en) + '</p>' : '';
        const borderCls = a.is_published ? 'border-amber-200 text-amber-600' : 'border-green-200 text-green-600';
        const actionLabel = a.is_published ? 'הסתר' : 'פרסם';
        return '<div class="bg-white rounded-2xl border border-slate-100 shadow-sm p-3.5 mb-2">' +
            '<div class="flex items-start justify-between">' +
            '<div class="flex-1 pr-2">' +
            '<p class="font-bold text-slate-800 text-sm">' + safeStr(a.title_he || '') + '</p>' +
            enTitle +
            '<p class="text-slate-400 mt-1" style="font-size:10px">' + dateStr + ' • ' + statusBadge + '</p>' +
            '</div>' +
            '<div class="flex gap-2 shrink-0">' +
            shareBtn +
            '<button onclick="window.toggleArticlePublish(' + a.id + ',' + (!a.is_published) + ')" class="text-xs font-bold px-2 py-1 rounded-lg border ' + borderCls + '">' + actionLabel + '</button>' +
            '<button onclick="window.deleteArticle(' + a.id + ')" class="text-red-400 hover:text-red-600"><i class="fa-solid fa-trash text-sm"></i></button>' +
            '</div></div></div>';
    }).join('');
};

window.openArticleShare = function(encodedUrl, encodedTitle) {
    const url = decodeURIComponent(encodedUrl);
    const title = decodeURIComponent(encodedTitle);
    document.getElementById('article-share-modal')?.remove();
    const liUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`;
    const waUrl = `https://wa.me/?text=${encodeURIComponent(title + '\n' + url)}`;
    const html = `<div id="article-share-modal" class="fixed inset-0 bg-slate-900/60 z-[9999] flex items-end justify-center" style="direction:rtl;">
        <div class="bg-white w-full max-w-md rounded-t-3xl shadow-2xl p-5">
            <div class="flex items-center justify-between mb-4">
                <h3 class="font-black text-slate-800 text-base">שתף מאמר 🔗</h3>
                <button onclick="document.getElementById('article-share-modal').remove()" class="text-slate-400 text-xl"><i class="fa-solid fa-xmark"></i></button>
            </div>
            <p class="text-xs text-slate-500 mb-4 bg-slate-50 px-3 py-2 rounded-xl truncate" dir="ltr">${url}</p>
            <div class="space-y-2">
                <a href="${liUrl}" target="_blank" onclick="document.getElementById('article-share-modal').remove()" class="flex items-center gap-3 bg-blue-600 text-white rounded-xl px-4 py-3 font-bold text-sm hover:bg-blue-700 transition">
                    <i class="fa-brands fa-linkedin text-xl"></i> שתף בלינקדאין
                </a>
                <a href="${waUrl}" target="_blank" onclick="document.getElementById('article-share-modal').remove()" class="flex items-center gap-3 bg-green-500 text-white rounded-xl px-4 py-3 font-bold text-sm hover:bg-green-600 transition">
                    <i class="fa-brands fa-whatsapp text-xl"></i> שתף בוואטסאפ
                </a>
                <button onclick="navigator.clipboard.writeText('${url.replace(/'/g,"\\'")}').then(()=>{showToast('success','הלינק הועתק — עבור לאינסטגרם ושתף בסטורי או בביו'); document.getElementById('article-share-modal').remove();})" class="w-full flex items-center gap-3 bg-gradient-to-r from-pink-500 to-purple-600 text-white rounded-xl px-4 py-3 font-bold text-sm hover:opacity-90 transition">
                    <i class="fa-brands fa-instagram text-xl"></i> העתק לינק לאינסטגרם
                </button>
                <button onclick="navigator.clipboard.writeText('${url.replace(/'/g,"\\'")}').then(()=>{showToast('success','הלינק הועתק'); document.getElementById('article-share-modal').remove();})" class="w-full flex items-center gap-3 bg-slate-100 text-slate-700 rounded-xl px-4 py-3 font-bold text-sm hover:bg-slate-200 transition">
                    <i class="fa-solid fa-copy"></i> העתק לינק
                </button>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
};

// ─── פניות נכנסות (Leads) ────────────────────────────────────
window._professionalLeadsCache = [];
window.renderProfessionalLeadsTab = async function() {
    const el = document.getElementById('content-leads');
    if (!el) return;
    el.innerHTML = '<div class="flex justify-center py-10"><div class="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div></div>';
    try {
        const res = await fetch(`${API}/professional-leads/${currentGroup.id}`);
        const data = await res.json();
        const leads = data.leads || [];
        window._professionalLeadsCache = leads;
        const statusLabel = { new:'חדש', contacted:'נוצר קשר', converted:'הפך לקוח', closed:'נסגר' };
        const statusColor = { new:'bg-blue-100 text-blue-700', contacted:'bg-amber-100 text-amber-700', converted:'bg-green-100 text-green-700', closed:'bg-slate-100 text-slate-500' };
        el.innerHTML = `
        <div class="pb-20">
            <div class="bg-gradient-to-r from-blue-700 to-indigo-800 rounded-[2rem] p-5 text-white shadow-xl mb-4">
                <h2 class="text-lg font-black mb-1">פניות נכנסות 📥</h2>
                <p class="text-blue-200 text-xs">פניות שהגיעו מהאתר הציבורי</p>
                <div class="flex gap-3 mt-3">
                    <div class="bg-white/10 rounded-xl px-3 py-2 text-center"><div class="text-xl font-black">${leads.filter(l=>l.status==='new').length}</div><div class="text-[10px] text-blue-200">חדשות</div></div>
                    <div class="bg-white/10 rounded-xl px-3 py-2 text-center"><div class="text-xl font-black">${leads.length}</div><div class="text-[10px] text-blue-200">סה"כ</div></div>
                </div>
            </div>
            ${leads.length===0?`<div class="text-center py-12 text-slate-400"><i class="fa-solid fa-inbox text-4xl mb-3 text-slate-200"></i><p class="font-medium">אין פניות עדיין</p><p class="text-xs mt-1">פניות מהאתר יופיעו כאן</p></div>`:
            leads.map(l=>{
                const isConverted = l.status === 'converted';
                return `
            <div class="bg-white rounded-2xl border border-slate-100 shadow-sm p-4 mb-3">
                <div class="flex items-start justify-between mb-2">
                    <div>
                        <p class="font-bold text-slate-800">${safeStr(l.name||'')}</p>
                        <p class="text-xs text-slate-400 mt-0.5">${safeStr(l.subject||'')} • ${new Date(l.created_at).toLocaleDateString('he-IL')}</p>
                    </div>
                    <select onchange="window.updateLeadStatus(${l.id},this.value)" class="text-xs font-bold px-2 py-1 rounded-lg border ${statusColor[l.status||'new']||statusColor.new} outline-none">
                        ${Object.entries(statusLabel).map(([k,v])=>`<option value="${k}" ${l.status===k?'selected':''}>${v}</option>`).join('')}
                    </select>
                </div>
                ${l.message?`<p class="text-xs text-slate-600 bg-slate-50 rounded-xl p-2.5 mb-2 leading-relaxed">"${safeStr(l.message)}"</p>`:''}
                <div class="flex items-center gap-3 text-xs mb-3">
                    ${l.phone?`<a href="tel:${safeStr(l.phone)}" class="text-blue-600 font-bold flex items-center gap-1"><i class="fa-solid fa-phone"></i>${safeStr(l.phone)}</a>`:''}
                    ${l.email?`<a href="mailto:${safeStr(l.email)}" class="text-indigo-600 font-bold flex items-center gap-1"><i class="fa-solid fa-envelope"></i>${safeStr(l.email)}</a>`:''}
                </div>
                <div class="flex gap-2 flex-wrap">
                    <button onclick="window.scheduleLeadMeeting(${JSON.stringify(l.name||'').replace(/"/g,'&quot;')}, ${JSON.stringify(l.phone||'').replace(/"/g,'&quot;')})"
                        class="flex items-center gap-1 text-[11px] font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 border border-indigo-200 px-2.5 py-1.5 rounded-xl transition">
                        <i class="fa-solid fa-calendar-plus text-[10px]"></i> קבע פגישה
                    </button>
                    ${!isConverted ? `<button onclick="window.convertLeadToCustomer(${l.id}, ${JSON.stringify(l.name||'').replace(/"/g,'&quot;')}, ${JSON.stringify(l.phone||'').replace(/"/g,'&quot;')}, ${JSON.stringify(l.email||'').replace(/"/g,'&quot;')})"
                        class="flex items-center gap-1 text-[11px] font-bold text-emerald-600 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 px-2.5 py-1.5 rounded-xl transition">
                        <i class="fa-solid fa-user-plus text-[10px]"></i> המר ללקוח
                    </button>` : `<span class="flex items-center gap-1 text-[11px] font-bold text-slate-400 bg-slate-50 border border-slate-100 px-2.5 py-1.5 rounded-xl">
                        <i class="fa-solid fa-check text-[10px]"></i> הפך ללקוח
                    </span>`}
                </div>
            </div>`;}).join('')}
        </div>`;
    } catch(e) { el.innerHTML = '<p class="text-center text-red-400 py-8">שגיאה בטעינת הפניות</p>'; }
};

window.updateLeadStatus = async function(id, status) {
    try {
        await fetch(`${API}/professional-leads/${id}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ status }) });
        showToast('success','סטטוס עודכן');
    } catch(e) { showToast('error','שגיאה'); }
};

window.scheduleLeadMeeting = function(name, phone) {
    switchTab('calendar');
    setTimeout(() => {
        if (typeof window.openCalEventModal === 'function') {
            window.openCalEventModal();
            const titleEl = document.getElementById('cal-event-title');
            const phoneEl = document.getElementById('cal-event-phone');
            if (titleEl) titleEl.value = `שיחת היכרות — ${name}`;
            if (phoneEl && phone) phoneEl.value = phone;
        }
    }, 400);
};

window.convertLeadToCustomer = async function(leadId, name, phone, email) {
    if (!await window._uiConfirm(`להמיר את "${name}" ללקוח רשום?`)) return;
    try {
        const custRes = await fetch(`${API}/store/customers`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ groupId: currentGroup.id, name, phone, email })
        });
        const custData = await custRes.json();
        if (!custData.success) throw new Error(custData.error || 'שגיאה ביצירת לקוח');
        await fetch(`${API}/professional-leads/${leadId}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ status: 'converted' })
        });
        // הצג אפשרות לשלוח הצעה
        const html = `<div id="lead-converted-modal" class="fixed inset-0 bg-slate-900/60 z-[9999] flex items-center justify-center p-4" style="direction:rtl;">
            <div class="bg-white rounded-3xl shadow-2xl p-6 max-w-sm w-full text-center">
                <div class="text-4xl mb-3">🎉</div>
                <h3 class="font-black text-slate-800 text-lg mb-1">הלקוח נוצר!</h3>
                <p class="text-sm text-slate-500 mb-5">${safeStr(name)} נוסף/ה לרשימת הלקוחות שלך</p>
                <div class="flex flex-col gap-2">
                    <button onclick="document.getElementById('lead-converted-modal').remove(); switchTab('sales');"
                        class="w-full bg-indigo-600 text-white rounded-xl py-3 font-bold text-sm hover:bg-indigo-700 transition">
                        📄 שלח הצעת מחיר
                    </button>
                    <button onclick="document.getElementById('lead-converted-modal').remove(); switchTab('customers');"
                        class="w-full bg-slate-100 text-slate-700 rounded-xl py-3 font-bold text-sm hover:bg-slate-200 transition">
                        👤 צפה בכרטיס הלקוח
                    </button>
                    <button onclick="document.getElementById('lead-converted-modal').remove(); renderProfessionalLeadsTab();"
                        class="text-slate-400 text-sm font-medium py-1">חזור לפניות</button>
                </div>
            </div>
        </div>`;
        document.body.insertAdjacentHTML('beforeend', html);
    } catch(e) { showToast('error', e.message || 'שגיאה בהמרה'); }
};

// ============================================================
// ===== END PROFESSIONAL CONTENT & LEADS MODULES =====
