// ======= EDITOR HELPERS =======
let _mtAutoSaveTimer = null;
window._mtEF = function(k, v) {
    _mtState.editForm[k] = v;
    // debounced auto-save after 1.5s
    clearTimeout(_mtAutoSaveTimer);
    const el = document.getElementById('mt-autosave-status');
    if (el) el.textContent = 'שינויים לא שמורים...';
    _mtAutoSaveTimer = setTimeout(async () => {
        const statusEl = document.getElementById('mt-autosave-status');
        if (statusEl) statusEl.textContent = 'שומר...';
        await window._mtSave(true);
        const statusEl2 = document.getElementById('mt-autosave-status');
        if (statusEl2) statusEl2.textContent = 'נשמר ✓';
        setTimeout(() => { const s = document.getElementById('mt-autosave-status'); if (s) s.textContent = ''; }, 2500);
    }, 1500);
};

window._mtUploadImg = async function(field) {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = async (e) => {
        const file = e.target.files[0]; if (!file) return;
        try {
            const [sr, pr] = await Promise.all([
                fetch(`${API}/public/settings/cloudinary_cloud_name`),
                fetch(`${API}/public/settings/cloudinary_upload_preset`)
            ]);
            const cloudName = (await sr.json()).value;
            const preset = (await pr.json()).value;
            if (!cloudName || !preset) { showToast('error', 'הגדרות Cloudinary חסרות — פנה למנהל מערכת'); return; }
            showToast('info', 'מעלה תמונה...');
            const dataUrl = await new Promise(resolve => compressImage(file, 1600, 1600, 0.85, resolve));
            const blob = await fetch(dataUrl).then(r => r.blob());
            const fd = new FormData();
            fd.append('file', blob, 'menu-img.jpg');
            fd.append('upload_preset', preset);
            fd.append('folder', 'family-flow-menus');
            const upData = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, { method: 'POST', body: fd }).then(r => r.json());
            if (!upData.secure_url) { showToast('error', 'שגיאה בהעלאת התמונה'); return; }
            _mtState.editForm[field] = upData.secure_url;
            _mtRenderEditor(document.getElementById('menu-templates-root'));
            showToast('success', 'התמונה הועלתה');
        } catch(err) { showToast('error', 'שגיאה בהעלאת תמונה'); }
    };
    input.click();
};

window._mtToggleSec = function(id) {
    _mtState.expandedSections[id] = !_mtState.expandedSections[id];
    _mtRender();
};

window._mtBack = async function() {
    _mtState.view = 'list';
    _mtState.cur = null;
    try {
        const res = await fetch('/api/menu-templates', { headers: { Authorization: `Bearer ${window._bizToken}` } });
        if (res.ok) _mtState.list = await res.json();
    } catch(e) {}
    _mtRender();
};

window._mtSave = async function(silent) {
    const f = _mtState.editForm;
    const t = _mtState.cur;
    if (!t) return;
    const name = (f.name || '').trim();
    if (!name) { if (!silent) _mtToast('שם התפריט נדרש', 'err'); return; }
    const btn = document.getElementById('mt-save-btn');
    if (btn && !silent) { btn.disabled = true; btn.textContent = '...'; }
    try {
        const res = await fetch(`/api/menu-templates/${t.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${window._bizToken}` },
            body: JSON.stringify({
                name,
                event_type: f.event_type || null,
                description: f.description || null,
                pricing_mode: f.pricing_mode || 'per_person',
                show_related_options: !!f.show_related_options,
                base_price_per_person: parseFloat(f.base_price_per_person) || 0,
                min_guests: f.min_guests ? parseInt(f.min_guests) : null,
                max_guests: f.max_guests ? parseInt(f.max_guests) : null,
                is_active: f.is_active,
                is_public: f.is_public,
                cover_image_url: f.cover_image_url || null,
                logo_url: f.logo_url || null,
                slogan: f.slogan || null,
                contact_phone: f.contact_phone || null,
                contact_address: f.contact_address || null,
                notification_email: f.notification_email || null,
                event_mode: !!f.event_mode,
                hide_prices: !!f.hide_prices,
                event_greeting: f.event_greeting || null,
                event_intro: f.event_intro || null,
                event_image_url: f.event_image_url || null
            })
        });
        const data = await res.json();
        if (!res.ok) { _mtToast(data.error || 'שגיאה', 'err'); }
        else { _mtState.cur = { ..._mtState.cur, ...data }; if (!silent) _mtToast('נשמר ✓'); }
    } catch(e) { if (!silent) _mtToast('שגיאת תקשורת', 'err'); }
    if (btn && !silent) { btn.disabled = false; btn.textContent = 'שמור'; }
};

// ======= ADD SECTION MODAL =======
window._mtAddSecModal = function() {
    _mtShowModal('mt-sec-modal', `
    <h3 style="margin:0 0 16px;font-size:16px;font-weight:700;color:#1e293b">הוספת שלב</h3>
    <div style="display:flex;flex-direction:column;gap:12px">
        <div>
            <label style="font-size:12px;color:#64748b;font-weight:600;display:block;margin-bottom:4px">שם השלב *</label>
            <input id="mt-sn" placeholder="ראשונות / עיקריות / קינוחים..." style="${_mtInputS()}">
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
            <div>
                <label style="font-size:12px;color:#64748b;font-weight:600;display:block;margin-bottom:4px">מינ' בחירות</label>
                <input id="mt-smin" type="number" min="0" value="0" style="${_mtInputS()}">
            </div>
            <div>
                <label style="font-size:12px;color:#64748b;font-weight:600;display:block;margin-bottom:4px">מקס' בחירות</label>
                <input id="mt-smax" type="number" min="1" value="99" style="${_mtInputS()}">
            </div>
        </div>
    </div>
    <div id="mt-sec-err" style="color:#ef4444;font-size:12px;min-height:16px;margin-top:7px"></div>
    <div style="display:flex;gap:8px;margin-top:16px">
        <button onclick="_mtCloseModal('mt-sec-modal')" style="${_mtBtnS('ghost')}">ביטול</button>
        <button id="mt-sec-add-btn" onclick="_mtDoAddSec()" style="${_mtBtnS('primary')};flex:2">הוסף שלב</button>
    </div>`);
    setTimeout(() => { const n = document.getElementById('mt-sn'); if (n) n.focus(); }, 60);
};

async function _mtDoAddSec() {
    const name = (document.getElementById('mt-sn')?.value || '').trim();
    const errEl = document.getElementById('mt-sec-err');
    if (!name) { if (errEl) errEl.textContent = 'שם השלב נדרש'; return; }
    const minC = parseInt(document.getElementById('mt-smin')?.value) || 0;
    const maxC = parseInt(document.getElementById('mt-smax')?.value) || 99;
    const btn = document.getElementById('mt-sec-add-btn');
    if (btn) { btn.disabled = true; btn.textContent = '...'; }
    try {
        const res = await fetch(`/api/menu-templates/${_mtState.cur.id}/sections`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${window._bizToken}` },
            body: JSON.stringify({ name, min_choices: minC, max_choices: maxC, is_required: minC > 0 })
        });
        const data = await res.json();
        if (!res.ok) {
            if (errEl) errEl.textContent = data.error || 'שגיאה';
            if (btn) { btn.disabled = false; btn.textContent = 'הוסף שלב'; }
            return;
        }
        _mtState.cur.sections = [...(_mtState.cur.sections || []), { ...data, items: [] }];
        _mtState.expandedSections[data.id] = true;
        _mtCloseModal('mt-sec-modal');
        _mtRender();
        _mtToast('השלב נוסף');
    } catch(e) {
        if (errEl) errEl.textContent = 'שגיאת תקשורת';
        if (btn) { btn.disabled = false; btn.textContent = 'הוסף שלב'; }
    }
}

window._mtDelSection = async function(id) {
    if (!confirm('למחוק שלב זה ואת כל פריטיו?')) return;
    try {
        const res = await fetch(`/api/menu-sections/${id}`, { method: 'DELETE', headers: { Authorization: `Bearer ${window._bizToken}` } });
        if (!res.ok) { const d = await res.json(); _mtToast(d.error || 'שגיאה', 'err'); return; }
        _mtState.cur.sections = (_mtState.cur.sections || []).filter(s => s.id !== id);
        _mtRender();
        _mtToast('השלב נמחק');
    } catch(e) { _mtToast('שגיאת תקשורת', 'err'); }
};

// ======= ADD ITEM MODAL =======
window._mtAddItemModal = function(sectionId) {
    _mtShowModal('mt-item-modal', `
    <h3 style="margin:0 0 14px;font-size:16px;font-weight:700;color:#1e293b">הוספת פריט</h3>
    <div style="display:flex;gap:0;border-bottom:2px solid #e2e8f0;margin-bottom:16px">
        <button id="mt-tab-manual" onclick="_mtItemTab('manual',${sectionId})" style="padding:8px 18px;border:none;background:transparent;font-size:13px;font-weight:700;color:#6366f1;border-bottom:2px solid #6366f1;margin-bottom:-2px;cursor:pointer;font-family:inherit">ידנית</button>
        <button id="mt-tab-catalog" onclick="_mtItemTab('catalog',${sectionId})" style="padding:8px 18px;border:none;background:transparent;font-size:13px;font-weight:600;color:#94a3b8;border-bottom:2px solid transparent;margin-bottom:-2px;cursor:pointer;font-family:inherit">מהקטלוג</button>
    </div>
    <div id="mt-tab-content"></div>`, '540px');
    _mtRenderManualTab(sectionId);
    setTimeout(() => { const n = document.getElementById('mt-in'); if (n) n.focus(); }, 60);
};

window._mtItemTab = function(tab, sectionId) {
    document.getElementById('mt-tab-manual').style.cssText += tab==='manual' ? ';color:#6366f1;border-bottom-color:#6366f1;font-weight:700' : ';color:#94a3b8;border-bottom-color:transparent;font-weight:600';
    document.getElementById('mt-tab-catalog').style.cssText += tab==='catalog' ? ';color:#6366f1;border-bottom-color:#6366f1;font-weight:700' : ';color:#94a3b8;border-bottom-color:transparent;font-weight:600';
    if (tab === 'manual') _mtRenderManualTab(sectionId);
    else _mtRenderCatalogTab(sectionId);
};

