async function _mtRenderCatalogTab(sectionId) {
    const el = document.getElementById('mt-tab-content');
    el.innerHTML = '<div style="padding:24px;text-align:center;color:#94a3b8;font-size:13px">טוען קטלוג...</div>';
    let catalog = [];
    try {
        const res = await fetch(`/api/store/catalog/${currentGroup.id}`);
        catalog = res.ok ? await res.json() : [];
    } catch(e) { catalog = []; }
    if (!catalog.length) {
        el.innerHTML = '<div style="padding:24px;text-align:center;color:#94a3b8;font-size:13px">הקטלוג ריק — הוסף מוצרים תחילה בממשק החנות</div>'; return;
    }
    window._mtCatalogSel = {};
    const rows = catalog.map(c => `
        <label style="display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:7px;cursor:pointer;transition:.12s" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='transparent'">
            <input type="checkbox" data-cid="${c.id}" data-cname="${_mtEsc(c.name)}" data-cdesc="${_mtEsc(c.description||'')}" data-cprice="${c.price||0}" data-cimg="${_mtEsc(c.image_url||'')}"
                style="width:16px;height:16px;accent-color:#6366f1;flex-shrink:0"
                onchange="window._mtCatalogSel[${c.id}]=this.checked;document.getElementById('mt-cat-count').textContent=Object.values(window._mtCatalogSel).filter(Boolean).length||''">
            ${c.image_url ? `<img src="${_mtEsc(c.image_url)}" style="width:36px;height:36px;object-fit:cover;border-radius:6px;border:1px solid #e2e8f0;flex-shrink:0">` : '<div style="width:36px;height:36px;background:#f1f5f9;border-radius:6px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:14px">🍽</div>'}
            <div style="flex:1;min-width:0">
                <div style="font-size:13.5px;font-weight:600;color:#1e293b">${_mtEsc(c.name)}</div>
                ${c.description ? `<div style="font-size:12px;color:#64748b;margin-top:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_mtEsc(c.description)}</div>` : ''}
            </div>
            ${c.price > 0 ? `<span style="font-size:12.5px;font-weight:600;color:#6366f1;white-space:nowrap;font-variant-numeric:tabular-nums">₪${Number(c.price).toLocaleString('he-IL')}</span>` : '<span style="font-size:11px;color:#94a3b8">כלול</span>'}
        </label>`).join('');
    el.innerHTML = `
    <input id="mt-cat-search" placeholder="חיפוש מוצר..." oninput="_mtFilterCatalog(this.value)"
        style="${_mtInputS()};margin-bottom:10px">
    <div id="mt-cat-list" style="max-height:300px;overflow-y:auto;border:1px solid #e2e8f0;border-radius:8px;padding:4px">${rows}</div>
    <div id="mt-item-err" style="color:#ef4444;font-size:12px;min-height:16px;margin-top:7px"></div>
    <div style="display:flex;gap:8px;margin-top:14px">
        <button onclick="_mtCloseModal('mt-item-modal')" style="${_mtBtnS('ghost')}">ביטול</button>
        <button id="mt-item-add-btn" onclick="_mtDoAddFromCatalog(${sectionId})" style="${_mtBtnS('primary')};flex:2">
            הוסף נבחרים <span id="mt-cat-count" style="background:rgba(255,255,255,.25);border-radius:10px;padding:1px 7px;margin-right:4px;font-size:11px"></span>
        </button>
    </div>`;
    document.getElementById('mt-cat-search').focus();
}

window._mtFilterCatalog = function(q) {
    const lq = q.trim().toLowerCase();
    document.querySelectorAll('#mt-cat-list label').forEach(row => {
        const name = (row.querySelector('input').dataset.cname || '').toLowerCase();
        const desc = (row.querySelector('input').dataset.cdesc || '').toLowerCase();
        row.style.display = (!lq || name.includes(lq) || desc.includes(lq)) ? '' : 'none';
    });
};

async function _mtDoAddFromCatalog(sectionId) {
    const selected = Object.entries(window._mtCatalogSel || {}).filter(([,v]) => v);
    if (!selected.length) { const e = document.getElementById('mt-item-err'); if (e) e.textContent = 'יש לסמן לפחות פריט אחד'; return; }
    const btn = document.getElementById('mt-item-add-btn');
    if (btn) { btn.disabled = true; btn.textContent = '...מוסיף'; }
    let added = 0, failed = 0;
    for (const [cidStr] of selected) {
        const inp = document.querySelector(`#mt-cat-list input[data-cid="${cidStr}"]`);
        if (!inp) continue;
        const payload = {
            name: inp.dataset.cname,
            description: inp.dataset.cdesc || null,
            catalog_item_id: parseInt(cidStr),
            is_available: true,
            image_url: inp.dataset.cimg || null,
        };
        const price = parseFloat(inp.dataset.cprice);
        if (price > 0) payload.custom_price = price;
        try {
            const res = await fetch(`/api/menu-sections/${sectionId}/items`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${window._bizToken}` },
                body: JSON.stringify(payload)
            });
            if (res.ok) { const d = await res.json(); const sec = (_mtState.cur?.sections||[]).find(s=>s.id===sectionId); if (sec) sec.items = [...(sec.items||[]), d]; added++; }
            else failed++;
        } catch(e) { failed++; }
    }
    _mtCloseModal('mt-item-modal');
    _mtRender();
    _mtToast(failed ? `נוספו ${added}, נכשלו ${failed}` : `נוספו ${added} פריטים מהקטלוג`);
}

async function _mtDoAddItem(sectionId) {
    const name = (document.getElementById('mt-in')?.value || '').trim();
    const errEl = document.getElementById('mt-item-err');
    if (!name) { if (errEl) errEl.textContent = 'שם הפריט נדרש'; return; }
    const priceVal = document.getElementById('mt-ip')?.value;
    const price = priceVal && parseFloat(priceVal) > 0 ? parseFloat(priceVal) : null;
    const btn = document.getElementById('mt-item-add-btn');
    if (btn) { btn.disabled = true; btn.textContent = '...'; }
    try {
        const imageUrl = document.getElementById('mt-img-url')?.value || null;
        const res = await fetch(`/api/menu-sections/${sectionId}/items`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${window._bizToken}` },
            body: JSON.stringify(Object.assign(
                { name, description: document.getElementById('mt-id')?.value || null, allergens: document.getElementById('mt-ia')?.value || null, is_available: true, image_url: imageUrl },
                price !== null ? { custom_price: price } : {}
            ))
        });
        const data = await res.json();
        if (!res.ok) {
            if (errEl) errEl.textContent = data.error || 'שגיאה';
            if (btn) { btn.disabled = false; btn.textContent = 'הוסף פריט'; }
            return;
        }
        const sec = (_mtState.cur?.sections || []).find(s => s.id === sectionId);
        if (sec) sec.items = [...(sec.items || []), data];
        _mtCloseModal('mt-item-modal');
        _mtRender();
        _mtToast('הפריט נוסף');
    } catch(e) {
        if (errEl) errEl.textContent = 'שגיאת תקשורת';
        if (btn) { btn.disabled = false; btn.textContent = 'הוסף פריט'; }
    }
}

window._mtPickItemImg = async function() {
    const input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/*';
    input.onchange = async (e) => {
        const file = e.target.files[0]; if (!file) return;
        try {
            const [sr, pr] = await Promise.all([
                fetch(`${API}/public/settings/cloudinary_cloud_name`),
                fetch(`${API}/public/settings/cloudinary_upload_preset`)
            ]);
            const cloudName = (await sr.json()).value;
            const preset = (await pr.json()).value;
            if (!cloudName || !preset) { const e2 = document.getElementById('mt-item-err'); if(e2) e2.textContent='הגדרות Cloudinary חסרות'; return; }
            const dataUrl = await new Promise(resolve => compressImage(file, 800, 800, 0.85, resolve));
            const blob = await fetch(dataUrl).then(r => r.blob());
            const fd = new FormData();
            fd.append('file', blob, 'item-img.jpg');
            fd.append('upload_preset', preset);
            fd.append('folder', 'family-flow-menu-items');
            const upData = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, { method: 'POST', body: fd }).then(r => r.json());
            if (!upData.secure_url) { const e2 = document.getElementById('mt-item-err'); if(e2) e2.textContent='שגיאה בהעלאה'; return; }
            document.getElementById('mt-img-url').value = upData.secure_url;
            const prev = document.getElementById('mt-img-preview');
            prev.src = upData.secure_url; prev.style.display = 'block';
            document.getElementById('mt-img-remove').style.display = '';
        } catch(err) { const e2 = document.getElementById('mt-item-err'); if(e2) e2.textContent='שגיאה בהעלאה'; }
    };
    input.click();
};

window._mtRemoveItemImgPreview = function() {
    document.getElementById('mt-img-url').value = '';
    const prev = document.getElementById('mt-img-preview');
    prev.src = ''; prev.style.display = 'none';
    document.getElementById('mt-img-remove').style.display = 'none';
};

window._mtUploadItemImg = async function(itemId, sectionId) {
    const input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/*';
    input.onchange = async (e) => {
        const file = e.target.files[0]; if (!file) return;
        try {
            const [sr, pr] = await Promise.all([
                fetch(`${API}/public/settings/cloudinary_cloud_name`),
                fetch(`${API}/public/settings/cloudinary_upload_preset`)
            ]);
            const cloudName = (await sr.json()).value;
            const preset = (await pr.json()).value;
            if (!cloudName || !preset) { _mtToast('הגדרות Cloudinary חסרות', 'err'); return; }
            _mtToast('מעלה תמונה...');
            const dataUrl = await new Promise(resolve => compressImage(file, 800, 800, 0.85, resolve));
            const blob = await fetch(dataUrl).then(r => r.blob());
            const fd = new FormData();
            fd.append('file', blob, 'item-img.jpg');
            fd.append('upload_preset', preset);
            fd.append('folder', 'family-flow-menu-items');
            const upData = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, { method: 'POST', body: fd }).then(r => r.json());
            if (!upData.secure_url) { _mtToast('שגיאה בהעלאת תמונה', 'err'); return; }
            await fetch(`/api/menu-items/${itemId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${window._bizToken}` },
                body: JSON.stringify({ image_url: upData.secure_url })
            });
            const sec = (_mtState.cur?.sections || []).find(s => s.id === sectionId);
            if (sec) { const item = sec.items.find(i => i.id === itemId); if (item) item.image_url = upData.secure_url; }
            _mtRender();
            _mtToast('התמונה עודכנה');
        } catch(err) { _mtToast('שגיאה בהעלאת תמונה', 'err'); }
    };
    input.click();
};

window._mtToggleItemA = async function(itemId, sectionId, avail) {
    try {
        await fetch(`/api/menu-items/${itemId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${window._bizToken}` },
            body: JSON.stringify({ is_available: avail })
        });
        const sec = (_mtState.cur?.sections || []).find(s => s.id === sectionId);
        if (sec) { const item = sec.items.find(i => i.id === itemId); if (item) item.is_available = avail; }
    } catch(e) { _mtToast('שגיאת תקשורת', 'err'); }
};

window._mtDelItem = async function(itemId, sectionId) {
    try {
        const res = await fetch(`/api/menu-items/${itemId}`, { method: 'DELETE', headers: { Authorization: `Bearer ${window._bizToken}` } });
        if (!res.ok) { const d = await res.json(); _mtToast(d.error || 'שגיאה', 'err'); return; }
        const sec = (_mtState.cur?.sections || []).find(s => s.id === sectionId);
        if (sec) sec.items = (sec.items || []).filter(i => i.id !== itemId);
        _mtRender();
        _mtToast('הפריט נמחק');
    } catch(e) { _mtToast('שגיאת תקשורת', 'err'); }
};

// ======= LIST ACTIONS =======
/* ── PDF design state (per-session, shared across all templates) ── */
window._mtPdfDesign = window._mtPdfDesign || { palette:'bordeaux', plating:'square', airiness:2 };

window._mtExportPDF = function(slug, name) {
    if (!slug) { showToast('error', 'יש לפרסם את התפריט תחילה (הגדר כציבורי ושמור)'); return; }

    const d = window._mtPdfDesign;
    const palettes = [
        { val:'bordeaux',   label:'בורדו קלאסי',    swatch:'#6B2434' },
        { val:'olive',      label:'זית ואבן',        swatch:'#4A6741' },
        { val:'charcoal',   label:'פחם ונחושת',      swatch:'#B87040' },
        { val:'indigo',     label:'דיו כחול',        swatch:'#2B4A7A' },
        { val:'rose',       label:'ורד בוקר',        swatch:'#9B4060' },
        { val:'forest',     label:'יער עמוק',        swatch:'#2C5038' },
        { val:'saffron',    label:'כרכום וזהב',      swatch:'#9B6818' },
        { val:'slate',      label:'פלדה קרה',        swatch:'#3A5878' },
        { val:'terracotta', label:'חמרה מדברית',     swatch:'#8C4030' },
        { val:'plum',       label:'שזיף בשל',        swatch:'#5C3474' },
        { val:'teal',       label:'טורקיז ים',       swatch:'#206874' },
        { val:'noir',       label:'שחור וזהב',       swatch:'#C4A040' },
        { val:'copper',     label:'נחושת ושרף',      swatch:'#7C4820' },
        { val:'sage',       label:'מרווה קיץ',       swatch:'#607060' },
    ];
    const platings = [
        { val:'square', label:'ריבועים קלאסיים' },
        { val:'circle', label:'מדליונים עגולים' },
        { val:'large',  label:'צלחות גדולות' },
        { val:'none',   label:'ללא תמונות' },
    ];

    const paletteChip = (p) => {
        const active = d.palette === p.val;
        return `<button onclick="window._mtPdfChip('palette','${p.val}')"
          id="mtpdf-palette-${p.val}"
          style="display:flex;align-items:center;gap:8px;padding:8px 11px;border-radius:22px;border:2px solid ${active?'#2C1A14':'#E2DAD0'};background:${active?'#2C1A14':'#FDFAF6'};color:${active?'#F5F0E8':'#4A3F35'};font-size:12px;font-family:inherit;cursor:pointer;transition:.13s;width:100%;text-align:right">
          <span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:${p.swatch};flex-shrink:0;box-shadow:0 0 0 1.5px rgba(0,0,0,.12)"></span>
          <span style="font-weight:${active?600:400};flex:1">${p.label}</span>
        </button>`;
    };
    const platingCard = (p) => {
        const active = d.plating === p.val;
        const icons = { square:'<rect x="3" y="3" width="18" height="18" rx="2" stroke="currentColor" stroke-width="1.8" fill="none"/>', circle:'<circle cx="12" cy="12" r="9" stroke="currentColor" stroke-width="1.8" fill="none"/>', large:'<rect x="1" y="4" width="22" height="16" rx="2" stroke="currentColor" stroke-width="1.8" fill="none"/>', none:'<line x1="4" y1="4" x2="20" y2="20" stroke="currentColor" stroke-width="1.8"/><line x1="20" y1="4" x2="4" y2="20" stroke="currentColor" stroke-width="1.8"/>' };
        return `<button onclick="window._mtPdfChip('plating','${p.val}')"
          id="mtpdf-plating-${p.val}"
          style="display:flex;flex-direction:column;align-items:center;gap:5px;padding:10px 4px 8px;border-radius:14px;border:2px solid ${active?'#2C1A14':'#E2DAD0'};background:${active?'#2C1A14':'#FDFAF6'};color:${active?'#F5F0E8':'#4A3F35'};font-size:10.5px;font-family:inherit;cursor:pointer;transition:.13s;flex:1;min-width:0">
          <svg width="24" height="24" viewBox="0 0 24 24" style="flex-shrink:0">${icons[p.val]||''}</svg>
          <span style="font-weight:${active?600:400};line-height:1.3;text-align:center;word-break:keep-all">${p.label}</span>
        </button>`;
    };

    window._mtPdfCurrentSlug = slug;
    window._mtPdfCurrentName = name || '';
    const previewUrl = () => `/menu/${encodeURIComponent(slug)}?palette=${d.palette}&plating=${d.plating}&air=${d.airiness}`;
    const publicUrl = () => `/menu/${encodeURIComponent(slug)}?palette=${d.palette}&plating=${d.plating}&air=${d.airiness}`;

    const overlay = document.createElement('div');
    overlay.id = 'mt-pdf-design-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:9000;background:rgba(15,10,8,.68);display:flex;align-items:center;justify-content:center;padding:12px';
    overlay.innerHTML = `
      <div style="background:#F3EDE3;width:min(920px,100%);max-height:96vh;border-radius:20px;overflow:hidden;direction:rtl;font-family:inherit;display:flex;flex-direction:column;box-shadow:0 24px 80px rgba(0,0,0,.4)">
        <!-- top bar -->
        <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px 12px;flex-shrink:0;background:#EDE6DA;border-bottom:1px solid #DDD5C5">
          <button onclick="document.getElementById('mt-pdf-design-overlay').remove()"
            style="width:30px;height:30px;border-radius:50%;border:none;background:#DFD8CC;color:#4A3F35;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;line-height:1;font-weight:300">×</button>
          <div style="display:flex;align-items:center;gap:10px">
            <span style="font-size:11px;color:#9C8C78;background:#E5DDD0;padding:4px 10px;border-radius:12px;font-weight:500">A4</span>
            <span style="font-size:13px;color:#7A6A58">תצוגה מקדימה</span>
          </div>
          <div style="text-align:right">
            <div style="font-size:16px;font-weight:700;color:#2C1A14;line-height:1.2">תצוגה מקדימה ושיתוף</div>
            <div style="font-size:11.5px;color:#8A7A68;margin-top:1px">${escHtml(name||'תפריט')}</div>
          </div>
        </div>
        <!-- body -->
        <div style="display:flex;flex:1;min-height:0">
          <!-- preview (left) -->
          <div style="flex:0 0 360px;background:#E4DDD3;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;padding:16px 14px;gap:0;overflow:hidden">
            <div style="width:100%;background:#fff;border-radius:6px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,.18);height:100%;max-height:540px;position:relative">
              <iframe id="mtpdf-preview-frame"
                src="${escHtml(previewUrl())}"
                style="width:640px;height:900px;border:none;transform:scale(0.5625);transform-origin:top right;background:#FBF7EF;pointer-events:none">
              </iframe>
            </div>
          </div>
          <!-- controls (right) -->
          <div style="flex:1;padding:18px 20px;display:flex;flex-direction:column;gap:18px;overflow-y:auto">
            <!-- palette -->
            <div>
              <div style="font-size:10px;font-weight:600;letter-spacing:.16em;color:#9C8C78;margin-bottom:9px;text-transform:uppercase">פלטת צבעים</div>
              <div style="display:grid;grid-template-columns:1fr 1fr;gap:5px">
                ${palettes.map(p=>paletteChip(p)).join('')}
              </div>
            </div>
            <!-- plating -->
            <div>
              <div style="font-size:10px;font-weight:600;letter-spacing:.16em;color:#9C8C78;margin-bottom:9px;text-transform:uppercase">סידור תמונות</div>
              <div style="display:flex;gap:7px">
                ${platings.map(p=>platingCard(p)).join('')}
              </div>
            </div>
            <!-- airiness -->
            <div>
              <div style="font-size:10px;font-weight:600;letter-spacing:.16em;color:#9C8C78;margin-bottom:9px;text-transform:uppercase">אנדריות</div>
              <div style="display:flex;align-items:center;gap:0;position:relative;padding:0 4px">
                <input type="range" min="1" max="3" step="1" value="${d.airiness}" id="mtpdf-air-slider"
                  oninput="window._mtPdfDesign.airiness=+this.value;window._mtPdfPreviewRefresh()"
                  style="width:100%;accent-color:#2C1A14;cursor:pointer;height:4px">
              </div>
              <div style="display:flex;justify-content:space-between;margin-top:4px;font-size:10.5px;color:#9C8C78;padding:0 4px">
                <span>אורירי</span><span>צפוף</span>
              </div>
            </div>
          </div>
        </div>
        <!-- bottom bar -->
        <div style="flex-shrink:0;padding:14px 18px;background:#EDE6DA;border-top:1px solid #DDD5C5;display:flex;flex-direction:column;gap:8px">
          <button onclick="window._mtPdfConfirm('${escHtml(slug)}')"
            style="width:100%;padding:13px;background:#2C1A14;color:#F5F0E8;border:none;border-radius:10px;font-size:14px;font-family:inherit;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;letter-spacing:.02em">
            <i class="fa-solid fa-file-pdf" style="font-size:15px"></i> הורדת PDF
          </button>
          <div style="display:flex;gap:8px">
            <button onclick="window._mtWaShareFromPanel('${escHtml(slug)}')"
              style="flex:1;padding:10px;background:#FDFAF6;color:#2C1A14;border:1.5px solid #DDD5C5;border-radius:10px;font-size:12.5px;font-family:inherit;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px">
              <span style="width:8px;height:8px;border-radius:50%;background:#25D366;display:inline-block;flex-shrink:0"></span> שיתוף בווצאפ
            </button>
            <button onclick="(()=>{const u='${location.origin}/menu/${encodeURIComponent(slug)}?palette='+window._mtPdfDesign.palette+'&plating='+window._mtPdfDesign.plating+'&air='+window._mtPdfDesign.airiness;navigator.clipboard?.writeText(u).then(()=>_mtToast('הקישור הועתק')).catch(()=>prompt('העתק קישור',u))})()"
              style="flex:1;padding:10px;background:#FDFAF6;color:#2C1A14;border:1.5px solid #DDD5C5;border-radius:10px;font-size:12.5px;font-family:inherit;font-weight:500;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px">
              <i class="fa-solid fa-link" style="font-size:13px;opacity:.7"></i> העתקת קישור ציבורי
            </button>
          </div>
          <div style="font-size:10.5px;color:#9C8C78;text-align:center" id="mtpdf-url-label">${location.origin}/menu/${encodeURIComponent(slug)}</div>
        </div>
      </div>`;
    document.body.appendChild(overlay);
};

window._mtPdfChip = function(group, val) {
    window._mtPdfDesign[group] = val;
    document.querySelectorAll(`[id^="mtpdf-${group}-"]`).forEach(el => {
        const active = el.id === `mtpdf-${group}-${val}`;
        el.style.background  = active ? '#2C1A14' : '#FDFAF6';
        el.style.borderColor = active ? '#2C1A14' : '#E2DAD0';
        el.style.color       = active ? '#F5F0E8' : '#4A3F35';
        const span = el.querySelector('span:last-child');
        if (span) span.style.fontWeight = active ? '600' : '400';
    });
    window._mtPdfPreviewRefresh();
};

let _mtPdfPreviewTimer = null;
window._mtPdfPreviewRefresh = function() {
    clearTimeout(_mtPdfPreviewTimer);
    _mtPdfPreviewTimer = setTimeout(() => {
        const d = window._mtPdfDesign;
        const slug = window._mtPdfCurrentSlug;
        if (!slug) return;
        const url = `/menu/${encodeURIComponent(slug)}?palette=${d.palette}&plating=${d.plating}&air=${d.airiness}`;
        const fr = document.getElementById('mtpdf-preview-frame');
        if (fr) fr.src = url;
        const lb = document.getElementById('mtpdf-link-btn');
        if (lb) lb.href = url;
    }, 400);
};

window._mtPdfConfirm = function(slug) {
    document.getElementById('mt-pdf-design-overlay')?.remove();
    const d = window._mtPdfDesign;
    const url = `/menu/${encodeURIComponent(slug)}?pdf=1&palette=${d.palette}&plating=${d.plating}&air=${d.airiness}`;
    const w = window.open(url, '_blank', 'width=900,height=700');
    if (!w) showToast('error', 'חסום חלון קופץ — אפשר זאת בדפדפן ונסה שוב');
};

window._mtWaShare = function(slug, name) {
    // פותח את פאנל התצוגה המקדימה (מוזג עם _mtExportPDF)
    window._mtExportPDF(slug, name);
};

window._mtWaShareFromPanel = function(slug) {
    const d = window._mtPdfDesign;
    const bizName = currentGroup?.name || '';
    const menuUrl = `${location.origin}/menu/${encodeURIComponent(slug)}?palette=${d.palette}&plating=${d.plating}&air=${d.airiness}`;
    const storeAlias = document.getElementById('store-alias-input')?.value?.trim() || '';
    const storeId = storeAlias || currentGroup?.group_code || '';
    const storeUrl = storeId ? (storeAlias ? `${location.origin}/${storeAlias}` : `${location.origin}/storefront.html?store=${storeId}`) : '';
    const intro = bizName ? `היי! אנחנו ${bizName}, שמחים לשתף אתכם בתפריט שלנו:` : 'היי! שמחים לשתף אתכם בתפריט שלנו:';
    let msg = `${intro}\n${menuUrl}`;
    if (storeUrl) msg += `\n\nלשירותים נוספים:\n${storeUrl}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
};

window._mtPdfOnly = function(slug, name) {
    // פותח PDF ישירות בלי פאנל עיצוב (legacy)
    window._mtExportPDF(slug, name);
};

window._mtCopyLink = function(slug) {
    if (!slug) { _mtToast('אין קישור ציבורי', 'err'); return; }
    const url = `${location.origin}/menu/${slug}`;
    if (navigator.clipboard) {
        navigator.clipboard.writeText(url).then(() => _mtToast('הקישור הועתק ✓'));
    } else {
        const ta = document.createElement('textarea');
        ta.value = url; document.body.appendChild(ta); ta.select();
        document.execCommand('copy'); ta.remove();
        _mtToast('הקישור הועתק ✓');
    }
};

window._mtPreview = function(slug) {
    if (!slug) { _mtToast('אין קישור ציבורי', 'err'); return; }
    window.open(`/menu/${slug}`, '_blank');
};

window._mtDuplicate = function() { _mtToast('שכפול — בקרוב 🔜'); };

window._mtDeleteConfirm = async function(id, name) {
    if (!confirm(`למחוק את התפריט "${name}"?\nפעולה זו אינה הפיכה.`)) return;
    try {
        const res = await fetch(`/api/menu-templates/${id}`, { method: 'DELETE', headers: { Authorization: `Bearer ${window._bizToken}` } });
        if (!res.ok) { const d = await res.json(); _mtToast(d.error || 'שגיאה במחיקה', 'err'); return; }
        _mtState.list = _mtState.list.filter(t => t.id !== id);
        _mtRender();
        _mtToast('התפריט נמחק');
    } catch(e) { _mtToast('שגיאת תקשורת', 'err'); }
};

// ======= MODAL UTILITIES =======
function _mtShowModal(id, html, maxW) {
    _mtCloseModal(id);
    const overlay = document.createElement('div');
    overlay.id = id;
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.42);z-index:9998;display:flex;align-items:center;justify-content:center;padding:16px';
    overlay.innerHTML = `<div style="background:#fff;border-radius:12px;padding:26px;width:100%;max-width:${maxW||'460px'};box-shadow:0 20px 60px rgba(0,0,0,.22);max-height:90vh;overflow-y:auto" dir="rtl">${html}</div>`;
    overlay.addEventListener('click', e => { if (e.target === overlay) _mtCloseModal(id); });
    document.body.appendChild(overlay);
}

window._mtCloseModal = function(id) { const el = document.getElementById(id); if (el) el.remove(); };

function _mtInputS() {
    return 'width:100%;padding:8px 11px;border:1.5px solid #e2e8f0;border-radius:7px;font-size:13.5px;outline:none;font-family:inherit;color:#1e293b;background:#fff';
}
function _mtBtnS(type) {
    if (type === 'primary') return 'padding:9px 18px;background:#6366f1;color:#fff;border:none;border-radius:7px;font-size:13.5px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;justify-content:center';
    return 'padding:9px 14px;background:#fff;color:#64748b;border:1.5px solid #e2e8f0;border-radius:7px;font-size:13.5px;font-weight:500;cursor:pointer;display:inline-flex;align-items:center;justify-content:center';
}
