function _renderBizQuickAreas() {
    var tabsEl = document.getElementById('biz-quick-area-tabs');
    var chipsEl = document.getElementById('biz-quick-area-chips');
    if (!tabsEl || !chipsEl) return;
    var categories = Object.keys(_QUICK_AREAS);
    var activeTab = categories[0];
    function renderTabs() {
        tabsEl.innerHTML = categories.map(function(cat) {
            var active = cat === activeTab;
            return '<button onclick="window._bizQuickTab(\'' + cat + '\')" style="padding:4px 10px;border-radius:20px;font-size:11px;font-weight:700;border:none;cursor:pointer;background:' + (active ? '#6366f1' : '#f1f5f9') + ';color:' + (active ? '#fff' : '#64748b') + ';">' + cat + '</button>';
        }).join('');
    }
    function renderChips() {
        chipsEl.innerHTML = (_QUICK_AREAS[activeTab] || []).map(function(a) {
            return '<button onclick="window._bizPickQuickArea(\'' + a.name.replace(/'/g,"\\'") + '\',' + a.lat + ',' + a.lng + ')" style="padding:5px 12px;border-radius:20px;font-size:12px;border:1.5px solid #e0e7ff;background:#f5f3ff;color:#4f46e5;cursor:pointer;font-weight:600;transition:all .15s;" onmouseover="this.style.background=\'#e0e7ff\'" onmouseout="this.style.background=\'#f5f3ff\'">' + a.name + '</button>';
        }).join('');
    }
    window._bizQuickTab = function(cat) { activeTab = cat; renderTabs(); renderChips(); };
    window._bizPickQuickArea = function(name, lat, lng) {
        var inp = document.getElementById('biz-area-city-input');
        if (inp) { inp.value = name; inp.dataset.lat = lat; inp.dataset.lng = lng; inp.focus(); }
    };
    renderTabs(); renderChips();
}

// ── ניווט ישיר לאזורי שירות ────────────────────────────────────────────────────
window.openServiceAreasSettings = function() {
    switchTab('sales');
    setTimeout(function() {
        if (typeof window.switchSalesTab === 'function') window.switchSalesTab('settings');
        setTimeout(function() {
            var el = document.getElementById('biz-service-areas-list');
            if (el && el.closest('.bg-white')) el.closest('.bg-white').scrollIntoView({ behavior: 'smooth', block: 'start' });
            _initBizNominatimAC();
            _renderBizQuickAreas();
        }, 400);
    }, 200);
};

window.openRadiusZonesSettings = function() {
    switchTab('sales');
    setTimeout(function() {
        if (typeof window.switchSalesTab === 'function') window.switchSalesTab('settings');
        setTimeout(function() {
            var el = document.getElementById('biz-radius-zones-list');
            if (el && el.closest('.bg-white')) el.closest('.bg-white').scrollIntoView({ behavior: 'smooth', block: 'start' });
            window.loadBizLocation();
            window.loadBizRadiusZones();
            _initBizLocationAC();
        }, 400);
    }, 200);
};

// ── Nominatim Autocomplete לעסקים ─────────────────────────────────────────────
function _initBizNominatimAC() {
    var input = document.getElementById('biz-area-city-input');
    if (!input || input._acInit) return;
    input._acInit = true;
    var wrap = input.parentElement;
    if (getComputedStyle(wrap).position === 'static') wrap.style.position = 'relative';
    var dd = document.createElement('div');
    dd.style.cssText = 'display:none;position:absolute;top:calc(100% + 4px);right:0;left:0;background:#fff;' +
        'border:1.5px solid #e2e8f0;border-radius:10px;box-shadow:0 6px 20px rgba(0,0,0,.1);z-index:9999;overflow:hidden;';
    wrap.appendChild(dd);
    var _t;
    input.addEventListener('input', function() {
        var val = input.value.trim();
        clearTimeout(_t);
        delete input.dataset.lat; delete input.dataset.lng;
        if (val.length < 2) { dd.style.display = 'none'; return; }
        _t = setTimeout(function() {
            var url = 'https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(val) +
                '&format=json&limit=10&addressdetails=1&accept-language=he&viewbox=34.2,29.4,35.9,33.4&bounded=0';
            fetch(url, { headers: { 'User-Agent': 'family-flow-app/1.0' } })
                .then(function(r) { return r.json(); })
                .then(function(items) {
                    if (!items.length) { dd.style.display = 'none'; return; }
                    dd.innerHTML = items.map(function(item) {
                        var a = item.address || {};
                        var short = a.quarter || a.suburb || a.neighbourhood || a.village || a.town || a.city || a.municipality || item.display_name.split(',')[0];
                        var extra = item.display_name.split(',').slice(1, 3).join(',').trim();
                        return '<div data-lat="' + item.lat + '" data-lng="' + item.lon + '" data-name="' + short.replace(/"/g,'') + '" ' +
                            'style="padding:9px 14px;font-size:13px;cursor:pointer;border-bottom:1px solid #f1f5f9;direction:rtl;text-align:right;">' +
                            '<span style="font-weight:700;color:#1e293b;">' + short + '</span>' +
                            (extra ? '<span style="font-size:11px;color:#94a3b8;margin-right:6px;">' + extra + '</span>' : '') +
                            '</div>';
                    }).join('');
                    dd.style.display = 'block';
                    dd.querySelectorAll('div').forEach(function(row) {
                        row.addEventListener('mouseover', function() { row.style.background = '#f8fafc'; });
                        row.addEventListener('mouseout', function() { row.style.background = ''; });
                        row.addEventListener('mousedown', function(e) {
                            e.preventDefault();
                            input.value = row.dataset.name;
                            input.dataset.lat = row.dataset.lat;
                            input.dataset.lng = row.dataset.lng;
                            dd.style.display = 'none';
                        });
                    });
                }).catch(function() { dd.style.display = 'none'; });
        }, 300);
    });
    input.addEventListener('blur', function() { setTimeout(function() { dd.style.display = 'none'; }, 200); });
    input.addEventListener('keydown', function(e) { if (e.key === 'Escape') dd.style.display = 'none'; });
}

window.delBizServiceArea = async function(areaId) {
    const gid = currentGroup?.id;
    if (!gid) return;
    try {
        await fetch(`/api/biz/service-areas/${gid}/${areaId}`, { method: 'DELETE' });
        window.loadBizServiceAreas();
    } catch(e) { showToast('error', 'שגיאת תקשורת'); }
};

// טעינה אוטומטית כשפותחים טאב הגדרות
const _origSwitchSalesTab = window.switchSalesTab;
window.switchSalesTab = function(tab) {
    if (_origSwitchSalesTab) _origSwitchSalesTab(tab);
    if (tab === 'settings') setTimeout(function() {
        window.loadBizServiceAreas();
        _initBizNominatimAC();
        _renderBizQuickAreas();
        window.loadBizLocation();
        window.loadBizRadiusZones();
        _initBizLocationAC();
    }, 300);
};

// ============================================================
// מעגלי משלוח — Radius Delivery Zones
// ============================================================

function _initBizLocationAC() {
    var inp = document.getElementById('biz-location-input');
    if (!inp || inp.dataset.acInit) return;
    inp.dataset.acInit = '1';
    var box = document.createElement('div');
    box.className = 'absolute z-50 bg-white border border-slate-200 rounded-xl shadow-lg w-full mt-1 max-h-56 overflow-y-auto hidden';
    box.style.top = '100%';
    inp.parentNode.style.position = 'relative';
    inp.parentNode.appendChild(box);
    var timer;
    inp.addEventListener('input', function() {
        clearTimeout(timer);
        delete inp.dataset.lat; delete inp.dataset.lng;
        var q = inp.value.trim();
        if (q.length < 2) { box.classList.add('hidden'); return; }
        timer = setTimeout(async function() {
            try {
                var url = 'https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(q) +
                    '&format=json&limit=10&addressdetails=1&accept-language=he&viewbox=34.2,29.4,35.9,33.4&bounded=0';
                var res = await fetch(url, { headers: { 'User-Agent': 'FamilyFlow/1.0' } });
                var results = await res.json();
                if (!results.length) { box.innerHTML = '<div class="p-3 text-xs text-slate-400">לא נמצאו תוצאות</div>'; box.classList.remove('hidden'); return; }
                box.innerHTML = '';
                results.forEach(function(r) {
                    var a = r.address || {};
                    var name = a.road ? ((a.road) + (a.house_number ? ' ' + a.house_number : '') + ', ' + (a.city || a.town || a.village || '')) : (a.quarter || a.suburb || a.neighbourhood || a.village || a.town || a.city || a.municipality || r.display_name);
                    var item = document.createElement('div');
                    item.className = 'px-3 py-2 text-sm cursor-pointer hover:bg-indigo-50 transition border-b border-slate-50 last:border-0';
                    item.textContent = name;
                    item.addEventListener('mousedown', function(e) {
                        e.preventDefault();
                        inp.value = name;
                        inp.dataset.lat = r.lat;
                        inp.dataset.lng = r.lon;
                        box.classList.add('hidden');
                    });
                    box.appendChild(item);
                });
                box.classList.remove('hidden');
            } catch(e) {}
        }, 350);
    });
    document.addEventListener('click', function(e) { if (!inp.parentNode.contains(e.target)) box.classList.add('hidden'); });
}

window.loadBizLocation = async function() {
    var gid = currentGroup?.id;
    if (!gid) return;
    try {
        var r = await fetch('/api/biz/location/' + gid);
        if (!r.ok) return;
        var data = await r.json();
        var disp = document.getElementById('biz-location-display');
        var inp = document.getElementById('biz-location-input');
        if (data.address) {
            if (disp) { disp.textContent = '✓ ' + data.address; disp.classList.remove('hidden'); }
            if (inp) { inp.value = ''; inp.dataset.lat = data.lat; inp.dataset.lng = data.lng; inp.placeholder = data.address; }
        }
    } catch(e) {}
};

window.saveBizLocation = async function() {
    var inp = document.getElementById('biz-location-input');
    var lat = inp?.dataset.lat;
    var lng = inp?.dataset.lng;
    var addr = inp?.value.trim();
    var gid = currentGroup?.id;
    if (!lat || !lng) { showToast('error', 'יש לבחור כתובת מרשימת ההצעות'); return; }
    if (!gid) return;
    try {
        var r = await fetch('/api/biz/location/' + gid, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ lat: parseFloat(lat), lng: parseFloat(lng), address: addr })
        });
        if (!r.ok) { showToast('error', 'שגיאת שרת ' + r.status); return; }
        var data = await r.json();
        if (data.success) {
            showToast('success', 'מיקום העסק נשמר');
            var disp = document.getElementById('biz-location-display');
            if (disp) { disp.textContent = '✓ ' + addr; disp.classList.remove('hidden'); }
            if (inp) { inp.placeholder = addr; inp.value = ''; }
        } else { showToast('error', data.error || 'שגיאה בשמירה'); }
    } catch(e) { showToast('error', 'שגיאת רשת: ' + e.message); }
};

window.loadBizRadiusZones = async function() {
    var gid = currentGroup?.id;
    var listEl = document.getElementById('biz-radius-zones-list');
    if (!listEl || !gid) return;
    try {
        var r = await fetch('/api/biz/radius-zones/' + gid);
        if (!r.ok) { listEl.innerHTML = '<p class="text-xs text-red-400 text-center py-2">שגיאה בטעינה (' + r.status + ')</p>'; return; }
        var data = await r.json();
        var zones = data.zones || [];
        if (!zones.length) {
            listEl.innerHTML = '<p class="text-xs text-slate-400 text-center py-2">אין מעגלים מוגדרים עדיין</p>';
            return;
        }
        listEl.innerHTML = zones.map(function(z) {
            return '<div class="flex items-center justify-between bg-slate-50 rounded-xl px-3 py-2 border border-slate-100">' +
                '<div class="flex items-center gap-2">' +
                '<span class="text-emerald-600 font-bold text-sm">📍 ' + z.radius_km + ' ק"מ</span>' +
                '<span class="text-xs text-slate-400 mx-1">·</span>' +
                (parseFloat(z.delivery_fee) > 0
                    ? '<span class="text-slate-600 text-xs font-bold">₪' + parseFloat(z.delivery_fee).toFixed(0) + ' משלוח</span>'
                    : '<span class="text-emerald-500 text-xs font-bold">חינם</span>') +
                '</div>' +
                '<button onclick="window.delBizRadiusZone(' + z.id + ')" class="text-slate-300 hover:text-red-400 transition text-sm px-2 py-0.5 rounded">✕</button>' +
                '</div>';
        }).join('');
    } catch(e) { if (listEl) listEl.innerHTML = '<p class="text-xs text-red-400 text-center py-2">שגיאת רשת</p>'; }
};

window.addBizRadiusZone = async function() {
    var gid = currentGroup?.id;
    if (!gid) { showToast('error', 'לא מזוהה קבוצה — נסה לרענן'); return; }
    var radius = parseInt(document.getElementById('biz-zone-radius')?.value) || 0;
    var fee = parseFloat(document.getElementById('biz-zone-fee')?.value) || 0;
    if (!radius || radius < 1) { showToast('error', 'יש להזין רדיוס תקין (1+)'); return; }
    try {
        var r = await fetch('/api/biz/radius-zones/' + gid, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ radius_km: radius, delivery_fee: fee })
        });
        if (!r.ok) { var txt = await r.text(); showToast('error', 'שגיאת שרת ' + r.status + (txt ? ': ' + txt.slice(0,80) : '')); return; }
        var data = await r.json();
        if (data.success) {
            showToast('success', 'מעגל נוסף בהצלחה');
            window.loadBizRadiusZones();
        } else { showToast('error', data.error || 'שגיאה'); }
    } catch(e) { showToast('error', 'שגיאת רשת: ' + e.message); }
};

window.delBizRadiusZone = async function(zoneId) {
    var gid = currentGroup?.id;
    if (!gid) return;
    try {
        var r = await fetch('/api/biz/radius-zones/' + gid + '/' + zoneId, { method: 'DELETE' });
        if (!r.ok) { showToast('error', 'שגיאת שרת ' + r.status); return; }
        var data = await r.json();
        if (data.success) { showToast('success', 'מעגל הוסר'); window.loadBizRadiusZones(); }
        else { showToast('error', data.error || 'שגיאה'); }
    } catch(e) { showToast('error', 'שגיאת רשת: ' + e.message); }
};
